/// In an open picker the arrows move the highlight, and the preview follows
/// it, with nothing saved; Escape and Cancel close it with nothing saved and
/// the saved value back in the preview.
#[test]
fn picker_arrow_keys_move_the_highlight_and_cancel_saves_nothing() {
    // One theme always, so the Color theme control opens the whole picker.
    let (mut runtime, instance, view) = theme_pair_runtime("theme = \"Default\"\n", true);
    let cx = view_cx();
    let open = |runtime: &mut NativeRuntime| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                    value: None,
                }),
            )
            .unwrap();
        let _ = compile_settings_view(runtime, instance, view, &cx);
    };
    let highlighted = |runtime: &NativeRuntime| {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        let picker = state.choice_picker.as_ref().expect("open picker");
        let index = state
            .common
            .last_focus
            .as_ref()
            .and_then(|focus| picker.option_index(focus))
            .expect("the keyboard is on an option");
        (
            index,
            picker.columns.get(),
            picker_candidate(state, prefs::EDIT_THEME).map(str::to_string),
            state.common.focus_visible,
        )
    };
    let press = |runtime: &mut NativeRuntime, event: AppEvent| {
        let outcome = runtime.dispatch(instance, view, event).unwrap();
        assert!(
            !outcome
                .effects
                .iter()
                .any(|effect| matches!(effect, AppEffect::ConfigPatch { .. })),
            "moving the highlight saves nothing"
        );
    };

    open(&mut runtime);
    let (start, columns, _, _) = highlighted(&runtime);
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(
        start,
        state.choice_picker.as_ref().unwrap().selected,
        "the picker opens on the saved theme"
    );
    assert!(columns >= 2);
    press(&mut runtime, AppEvent::StepFocus(1));
    let (down, _, candidate, visible) = highlighted(&runtime);
    assert_eq!(down, start + columns, "Down moves one row");
    assert!(visible, "the keyboard's highlight wears the focus ring");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    let expected = state.choice_picker.as_ref().unwrap().options[down]
        .value
        .clone();
    assert_eq!(candidate, expected, "the preview follows the highlight");
    press(
        &mut runtime,
        AppEvent::TextInput(TextInputEvent::Right { extend: false }),
    );
    assert_eq!(
        highlighted(&runtime).0,
        start + columns + 1,
        "Right moves one option"
    );
    press(
        &mut runtime,
        AppEvent::TextInput(TextInputEvent::Left { extend: false }),
    );
    press(&mut runtime, AppEvent::StepFocus(-1));
    assert_eq!(highlighted(&runtime).0, start, "Left and Up move back");
    // End moves it to the last option.
    press(
        &mut runtime,
        AppEvent::TextInput(TextInputEvent::End { extend: false }),
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    let last = state.choice_picker.as_ref().unwrap().options.len() - 1;
    assert_eq!(highlighted(&runtime).0, last, "End reaches the last option");

    // Escape: closed, nothing saved, the saved theme previewed again.
    press(&mut runtime, AppEvent::TextInput(TextInputEvent::Cancel));
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.choice_picker.is_none());
    assert_eq!(
        state.raw_value(prefs::EDIT_THEME).as_deref(),
        Some("Default")
    );
    assert_eq!(picker_candidate(state, prefs::EDIT_THEME), None);

    // Cancel does the same, from wherever the highlight was.
    open(&mut runtime);
    press(&mut runtime, AppEvent::StepFocus(1));
    press(
        &mut runtime,
        AppEvent::Action(ActionInvocation {
            id: ActionId::new("settings/choice-close"),
            value: None,
        }),
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.choice_picker.is_none());
    assert_eq!(
        state.raw_value(prefs::EDIT_THEME).as_deref(),
        Some("Default")
    );
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some(format!("settings/control/{}", prefs::EDIT_THEME).as_str()),
        "the keyboard returns to the control that opened the picker"
    );
}

/// The picker is sized to the room under the preview: at 1200x820 every
/// theme (its sections, filter and footer with it) is on glass at once, and
/// the card ends at its last row: no blank band, and no tile wider than its
/// column. The 150x48 window scrolls it: a theme tile carries its swatches,
/// and four sections do not fit 684 points.
#[test]
fn top_pickers_show_every_option_where_they_fit() {
    let cx = view_cx_at(1_200.0, 820.0);
    {
        let key = prefs::EDIT_THEME;
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{key}")),
                    value: None,
                }),
            )
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&compiled, key);
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        let picker = state.choice_picker.as_ref().unwrap();
        let prefix = format!("settings/choice/{key}/");
        let tiles = compiled
            .hits
            .iter()
            .filter(|hit| hit.key.as_str().starts_with(&prefix))
            .collect::<Vec<_>>();
        assert_eq!(tiles.len(), picker.options.len(), "{key}: every option");
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/choice-scroll/{key}")))
                .is_none(),
            "{key}: nothing to scroll"
        );
        assert!(
            tiles
                .iter()
                .all(|tile| (tile.rect.width - tiles[0].rect.width).abs() < 0.5),
            "{key}: every tile keeps its column's width"
        );
        let card = compiled
            .semantic(&UiKey::new(format!("settings/choice-picker/{key}")))
            .unwrap();
        // Its last row is the footer's (the themes folder, Import…).
        let last_row = compiled
            .hits
            .iter()
            .filter(|hit| {
                hit.rect.x >= card.rect.x - 0.5
                    && hit.rect.y >= card.rect.y - 0.5
                    && hit.rect.bottom() <= card.rect.bottom() + 0.5
            })
            .map(|hit| hit.rect.bottom())
            .fold(0.0_f32, f32::max);
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/themes/footer/{key}")))
                .is_some(),
            "{key}: the footer is on glass"
        );
        assert!(
            card.rect.bottom() - last_row <= 12.5,
            "{key}: the card ends at its last row, not {:.1}pt below it",
            card.rect.bottom() - last_row
        );
    }
}

/// At the default 80x24 window (744x420) and the shorter 584x348 one the open
/// theme picker on Top Settings scrolls instead of clipping: nothing in it is
/// cut, a thumb says there is more, and the keyboard reaches every option.
#[test]
fn compact_pickers_scroll_instead_of_clipping_at_the_default_window() {
    for (width, height) in [(738.0, 418.0), (584.0, 348.0)] {
        let cx = view_cx_at(width, height);
        {
            let route = SettingsRoute::Home;
            let (mut runtime, instance, view) = setup();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(route),
                        value: None,
                    }),
                )
                .unwrap();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                        value: None,
                    }),
                )
                .unwrap();
            let key = prefs::EDIT_THEME;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let context = format!("{route:?} at {width}x{height}");
            assert!(
                compiled
                    .semantic(&UiKey::new(format!("settings/choice-scroll/{key}")))
                    .is_some(),
                "{context}: the list says it scrolls"
            );
            walk_open_choice_picker(&mut runtime, instance, view, &cx, key, |compiled, index| {
                let context = format!("{context} option {index}");
                assert_zero_top_paint(compiled, &context);
                assert_picker_descendants_contained(compiled, key, &context);
                for hit in &compiled.hits {
                    assert!(
                        hit_matches_paint(compiled, hit),
                        "{context}: {:?} is clipped",
                        hit.key
                    );
                }
            });
        }
    }
}

/// A short choice is its row: two or three options that fit are segments in
/// the row, one click to save, instead of a full-page picker. The saved
/// segment keeps the setting's own key and action (focus, automation and
/// introspection find it where they always did), the others save their
/// option, the default one by removing the key. A saved value the segments
/// do not offer keeps the picker.
#[test]
fn short_choices_are_segments_that_save_in_one_click() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Terminal),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_zero_top_paint(&compiled, "Terminal");
    let label = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("missing {key}"))
            .label
            .clone()
    };
    assert_eq!(
        label(&format!("settings/control/{}", prefs::EDIT_BIDI)),
        "Bidirectional text: Auto"
    );
    assert_eq!(
        label(&format!("settings/segment/{}/1", prefs::EDIT_BIDI)),
        "Bidirectional text: Off"
    );
    assert!(
        label(&format!(
            "settings/segment/{}/1",
            prefs::EDIT_AMBIGUOUS_WIDTH
        ))
        .contains(": Wide")
    );
    let saved = compiled
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_AMBIGUOUS_WIDTH
        )))
        .unwrap();
    assert_eq!(
        saved.action.as_ref().map(ActionId::as_str),
        Some(format!("settings/set/{}", prefs::EDIT_AMBIGUOUS_WIDTH).as_str())
    );
    // The saved segment speaks the words it shows, never the config token.
    assert_eq!(
        saved.value,
        SemanticValue::Text("Narrow (default)".to_string())
    );

    // The saved segment opens nothing and writes nothing.
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_AMBIGUOUS_WIDTH)),
                value: None,
            }),
        )
        .unwrap();
    assert!(outcome.effects.is_empty());
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.choice_picker.is_none(), "no page-wide picker");

    // The keyboard on the next segment (Right takes it there, through the
    // page's segmented control: `a_segmented_control_is_one_tab_stop_and_one_arrow_model`);
    // activating it saves its option.
    let wide = format!("settings/segment/{}/1", prefs::EDIT_AMBIGUOUS_WIDTH);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new(wide.clone()))),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some(wide.as_str())
    );
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(wide.clone()),
                value: None,
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&outcome);
    assert_eq!(patch.edits.len(), 1);
    assert_eq!(patch.edits[0].key, prefs::EDIT_AMBIGUOUS_WIDTH);
    assert_eq!(patch.edits[0].value.as_deref(), Some("wide"));

    // Once saved, Wide is the control, and the keyboard follows it there.
    replace_settings_source(
        &mut runtime,
        view,
        "ambiguous_width = \"wide\"\n".to_string(),
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.navigate(SettingsRoute::Terminal);
    state.common.last_focus = Some(UiKey::new(wide));
    state.reseat_segment_focus();
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some(format!("settings/control/{}", prefs::EDIT_AMBIGUOUS_WIDTH).as_str())
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let narrow = compiled
        .semantic(&UiKey::new(format!(
            "settings/segment/{}/0",
            prefs::EDIT_AMBIGUOUS_WIDTH
        )))
        .expect("Narrow is now the other segment");
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: narrow.action.clone().unwrap(),
                value: None,
            }),
        )
        .unwrap();
    assert_eq!(
        emitted_config_patch(&outcome).edits[0].value,
        None,
        "the default segment removes the key"
    );

    // A saved value the segments do not offer keeps the picker that names it.
    let (mut runtime, instance, view) = setup();
    replace_settings_source(
        &mut runtime,
        view,
        "predictive_echo = \"always\"\n".to_string(),
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_PREDICTIVE_ECHO)),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    let picker = state
        .choice_picker
        .as_ref()
        .expect("the picker names the value");
    assert_eq!(picker.options[picker.selected].label, "Always (current)");
}

#[test]
fn top_choice_picker_pointer_hover_previews_without_persisting() {
    let (mut runtime, instance, view) = setup();
    let before = {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view");
        };
        renderer_preview_spec_for_key_with_font(
            state,
            prefs::EDIT_THEME,
            720,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            1.0,
            None,
        )
        .unwrap()
    };
    let opened = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        opened
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. }))
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    let picker = state.choice_picker.as_mut().unwrap();
    let nord = picker
        .options
        .iter()
        .position(|option| option.value.as_deref() == Some("Nord"))
        .unwrap();
    picker.scroll_to(picker.position_of(nord));
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/choice/{}/{}",
        prefs::EDIT_THEME,
        picker.selected
    )));
    state.common.hovered = Some(UiKey::new(format!(
        "settings/choice/{}/{nord}",
        prefs::EDIT_THEME
    )));
    assert_eq!(picker_candidate(state, prefs::EDIT_THEME), Some("Nord"));
    let candidate = renderer_preview_spec_for_key_with_font(
        state,
        prefs::EDIT_THEME,
        720,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
        None,
    )
    .unwrap();
    let (_, before_pixels) = compile_preview_for_pixels(before);
    let (_, candidate_pixels) = compile_preview_for_pixels(candidate);
    assert_ne!(
        before_pixels, candidate_pixels,
        "hovered candidate changes pixels"
    );
    assert!(!state.is_explicit(prefs::EDIT_THEME));

    let cx = view_cx_at(390.0, 568.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let preview = compiled
        .semantic(&UiKey::new("settings/top/choice-preview"))
        .expect("Top picker retains its live preview");
    let picker = compiled
        .semantic(&UiKey::new(format!(
            "settings/choice-picker/{}",
            prefs::EDIT_THEME
        )))
        .expect("theme picker");
    assert!(preview.rect.bottom() <= picker.rect.y + 0.01);
    assert!(picker.rect.bottom() <= cx.viewport.bottom() + 0.01);
}

#[test]
fn route_paths_round_trip_for_restore_and_control() {
    for route in SettingsRoute::ALL {
        assert_eq!(SettingsRoute::from_path(route.path()), Some(route));
    }
    assert_eq!(SettingsRoute::from_path("/unknown"), None);
}

/// A live packages snapshot exactly as the host builds one: through the
/// service reducer (begin → worker report → finish), never hand-assembled.
fn live_packages_state(busy: Option<crate::packages_screen::PackagesBusy>) -> PackagesState {
    live_packages_state_with_policy(busy, true, true, true)
}

fn live_packages_state_with_policy(
    busy: Option<crate::packages_screen::PackagesBusy>,
    master_enabled: bool,
    auto_install: bool,
    loop_running: bool,
) -> PackagesState {
    let mut service = packages_service(packages_report(&ay_status(), true));
    if busy.is_some() {
        let _ = service.begin(busy).unwrap();
    }
    service.state(master_enabled, auto_install, loop_running)
}

/// An atpkg status ledger as a pass writes it: `programs` as (name, installed build,
/// state), and every field the page does not read at its default.
fn atpkg_status(
    updated_at: &str,
    outcome: &str,
    programs: Vec<(&str, Option<u64>, String)>,
) -> atpkg::Status {
    atpkg::Status {
        schema: 1,
        updated_at: updated_at.to_string(),
        enabled: true,
        index_source: "alabsystems/aterm".to_string(),
        outcome: outcome.to_string(),
        programs: programs
            .into_iter()
            .map(|(name, installed_build, state)| {
                (
                    name.to_string(),
                    atpkg::ProgramStatus {
                        installed_build,
                        state,
                        tree_root: String::new(),
                    },
                )
            })
            .collect(),
        ..Default::default()
    }
}

/// The ledger of one active `ay` at build 1971.
fn ay_status() -> atpkg::Status {
    atpkg_status(
        "2026-07-21T00:00:00Z",
        "up to date",
        vec![("ay", Some(1971), "active".to_string())],
    )
}

/// The report the status worker hands the service for `status`.
fn packages_report(
    status: &atpkg::Status,
    manager_enabled: bool,
) -> crate::packages_screen::PackagesStatusReport {
    crate::packages_screen::PackagesStatusReport::from_parts(
        true,
        manager_enabled,
        "fp".to_string(),
        Some(status),
        &[],
    )
}

/// A packages service that has taken `report` exactly as the host feeds one:
/// through the service reducer (begin → worker report → finish).
fn packages_service(
    report: crate::packages_screen::PackagesStatusReport,
) -> crate::packages_screen::PackagesService {
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(report),
    ));
    service
}

/// A live packages snapshot whose machine read has also completed
/// (`replace_machine_state` after the status worker), as the host feeds the card.
fn live_packages_state_with_machine(
    busy: Option<crate::packages_screen::PackagesBusy>,
    machine: Result<atpkg::machine::MachineState, String>,
) -> PackagesState {
    live_packages_state_with_machine_reads(busy, true, None, vec![machine])
}

/// The general form: `manager_enabled` and a collection error seed the report, and
/// `reads` are reduced in order, so a read error after a good record is built as the
/// host builds it.
fn live_packages_state_with_machine_reads(
    busy: Option<crate::packages_screen::PackagesBusy>,
    manager_enabled: bool,
    collection_error: Option<&str>,
    reads: Vec<Result<atpkg::machine::MachineState, String>>,
) -> PackagesState {
    let mut report = packages_report(&ay_status(), manager_enabled);
    report.collection_error = collection_error.map(str::to_string);
    let mut service = packages_service(report);
    for read in reads {
        let _ = service.replace_machine_state(read);
    }
    if busy.is_some() {
        let _ = service.begin(busy).unwrap();
    }
    service.state(true, true, true)
}

fn machine_state_fixture(
    uc: atpkg::machine::UcPosture,
    home: atpkg::machine::HomePosture,
) -> atpkg::machine::MachineState {
    atpkg::machine::MachineState {
        universal_control: uc,
        policy: atpkg::config::UniversalControlPolicy::Off,
        home,
        config_unreadable: false,
    }
}

fn failed_packages_state() -> PackagesState {
    let old = packages_report(
        &atpkg_status("2026-07-20T00:00:00Z", "up to date", Vec::new()),
        true,
    );
    let mut service = packages_service(old.clone());
    let sequence = service
        .begin(Some(crate::packages_screen::PackagesBusy::Check))
        .unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::command(
            old,
            crate::packages_screen::PackagesCommandOutcome::Failed {
                operation: crate::packages_screen::PackagesBusy::Check,
                message: "atpkg update exited with status 7".to_string(),
            },
        )
    ));
    service.state(true, true, true)
}

/// The Packages route is a first-class destination: rail entry, page with both action
/// buttons, the maintenance switches, the program list and the contextual command all
/// derive from one route and one projection.
#[test]
fn packages_route_renders_status_actions_switches_and_programs() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/page/packages"))
            .is_some(),
        "the /packages route owns its own page"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/nav/packages"))
            .is_some(),
        "the rail exposes the Packages destination"
    );
    for key in ["packages/check", "packages/install-default"] {
        let control = compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key} button renders"));
        assert!(
            control.state.is_none_or(|state| state.enabled),
            "{key} is enabled on a live manager"
        );
        assert!(
            compiled.hits.iter().any(|hit| hit.key.as_str() == key),
            "{key} is activatable"
        );
    }
    for key in PACKAGES_PAGE_SWITCHES {
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .is_some(),
            "the {key} consent switch renders on the special page"
        );
    }
    // Retired keys get no row: updates have one switch, "Automatic updates".
    for retired in ["packages.auto_update", "packages.seed_install"] {
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{retired}")))
                .is_none(),
            "{retired} is retired: no row of its own"
        );
    }
    let tray = compiled.tray(aterm_render::Theme::default(), 13.0);
    for key in [
        prefs::EDIT_PACKAGES_ENABLED,
        prefs::EDIT_PACKAGES_AUTO_INSTALL,
    ] {
        let visible_label = compiled
            .semantic(&UiKey::new(format!("settings/label/{key}")))
            .map(|node| node.label.clone())
            .unwrap_or_else(|| panic!("the {key} switch has a label"));
        assert!(
            tray.prims.iter().any(|prim| matches!(
                prim,
                crate::widget::DrawPrim::Text { s, .. } if *s == visible_label
            )),
            "the {key} label must survive lowering into the pixel tray"
        );
    }
    // The program card may sit below the first screen: the page is one scrolling list of
    // whole cards, so the read takes every screen of it.
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(
        seen.iter().any(|(key, _)| key == "packages/programs/ay"),
        "installed programs render as read-only rows"
    );

    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands.iter().any(|command| command.id.as_str()
            == format!("settings/route{}", SettingsRoute::Packages.path())),
        "the route loop exports Go to Packages"
    );
    let check = commands
        .iter()
        .find(|command| command.id.as_str() == "packages/check")
        .expect("contextual packages/check command on the Packages route");
    assert!(check.enabled);
}

/// atpkg's whole-toolset pseudo-row is `*toolset*` in its status ledger; the page shows
/// the product name, never literal asterisks. The raw name stays in the node key.
#[test]
fn packages_toolset_pseudo_row_paints_its_product_name_without_asterisks() {
    let status = atpkg_status(
        "2026-08-22T00:00:00Z",
        "up to date",
        vec![(
            "*toolset*",
            None,
            "unavailable: no build for this architecture".to_string(),
        )],
    );
    let service = packages_service(packages_report(&status, true));
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(service.state(true, true, true), 2));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    // Whichever screen of the list carries the program list (the read takes them all).
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    let row = seen
        .iter()
        .find(|(key, _)| key == "packages/programs/*toolset*")
        .map(|(_, label)| label)
        .expect("the pseudo-row keeps its raw-name key");
    assert!(
        row.starts_with("ALab tools")
            && row.contains("unavailable: no build for this architecture"),
        "the toolset meta-row names the product: {row}"
    );
    assert!(
        !row.contains('*'),
        "no literal ledger asterisks reach the page: {row}"
    );
    assert_eq!(package_program_display_name("*toolset*"), "ALab tools");
    assert_eq!(package_program_display_name("*beta*"), "beta");
    assert_eq!(package_program_display_name("ay"), "ay");
    assert_eq!(package_program_display_name("*"), "*");
}

/// A toolchain failure's one surface is Settings: while the Packages projection names
/// one, the rail's Packages entry wears the dot and says it (its semantic value is the
/// page's headline), no other entry does, and once it clears neither remains.
#[test]
fn the_packages_rail_entry_wears_the_badge_while_a_failure_is_named() {
    let (mut runtime, instance, view) = setup();
    let rail = |runtime: &NativeRuntime| {
        let cx = view_cx();
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        SettingsRoute::ALL
            .into_iter()
            .filter(|route| route.on_rail())
            .map(|route| {
                let key = UiKey::new(format!("settings/nav{}", route.path()));
                let value = compiled
                    .semantic(&key)
                    .unwrap_or_else(|| panic!("{} is on the rail", route.label()))
                    .value
                    .clone();
                let badge = compiled.paint.iter().any(|node| {
                    node.key == key && matches!(&node.content, UiContent::Button(c) if c.spec.badge)
                });
                (route, value, badge)
            })
            .collect::<Vec<_>>()
    };
    assert!(runtime.replace_settings_packages(
        packages_state_with_program_state("error: ay stage failed: no space left on device"),
        2,
    ));
    for (route, value, badge) in rail(&runtime) {
        if route == SettingsRoute::Packages {
            assert!(badge, "the Packages entry wears the dot");
            assert_ne!(value, SemanticValue::None, "…and says it");
        } else {
            assert!(!badge && value == SemanticValue::None, "{}", route.label());
        }
    }
    // THE COMPACT CATEGORIES PAGE (review, 2026-09-22) — the second place the
    // entry is drawn, a full-width row whose spec also carries a Forward
    // chevron: it wears the dot and says it, and the glass shows exactly one
    // dot, inside that row and at its end.
    let compiled =
        compact_categories_showing(&mut runtime, instance, view, SettingsRoute::Packages);
    let key = UiKey::new(format!(
        "settings/categories{}",
        SettingsRoute::Packages.path()
    ));
    let node = compiled
        .paint
        .iter()
        .find(|node| node.key == key)
        .expect("the Packages row is painted");
    assert!(
        matches!(&node.content, UiContent::Button(c) if c.spec.badge
            && c.spec.trailing_icon == Some(ButtonIcon::Forward)),
        "the chevron row wears the badge"
    );
    assert_ne!(
        compiled.semantic(&key).expect("semantics").value,
        SemanticValue::None,
        "the badge is said, not only drawn"
    );
    let dots = painted_badge_dots(&compiled);
    assert_eq!(dots.len(), 1, "one dot on the glass: {dots:?}");
    let (x, y) = dots[0];
    assert!(
        node.rect.contains(x, y) && x > node.rect.x + node.rect.width * 0.75,
        "inside the Packages row, at its end: ({x}, {y}) in {:?}",
        node.rect
    );

    assert!(runtime.replace_settings_packages(
        packages_state_with_program_state(&atpkg::state::managed(1971, 44)),
        3,
    ));
    let compiled =
        compact_categories_showing(&mut runtime, instance, view, SettingsRoute::Packages);
    assert!(painted_badge_dots(&compiled).is_empty(), "cleared");
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.compact_navigation = false;
        state.page_scroll = 0;
    }
    for (route, value, badge) in rail(&runtime) {
        assert!(
            !badge && value == SemanticValue::None,
            "{}: cleared, the badge is gone",
            route.label()
        );
    }
}

/// The danger dots a compiled Settings view paints, as centres.
fn painted_badge_dots(compiled: &crate::native_ui::CompiledUi) -> Vec<(f32, f32)> {
    let theme = aterm_render::Theme::default();
    let danger = crate::settings::Roles::from_theme(theme).danger;
    compiled
        .tray(theme, 13.0)
        .prims
        .iter()
        .filter_map(|p| match p {
            crate::widget::DrawPrim::Dot { cx, cy, color, .. } if color[..3] == danger => {
                Some((*cx, *cy))
            }
            _ => None,
        })
        .collect()
}

/// The compact categories page, compiled on the page that shows `route`.
fn compact_categories_showing(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    route: SettingsRoute,
) -> crate::native_ui::CompiledUi {
    let cx = view_cx_at(568.0, 900.0);
    let key = UiKey::new(format!("settings/categories{}", route.path()));
    for page in 0..SettingsRoute::ALL.len() {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.compact_navigation = true;
        state.page_scroll = page;
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        if compiled.semantic(&key).is_some() {
            return compiled;
        }
    }
    panic!("{} is on no page of the compact categories", route.label());
}

/// The wall clock now, in Unix seconds — the Packages page says every time relative
/// to it (Phase 4), so its fixtures stamp their events against it.
fn wall_now() -> i64 {
    aterm_time::unix_secs().map_or(0, |s| i64::try_from(s).unwrap_or(0))
}

/// A Packages page as a working Mac shows it: claude at Anthropic's latest, codex
/// keeping 0.156.0 after refusing 0.157.0, the ALab toolset on index 44 (one program
/// held), and `events` lines of package activity, the newest a minute old.
fn packages_state_with_activity(events: usize) -> PackagesState {
    packages_state_with_activity_policy(events, true)
}

/// [`packages_state_with_activity`] with Automatic updates resolved to `master_enabled`.
fn packages_state_with_activity_policy(events: usize, master_enabled: bool) -> PackagesState {
    use atpkg::packages_log::{Entry, kind};
    let vendor = |v: &str| Some(atpkg::vendor_direct::Version::parse(v).unwrap().build_id());
    let now = wall_now();
    let a_minute_ago = aterm_types::rfc3339::format_rfc3339(u64::try_from(now - 60).unwrap());
    let status = atpkg::Status {
        last_success_at: a_minute_ago.clone(),
        last_index_build: 44,
        ..atpkg_status(
            &a_minute_ago,
            "up to date (index build 44)",
            vec![
                (
                    "claude",
                    vendor("2.1.280"),
                    atpkg::state::vendor_managed("2.1.280", "Anthropic"),
                ),
                (
                    "codex",
                    vendor("0.156.0"),
                    "error: codex 0.157.0 refused: digest mismatch \u{2014} keeping 0.156.0"
                        .to_string(),
                ),
                ("ay", Some(1971), atpkg::state::managed(1971, 44)),
                ("ty", Some(812), atpkg::state::managed(812, 44)),
                (
                    "nn",
                    Some(108),
                    atpkg::state::held_unpublished(None, 112, "aarch64-apple-darwin", 108),
                ),
            ],
        )
    };
    let mut report = packages_report(&status, true);
    for row in &mut report.programs {
        let (updated, latest, checked) = match row.name.as_str() {
            "claude" => (now - 3 * 3600, "2.1.280", Some(now - 240)),
            "codex" => (now - 3 * 86_400, "0.157.0", Some(now - 240)),
            "ay" => (now - 86_400, "build 1971", None),
            "ty" => (now - 5 * 86_400, "build 815", None),
            _ => (now - 20 * 86_400, "build 112", None),
        };
        row.update.updated_at = Some(updated);
        row.update.latest_known = Some(latest.to_string());
        row.update.checked_at = checked;
    }
    let line = |i: usize| -> Entry {
        let at = now - 60 - 3600 * i as i64;
        let fields: Vec<(&str, String)> = match i % 4 {
            0 => vec![
                ("lane", "window".into()),
                ("verb", "update".into()),
                ("exit", "0".into()),
                ("secs", "7".into()),
                ("outcome", "up to date (index build 44)".into()),
            ],
            1 => vec![
                ("program", "claude".into()),
                ("from", "2.1.278".into()),
                ("to", "2.1.280".into()),
                ("source", "Anthropic latest".into()),
                ("result", "updated".into()),
            ],
            2 => vec![
                ("program", "codex".into()),
                ("from", "0.156.0".into()),
                ("source", "OpenAI latest".into()),
                ("result", "refused".into()),
                (
                    "reason",
                    "error: codex 0.157.0 refused: digest mismatch \u{2014} keeping 0.156.0".into(),
                ),
            ],
            _ => vec![
                ("lane", "head watch".into()),
                ("verb", "update codex".into()),
                ("exit", "69".into()),
            ],
        };
        Entry {
            at: Some(at),
            kind: if matches!(i % 4, 1 | 2) {
                kind::PROGRAM
            } else {
                kind::PASS_END
            }
            .to_string(),
            pid: 1000 + i as u32,
            fields: fields
                .into_iter()
                .map(|(k, v)| (k.to_string(), v))
                .collect(),
        }
    };
    report.activity = (0..events).map(line).collect();
    report.clock = crate::packages_screen::LocalClock::fixed(0);
    report.log_path = Some(std::path::PathBuf::from(
        "/Users//who/Library/Logs/aterm/packages.log",
    ));
    packages_service(report).state(master_enabled, true, true)
}

/// Every semantic key and label the Packages page shows across its card pages.
fn packages_page_semantics(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
) -> Vec<(String, String)> {
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    let mut out = Vec::new();
    each_screen(runtime, instance, view, cx, |compiled, _| {
        out.extend(
            compiled
                .semantics
                .iter()
                .map(|n| (n.key.as_str().to_string(), n.label.clone())),
        );
    });
    out
}

/// An ALab build's row says the upstream it is based on among its facts, in `which`'s
/// words, whole at every width; a row whose record names none (an older package, any
/// other program) says nothing of it.
#[test]
fn an_alab_codex_row_says_the_upstream_it_is_based_on() {
    const BUILD: u64 = 2_026_101_601;
    let words = "based on upstream rust-v0.163.0+g0123456789ab";
    let status = atpkg_status(
        "2026-10-21T00:00:00Z",
        "up to date (index build 75)",
        vec![
            ("codex", Some(BUILD), atpkg::state::managed(BUILD, 75)),
            ("ay", Some(1971), atpkg::state::managed(1971, 75)),
        ],
    );
    let projection = |upstream: Option<&str>| {
        let mut report = packages_report(&status, true);
        for row in &mut report.programs {
            if row.name == "codex" {
                row.upstream = upstream.map(str::to_string);
            }
        }
        packages_service(report)
            .state(true, true, true)
            .projection()
    };
    let text = |lines: &[ProgramLine], name: &str| {
        let key = format!("packages/programs/{name}");
        lines
            .iter()
            .filter(|l| l.key == key || l.key.starts_with(&format!("{key}/")))
            .map(|l| l.text.clone())
            .collect::<Vec<_>>()
            .join(" | ")
    };
    let based = projection(Some(words));
    let older = projection(None);
    for width in [
        SettingsWidth::Compact,
        SettingsWidth::Medium,
        SettingsWidth::Wide,
    ] {
        let lines = packages_program_lines(&based, width);
        let codex = text(&lines, "codex");
        assert!(codex.contains(words), "{width:?}: {codex}");
        let ay = text(&lines, "ay");
        assert!(!ay.contains("based on upstream"), "{width:?}: {ay}");
        let codex = text(&packages_program_lines(&older, width), "codex");
        assert!(!codex.contains("based on upstream"), "{width:?}: {codex}");
    }
}

/// The program list says each row's facts: version and source, when it was updated,
/// the latest known, relative, never raw UTC. A state those words say is not
/// repeated; a refusal keeps its own words under its row, a hold its canonical words,
/// and a shadowed row its per-shell truth.
#[test]
fn program_lines_say_version_source_updated_and_latest_known() {
    let packages = packages_state_with_activity(0).projection();
    let lines = packages_program_lines(&packages, SettingsWidth::Wide);
    let text = |key: &str| {
        lines
            .iter()
            .filter(|l| l.key == key || l.key.starts_with(&format!("{key}/")))
            .map(|l| l.text.clone())
            .collect::<Vec<_>>()
            .join(" | ")
    };
    let codex = text("packages/programs/codex");
    assert!(
        codex.contains("error: codex 0.157.0 refused: digest mismatch"),
        "a refusal's own words stay on the row: {codex}"
    );
    assert!(codex.contains("0.157.0"), "the latest known: {codex}");
    let nn_line = lines
        .iter()
        .find(|line| line.key == "packages/programs/nn")
        .unwrap();
    assert!(
        nn_line
            .state
            .as_deref()
            .is_some_and(|state| state.starts_with("held: ")),
        "a held row keeps its canonical words as its accessible value: {nn_line:?}"
    );
    for line in &lines {
        assert!(
            !line.text.contains("T00:") && !line.text.ends_with('Z'),
            "no raw UTC on a row: {}",
            line.text
        );
    }
    // A shadowed row's state is said after the facts.
    let shadowed = packages_state_with_program_state(&atpkg::state::shadowed(
        1971,
        std::path::Path::new("/opt/homebrew/bin/ay"),
    ))
    .projection();
    let line = &packages_program_lines(&shadowed, SettingsWidth::Wide)[0];
    assert!(line.text.contains("/opt/homebrew/bin/ay"), "{}", line.text);
    assert!(
        line.state
            .as_deref()
            .is_some_and(|state| state.contains("SHADOWED")),
        "the canonical line is the row's accessible value: {line:?}"
    );
}

/// A row's words are plain and its state canonical: the page paints `ay · build 1971 ·
/// up to date`, and the row's semantic node carries atpkg's own line after the words.
#[test]
fn a_program_rows_accessible_value_is_atpkgs_own_state() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(0), 2));
    let seen = packages_page_semantics(&mut runtime, instance, view, &view_cx());
    let label = |key: &str| {
        seen.iter()
            .find(|(k, _)| k == key)
            .map(|(_, l)| l.clone())
            .unwrap_or_else(|| panic!("{key} on the page"))
    };
    let ay = label("packages/programs/ay");
    assert!(
        ay.ends_with(&format!("\n{}", atpkg::state::managed(1971, 44))),
        "{ay}"
    );
    // The short-landscape list, where the Programs card splits between its
    // rows, says the same on the row's own screen.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(0), 2));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    let cx = view_cx_at(568.0, 320.0);
    let mut value = None;
    each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
        if let Some(node) = compiled.semantic(&UiKey::new("packages/programs/ay")) {
            value.get_or_insert_with(|| node.label.clone());
        }
    });
    let value = value.expect("the short-landscape list reaches the ay row");
    assert!(
        value.ends_with(&format!("\n{}", atpkg::state::managed(1971, 44))),
        "{value}"
    );
}

/// WHICH LINES ARE TRANSIENT (xa-13): a completion with no control on its line —
/// the drafts' "Discarded …" and "No unsaved Settings drafts.", a copy, an opened
/// project site — runs the status clock on any page; the discard question, a config
/// patch's result with its Undo and an in-flight "Opening aterm.toml…" stand. And a
/// line that replaced a transient one is never cleared by that one's clock.
#[test]
fn a_completion_line_is_transient_and_a_line_with_an_answer_stands() {
    let (mut runtime, instance, view) = setup();
    let act = |runtime: &mut NativeRuntime, id: &str| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap()
    };
    let line = |runtime: &NativeRuntime| -> (Option<String>, Option<bool>) {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        (state.feedback.clone(), state.status_clock())
    };
    // No drafts: the completion is transient.
    act(&mut runtime, "settings/drafts/discard-all");
    let (said, clock) = line(&runtime);
    assert_eq!(said.as_deref(), Some("No unsaved Settings drafts."));
    assert_eq!(clock, Some(false), "a completion runs the clock");
    // The next action clears it; opening aterm.toml stands while in flight.
    act(&mut runtime, "settings/manual/open");
    let (said, clock) = line(&runtime);
    assert!(
        said.as_deref()
            .is_some_and(|line| line.starts_with("Opening")),
        "{said:?}"
    );
    assert_eq!(clock, None, "an operation in flight stands");
    // A line that replaced a transient one is never cleared by its clock.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.show_transient_status_for_test("Copied");
        state.feedback = Some("Font size set to 14 px".to_string());
        assert_eq!(state.status_clock(), None, "441 (q): the new line stands");
    }
    // A completion is transient where it SETS the line, and only there: one this
    // view no longer waits for (already finished) leaves a standing line standing.
    let copied = act(&mut runtime, "about/copy-build-info");
    let operation = copied
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Clipboard { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("the copy asks the clipboard");
    let finish = |runtime: &mut NativeRuntime| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ClipboardFinished {
                    operation,
                    outcome: ClipboardOutcome::Copied,
                },
            )
            .unwrap();
    };
    finish(&mut runtime);
    let (said, clock) = line(&runtime);
    assert_eq!(said.as_deref(), Some("Build information copied"));
    assert_eq!(clock, Some(false), "the copy's outcome runs the clock");
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.feedback = Some("Font size set to 14 px \u{b7} Undo".to_string());
    }
    finish(&mut runtime);
    let (said, clock) = line(&runtime);
    assert_eq!(said.as_deref(), Some("Font size set to 14 px \u{b7} Undo"));
    assert_eq!(
        clock, None,
        "a completion this view did not wait for never times out the line it finds"
    );
}

/// THE ACTIVITY CARD LISTS THE LOG AS STOPS OF THE PAGE (Phase 4; s-25): the package
/// log's newest events on the page with relative times — trouble painted as such —
/// every line a stop of the page's one scrolling list, and "Open Log", which asks the
/// host to open the file (NSWorkspace; no shell, no Terminal). There is no pager of its
/// own: its last page shrank the card, jumped the page 128pt under the reader and left
/// focus on a disabled Older. A full tail says Open Log has the rest; an empty log says
/// so and offers nothing to open.
#[test]
fn the_activity_card_lists_the_log_as_stops_of_the_page() {
    let act = |runtime: &mut NativeRuntime,
               instance: crate::native_app::AppInstanceId,
               view: crate::native_app::ViewId,
               id: &str| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap()
    };
    for cx in [
        view_cx(),
        view_cx_at(1_074.0, 684.0),
        view_cx_at(738.0, 420.0),
    ] {
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(packages_state_with_activity(20), 2));
        let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
        let at = format!("{}x{}", cx.viewport.width, cx.viewport.height);
        for event in 0..20 {
            let key = format!("packages/activity/{event}");
            assert!(
                seen.iter().any(|(k, _)| *k == key),
                "{at}: {key} is reached"
            );
        }
        let label = |key: &str| {
            seen.iter()
                .find(|(k, _)| k == key)
                .map(|(_, l)| l.clone())
                .unwrap_or_else(|| panic!("{key} on the page"))
        };
        assert!(
            label("packages/activity/2").contains("codex 0.157.0 refused: digest mismatch"),
            "{}",
            label("packages/activity/2")
        );
        for gone in ["pager", "newer", "older", "range", "more"] {
            let key = format!("packages/activity/{gone}");
            assert!(!seen.iter().any(|(k, _)| *k == key), "{at}: no {key}");
        }
        assert!(seen.iter().any(|(k, _)| k == "packages/activity/open-log"));
        // Geometry is the scroll's alone: back at the top after walking every
        // screen, the cards above Activity stand where they stood.
        let top = |runtime: &mut NativeRuntime| {
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = 0;
                state.page_reveal = None;
            }
            compile_settings_view(runtime, instance, view, &cx)
                .paint
                .iter()
                .find(|node| node.key.as_str() == "packages/hero")
                .map(|node| node.rect)
        };
        let before = top(&mut runtime);
        let _ = packages_page_semantics(&mut runtime, instance, view, &cx);
        assert_eq!(
            top(&mut runtime),
            before,
            "{at}: the page never moves by itself"
        );

        let opened = act(&mut runtime, instance, view, "packages/activity/open-log");
        let asked = opened
            .effects
            .iter()
            .any(|e| matches!(e, AppEffect::OpenPackagesLog));
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        assert_eq!(
            asked,
            cfg!(target_os = "macos"),
            "only macOS opens the file"
        );
        assert!(state.feedback.is_some());
    }

    // A full tail: the card says the log has more, and Open Log is where.
    let cx = view_cx();
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(
        packages_state_with_activity(atpkg::packages_log::ACTIVITY_EVENTS),
        2
    ));
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(
        seen.iter()
            .any(|(k, l)| k == "packages/activity/more" && l.contains("Open Log")),
        "a full tail names the rest"
    );

    // Nothing recorded: the card says so, and Open Log is off.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(0), 2));
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(seen.iter().any(|(k, _)| k == "packages/activity/empty"));
    let opened = act(&mut runtime, instance, view, "packages/activity/open-log");
    assert!(
        !opened
            .effects
            .iter()
            .any(|e| matches!(e, AppEffect::OpenPackagesLog))
    );
}

/// THE RELEASE NOTES ARE ONE CARD, READ ROW BY ROW (s-25): one card headed "RELEASE
/// NOTES", no "/continued-" cards and no " OF " headings, every paragraph reached
/// as a stop, and the last screen ends at the card's last row, no room-tall card
/// around a few lines.
#[test]
fn release_notes_are_one_card_scrolled_row_by_row() {
    let mut status = update_status(true);
    status.changelog = Some(
        (0..80)
            .map(|index| format!("- Change {index}: a release note line"))
            .collect::<Vec<_>>()
            .join("\n"),
    );
    for (width, height) in [(1_224.0, 722.0), (738.0, 420.0)] {
        let pages = update_route_pages(
            UpdateState::from_status(1, "0.1.0", Some(&status), false),
            width,
            height,
        );
        let mut said = BTreeSet::new();
        for page in &pages {
            for node in &page.paint {
                let key = node.key.as_str();
                assert!(!key.contains("/continued-"), "{width}x{height}: {key}");
                if let UiContent::Text(text) = &node.content
                    && key.starts_with("updates/release-notes-heading")
                {
                    assert_eq!(text.text, "RELEASE NOTES", "{width}x{height}");
                }
                // Reached = live: what the room shows is read out, and a row
                // painted only in the strip under it is not. (A kept caption's
                // rows on the last screen are live under a cut-on-purpose
                // `peek` wrapper, so the flag cannot tell.)
                if let UiContent::RichText(spec) = &node.content
                    && key.starts_with("updates/release-notes")
                    && page.semantic(&node.key).is_some()
                {
                    said.insert(spec.semantic_text.clone());
                }
            }
            let cards = page
                .paint
                .iter()
                .filter(|node| node.key.as_str() == "updates/release-notes-card")
                .count();
            assert!(cards <= 1, "{width}x{height}: one notes card");
        }
        for index in 0..80 {
            let line = format!("Change {index}: a release note line");
            assert!(
                said.iter().any(|text| text.contains(&line)),
                "{width}x{height}: {line:?} is reached"
            );
        }
        let last = pages.last().expect("a last screen");
        let card = last
            .paint
            .iter()
            .find(|node| node.key.as_str() == "updates/release-notes-card")
            .expect("the last screen holds the notes");
        let bottom = last
            .paint
            .iter()
            .filter(|node| node.key.as_str().starts_with("updates/release-notes/"))
            .map(|node| node.rect.bottom())
            .fold(0.0_f32, f32::max);
        assert!(
            card.rect.bottom() - bottom <= 40.0,
            "{width}x{height}: no blank band under the last row ({} vs {bottom})",
            card.rect.bottom()
        );
    }
}

/// Settings ▸ Software Update links to its record — Settings ▸ Messages with the
/// update chip down — and the link is whole on the page that shows it. (Packages'
/// Activity is that page's own log, ruling 41: it carries no second log link.)
#[test]
fn software_update_links_to_its_messages() {
    let key = "updates/messages";
    let (mut runtime, instance, view) = setup();
    for (width, height) in [
        (1_200.0, 820.0),
        (864.0, 518.0),
        (849.0, 513.0),
        (320.0, 568.0),
    ] {
        let cx = view_cx_at(width, height);
        let mut found = false;
        for page in 0..200 {
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::SoftwareUpdate);
                state.page_scroll = page;
            }
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            if let Some(hit) = compiled.hits.iter().find(|hit| hit.key.as_str() == key) {
                assert_eq!(hit.action, ActionId::new(MESSAGES_SHOW_UPDATE));
                assert!(
                    hit.rect.bottom() <= cx.viewport.bottom() + 0.01,
                    "{key} at {width}×{height} is below the page"
                );
                let clipped = compiled.paint_audit_lines().into_iter().any(|line| {
                    line.contains(&format!("key=\"{key}\""))
                        && (line.contains("overflow=true") || line.contains("clip-truncated=true"))
                });
                assert!(!clipped, "{key} at {width}×{height} is clipped");
                found = true;
                break;
            }
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                unreachable!();
            };
            if state
                .result_page_limit
                .get()
                .is_some_and(|limit| page >= limit)
            {
                break;
            }
        }
        assert!(
            found,
            "Software Update at {width}×{height} links to its messages"
        );
    }
}

/// Text & Fonts' display-face switches end where the page's other controls
/// end (before Reset's place, which every row keeps), and each face's name
/// sits on its switch's centre line.
#[test]
fn display_face_switches_line_up_with_the_pages_controls() {
    for (width, height) in [(738.0, 418.0), (1_074.0, 684.0)] {
        let (mut runtime, instance, view) = setup();
        let cx = view_cx_at(width, height);
        let mut font_right = None;
        let mut face = None;
        for page in 0..24 {
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::TextFonts);
                state.page_scroll = page;
            }
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let rect = |key: &str| {
                compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == key && !node.peek)
                    .map(|node| node.rect)
            };
            if let Some(rect) = rect("settings/control/font_family") {
                font_right.get_or_insert(rect.right());
            }
            if let (Some(switch), Some(label)) = (
                rect("settings/display-face/chunky"),
                rect("settings/display-face/label/chunky"),
            ) {
                face.get_or_insert((switch, label));
            }
            if font_right.is_some() && face.is_some() {
                break;
            }
        }
        let font_right = font_right.expect("the font family control");
        let (switch, label) = face.expect("the Chunky face row");
        assert!(
            (switch.right() - font_right).abs() < 0.5,
            "{width}x{height}: face switch ends at {}, font family at {font_right}",
            switch.right()
        );
        let centre = |rect: LogicalRect| rect.y + rect.height / 2.0;
        assert!(
            (centre(switch) - centre(label)).abs() < 0.5,
            "{width}x{height}: name {label:?} centred on its switch {switch:?}"
        );
    }
}

/// ONE RULE DECIDES WHETHER A COMPACT ROW FITS ON ONE LINE
/// ([`one_line_label_measure`]): a card's own switch rows (the display faces,
/// Top's cards, the update and consent cards, through [`compact_row_inline`])
/// and the page's setting rows ([`compact_inline_control_width`]) go one-line
/// at the same column width, at every text size, so a face's switch ends
/// where Thicken strokes' does. On the old rules (a 180pt label floor against
/// 170pt) a 10pt band of columns put the faces' switches 84pt right of the
/// page's.
#[test]
fn one_line_compact_rows_share_one_fit_rule() {
    at_each_text_scale(
        &[0.85, 1.0, 1.15, 1.25, 1.5, 2.0],
        "one-line fit rule",
        |scale| {
            let mut width = 300.0_f32;
            while width <= 520.0 {
                assert_eq!(
                    compact_row_inline(&EditKind::Bool, width, true),
                    compact_inline_control_width(&EditKind::Bool, width).is_some(),
                    "{scale}x at a {width}pt column"
                );
                width += 0.5;
            }
        },
    );
    // The band the two old rules split on, at 59 columns (437pt), between
    // them, and at 80x24.
    for (width, height) in [
        (374.0, 900.0),
        (437.0, 900.0),
        (444.0, 900.0),
        (584.0, 900.0),
    ] {
        let (mut runtime, instance, view) = setup();
        let cx = view_cx_at(width, height);
        // Thicken strokes is a Text & Fonts row only where it actuates (macOS,
        // `row_available_here`); elsewhere Synthetic styles is the page's switch.
        let row_switch = if row_available_here(
            prefs::EDIT_FONT_THICKEN,
            SettingsAvailability::runtime(true),
        ) {
            prefs::EDIT_FONT_THICKEN
        } else {
            prefs::EDIT_FONT_SYNTHETIC_STYLE
        };
        let (mut thicken, mut face) = (None, None);
        for page in 0..40 {
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::TextFonts);
                state.page_scroll = page;
            }
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let rect = |key: &str| {
                compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == key && !node.peek)
                    .map(|node| node.rect)
            };
            thicken = thicken.or(rect(&format!("settings/control/{row_switch}")));
            face = face.or(rect("settings/display-face/chunky"));
            if thicken.is_some() && face.is_some() {
                break;
            }
        }
        let thicken = thicken.unwrap_or_else(|| panic!("{row_switch}'s switch"));
        let face = face.expect("the Chunky face's switch");
        assert!(
            (face.right() - thicken.right()).abs() < 0.5,
            "{width}: face switch ends at {}, {row_switch}'s at {}",
            face.right(),
            thicken.right()
        );
    }
}

/// At 80x24 the Playful effects card keeps its note on the screen that shows
/// its switches: the one place that says Sparkle words means swear words and
/// Keyword kitties a cat. The note rides beside the title when the card would
/// otherwise drop it for room.
#[test]
fn compact_top_settings_keeps_the_playful_effects_note() {
    let (mut runtime, instance, view) = setup();
    let cx = view_cx_at(584.0, 348.0);
    let mut shown = false;
    for page in 0..12 {
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Home);
            state.page_scroll = page;
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let painted = |key: &str| {
            compiled
                .paint
                .iter()
                .any(|node| node.key.as_str() == key && !node.peek)
        };
        if !painted(&format!("settings/control/{SPARKLE_WORDS_KEY}")) {
            continue;
        }
        shown = true;
        let note = compiled
            .paint
            .iter()
            .filter(|node| !node.peek)
            .filter_map(|node| match &node.content {
                UiContent::Text(spec) => Some(spec.text.as_str()),
                _ => None,
            })
            .find(|text| text.contains("Swear words"));
        assert!(
            note.is_some(),
            "page {page}: no note says what Sparkle words does"
        );
        assert!(
            painted(&format!("settings/control/{KEYWORD_KITTIES_KEY}")),
            "page {page}: the note and both toy switches share a screen"
        );
        for line in compiled.paint_audit_lines() {
            if line.contains("settings/top/playful-effects") {
                assert!(
                    !line.contains("overflow=true") && !line.contains("clip-truncated=true"),
                    "{line}"
                );
            }
        }
    }
    assert!(shown, "the Playful effects switches show on some screen");
}

/// At the shipped 102x29 window (738x420) the status card holds its action
/// and the Settings ▸ Messages link side by side: the card with them fits the
/// list's room, so neither is split out to a stop of its own.
#[test]
fn software_update_keeps_its_buttons_in_the_status_card_at_the_default_window() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(9), 2));
    let cx = view_cx_at(738.0, 420.0);
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::SoftwareUpdate);
    }
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let rect = |key: &str| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .map(|node| node.rect)
            .unwrap_or_else(|| panic!("{key} is on the first screen"))
    };
    let hero = rect("updates/hero");
    let action = rect("updates/install-now");
    let link = rect("updates/messages");
    for (key, inner) in [("updates/install-now", action), ("updates/messages", link)] {
        assert!(
            inner.x >= hero.x
                && inner.y >= hero.y
                && inner.right() <= hero.right() + 0.01
                && inner.bottom() <= hero.bottom() + 0.01,
            "{key} {inner:?} lies inside the status card {hero:?}"
        );
    }
    assert!(
        (action.y - link.y).abs() < 0.5,
        "one row: {action:?} {link:?}"
    );
}

/// The update switches' names as the registry holds them: the card, Search, Modified
/// and every accessible name say these and nothing else.
fn update_switch_registry_names() -> [&'static str; 2] {
    let names = [prefs::EDIT_UPDATE_ENABLED, "update.auto_apply"].map(|key| {
        prefs::NESTED_LEAVES
            .iter()
            .find(|leaf| leaf.key == key)
            .map(|leaf| leaf.label)
            .expect("both update switches are registry rows")
    });
    // NEGATIVE CONTROL: a page-side short form the registry does not hold is not
    // contained in the accessible name, which is what the card used to paint.
    assert!(!format!("{} \u{b7} note", names[0]).starts_with("Check for updates \u{b7}"));
    names
}

/// THE SOFTWARE UPDATE CARD CARRIES BOTH `[update]` SWITCHES (2026-09-23): "Check for
/// updates automatically" (`[update] enabled`, until now only on Terminal ▸ Updates)
/// above "Install updates automatically" (`auto_apply`), each the registry's own
/// control — so the check switch's semantic label carries the reader's timing
/// ("Applies next launch": `aterm_update_core::settings` reads the key once per
/// process) and a press writes the key the updater reads. Each switch paints its one
/// registry name at every width, its accessible name starts with those words and Reset
/// is named after them (label in name), and no width ellipsizes either label. The
/// `linux-` rows project an enrolled
/// Linux copy (`UpdateProjection::linux_host`) — the page a shipping Linux build
/// shows, both switches live — so that card is checked on every host, not only on a
/// Linux build, where the plain rows render the no-updater page (2026-09-24 review).
#[test]
fn the_update_card_carries_both_switches_and_their_labels_fit() {
    let (mut runtime, instance, view) = setup_with_update(UpdateState::from_status(
        1,
        "0.1.0",
        Some(&update_status(false)),
        false,
    ));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let checks = UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED));
    let install = UiKey::new("settings/control/update.auto_apply");
    let mut revision = 1;
    // Each window holds the whole card on one screen (the medium page lists it
    // under the status card); the written phase below pages the shipped sizes.
    for (variant, cx, running, linux) in [
        ("wide", view_cx_at(1_200.0, 820.0), true, false),
        ("medium", view_cx_at(849.0, 760.0), true, false),
        ("medium-off", view_cx_at(849.0, 760.0), false, false),
        ("compact", view_cx_at(600.0, 820.0), true, false),
        ("linux-wide", view_cx_at(1_200.0, 820.0), true, true),
        ("linux-medium", view_cx_at(849.0, 760.0), true, true),
        ("linux-medium-off", view_cx_at(849.0, 760.0), false, true),
        ("linux-compact", view_cx_at(600.0, 820.0), true, true),
    ] {
        revision += 1;
        let mut status = update_status(false);
        status.linux = linux.then_some(aterm_update::LinuxUpdateStatus {
            installed_build: 1,
            installed_version: String::new(),
            staged_build: None,
            staged_version: None,
            staged_commit: None,
            trial_phase: None,
            trial_starts: 0,
            trial_healthy: false,
            refused_newer: false,
        });
        assert!(
            runtime.replace_settings_update(
                UpdateState::from_status(1, "0.1.0", Some(&status), false)
                    .with_automatic_checks(running, running),
                revision,
            )
        );
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = 0;
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            compiled.semantic(&UiKey::new("updates/headline")).is_some(),
            "{variant}: the headline is on the first page"
        );
        // The switches' card: beside the status where it fits, else listed under it.
        let compiled = screen_showing(&mut runtime, instance, view, &cx, "updates/automatic")
            .unwrap_or_else(|| panic!("{variant}: the card is listed"));
        let card = compiled
            .semantic(&UiKey::new("updates/automatic"))
            .expect("the card's screen")
            .rect;
        let mut tops = Vec::new();
        let mut painted_pair = Vec::new();
        for key in [&checks, &install] {
            let switch = compiled
                .semantic(key)
                .unwrap_or_else(|| panic!("{variant}: {key:?} is on the card"));
            assert!(
                switch.rect.y >= card.y && switch.rect.bottom() <= card.bottom() + 0.01,
                "{variant}: {key:?} inside the card"
            );
            // The updater runs on the platform (`aterm_update::enabled`: macOS and
            // Linux, whose copy reads both keys before its own status is read),
            // not by what a status says about this copy.
            assert_eq!(
                switch.state.expect("a control carries state").enabled,
                linux || aterm_update::enabled(),
                "{variant}: live where the updater runs, disabled elsewhere"
            );
            tops.push(switch.rect.y);
            let field_key = key.as_str().trim_start_matches("settings/control/");
            let painted = painted_row_label(&compiled, field_key)
                .unwrap_or_else(|| panic!("{variant}: {field_key}'s label is painted"));
            // LABEL IN NAME: the switch's accessible name starts with the words it
            // paints, and Reset is named after them.
            assert!(
                switch.label.starts_with(painted.as_str()),
                "{variant}: {:?} is not named by its painted words {:?}",
                switch.label,
                painted
            );
            painted_pair.push(painted);
        }
        assert!(tops[0] < tops[1], "{variant}: checking comes first");
        assert_eq!(
            painted_pair,
            update_switch_registry_names(),
            "{variant}: the registry's one name at every width"
        );
        let title = compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == "updates/automatic/title");
        assert!(
            title.is_some(),
            "{variant}: the card's caption says what the two switches have in common"
        );
        let overflowing = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .filter(|line| {
                line.contains("paint-text key=\"updates/")
                    || line.contains("paint-text key=\"settings/label/update.")
            })
            .collect::<Vec<_>>();
        assert!(
            overflowing.is_empty(),
            "{variant}: the card's copy overflows its slot:\n{}",
            overflowing.join("\n")
        );
    }
    // Written (one switch or both, the state anyone who turned one off is in):
    // each switch keeps the same words, says Changed, is never cut off at any
    // window size, and the two switches stay in one column (the unwritten one
    // keeps an empty slot where Reset would be). Negative control: the
    // unwritten switch says no Changed.
    revision += 1;
    assert!(
        runtime.replace_settings_update(
            UpdateState::from_status(1, "0.1.0", Some(&update_status(false)), false)
                .with_automatic_checks(true, true),
            revision,
        )
    );
    for (source, written) in [
        (
            "[update]\nenabled = false\nauto_apply = false\n",
            [true, true],
        ),
        ("[update]\nauto_apply = false\n", [false, true]),
        ("[update]\nenabled = false\n", [true, false]),
    ] {
        replace_settings_source(&mut runtime, view, source.to_string());
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        for (size, cx) in [
            ("150x48", view_cx_at(1_074.0, 684.0)),
            ("167x36", view_cx_at(1_193.0, 516.0)),
            ("120x36", view_cx_at(864.0, 516.0)),
            ("220x60", view_cx_at(1_564.0, 854.0)),
            ("102x29", view_cx_at(738.0, 420.0)),
            ("80x24", view_cx_at(584.0, 350.0)),
        ] {
            let mut lefts = BTreeMap::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
                for ((key, wording), written) in [&checks, &install]
                    .into_iter()
                    .zip(update_switch_registry_names())
                    .zip(written)
                {
                    let Some(switch) = compiled.semantic(key) else {
                        continue;
                    };
                    lefts.insert(key.as_str().to_string(), switch.rect.x);
                    let field_key = key.as_str().trim_start_matches("settings/control/");
                    let painted = painted_row_label(compiled, field_key);
                    let want = if written {
                        format!("{wording}{FACT_SEPARATOR}{CHANGED_WORD}")
                    } else {
                        wording.to_string()
                    };
                    assert_eq!(painted.as_deref(), Some(want.as_str()), "{source} {size}");
                    assert!(
                        switch.label.starts_with(wording),
                        "{source} {size}: {:?} starts with {wording:?}",
                        switch.label
                    );
                    if written {
                        let reset = compiled
                            .semantic(&UiKey::new(format!("settings/reset/{field_key}")))
                            .map(|node| node.label.clone());
                        assert_eq!(
                            reset.as_deref(),
                            Some(format!("Reset {wording}").as_str()),
                            "{source} {size}"
                        );
                    }
                }
                let cut = compiled
                    .paint_audit_lines()
                    .into_iter()
                    .filter(|line| {
                        line.contains("overflow=true")
                            || line.contains("clip-truncated=true")
                            || line.contains("clipped=true")
                    })
                    .filter(|line| {
                        line.contains("key=\"settings/label/update.")
                            || line.contains("key=\"settings/reset/update.")
                            || line.contains("key=\"settings/control/update.")
                    })
                    .collect::<Vec<_>>();
                assert!(cut.is_empty(), "{source} {size}:\n{}", cut.join("\n"));
            });
            assert_eq!(lefts.len(), 2, "{source} {size}: both switches are listed");
            let mut x = lefts.values();
            assert_eq!(
                x.next(),
                x.next(),
                "{source} {size}: the switches share one column"
            );
        }
    }
    replace_settings_source(&mut runtime, view, String::new());
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    // A press writes `[update] enabled` alone — the key the updater reads.
    let off = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_UPDATE_ENABLED)),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let written: Vec<(String, Option<String>)> = emitted_config_patch(&off)
        .edits
        .iter()
        .map(|edit| (edit.key.clone(), edit.value.clone()))
        .collect();
    assert_eq!(
        written,
        vec![(prefs::EDIT_UPDATE_ENABLED.to_string(), Some("false".into()))]
    );
}

/// THE COMPACT UPDATE PAGE'S FORM IS MEASURED (s-1, s-3): the page takes the form
/// whose first screen shows the whole status — headline, and the detail sentence
/// with its cause or remedy — with the most switches beside it, the full card on a
/// tie. The shipped default (102x29) used to show the full card and one switch, a
/// 100x34 window cut the install switch through its label, and 80x24 took the
/// two-column summary by the window's shape and painted only "Can't update" /
/// "Needs an installed copy", never the remedy. Now each shows the whole status and
/// every switch the window can hold with it, whole and live: wherever the summary is
/// drawn the detail sentence it shortens is painted on its card, on the FIRST
/// screen, never traded for a switch. 80x24, its toolbar naming the page, seats the
/// check switch beside the summary, and so does 584x330, whose page gives its
/// insets to the list where its first screen would not reach a switch
/// ([`PageChrome`]). NEGATIVE CONTROLS: a window shorter still (584x310), where
/// neither form seats a switch beside the whole status under any chrome, keeps the
/// full card with its whole headline; a window where the full card already holds
/// both switches keeps it.
#[test]
fn a_compact_update_page_shows_its_status_and_both_switches_on_its_first_screen() {
    let checks = UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED));
    let install = UiKey::new("settings/control/update.auto_apply");
    let cannot = || {
        let mut status = update_status(false);
        status.installable = false;
        status
    };
    for (name, status) in [
        ("can't update", cannot()),
        ("installed", update_status(false)),
    ] {
        let update = || UpdateState::from_status(1, "0.1.0", Some(&status), false);
        let detail = update_status_detail(&update().projection(), SettingsWidth::Compact);
        for (width, height, switches) in [
            (738.0, 420.0, 2),
            (724.0, 500.0, 2),
            (724.0, 474.0, 2),
            (584.0, 350.0, 1),
            (584.0, 330.0, 1),
            (584.0, 310.0, 0),
        ] {
            let context = format!("{name} {width}x{height}");
            let pages = update_route_pages(update(), width, height);
            let first = &pages[0];
            let list = first
                .paint
                .iter()
                .find(|node| node.key.as_str() == "updates/list")
                .map(|node| node.clip)
                .unwrap_or_else(|| panic!("{context}: the page's list"));
            assert!(
                first.semantic(&UiKey::new("updates/hero")).is_some(),
                "{context}: the status is on the first screen"
            );
            for key in [&checks, &install].into_iter().take(switches) {
                assert!(
                    first.semantic(key).is_some(),
                    "{context}: {} is live on the first screen",
                    key.as_str()
                );
                let painted = first
                    .paint
                    .iter()
                    .find(|node| &node.key == key)
                    .unwrap_or_else(|| panic!("{context}: {} is painted", key.as_str()));
                assert!(
                    painted.clip.height >= painted.rect.height - 0.5
                        && painted.rect.y >= list.y - 0.5
                        && painted.rect.bottom() <= list.bottom() + 0.5,
                    "{context}: {} {:?} is whole in the list {list:?}",
                    key.as_str(),
                    painted.rect
                );
            }
            let summary = first
                .paint
                .iter()
                .any(|node| node.key.as_str() == "updates/summary/state");
            // The FIRST screen's words: the remedy is on the screen the status is.
            let words = painted_texts(first).join(" ");
            let words_in_order = words.split_whitespace().collect::<Vec<_>>().join(" ");
            assert!(
                words_in_order.contains(&detail),
                "{context}: the detail {detail:?} is painted with the status: {words}"
            );
            if summary {
                assert!(
                    switches > 0,
                    "{context}: the summary is drawn only where it seats a switch the \
                     full card does not"
                );
            } else {
                assert!(
                    words.contains(&update().projection().headline),
                    "{context}: the full card paints its whole headline: {words}"
                );
            }
            // NEGATIVE CONTROL (s-3): the full card fits there, and neither form
            // seats a switch beside the whole status, so the headline is whole.
            if (width, height) == (584.0, 310.0) {
                assert!(
                    !summary,
                    "{context}: the full card, not the summary, where both seat no switch"
                );
            }
        }
        // NEGATIVE CONTROL: a window whose full card holds both switches keeps it.
        let roomy = &update_route_pages(update(), 724.0, 640.0)[0];
        assert!(
            roomy.semantic(&UiKey::new("updates/headline")).is_some()
                && roomy.semantic(&checks).is_some()
                && roomy.semantic(&install).is_some(),
            "{name} 724x640: the full card and both switches"
        );
    }
}

/// WHEREVER THE SUMMARY IS DRAWN, ITS DETAIL IS PAINTED WHOLE (s-3): the summary's
/// second column says only "Needs an installed copy", "Checks failing" or "Channel
/// unreadable"; the cause and the remedy are on the same card, every word painted
/// on the screen the summary is on and said once. At the platform maximum Dynamic
/// Type too.
#[test]
fn short_landscape_update_paints_the_detail_it_summarises() {
    at_each_text_scale(&[1.0, 2.0], "compact update detail", |scale| {
        let mut cannot = update_status(false);
        cannot.installable = false;
        let mut failing = update_status(false);
        failing.failing_checks = aterm_update::PERSISTENT_AFTER;
        failing.failing_persistent = true;
        failing.failing_kind = "network".into();
        let mut stranded = update_status(false);
        stranded.channel_unreadable = true;
        let mut drawn = 0;
        for (name, status) in [
            ("can't update", cannot),
            ("failing", failing),
            ("channel unreadable", stranded),
        ] {
            let update = || UpdateState::from_status(1, "0.1.0", Some(&status), false);
            let detail = update_status_detail(&update().projection(), SettingsWidth::Compact);
            for (width, height) in [(568.0, 320.0), (584.0, 350.0), (738.0, 420.0)] {
                let context = format!("{name} {width}x{height} at {scale}x");
                let pages = update_route_pages(update(), width, height);
                if !pages[0]
                    .paint
                    .iter()
                    .any(|node| node.key.as_str() == "updates/summary/state")
                {
                    continue;
                }
                drawn += 1;
                let words = painted_texts(&pages[0]).join(" ");
                assert!(
                    detail
                        .split_whitespace()
                        .all(|word| words.split_whitespace().any(|painted| painted == word)),
                    "{context}: every word of {detail:?} is painted: {words}"
                );
                for page in &pages {
                    let said = page
                        .semantics
                        .iter()
                        .filter(|node| node.label.contains(&detail))
                        .count();
                    assert!(said <= 1, "{context}: the detail is said once per screen");
                    assert_zero_top_paint(page, &context);
                }
            }
        }
        assert!(drawn > 0, "at {scale}x some window draws the summary");
    });
}

/// A SHORT PHONE STILL SHOWS A SWITCH ON THE FIRST SCREEN (2026-09-23 review): the
/// status card alone over an empty screen is the friction the page exists to lose.
/// The list lays the automatic-updates card out row by row, so the status and the
/// check switch share the first screen at 600x560 and the caption follows; where only
/// the short summary lets both switches share it with the status, the page takes the
/// summary (s-1). A taller phone shows the whole card at once.
#[test]
fn a_short_compact_page_pairs_the_status_card_with_the_check_switch() {
    let (mut runtime, instance, view) = setup_with_update(UpdateState::from_status(
        1,
        "0.1.0",
        Some(&update_status(false)),
        false,
    ));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let checks = UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED));
    let install = UiKey::new("settings/control/update.auto_apply");
    let page = |runtime: &mut NativeRuntime, cx: &ViewCx<'static>, index: usize| {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.page_scroll = index;
        let compiled = compile_settings_view(runtime, instance, view, cx);
        let overflowing = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .filter(|line| line.contains("paint-text key=\"updates/"))
            .collect::<Vec<_>>();
        assert!(overflowing.is_empty(), "{}", overflowing.join("\n"));
        compiled
    };
    let short = view_cx_at(600.0, 560.0);
    let first = page(&mut runtime, &short, 0);
    assert!(first.semantic(&UiKey::new("updates/hero")).is_some());
    assert!(
        first.semantic(&checks).is_some(),
        "the check switch is on the first screen"
    );
    let mut later = BTreeSet::new();
    each_screen(&mut runtime, instance, view, &short, |compiled, _| {
        for key in [install.as_str(), "updates/automatic/caption"] {
            if compiled.semantic(&UiKey::new(key)).is_some() {
                later.insert(key.to_string());
            }
        }
    });
    assert_eq!(
        later.len(),
        2,
        "the install switch and the caption follow: {later:?}"
    );
    let tall = view_cx_at(600.0, 820.0);
    let whole = page(&mut runtime, &tall, 0);
    assert!(whole.semantic(&checks).is_some() && whole.semantic(&install).is_some());

    // An enrolled Linux copy too, whatever its detail: the Linux facts (and the timing
    // sentence while checks are off) run longer, so the detail paints a line fewer
    // here to keep the check switch on page 1; its whole sentence stays the value.
    let linux = |staged: Option<u64>| aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: staged,
        staged_version: staged.map(|_| "0.2.0".to_string()),
        staged_commit: staged.map(|_| "ab".repeat(20)),
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    };
    let mut revision = 1;
    for (state, staged, running, saved) in [
        ("idle, checks off", None, false, false),
        ("idle, checks on", None, true, true),
        ("idle, checks stop next launch", None, true, false),
        ("downloaded", Some(2), true, true),
    ] {
        let mut status = update_status(false);
        status.linux = Some(linux(staged));
        revision += 1;
        let update = UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved);
        let full_detail = update.projection().detail.expect("the Linux detail");
        assert!(runtime.replace_settings_update(update, revision));
        for face in [LinuxLayoutFace::Host, LinuxLayoutFace::LinuxLadder] {
            let Some(short) = linux_layout_cx(face, 600.0, 560.0) else {
                continue;
            };
            let first = page(&mut runtime, &short, 0);
            assert!(
                first.semantic(&checks).is_some(),
                "{face:?} Linux {state}: the check switch shares the first screen with the status card"
            );
            let detail = first
                .semantic(&UiKey::new("updates/detail"))
                .expect("the detail is on the first screen");
            assert_eq!(
                detail.label, full_detail,
                "{face:?} Linux {state}: the painted lines are bounded, the value is whole"
            );
        }
    }
}

/// One live "Automatic updates" switch: `[packages] enabled` off paints it off, the
/// service line says nothing updates by itself (no "next launch"), and no retired
/// `auto_update` row stands beside it. The install consent keeps its authored value
/// while the switch is off (dormant: no unattended pass installs anything).
#[test]
fn packages_page_shows_one_live_switch_and_the_dormant_install_consent() {
    let service = VersionedConfigService::new(
        "[packages]\nenabled = false\nauto_install = true\n".to_string(),
    )
    .unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    // The lane stands by whatever the switch says, so the loop is up.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_policy(None, false, true, true),
        2,
    ));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let switch = compiled
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_PACKAGES_ENABLED
        )))
        .unwrap();
    assert_eq!(switch.value, SemanticValue::Bool(false));
    assert_eq!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_PACKAGES_AUTO_INSTALL
            )))
            .unwrap()
            .value,
        SemanticValue::Bool(true),
        "the consent keeps its authored value while the switch is off"
    );
}

/// `enabled = true` beside the retired `auto_update = false` holds every update off, so
/// "Automatic updates" reads Off (seeded by `Config::packages_enabled`, the reader the
/// loop's gate shares) on the page and in Search, and the service line names the
/// retired key and the control that clears it. On writes `enabled = true` alone, and
/// `prefs::apply_prefs_edits` (`RETIRED_PACKAGES_SPELLINGS`) removes the retired key
/// with it. Off writes `enabled = false` alone.
#[test]
fn automatic_updates_reads_and_restores_auto_update() {
    let mut service = VersionedConfigService::new(
        "[packages]\nenabled = true\nauto_update = false\n".to_string(),
    )
    .unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let config: Config =
        aterm_toml::from_str("[packages]\nenabled = true\nauto_update = false\n").unwrap();
    assert!(
        runtime.replace_settings_packages(
            live_packages_state_with_policy(None, config.packages_enabled(), true, true)
                .with_retired_switch_note(config.packages_retired_switch_note()),
            2,
        )
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    // The switches' card is on whichever page the wide page packs it onto.
    let cx = view_cx();
    let control = UiKey::new(format!("settings/control/{}", prefs::EDIT_PACKAGES_ENABLED));
    let compiled = (0..4)
        .map(|page| {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = page;
            runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap()
        })
        .find(|compiled| compiled.semantic(&control).is_some())
        .expect("the Automatic updates switch is on a page");
    assert_eq!(
        compiled.semantic(&control).unwrap().value,
        SemanticValue::Bool(false),
        "nothing updates, so the switch is off"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("packages/retired-note"))
            .map(|note| note.label.clone()),
        config.packages_retired_switch_note(),
        "atpkg's sentence is under the switch it explains"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        assert!(
            !field_bool(state, prefs::EDIT_PACKAGES_ENABLED, true),
            "Search's row reads the same value"
        );
    }
    let on = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_PACKAGES_ENABLED)),
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&on);
    let written: Vec<(String, Option<String>)> = patch
        .edits
        .iter()
        .map(|edit| (edit.key.clone(), edit.value.clone()))
        .collect();
    assert_eq!(
        written,
        vec![(prefs::EDIT_PACKAGES_ENABLED.to_string(), None)],
        "one key touched: the switch, removed since on is its default"
    );
    let (after, _) = apply_real_config_patch(&mut service, &patch);
    assert!(
        !after.text.contains("auto_update"),
        "the writer drops the retired key with it: {:?}",
        after.text
    );
    let reread: Config = aterm_toml::from_str(&after.text).unwrap();
    assert!(reread.packages_enabled(), "on turns updates on");
    assert_eq!(reread.packages_retired_switch_note(), None);

    // Off: `enabled = false` alone, from a machine where it is on.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    let off = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_PACKAGES_ENABLED)),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let written: Vec<(String, Option<String>)> = emitted_config_patch(&off)
        .edits
        .into_iter()
        .map(|edit| (edit.key, edit.value))
        .collect();
    assert_eq!(
        written,
        vec![(
            prefs::EDIT_PACKAGES_ENABLED.to_string(),
            Some("false".into())
        )]
    );
}

/// A retired `[packages]` spelling (`auto_update`, `seed_install`) on Modified is named,
/// read and resettable: its row names the switch it is the retired spelling of and
/// what it does to it, its Reset removes that key alone, Reset All removes it with the
/// rest (Undo writes it back as the Bool atpkg reads), and Search finds each switch by
/// the old name.
#[test]
fn a_retired_packages_spelling_is_named_resettable_and_reset_by_reset_all() {
    let source = "[packages]\nauto_update = false\nseed_install = false\n";
    let mut service = VersionedConfigService::new(source.to_string()).unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    state.navigate(SettingsRoute::Modified);
    let overrides = authored_manual_overrides(state);
    let row = |key: &str| -> ManualOverride {
        overrides
            .iter()
            .find(|entry| entry.key == key)
            .cloned()
            .unwrap_or_else(|| panic!("{key} is listed: {overrides:?}"))
    };
    for key in [
        prefs::RETIRED_PACKAGES_AUTO_UPDATE,
        prefs::RETIRED_PACKAGES_SEED_INSTALL,
    ] {
        let retired = row(key);
        assert!(retired.known, "{key} is not an unknown key: {retired:?}");
        assert_ne!(retired.label, UNKNOWN_KEY_LABEL, "{key}");
    }
    assert!(row(prefs::RETIRED_PACKAGES_AUTO_UPDATE).reset_safe);
    // Search finds each switch by the key a person actually has.
    for (query, key) in [
        ("auto_update", prefs::EDIT_PACKAGES_ENABLED),
        ("auto-update", prefs::EDIT_PACKAGES_ENABLED),
        ("seed_install", prefs::EDIT_PACKAGES_AUTO_INSTALL),
    ] {
        let field = state.field_by_key(key).unwrap();
        assert!(
            field_match_score(field, query, &crate::app_config::ThemeCatalog::default()).is_some(),
            "{query} finds {key}"
        );
    }

    // The row's Reset removes that key alone, CAS on the value shown.
    state.page_scroll = overrides
        .iter()
        .position(|entry| entry.key == prefs::RETIRED_PACKAGES_AUTO_UPDATE)
        .unwrap();
    let cx = view_cx_at(1_080.0, 720.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/modified/manual/reset/{}",
                key_fragment(prefs::RETIRED_PACKAGES_AUTO_UPDATE)
            )))
            .is_some(),
        "a retired spelling has an exact Reset"
    );
    let reset = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: manual_override_reset_action(prefs::RETIRED_PACKAGES_AUTO_UPDATE).unwrap(),
                value: None,
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&reset);
    assert_eq!(patch.edits.len(), 1);
    assert_eq!(patch.edits[0].key, prefs::RETIRED_PACKAGES_AUTO_UPDATE);
    assert_eq!(patch.edits[0].value, None);
    assert_eq!(
        patch.edits[0].expected,
        ExpectedConfigValue::Exact(Some("false".to_string()))
    );
    let (after, _) = apply_real_config_patch(&mut service, &patch);
    assert!(!after.text.contains("auto_update"), "{:?}", after.text);
    assert!(after.text.contains("seed_install"), "that key alone");
    let reread: Config = aterm_toml::from_str(&after.text).unwrap();
    assert!(reread.packages_enabled(), "Automatic updates reads on");

    // Reset All takes the retired spelling with the fields, and Undo writes it back.
    let source = "font_px = 14.0\n[packages]\nauto_update = false\n";
    let mut service = VersionedConfigService::new(source.to_string()).unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    for id in ["settings/reset-all", "settings/reset-all-confirm"] {
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap();
        if id != "settings/reset-all-confirm" {
            continue;
        }
        let patch = emitted_config_patch(&outcome);
        let keys: BTreeSet<&str> = patch.edits.iter().map(|edit| edit.key.as_str()).collect();
        assert_eq!(
            keys,
            BTreeSet::from([prefs::EDIT_FONT_PX, prefs::RETIRED_PACKAGES_AUTO_UPDATE])
        );
        let request = ConfigPatchRequest {
            base_revision: patch.base_revision,
            edits: patch
                .edits
                .iter()
                .map(|edit| ConfigKeyEdit {
                    key: edit.key.clone(),
                    expected: ExpectedValue::Any,
                    value: edit.value.clone(),
                })
                .collect(),
        };
        let ConfigPatchResult::Applied { snapshot, undo } = service.patch(request) else {
            panic!("Reset All applies");
        };
        assert!(
            !snapshot.text.contains("auto_update"),
            "{:?}",
            snapshot.text
        );
        let reset: Config = aterm_toml::from_str(&snapshot.text).unwrap();
        assert!(reset.packages_enabled(), "after Reset All, updates are on");
        let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
            panic!("Undo applies");
        };
        let undone: Config = aterm_toml::from_str(&snapshot.text).unwrap();
        assert!(
            snapshot.text.contains("auto_update = false") && !undone.packages_enabled(),
            "Undo restores the Bool: {:?}",
            snapshot.text
        );
    }
}

/// A retired `auto_update = false`'s way out reads whole at every width: the service
/// line wraps in its column and the note is its own wrapped lines under the switch, so
/// at each layout's narrowest viewport every line fits and every word of the remedy
/// paints; the ordinary Off and On lines keep "Update Now still works" and the last
/// full check; the hero detail carries no note.
#[test]
fn the_retired_switch_note_and_the_service_line_paint_whole_at_every_width() {
    let note = atpkg::config::auto_update_note(false, Some(true));
    let painted = |line: &str| -> String {
        let quoted = line
            .rsplit_once("painted=")
            .map_or("", |(_, painted)| painted);
        quoted
            .strip_prefix('"')
            .and_then(|rest| rest.strip_suffix('"'))
            .unwrap_or(quoted)
            .replace("\\\"", "\"")
    };
    let line_index = |line: &str| -> usize {
        line.split("/line/")
            .nth(1)
            .and_then(|rest| rest.split('"').next())
            .and_then(|n| n.parse().ok())
            .unwrap_or(0)
    };
    for (state_name, master, retired) in [
        ("on", true, false),
        ("off", false, false),
        ("retired", false, true),
    ] {
        for (viewport_width, viewport_height) in [
            (474.0_f32, 658.0_f32),
            (568.0, 900.0),
            (760.0, 820.0),
            (900.0, 820.0),
            (1_040.0, 820.0),
            (1_200.0, 820.0),
        ] {
            let context = format!("{state_name} at {viewport_width}");
            let (mut runtime, instance, view) = setup();
            let mut packages = packages_state_with_activity_policy(2, master);
            if retired {
                packages = packages.with_retired_switch_note(Some(note.clone()));
            }
            assert!(runtime.replace_settings_packages(packages, 2));
            let cx = view_cx_at(viewport_width, viewport_height);
            let mut service = std::collections::BTreeMap::new();
            let mut notes = std::collections::BTreeMap::new();
            let mut audits = Vec::new();
            let mut note_semantic = None;
            for page in 0..40 {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Packages);
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if let Some(detail) = compiled.semantic(&UiKey::new("packages/detail")) {
                    assert!(!detail.label.contains(&note), "{context}: {}", detail.label);
                }
                if let Some(semantic) = compiled.semantic(&UiKey::new("packages/retired-note")) {
                    note_semantic = Some(semantic.label.clone());
                }
                // The next stop peeking in under the screen is not yet shown.
                let peek: std::collections::BTreeSet<&str> = compiled
                    .paint
                    .iter()
                    .filter(|node| node.peek)
                    .map(|node| node.key.as_str())
                    .collect();
                for line in compiled.paint_audit_lines().into_iter().filter(|line| {
                    line.split("key=\"")
                        .nth(1)
                        .and_then(|rest| rest.split('"').next())
                        .is_none_or(|key| !peek.contains(key))
                }) {
                    if line.contains("paint-text key=\"packages/loop-status/value/line/") {
                        service.insert(line_index(&line), painted(&line));
                        audits.push(line);
                    } else if line.contains("paint-text key=\"packages/retired-note/line/") {
                        notes.insert(line_index(&line), painted(&line));
                        audits.push(line);
                    }
                }
                if !service.is_empty() && (!retired || !notes.is_empty()) {
                    break;
                }
            }
            assert!(!service.is_empty(), "{context}: the service line paints");
            assert!(
                audits
                    .iter()
                    .all(|line| line.contains("overflow=false")
                        && line.contains("clip-truncated=false")),
                "{context}: every line fits its box:\n{}",
                audits.join("\n")
            );
            if retired {
                assert_eq!(note_semantic.as_deref(), Some(note.as_str()), "{context}");
                let painted_note = notes.into_values().collect::<Vec<_>>().join(" ");
                assert_eq!(
                    painted_note, note,
                    "{context}: every word of the note paints"
                );
            } else {
                assert!(notes.is_empty() && note_semantic.is_none(), "{context}");
            }
        }
    }
}

/// A long Activity line (a ~700-character refusal) wraps to the page's measure, every
/// line painted as trouble, bounded, the rest in Open Log; the compact page keeps the
/// danger colour and names each line as package activity.
#[test]
fn a_long_activity_line_wraps_and_keeps_its_trouble() {
    use crate::packages_screen::{ActivityLine, MAX_ACTIVITY_LINES};
    let mut packages = packages_state_with_activity(2).projection();
    let long = format!(
        "claude 2.1.281 refused: {} \u{2014} keeping 2.1.280",
        "the platform signer check reported an unexpected team identifier ".repeat(8)
    );
    packages.activity[0] = ActivityLine {
        when: "2 h ago".into(),
        text: long.clone(),
        trouble: true,
    };
    for width in [SettingsWidth::Compact, SettingsWidth::Wide] {
        let rows = packages_activity_rows(&packages, width);
        let first: Vec<&ActivityRow> = rows
            .iter()
            .filter(|r| r.key == "packages/activity/0" || r.key.starts_with("packages/activity/0/"))
            .collect();
        assert!(first.len() > 1, "{width:?}: wrapped, not cut");
        assert!(first.len() <= MAX_ACTIVITY_LINES, "{width:?}: bounded");
        assert!(first[0].text.starts_with("2 h ago"), "{:?}", first[0].text);
        assert!(first.iter().all(|r| r.trouble), "every line is trouble");
        assert!(first.iter().skip(1).all(|r| r.continuation));
        assert!(
            first.iter().all(|r| crate::packages_screen::fits_one_line(
                &r.text,
                packages_reason_wrap_chars(width)
            )),
            "{width:?}: no line meets the ellipsis"
        );
        assert!(
            first.last().unwrap().text.contains("more)"),
            "the bound says what it hid"
        );
        // The next event keeps its own key.
        assert!(
            rows.iter()
                .any(|r| r.key == "packages/activity/1" && !r.continuation)
        );
    }
    let rows = packages_activity_rows(&packages, SettingsWidth::Compact);
    let row = rows[1].clone();
    let (node, _) = packages_activity_row(row.key, &row.text, row.trouble, 24.0, 2_000.0);
    assert!(
        matches!(&node.content, UiContent::Text(t) if t.style == StyleRef::Danger),
        "a continued trouble line keeps the danger colour"
    );
}

/// The palette's "Apply Now" command (`machine/apply`) is offered only on Security,
/// enabled by the same bit as the button under the Universal Control row.
#[cfg(target_os = "macos")]
#[test]
fn the_security_route_offers_the_machine_apply_command_in_the_palette() {
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    let command_named = |runtime: &NativeRuntime, view| {
        runtime
            .commands(instance, view)
            .unwrap()
            .into_iter()
            .find(|command| command.id.as_str() == "machine/apply")
    };
    // Another route: absent, however the machine reads.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account
            )),
        ),
        2,
    ));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    assert!(
        command_named(&runtime, view).is_none(),
        "the command belongs to Security"
    );

    // Security, with something to apply: offered and enabled.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
    }
    let offered = command_named(&runtime, view).expect("Security offers it");
    assert!(offered.enabled, "something is left to apply");

    // Nothing left to apply: still offered, but disabled — the same bit the
    // button reads, so the two doors never disagree.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Disabled,
                HomePosture::Account
            )),
        ),
        3,
    ));
    let settled = command_named(&runtime, view).expect("still offered");
    assert!(!settled.enabled, "nothing to apply ⇒ nothing to press");
}

/// The scroll limit counts every stop the renderer draws, the macOS-access card
/// included, so on a short window the rows after it are reachable: on Security,
/// the Universal Control row and the This Mac status under it.
#[cfg(target_os = "macos")]
#[test]
fn the_short_security_list_reaches_its_last_row_under_the_access_card() {
    use aterm_containment::FdaScope;
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        assert!(state.replace_macos_access(access_fixture(
            FdaState::Denied,
            DrClass::Identity,
            FdaScope::Unknown
        )));
    }
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account
            )),
        ),
        3,
    ));
    let cx = view_cx_at(624.0, 348.0);
    // Scroll with Page Down, not by writing `page_scroll`: the limit is what
    // clamps that reducer, so a test that sets the field directly cannot see a
    // limit that is too small.
    let mut seen: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for page in 0..64 {
        if page > 0 {
            runtime
                .dispatch(instance, view, AppEvent::ScrollPage(1))
                .unwrap();
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        let rows: Vec<String> = compiled
            .semantics
            .iter()
            .filter(|node| {
                node.key.as_str().starts_with("settings/row/") || node.key.as_str() == MACHINE_APPLY
            })
            .map(|node| node.key.as_str().to_string())
            .collect();
        // No early break: the first screens are the access card and carry no
        // control row at all, the shape a limit that skips the card gets wrong.
        seen.extend(rows);
    }
    assert!(
        seen.iter()
            .any(|row| row.contains("machine.universal_control")),
        "scrolling never reached machine.universal_control: {seen:?}"
    );
    assert!(
        seen.contains(MACHINE_APPLY),
        "scrolling never reached the Apply Now under it: {seen:?}"
    );
}

/// A copy with no package tool beside it: the report says so, and the
/// machine read fails for the same reason, as the host's does.
fn missing_tool_packages_state() -> PackagesState {
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    let report = crate::packages_screen::PackagesStatusReport::from_parts(
        false,
        true,
        String::new(),
        None,
        &[],
    );
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(report),
    ));
    let _ = service.replace_machine_state(Err(
        "the package tool is not installed beside aterm".to_string()
    ));
    service.state(true, true, true)
}

/// PACKAGE ADMISSION IS KNOWN BEFORE THE STATUS READ (s-17). Whether this copy can
/// manage packages at all — an `atpkg` beside it, a build with its root key — is
/// noted before the first frame, and the slow status read learns nothing new about
/// it; so a fact aterm.toml alone decides ("Waits until Keep ALab tools up to date is
/// on") is drawn on the first frame and the read changes none of the admission-drawn
/// text, for a copy with its tool and one without. NEGATIVE CONTROL: a service no tool
/// was noted on admits nothing yet.
#[test]
fn package_admission_is_drawn_from_the_tool_before_the_status_read() {
    use crate::packages_screen::{PackagesService, PackagesStatusReport, PackagesWorkerCompletion};
    let unnoted = PackagesService::new().state(true, true, true).projection();
    assert_eq!(
        PackageAdmission::from_projection(&unnoted),
        PackageAdmission::Unobserved
    );
    let drawn = |state: PackagesState| {
        let (mut runtime, instance, view) = setup();
        replace_settings_source(
            &mut runtime,
            view,
            "[packages]\nenabled = false\n".to_string(),
        );
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Packages);
        }
        assert!(runtime.replace_settings_packages(state, 2));
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_074.0, 900.0));
        let mut said = Vec::new();
        for key in [
            format!("settings/label/{}", prefs::EDIT_PACKAGES_AUTO_INSTALL),
            format!("settings/control/{}", prefs::EDIT_PACKAGES_AUTO_INSTALL),
            "packages/loop-status".to_string(),
            "packages/consent-note".to_string(),
        ] {
            said.push(compiled.semantic(&UiKey::new(key.as_str())).map(|node| {
                format!(
                    "{key}={}|{}",
                    node.label,
                    crate::native_ui::semantic_value_words(&node.value)
                )
            }));
        }
        said.push(
            compiled
                .paint
                .iter()
                .find(|node| {
                    node.key.as_str()
                        == format!(
                            "settings/label/{}/visual",
                            prefs::EDIT_PACKAGES_AUTO_INSTALL
                        )
                })
                .map(|node| format!("{:?}", node.content)),
        );
        said
    };
    for available in [true, false] {
        let mut service = PackagesService::new();
        assert!(service.note_tool(available));
        assert!(
            !service.note_tool(available),
            "an unchanged tool bumps nothing"
        );
        let sequence = service.begin(None).expect("a status read starts");
        let before = service.state(true, true, true);
        let projection = before.projection();
        assert!(!projection.observed && projection.tool_observed);
        let admission = PackageAdmission::from_projection(&projection);
        if available && atpkg::manager_enabled() {
            assert_eq!(admission, PackageAdmission::Ready);
        } else if !available {
            assert_eq!(admission, PackageAdmission::MissingBinary);
        }
        let first = drawn(before);
        let report = PackagesStatusReport::from_parts(
            available,
            atpkg::manager_enabled(),
            String::new(),
            None,
            &[],
        );
        assert!(service.finish(sequence, PackagesWorkerCompletion::refresh(report)));
        let settled = drawn(service.state(true, true, true));
        assert_eq!(
            first, settled,
            "available={available}: the read changes no admission text"
        );
        if available && atpkg::manager_enabled() {
            assert!(
                first
                    .iter()
                    .flatten()
                    .any(|line| line.contains("Waits until")),
                "the config-only reason is drawn on the first frame: {first:?}"
            );
        }
    }
}

/// PACKAGES SAYS A MISSING TOOL ONCE, AND KEEPS ITS VERBS IN ITS CARD: the
/// status card says the package tool is missing, so no switch row repeats it;
/// the Background service line is plain text, not a card that reads as a
/// field; and the three verbs are one row of the hero (side by side wherever
/// they fit at their own widths), so no screen holds a button apart from the
/// card it belongs to, at the 80x24, 102x29 and 150x48 windows.
#[test]
fn packages_says_a_missing_tool_once_and_keeps_its_verbs_in_its_card() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    assert!(runtime.replace_settings_packages(missing_tool_packages_state(), 2));
    let verbs = [
        "packages/check",
        "packages/install-default",
        "packages/uninstall-all",
    ];
    for (width, height) in [(584.0, 350.0), (738.0, 420.0), (1_074.0, 684.0)] {
        let (mut labels, mut verbs_seen, mut service_seen) = (BTreeSet::new(), 0, false);
        each_screen(
            &mut runtime,
            instance,
            view,
            &view_cx_at(width, height),
            |compiled, top| {
                for key in PACKAGES_PAGE_SWITCHES {
                    let Some(text) = painted_row_label(compiled, key) else {
                        continue;
                    };
                    assert!(
                        !text.contains("Package tool") && !text.contains("No effect"),
                        "{key} at {width}x{height} repeats the status card: {text}"
                    );
                    labels.insert(key);
                }
                if let Some(service) = compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == "packages/loop-status")
                {
                    assert!(
                        matches!(&service.content,
                            UiContent::Group(spec) if spec.style == StyleRef::Plain),
                        "the service line is text, not a card: {:?}",
                        service.content
                    );
                    service_seen = true;
                }
                let shown = verbs
                    .iter()
                    .filter_map(|key| compiled.semantic(&UiKey::new(*key)))
                    .collect::<Vec<_>>();
                if !shown.is_empty() {
                    assert_eq!(shown.len(), 3, "the verbs together at {width}x{height}");
                    let hero = compiled
                        .semantic(&UiKey::new("packages/hero"))
                        .unwrap_or_else(|| panic!("the verbs' card ({width}x{height})"))
                        .rect;
                    for verb in &shown {
                        assert!(
                            verb.rect.y >= hero.y && verb.rect.bottom() <= hero.bottom() + 0.01,
                            "{} inside the status card at {width}x{height}",
                            verb.key.as_str()
                        );
                    }
                    assert!(
                        compiled
                            .semantic(&UiKey::new("packages/headline"))
                            .is_some(),
                        "the verbs with the status they act on ({width}x{height}, screen {top})"
                    );
                    verbs_seen += 1;
                }
            },
        );
        assert_eq!(
            labels.len(),
            PACKAGES_PAGE_SWITCHES.len(),
            "{width}x{height}"
        );
        assert!(verbs_seen > 0 && service_seen, "{width}x{height}");
    }
}

/// ONE CAUSE, ONE NOTE (h-30): a saved setting that does nothing here says why the
/// same way wherever it is listed. Universal Control and Keep ALab tools up to date
/// are held back by the same missing package tool and paint the same words; the
/// update switches paint their own cause; every such note leads with its cause, and
/// a row whose label line cannot hold it moves it whole to its second line, never
/// cut — on Modified and in a search, from 80x24 to 220x60.
#[test]
fn one_cause_paints_one_note() {
    let mut status = update_status(false);
    status.installable = false;
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    replace_settings_source(
        &mut runtime,
        view,
        "[update]\nenabled = false\nauto_apply = false\n[packages]\nenabled = false\n\
         [machine]\nuniversal_control = \"off\"\n"
            .to_string(),
    );
    assert!(runtime.replace_settings_packages(missing_tool_packages_state(), 2));
    let tool = NoEffectCause::PackageToolMissing.disclosure().visual;
    let copy = NoEffectCause::CopyCantUpdate.disclosure().visual;
    // Universal Control waits on the package tool only where it actuates
    // (macOS, `row_available_here`); elsewhere its one cause is the platform,
    // in the platform note's own words.
    let universal = if row_available_here(
        prefs::EDIT_MACHINE_UNIVERSAL_CONTROL,
        SettingsAvailability::runtime(true),
    ) {
        tool.clone()
    } else {
        platform_unavailability(
            &SettingsViewState::new(&Config::default()),
            None,
            prefs::EDIT_MACHINE_UNIVERSAL_CONTROL,
            SettingsAvailability::runtime(true),
        )
        .expect("a row that does nothing here says why")
        .visual
    };
    let keys = [
        prefs::EDIT_MACHINE_UNIVERSAL_CONTROL,
        prefs::EDIT_PACKAGES_ENABLED,
        prefs::EDIT_UPDATE_ENABLED,
        "update.auto_apply",
    ];
    for (route, search) in [
        (SettingsRoute::Modified, ""),
        (SettingsRoute::Security, "universal"),
        (SettingsRoute::Security, "ALab"),
        (SettingsRoute::Security, "automatically"),
    ] {
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(route);
            state.search = search.to_string();
        }
        for (width, height) in [
            (584.0, 350.0),
            (738.0, 420.0),
            (1_074.0, 684.0),
            (1_564.0, 854.0),
        ] {
            let mut painted: std::collections::BTreeMap<&str, String> =
                std::collections::BTreeMap::new();
            let mut cut = Vec::new();
            each_screen(
                &mut runtime,
                instance,
                view,
                &view_cx_at(width, height),
                |compiled, _| {
                    for key in keys {
                        // The label's painted lines, then its second line's.
                        let label = format!("settings/label/{key}/visual/line-");
                        let detail = format!("settings/detail/{key}/line-");
                        let words = compiled
                            .paint
                            .iter()
                            .filter(|node| {
                                node.key.as_str().starts_with(&label)
                                    || node.key.as_str().starts_with(&detail)
                            })
                            .filter_map(|node| match &node.content {
                                UiContent::Text(text) => Some(text.text.clone()),
                                _ => None,
                            })
                            .collect::<Vec<_>>();
                        // The screen that shows the row whole: an edge peek paints
                        // its label line alone.
                        let words = words.join(" ");
                        if !words.is_empty()
                            && painted.get(key).is_none_or(|held| words.len() > held.len())
                        {
                            painted.insert(key, words);
                        }
                    }
                    cut.extend(
                        compiled
                            .paint_audit_lines()
                            .into_iter()
                            .filter(|line| {
                                keys.iter().any(|key| {
                                    line.contains(&format!("key=\"settings/label/{key}"))
                                        || line.contains(&format!("key=\"settings/detail/{key}"))
                                })
                            })
                            .filter(|line| {
                                line.contains("overflow=true")
                                    || line.contains("clip-truncated=true")
                            }),
                    );
                },
            );
            let at = format!("{route:?} {search:?} {width}x{height}");
            assert!(cut.is_empty(), "{at}:\n{}", cut.join("\n"));
            for (key, words) in &painted {
                let want = if key.starts_with("update.") {
                    &copy
                } else if *key == prefs::EDIT_MACHINE_UNIVERSAL_CONTROL {
                    &universal
                } else {
                    &tool
                };
                assert!(words.contains(want.as_str()), "{at} {key}: {words:?}");
            }
            if let (Some(machine), Some(packages)) = (
                painted.get(prefs::EDIT_MACHINE_UNIVERSAL_CONTROL),
                painted.get(prefs::EDIT_PACKAGES_ENABLED),
            ) {
                assert!(
                    machine.contains(universal.as_str()) && packages.contains(tool.as_str()),
                    "{at}: one cause, one note: {machine:?} / {packages:?}"
                );
            }
        }
    }
    // Every cause's note leads with the cause, then "no effect".
    for cause in [
        NoEffectCause::NoUpdater,
        NoEffectCause::CopyCantUpdate,
        NoEffectCause::PackageToolMissing,
        NoEffectCause::PackagesNotInBuild,
    ] {
        let visual = cause.disclosure().visual;
        let (reason, effect) = visual.split_once(": ").expect("cause first");
        assert!(
            !reason.is_empty() && effect.starts_with("no effect"),
            "{visual}"
        );
    }
}

/// THE "THIS MAC" STATUS LIVES IN ITS ROW'S GROUP. On macOS, once the host has
/// read the Mac, Security's one "This Mac" group holds the Universal Control
/// row and, under it, the measured state in a sentence; where there is
/// something to apply, what Apply Now does with the button beside it at its own
/// width; whatever is in the way. There is no second card, nothing before the
/// read, nothing in Modified or a search, and in a copy without its package
/// tool, whose row says it has no effect, only the one line that says why.
/// A GROUP'S IDENTITY IS ITS OWN: a search result group has the same key
/// whatever page the search started on (search keeps that route), and no
/// group key carries a page path, so none has a doubled slash.
#[test]
fn search_result_groups_keep_their_identity_whatever_page_search_started_on() {
    let cx = view_cx_at(1_100.0, 1_400.0);
    let groups = |route: SettingsRoute, search: &str| {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(route);
            state.search = search.to_string();
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled
            .semantics
            .iter()
            .map(|node| node.key.as_str().to_string())
            .filter(|key| key.starts_with("settings/group/"))
            .collect::<BTreeSet<_>>()
    };
    let from_home = groups(SettingsRoute::Home, "bloom");
    assert!(
        from_home.contains("settings/group/cursor-styles---bloom---glow/cursor-trail-bloom"),
        "{from_home:?}"
    );
    for route in SettingsRoute::ALL {
        let found = groups(route, "bloom");
        assert_eq!(found, from_home, "search started on {route:?}");
    }
    let security = groups(SettingsRoute::Security, "");
    assert!(!security.is_empty());
    assert!(
        security.iter().all(|key| !key.contains("//")),
        "{security:?}"
    );
}

#[test]
fn the_security_page_shows_this_mac_under_its_row() {
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
    }
    let cx = view_cx_at(1100.0, 1400.0);
    let row_key = format!("settings/control/{}", prefs::EDIT_MACHINE_UNIVERSAL_CONTROL);
    // Unobserved: no status on any platform — nothing invented.
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled.semantic(&UiKey::new("settings/machine")).is_none(),
        "no machine read yet ⇒ no status"
    );

    let seat = |runtime: &mut NativeRuntime, state: PackagesState, revision: u64| {
        assert!(runtime.replace_settings_packages(state, revision));
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        compiled
    };
    let text = |compiled: &crate::native_ui::CompiledUi, key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .map(|node| node.label.clone())
    };

    // Observed with something left to do.
    let compiled = seat(
        &mut runtime,
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account,
            )),
        ),
        3,
    );
    assert_eq!(
        compiled.semantic(&UiKey::new("settings/machine")).is_some(),
        cfg!(target_os = "macos"),
        "the status is a macOS host-settings surface"
    );
    if !cfg!(target_os = "macos") {
        return;
    }
    assert!(
        compiled
            .semantics
            .iter()
            .all(|node| !node.key.as_str().starts_with("settings/machine/heading")),
        "one This Mac group, no second card"
    );
    let row = compiled
        .semantic(&UiKey::new(row_key.as_str()))
        .unwrap()
        .rect;
    let status = compiled
        .semantic(&UiKey::new("settings/machine"))
        .unwrap()
        .rect;
    let group = compiled
        .semantics
        .iter()
        .find(|node| node.key.as_str().starts_with("settings/group/this-mac/"))
        .expect("the This Mac group")
        .rect;
    assert!(status.y >= row.bottom(), "under the row");
    assert!(
        status.y >= group.y && status.bottom() <= group.bottom(),
        "inside the row's group: {status:?} in {group:?}"
    );
    assert!(text(&compiled, "settings/machine/universal-control").is_some());
    assert_eq!(
        text(&compiled, "settings/machine/next").as_deref(),
        Some(crate::packages_screen::MACHINE_APPLY_WOULD)
    );
    for quiet in [
        "settings/machine/home",
        "settings/machine/last-applied",
        "settings/machine/debugger",
    ] {
        assert!(text(&compiled, quiet).is_none(), "{quiet}: nothing to say");
    }
    let apply = compiled
        .semantic(&UiKey::new(MACHINE_APPLY))
        .expect("Apply Now is a hit target");
    assert!(apply.state.as_ref().is_some_and(|s| s.enabled));
    assert!(
        apply.rect.width < 160.0,
        "Apply Now keeps its own width, not the row's: {:?}",
        apply.rect
    );
    let next = compiled
        .semantic(&UiKey::new("settings/machine/next"))
        .unwrap()
        .rect;
    assert!(
        apply.rect.x >= next.right() && apply.rect.y < next.bottom(),
        "beside what it does"
    );

    // Other package work running: the button stays where it was, greyed,
    // so the row doesn't jump as that work comes and goes.
    let compiled = seat(
        &mut runtime,
        live_packages_state_with_machine(
            Some(crate::packages_screen::PackagesBusy::Check),
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account,
            )),
        ),
        4,
    );
    let busy = compiled
        .semantic(&UiKey::new(MACHINE_APPLY))
        .expect("still offered while other work runs");
    assert!(busy.state.as_ref().is_some_and(|s| !s.enabled));
    assert_eq!(busy.rect, apply.rect, "in the same place");

    // Nothing left: no button is offered.
    let compiled = seat(
        &mut runtime,
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Disabled,
                HomePosture::Account,
            )),
        ),
        5,
    );
    assert!(compiled.semantic(&UiKey::new(MACHINE_APPLY)).is_none());

    // A home mismatch names what is in the way, and offers nothing to press.
    let compiled = seat(
        &mut runtime,
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Mismatch,
            )),
        ),
        6,
    );
    assert!(
        text(&compiled, "settings/machine/home")
            .is_some_and(|reason| reason.starts_with("Not applied:")
                && !reason.contains("HOME")
                && !reason.contains("defaults")),
        "{:?}",
        text(&compiled, "settings/machine/home")
    );
    assert!(compiled.semantic(&UiKey::new(MACHINE_APPLY)).is_none());

    // A read error after a good record: the reason line shows and nothing
    // is offered.
    let compiled = seat(
        &mut runtime,
        live_packages_state_with_machine_reads(
            None,
            true,
            None,
            vec![
                Ok(machine_state_fixture(
                    UcPosture::Default,
                    HomePosture::Account,
                )),
                Err("atpkg machine printed no state".to_string()),
            ],
        ),
        7,
    );
    assert!(text(&compiled, "settings/machine/home").is_some());
    assert!(compiled.semantic(&UiKey::new(MACHINE_APPLY)).is_none());

    // No package tool: the one This Mac line under the row says why — nothing is
    // read, and there is nothing to apply — so the row paints no second copy of
    // that cause; its accessible name still says it.
    let compiled = seat(&mut runtime, missing_tool_packages_state(), 8);
    assert_eq!(
        text(&compiled, "settings/machine/universal-control").as_deref(),
        Some(MACHINE_TOOL_MISSING)
    );
    for key in [
        MACHINE_APPLY,
        "settings/machine/refreshing",
        "settings/machine/home",
        "settings/machine/saved",
    ] {
        assert!(compiled.semantic(&UiKey::new(key)).is_none(), "{key}");
    }
    let cause = NoEffectCause::PackageToolMissing.disclosure();
    let painted_row = |compiled: &crate::native_ui::CompiledUi| {
        let label = format!(
            "settings/label/{}/visual",
            prefs::EDIT_MACHINE_UNIVERSAL_CONTROL
        );
        let detail = format!(
            "settings/detail/{}/line-",
            prefs::EDIT_MACHINE_UNIVERSAL_CONTROL
        );
        compiled
            .paint
            .iter()
            .filter(|node| node.key.as_str() == label || node.key.as_str().starts_with(&detail))
            .filter_map(|node| match &node.content {
                UiContent::Text(text) => Some(text.text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join(" ")
    };
    let on_security = painted_row(&compiled);
    assert!(
        !on_security.is_empty() && !on_security.contains(cause.visual.as_str()),
        "the status says it once: {on_security:?}"
    );
    assert!(
        compiled
            .semantic(&UiKey::new(row_key.as_str()))
            .is_some_and(|control| control.label.contains(cause.semantic.as_str())),
        "the control's name still says why"
    );
    // Off Security (no status under the row), the row paints the cause itself.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.search = "universal".to_string();
    }
    let searched = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        painted_row(&searched).contains(cause.visual.as_str()),
        "{:?}",
        painted_row(&searched)
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.search.clear();
    }

    // Modified and a global search never carry it.
    let _ = seat(
        &mut runtime,
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account,
            )),
        ),
        9,
    );
    for (route, search) in [
        (SettingsRoute::Modified, ""),
        (SettingsRoute::Security, "universal"),
    ] {
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(route);
            state.search = search.to_string();
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            compiled.semantic(&UiKey::new("settings/machine")).is_none(),
            "{route:?} {search:?}"
        );
    }

    // With the macOS access block drawn above, the status points at its
    // Debugger access row.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.search.clear();
        state.navigate(SettingsRoute::Security);
        state.replace_macos_access(debugger_access(debugger_facts(
            aterm_containment::consent::DebuggerMode::Disabled,
            aterm_containment::consent::DebuggerMember::Admin,
            aterm_containment::consent::SelfHardening::Hardened,
        )));
    }
    let with_row = compile_settings_view(&runtime, instance, view, &view_cx_at(1100.0, 2400.0));
    with_row.validate_parity().unwrap();
    assert!(
        with_row
            .semantic(&UiKey::new("settings/macos-access/debugger/state"))
            .is_some(),
        "the Debugger access row is drawn"
    );
    assert!(text(&with_row, "settings/machine/debugger").is_some());
}

/// `machine/apply` goes through the same reducer as every package verb: refused
/// before the machine is read (no effect minted), dispatched as the typed
/// `MachineApply` request when the measured state says something is left to do,
/// settled through PackagesFinished, refused while a verb runs, and refused, with
/// the verdict, when there is nothing to apply.
#[test]
fn machine_apply_gates_dispatch_and_finish() {
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Security),
                value: None,
            }),
        )
        .unwrap();
    let apply = || {
        AppEvent::Action(ActionInvocation {
            id: ActionId::new(MACHINE_APPLY),
            value: None,
        })
    };
    let no_effect = |result: &crate::native_app::DispatchOutcome| {
        result
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Packages { .. }))
    };
    let feedback = |runtime: &NativeRuntime| -> String {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        state.feedback.clone().unwrap_or_default()
    };

    // Unobserved (fresh controller): refuse without an effect.
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(
        no_effect(&refused),
        "no effect before the first observation"
    );
    assert!(feedback(&runtime).contains("still being read"));

    // Packages observed, machine not yet read: still refused, in machine words.
    assert!(runtime.replace_settings_packages(live_packages_state(None), 3));
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&refused));
    if cfg!(target_os = "macos") {
        assert!(
            feedback(&runtime).contains("settings are still being read"),
            "{}",
            feedback(&runtime)
        );
    } else {
        assert!(feedback(&runtime).contains("for macOS"));
        return;
    }

    // Nothing to apply: refused with the verdict, no effect.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Disabled,
                HomePosture::Account
            )),
        ),
        4,
    ));
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&refused));
    assert!(
        feedback(&runtime).starts_with("Nothing to apply"),
        "{}",
        feedback(&runtime)
    );

    // A home mismatch: refused with the reason.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Mismatch
            )),
        ),
        5,
    ));
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&refused));
    assert!(
        feedback(&runtime).starts_with("Not applied:"),
        "{}",
        feedback(&runtime)
    );

    // Something left to do: the typed request reaches the host executor.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account
            )),
        ),
        6,
    ));
    let accepted = runtime.dispatch(instance, view, apply()).unwrap();
    let operation = accepted
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Packages { request, reply } => {
                assert_eq!(*request, crate::native_app::PackagesRequest::MachineApply);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("a live machine dispatches the machine apply");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.pending.len(), 1);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::PackagesFinished {
                operation,
                outcome: crate::native_app::PackagesOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.pending.is_empty());
    // Admission says nothing in the footer: the card's headline says the verb runs.
    assert_eq!(state.feedback, None);

    // Busy with the apply itself: a second press is refused without an effect.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            Some(crate::packages_screen::PackagesBusy::MachineApply),
            Ok(machine_state_fixture(
                UcPosture::Default,
                HomePosture::Account
            )),
        ),
        7,
    ));
    let busy = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&busy), "a running verb blocks a second one");
    assert!(
        feedback(&runtime).contains("already running"),
        "{}",
        feedback(&runtime)
    );
}

/// With the package manager inert (no pinned root key) or the status collection torn,
/// `packages/check` is refused with the true cause, and `machine/apply`, a local verb,
/// still dispatches.
#[test]
fn machine_apply_dispatches_with_the_manager_off() {
    use atpkg::machine::{HomePosture, UcPosture};
    for (manager_enabled, collection_error) in
        [(false, None), (true, Some("status.toml: torn record"))]
    {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Security),
                    value: None,
                }),
            )
            .unwrap();
        assert!(runtime.replace_settings_packages(
            live_packages_state_with_machine_reads(
                None,
                manager_enabled,
                collection_error,
                vec![Ok(machine_state_fixture(
                    UcPosture::Default,
                    HomePosture::Account
                ))],
            ),
            3,
        ));
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(MACHINE_APPLY),
                    value: None,
                }),
            )
            .unwrap();
        let dispatched = outcome.effects.iter().any(|effect| {
            matches!(
                effect,
                AppEffect::Packages {
                    request: crate::native_app::PackagesRequest::MachineApply,
                    ..
                }
            )
        });
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        let feedback = state.feedback.clone().unwrap_or_default();
        if cfg!(target_os = "macos") {
            assert!(
                dispatched,
                "manager_enabled={manager_enabled} error={collection_error:?}: {feedback}"
            );
        } else {
            assert!(!dispatched);
            assert!(feedback.contains("for macOS"), "{feedback}");
            continue;
        }
        if !manager_enabled {
            // The package verb in the same state is still refused, with the cause.
            let refused = runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new("packages/check"),
                        value: None,
                    }),
                )
                .unwrap();
            assert!(
                refused
                    .effects
                    .iter()
                    .all(|effect| !matches!(effect, AppEffect::Packages { .. }))
            );
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                unreachable!();
            };
            let feedback = state.feedback.clone().unwrap_or_default();
            assert!(
                feedback.contains("can\u{2019}t install packages") && !feedback.contains("ATPKG_"),
                "{feedback}"
            );
        }
    }
}

/// The action reducer refuses (unobserved / busy) without minting an effect,
/// dispatches the typed request when live, and settles pending state through
/// PackagesFinished.
#[test]
fn packages_actions_gate_dispatch_and_finish() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let check = || {
        AppEvent::Action(ActionInvocation {
            id: ActionId::new("packages/check"),
            value: None,
        })
    };

    // Unobserved (fresh controller): refuse without an effect.
    let refused = runtime.dispatch(instance, view, check()).unwrap();
    assert!(
        refused
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Packages { .. })),
        "no effect before the first worker observation"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(
        state
            .feedback
            .as_deref()
            .unwrap()
            .contains("still being read")
    );

    // Live manager: the typed request goes to the host executor.
    assert!(runtime.replace_settings_packages(live_packages_state(None), 3));
    let accepted = runtime.dispatch(instance, view, check()).unwrap();
    let operation = accepted
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Packages { request, reply } => {
                assert_eq!(*request, crate::native_app::PackagesRequest::CheckUpdate);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("a live manager dispatches the packages effect");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.pending.len(), 1);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::PackagesFinished {
                operation,
                outcome: crate::native_app::PackagesOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.pending.is_empty());
    // Admission says nothing in the footer: the card's headline says the verb runs.
    assert_eq!(state.feedback, None);

    // The worker exits non-zero while status.toml still holds an older success:
    // typed completion replaces the admission message.
    assert!(runtime.replace_settings_packages(failed_packages_state(), 4));
    runtime
        .dispatch(instance, view, AppEvent::PackagesChanged { revision: 4 })
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    // The failure is the card's headline and detail, not a footer repeating them.
    assert_eq!(state.feedback, None);
    let card = failed_packages_state().projection();
    assert!(
        card.detail
            .as_deref()
            .is_some_and(|d| d.contains("atpkg update exited with status 7")),
        "{:?}",
        card.detail
    );

    // Busy: the second verb is refused without a second effect.
    assert!(runtime.replace_settings_packages(
        live_packages_state(Some(crate::packages_screen::PackagesBusy::Check)),
        5,
    ));
    let busy = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("packages/install-default"),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        busy.effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Packages { .. })),
        "a running verb blocks a second one"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(
        state
            .feedback
            .as_deref()
            .unwrap()
            .contains("already running")
    );
}

/// A live packages snapshot whose one program carries `state` verbatim.
fn packages_state_with_program_state(state: &str) -> PackagesState {
    let status = atpkg_status(
        "2026-09-14T00:00:00Z",
        "install failed",
        vec![("ay", Some(1971), state.to_string())],
    );
    packages_service(packages_report(&status, true)).state(true, true, true)
}

/// A long `error: stage: …` state whose `fix:` clause comes last: the fix leads,
/// whole, on continuation lines under its row at every width (measured by the
/// painter), and a short state paints as before.
#[test]
fn packages_long_reason_rows_put_the_fix_first_and_keep_short_states_stable() {
    let incident = crate::packages_screen::INCIDENT_2026_09_14_REASON.to_string();
    assert!(
        incident.chars().count() > 600,
        "{}",
        incident.chars().count()
    );
    let fix_at = incident
        .find(" fix: ")
        .expect("atpkg spells the remedy ` fix: `");
    let fix_clause = &incident[fix_at + " fix: ".len()..];
    let widths = [
        SettingsWidth::Compact,
        SettingsWidth::Medium,
        SettingsWidth::Wide,
    ];

    // The common case: one line, the row's facts inline, at every width.
    let short =
        packages_state_with_program_state("managed 1971 \u{2014} pinned by index 41").projection();
    for width in widths {
        let lines = packages_program_lines(&short, width);
        assert_eq!(lines.len(), 1, "{width:?}");
        assert!(!lines[0].continuation);
        assert_eq!(packages_program_lines(&short, width).len(), 1);
    }

    // A long state leaves the row, and the fix is the first line under it.
    let long = packages_state_with_program_state(&incident).projection();
    for width in widths {
        let budget = packages_reason_wrap_chars(width);
        let lines = packages_program_lines(&long, width);
        assert_eq!(lines[0].key, "packages/programs/ay");
        assert!(
            !lines[0].text.contains("error: stage:"),
            "{width:?}: a FAULT keeps its own words below the row's facts"
        );
        assert!(!lines[0].continuation);
        let reason: Vec<String> = lines[1..].iter().map(|line| line.text.clone()).collect();
        assert_eq!(
            reason,
            crate::packages_screen::reason_lines(&incident, budget),
            "{width:?}"
        );
        for (index, line) in lines[1..].iter().enumerate() {
            assert!(line.continuation);
            assert_eq!(
                line.key,
                format!("packages/programs/ay/reason/{}", index + 1)
            );
            // The wrap measures glyph advance, not characters; the paint audit below
            // says whether the line fits.
            assert!(
                line.text.chars().count() <= budget * 5 / 4,
                "{width:?}: {:?}",
                line.text
            );
        }
        assert!(
            lines[1]
                .text
                .starts_with("fix: unset ATPKG_REFUSE_TRACKED_INSTALL"),
            "{width:?}: {:?}",
            lines[1].text
        );
        let fix_lines: Vec<&str> = reason
            .iter()
            .map(String::as_str)
            .take_while(|line| !line.starts_with("error: stage:") && !line.starts_with('\u{2026}'))
            .collect();
        assert_eq!(
            fix_lines.join(" "),
            format!("fix: {fix_clause}"),
            "{width:?}: nothing of the fix is cut"
        );
        assert_eq!(packages_program_lines(&long, width).len(), lines.len());
    }

    // Every painted continuation line fits its box at the compact and wide viewport.
    for (viewport_width, viewport_height) in [(474.0_f32, 658.0_f32), (1_280.0, 800.0)] {
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(packages_state_with_program_state(&incident), 2));
        let cx = view_cx_at(viewport_width, viewport_height);
        let mut reason_audit = Vec::new();
        for page in 0..16 {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Packages);
            state.page_scroll = page;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let painted: Vec<String> = compiled
                .paint_audit_lines()
                .into_iter()
                .filter(|line| line.contains("paint-text key=\"packages/programs/ay/reason/"))
                .collect();
            if !painted.is_empty() {
                reason_audit = painted;
                break;
            }
        }
        assert!(
            reason_audit
                .iter()
                .any(|line| line.contains("packages/programs/ay/reason/1")),
            "{viewport_width}: the fix line paints:\n{}",
            reason_audit.join("\n")
        );
        assert!(
            reason_audit.iter().all(
                |line| line.contains("overflow=false") && !line.contains("clip-truncated=true")
            ),
            "{viewport_width}:\n{}",
            reason_audit.join("\n")
        );
    }
}

/// The program list: one flat list with no group headings and no Install controls. A
/// vendor row names its version and source, and a row an older atpkg wrote in a
/// retired spelling rides verbatim. (No install id reaches the reducer: its packages
/// arms are exact matches and `PackagesRequest` has no install-one variant.)
#[test]
fn packages_rows_are_one_list_with_no_install_controls() {
    let claude = atpkg::vendor_direct::Version::parse("2.1.280")
        .unwrap()
        .build_id();
    let programs = atpkg_status(
        "",
        "",
        vec![
            ("ay", Some(1971), atpkg::state::managed(1971, 41)),
            (
                "claude",
                Some(claude),
                atpkg::state::vendor_managed("2.1.280", "Anthropic"),
            ),
            (
                "clt",
                None,
                "needs admin — run: aterm pkg install clt".to_string(),
            ),
        ],
    )
    .programs;
    let status = atpkg::Status {
        schema: 1,
        programs,
        ..Default::default()
    };
    let state = packages_service(packages_report(&status, true)).state(true, true, true);
    let projection = state.projection();
    let lines = packages_program_lines(&projection, SettingsWidth::Wide);
    let keys: Vec<&str> = lines.iter().map(|line| line.key.as_str()).collect();
    assert_eq!(
        keys,
        vec![
            "packages/programs/ay",
            "packages/programs/claude",
            "packages/programs/clt",
        ]
    );
    let line = |key: &str| lines.iter().find(|line| line.key == key).unwrap();
    // A vendor program's row names its version and source — never its store id.
    let claude = &line("packages/programs/claude").text;
    assert!(
        claude.contains(" · 2.1.280 · latest from Anthropic"),
        "{claude}"
    );
    assert!(!claude.contains("build "), "{claude}");
    assert!(
        line("packages/programs/clt")
            .text
            .contains("needs admin — run: aterm pkg install clt"),
        "a retired spelling rides verbatim"
    );
    assert_eq!(
        packages_program_lines(&projection, SettingsWidth::Wide).len(),
        lines.len()
    );
}

/// The two switches on the special page are ordinary registry rows: activation flips
/// the resolved value through the dotted-key ConfigPatch (both default on, so the
/// first flip writes false), with per-key OCC expectations.
#[test]
fn packages_consent_switches_patch_the_dotted_keys() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    for (key, expected_write) in [
        (prefs::EDIT_PACKAGES_ENABLED, "false"),
        (prefs::EDIT_PACKAGES_AUTO_INSTALL, "false"),
    ] {
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{key}")),
                    value: None,
                }),
            )
            .unwrap();
        let edit = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => patch.edits.first().cloned(),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{key} switch emits a config patch"));
        assert_eq!(edit.key, key);
        assert_eq!(edit.value.as_deref(), Some(expected_write));
        assert_eq!(
            edit.expected,
            ExpectedConfigValue::Exact(None),
            "an absent [packages] child key carries an exact-absent OCC expectation"
        );
    }
}

/// Packages revision fan-out mirrors the updater: the shared controller
/// snapshot advances and every view bumps its presentation revision.
#[test]
fn packages_changed_revision_repaints_every_view() {
    let (mut runtime, instance, view) = setup();
    let before = match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => state.common.presentation_revision,
        _ => unreachable!(),
    };
    runtime
        .dispatch(instance, view, AppEvent::PackagesChanged { revision: 7 })
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.common.presentation_revision > before);
}

#[test]
fn visual_preview_matrix_covers_four_viewports_at_three_text_scales() {
    at_each_text_scale(
        &[1.0, 1.5, 2.0],
        "Settings viewport/scale matrix",
        visual_preview_matrix_covers_four_viewports_at_three_text_scales_at_scale,
    );
}

/// One rung of [`visual_preview_matrix_covers_four_viewports_at_three_text_scales`].
fn visual_preview_matrix_covers_four_viewports_at_three_text_scales_at_scale(scale: f32) {
    let mut renderer = aterm_render::Renderer::from_bytes(
        include_bytes!("../../aterm-render/tests/fixtures/jetbrains-mono.ttf"),
        14.0,
        aterm_render::Theme::default(),
    )
    .expect("matrix semantic renderer");
    renderer.set_runtime_font_discovery(false);
    renderer.prepare_semantic_typography("Bold Italic != => 你好 ∑✓♥ 😀 🚀 👩‍💻");
    // Settled install: `set_chrome_fonts` parks an async prewarm whose landing
    // between two paints could swap the semantic cascade mid-assertion.
    crate::tray_raster::install_settled_chrome_fonts_for_test(renderer);

    let compile = |runtime: &NativeRuntime,
                   instance: crate::native_app::AppInstanceId,
                   view: crate::native_app::ViewId,
                   width: f32,
                   height: f32| {
        let mut cx = view_cx_at(width, height);
        let state = match runtime.view_state(view) {
            Some(AppViewState::Settings(state)) => state,
            _ => panic!("Settings view state"),
        };
        cx.semantic_font = state
            .preview_font_candidate(cx.animation_phase_ms, cx.motion, cx.terminal_font_px)
            .map(|candidate| crate::tray_raster::prepare_semantic_font(&candidate));
        runtime
            .render(instance, view, &cx)
            .expect("Settings renders")
            .compile(cx.viewport)
            .expect("Settings compiles")
    };
    let assert_whole =
        |compiled: &crate::native_ui::CompiledUi, width: f32, height: f32, context: &str| {
            compiled
                .validate_parity()
                .unwrap_or_else(|error| panic!("{context}: {error:?}"));
            for hit in &compiled.hits {
                let paint = compiled
                    .paint
                    .iter()
                    .find(|paint| paint.key == hit.key)
                    .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
                let parity_delta = (paint.rect.x - hit.rect.x).abs()
                    + (paint.rect.y - hit.rect.y).abs()
                    + (paint.rect.width - hit.rect.width).abs()
                    + (paint.rect.height - hit.rect.height).abs();
                assert!(
                    parity_delta < 0.001 || hit_matches_paint(compiled, hit),
                    "{context}: {:?} parity differs by {parity_delta}: paint={:?}, hit={:?}",
                    hit.key,
                    paint.rect,
                    hit.rect,
                );
                assert!(
                    hit.rect.x >= -0.01
                        && hit.rect.y >= -0.01
                        && hit.rect.right() <= width + 0.01
                        && hit.rect.bottom() <= height + 0.01,
                    "{context}: {:?} is clipped: {:?}",
                    hit.key,
                    hit.rect,
                );
            }
        };

    let viewports = [
        (624.0, 404.0),
        (320.0, 568.0),
        (390.0, 844.0),
        (568.0, 320.0),
        (1_280.0, 800.0),
    ];
    let routes = [
        SettingsRoute::Appearance,
        SettingsRoute::TextFonts,
        SettingsRoute::CursorMotion,
    ];
    for (width, height) in viewports {
        for route in routes {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.navigate(route);
            let compiled = compile(&runtime, instance, view, width, height);
            let context = format!("{} {width}×{height} at {scale}×", route.label());
            assert_whole(&compiled, width, height, &context);
            let preview_key = UiKey::new(format!("settings/preview{}", route.path()));
            let expected_height =
                renderer_preview_height(SettingsWidth::for_viewport_at_scale(width, scale));
            // In a short window or at large type, where even one whole
            // specimen row and the list's tallest stop cannot share a screen,
            // the preview yields altogether rather than showing its header
            // over a sliver.
            let preview = compiled.semantic(&preview_key);
            if preview.is_none() {
                assert!(
                    scale > 1.25 || height < 400.0,
                    "{context}: live preview is visible"
                );
            }
            if let Some(preview) = preview {
                if route == SettingsRoute::TextFonts && preview.rect.height >= expected_height {
                    // A specimen with its full minimum paints whole rows clear
                    // of its status band; a shorter one (a pinned specimen
                    // yielding toward its one-row floor) shows what fits.
                    assert!(
                        preview.rect.bottom() <= height + 0.01,
                        "{context}: whole specimen card"
                    );
                    let paint = compiled
                        .paint
                        .iter()
                        .find(|paint| paint.key == preview_key)
                        .unwrap();
                    let UiContent::SettingsPreview(spec) = &paint.content else {
                        unreachable!()
                    };
                    let mut prims = Vec::new();
                    spec.paint(
                        &mut prims,
                        paint.rect,
                        aterm_render::Theme::default(),
                        crate::settings::Roles::from_theme(aterm_render::Theme::default()),
                    );
                    let (y, specimen) = prims
                        .iter()
                        .find_map(|prim| match prim {
                            crate::widget::DrawPrim::TerminalSpecimen { y, spec, .. } => {
                                Some((*y, spec))
                            }
                            _ => None,
                        })
                        .expect("typography paints complete specimen rows");
                    if width == 624.0 && height == 404.0 && scale == 1.0 {
                        // The pinned specimen shares the window with the list
                        // under it, never a screen of its own.
                        assert!(
                            specimen.input.rows >= 2,
                            "a short desktop window still shows whole specimen rows"
                        );
                    }
                    let pill_y = prims
                        .iter()
                        .find_map(|prim| match prim {
                            crate::widget::DrawPrim::Panel { y, radius, .. } if *radius == 6.0 => {
                                Some(*y)
                            }
                            _ => None,
                        })
                        // A font that is ready has no status pill: its rows
                        // stop clear of the body's bottom inset instead.
                        .unwrap_or(paint.rect.bottom() - 10.0);
                    for dpi in [1.0, 1.25, 2.0, 3.0] {
                        let variations = specimen
                            .variations
                            .iter()
                            .map(|v| (v.tag, v.value()))
                            .collect::<Vec<_>>();
                        let row_h = specimen
                            .prepared_font
                            .specimen_cell_height(
                                specimen.font_px * dpi,
                                specimen.line_height,
                                &variations,
                            )
                            .unwrap() as f32
                            / dpi;
                        assert!(
                            y + specimen.input.rows as f32 * row_h <= pill_y - 4.0,
                            "{context} at {dpi}dpi: specimen rows never meet the status badge"
                        );
                    }
                } else {
                    // The pinned preview yields height toward its floor (one
                    // whole specimen row at the authored size) before the
                    // list under it loses its first two stops, and never
                    // under it.
                    let floor = compiled
                        .paint
                        .iter()
                        .find_map(|paint| match &paint.content {
                            UiContent::SettingsPreview(spec) if paint.key == preview_key => {
                                Some(spec.minimum_height(48.0))
                            }
                            _ => None,
                        })
                        .expect("the preview paints a specimen");
                    assert!(
                        preview.rect.height >= floor - 0.01,
                        "{context}: preview height is {:?}, floor {floor}",
                        preview.rect,
                    );
                    if route != SettingsRoute::TextFonts {
                        assert!(
                            preview.rect.height <= expected_height + 0.01,
                            "{context}: preview height is {:?}, natural {expected_height}",
                            preview.rect,
                        );
                    }
                }
            }

            // The preview is never a screen of its own: the first screen
            // holds a real control, every screen keeps the preview pinned,
            // and the list reaches the route's last field whole.
            assert!(
                compiled.semantics.iter().any(|node| {
                    node.parent
                        .as_ref()
                        .is_some_and(|parent| parent.as_str() == "settings/list")
                }),
                "{context}: the first screen holds more than the preview"
            );
            let section = route.section().expect("preview route has a section");
            let last_key = {
                let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                    unreachable!()
                };
                let mut fields = state
                    .legacy
                    .fields
                    .iter()
                    .enumerate()
                    .filter(|(_, field)| prefs::section_of(field.key) == section)
                    .filter(|(_, field)| field_visible(field.key, false, false))
                    .filter(|(_, field)| {
                        !(route == SettingsRoute::TextFonts
                            && field.key == prefs::EDIT_DISPLAY_FONT)
                    })
                    .collect::<Vec<_>>();
                fields.sort_by_key(|(index, field)| (prefs::group_of(field.key).1, *index));
                fields.last().expect("preview route has fields").1.key
            };
            let last_control = UiKey::new(format!("settings/control/{last_key}"));
            let mut screen_cx = view_cx_at(width, height);
            screen_cx.semantic_font = {
                let state = match runtime.view_state(view) {
                    Some(AppViewState::Settings(state)) => state,
                    _ => panic!("Settings view state"),
                };
                state
                    .preview_font_candidate(
                        screen_cx.animation_phase_ms,
                        screen_cx.motion,
                        screen_cx.terminal_font_px,
                    )
                    .map(|candidate| crate::tray_raster::prepare_semantic_font(&candidate))
            };
            let mut reached_last = false;
            let screens = each_screen(&mut runtime, instance, view, &screen_cx, |screen, top| {
                assert_whole(screen, width, height, &format!("{context}, screen {top}"));
                reached_last |= screen.semantic(&last_control).is_some();
            });
            assert!(
                reached_last,
                "{context}: last field {last_key} is reachable in {screens} screens"
            );
        }

        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.set_search("font".to_string());
        state.common.last_focus = Some(UiKey::new("settings/search"));
        let searched = compile(&runtime, instance, view, width, height);
        let context = format!("font search {width}×{height} at {scale}×");
        assert_whole(&searched, width, height, &context);
        // The contextual preview is pinned, or (in a short window or at
        // large type, where it and a whole result cannot share a screen)
        // the results are.
        assert!(
            searched
                .semantic(&UiKey::new("settings/preview/search"))
                .is_some()
                || ((scale > 1.25 || height < 400.0)
                    && searched.semantics.iter().any(|node| {
                        node.parent
                            .as_ref()
                            .is_some_and(|parent| parent.as_str() == "settings/list")
                    })),
            "{context}: global search retains the matching contextual preview"
        );
        assert!(
            searched.semantic(&UiKey::new("settings/search")).is_some(),
            "{context}: the full search surface remains present"
        );
    }
}

/// ABOUT'S ONE TAGLINE AND WHOLE FACTS: the hero paints the build
/// information's `tagline` row — the sentence Copy Build Information copies —
/// and each build fact is ONE block of the card, its wrapped lines inside it,
/// so a list that lays the card out fact by fact never parts a fact from its
/// own continuation.
#[test]
fn about_paints_the_copied_tagline_and_lists_each_fact_whole() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 900.0));
    let tagline = compiled
        .paint
        .iter()
        .filter(|node| node.key.as_str().starts_with("about/tagline/line-"))
        .map(|node| match &node.content {
            UiContent::Text(text) => text.text.trim().to_string(),
            other => panic!("{other:?}"),
        })
        .collect::<Vec<_>>()
        .join(" ");
    assert_eq!(tagline, crate::build_info::TAGLINE);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("about/tagline"))
            .map(|node| node.label.as_str()),
        Some(crate::build_info::TAGLINE)
    );
    assert!(
        crate::about::provenance_text()
            .contains(&format!("tagline: {}\n", crate::build_info::TAGLINE)),
        "the copied block says the same sentence"
    );
    for (width, height) in [(1_200.0, 900.0), (474.0, 900.0), (320.0, 900.0)] {
        let mut blocks = 0;
        each_screen(
            &mut runtime,
            instance,
            view,
            &view_cx_at(width, height),
            |compiled, _| {
                // A fact the list's edge cuts is its peek: a picture, not a
                // block to read.
                for line in compiled.paint.iter().filter(|node| {
                    !node.peek && node.key.as_str().starts_with("about/provenance/value/")
                }) {
                    let fact = line.key.as_str()["about/provenance/value/".len()..]
                        .split('/')
                        .next()
                        .unwrap_or_default();
                    let block = compiled
                        .semantic(&UiKey::new(format!("about/provenance/row/{fact}")))
                        .unwrap_or_else(|| panic!("{fact}'s block ({width})"));
                    assert!(
                        line.rect.y >= block.rect.y - 0.01
                            && line.rect.bottom() <= block.rect.bottom() + 0.01,
                        "{} inside its fact's block at {width}",
                        line.key.as_str()
                    );
                    blocks += 1;
                }
            },
        );
        assert!(blocks > 0, "facts are listed at {width}");
    }
}

/// Where a Linux-layout test takes its UI face from ([`linux_layout_cx`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LinuxLayoutFace {
    /// The host's own UI face — Helvetica Neue on a Mac.
    Host,
    /// The Linux ladder's first readable pair (Noto Sans, else DejaVu Sans): the
    /// host's Linux font tree, or the directory `ATERM_TEST_LINUX_UI_FONTS` names.
    LinuxLadder,
    /// No UI face at all: every string measures at the 0.6 em mono approximation, as
    /// on a Linux host with neither Noto nor DejaVu Sans installed — wider than both.
    NoUiFace,
}

/// A `ViewCx` whose compile measures in `face`, or `None` when this host cannot read
/// the Linux ladder's faces. Compile with it before building another: `view_cx_at`
/// reinstalls the host's faces.
fn linux_layout_cx(face: LinuxLayoutFace, width: f32, height: f32) -> Option<ViewCx<'static>> {
    let cx = view_cx_at(width, height);
    match face {
        LinuxLayoutFace::Host => {}
        LinuxLayoutFace::LinuxLadder => {
            let root = std::env::var_os("ATERM_TEST_LINUX_UI_FONTS").map(std::path::PathBuf::from);
            crate::tray_raster::install_linux_ui_fonts_for_test(root.as_deref())?;
        }
        LinuxLayoutFace::NoUiFace => crate::tray_raster::clear_ui_fonts_for_test(),
    }
    Some(cx)
}

/// The live Linux update page on every host, in the host's face, the Linux ladder's
/// (where readable) and no UI face: an enrolled copy idle (checks on, off, saved the
/// other way), downloading, needing attention and awaiting its startup trial, at every
/// width and the short phone. A real face paints clean; with none the cards still fit.
/// The apply button is disabled and names `aterm update apply`; both switches are live.
#[test]
fn linux_update_status_settings_preserves_manual_authority_and_effective_policy() {
    let facts = |staged: Option<u64>| aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: staged,
        staged_version: staged.map(|_| "0.2.0".to_string()),
        staged_commit: staged.map(|_| "ab".repeat(20)),
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    };
    let mut status = update_status(false);
    status.linux = Some(facts(Some(2)));
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 820.0));
    assert_zero_top_paint(&compiled, "wide Linux downloaded update");
    let apply = compiled
        .semantic(&UiKey::new("updates/install-now"))
        .unwrap();
    assert!(!apply.state.unwrap().enabled);
    assert!(apply.label.contains("aterm update apply"));
    // Both `[update]` switches are live: the Linux updater reads `enabled` (its
    // background checker, once per process) and `auto_apply` (each replacement).
    for key in [
        "settings/control/update.enabled",
        "settings/control/update.auto_apply",
    ] {
        let switch = compiled.semantic(&UiKey::new(key)).unwrap();
        assert!(switch.state.unwrap().enabled, "{key} is live on Linux");
    }

    let mut trial = facts(None);
    trial.installed_build = 2;
    trial.trial_phase = Some("Installed".into());
    trial.trial_starts = 1;
    let mut attention = update_status(false);
    attention.linux = Some(facts(None));
    attention.failing_checks = 1;
    attention.outcome = "linux-update: GitHub answered 503 Service Unavailable while \
                         listing releases for alabsystems/aterm"
        .into();
    let mut states = Vec::new();
    for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
        for (name, linux) in [("idle", facts(None)), ("downloaded", facts(Some(2)))] {
            let mut status = update_status(false);
            status.linux = Some(linux);
            states.push((
                format!("{name} r{running} s{saved}"),
                status,
                running,
                saved,
            ));
        }
    }
    let mut pending = update_status(false);
    pending.linux = Some(trial);
    states.push(("trial r0 s0".to_string(), pending, false, false));
    states.push(("attention".to_string(), attention, true, true));

    let mut measured_linux_faces = false;
    let mut revision = 1;
    for face in [
        LinuxLayoutFace::Host,
        LinuxLayoutFace::LinuxLadder,
        LinuxLayoutFace::NoUiFace,
    ] {
        for (state, status, running, saved) in &states {
            revision += 1;
            assert!(
                runtime.replace_settings_update(
                    UpdateState::from_status(1, "0.1.0", Some(status), false)
                        .with_automatic_checks(*running, *saved),
                    revision,
                )
            );
            for (size, width, height) in [
                ("wide", 1_200.0, 820.0),
                ("medium", 849.0, 513.0),
                ("compact", 600.0, 820.0),
                ("short compact", 600.0, 560.0),
            ] {
                let Some(cx) = linux_layout_cx(face, width, height) else {
                    continue;
                };
                measured_linux_faces |= face == LinuxLayoutFace::LinuxLadder;
                let context = format!("{face:?} {size} Linux {state}");
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if face == LinuxLayoutFace::NoUiFace {
                    // The approximation is wider than any face, so a line may
                    // ellipsize; a card may not outgrow its section.
                    let clipped = compiled
                        .paint_audit_lines()
                        .into_iter()
                        .filter(|line| {
                            line.contains("clipped=true") && line.contains("key=\"updates/")
                        })
                        .collect::<Vec<_>>();
                    assert!(
                        clipped.is_empty(),
                        "{context}: a card outgrows its section:\n{}",
                        clipped.join("\n")
                    );
                } else {
                    assert_zero_top_paint(&compiled, &context);
                }
            }
        }
    }
    if !measured_linux_faces {
        crate::logging::stderr_line!(
            "NOTICE: the Linux UI faces (Noto Sans, DejaVu Sans) are not readable on this \
             host, so the Linux update page was measured in the host's face and with no UI \
             face only; point ATERM_TEST_LINUX_UI_FONTS at a directory holding \
             NotoSans-Regular.ttf and NotoSans-Bold.ttf to measure it in Linux's own"
        );
    }
}

/// Every screen of the Software Update route in a `width`×`height` window, top to
/// the last one its list scrolls to. A fresh runtime per walk, so it measures in
/// the host's face.
fn update_route_pages(
    update: UpdateState,
    width: f32,
    height: f32,
) -> Vec<crate::native_ui::CompiledUi> {
    let (mut runtime, instance, view) = setup_with_update(update);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx_at(width, height);
    let mut screens = Vec::new();
    each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
        screens.push(compiled.clone());
    });
    screens
}

/// The text a compiled page paints (semantic labels keep complete sentences).
fn painted_texts(compiled: &crate::native_ui::CompiledUi) -> Vec<String> {
    compiled
        .paint
        .iter()
        .filter_map(|node| match &node.content {
            UiContent::Text(text) => Some(text.text.clone()),
            _ => None,
        })
        .collect()
}

/// The macOS status card fits its section beside a failed check under every switch
/// state: it steps its outcome, then its detail, down to the section it is windowed
/// into. Checked for the four running/saved pairs at the wide, medium and compact
/// widths and the short phone, in the host's face (clean) and with no UI face (no card
/// outgrows its section); the failed check's cause stays on the desktop page.
#[test]
fn the_status_card_fits_its_section_beside_a_failed_check_under_every_switch_state() {
    let outcome = "check failed (network): error sending request for url \
                   (https://api.github.com/repos/alabsystems/aterm/releases?per_page=20): \
                   operation timed out";
    let failed_check = |running: bool, saved: bool| {
        let mut status = update_status(false);
        status.failing_checks = 1;
        status.failing_kind = "network".into();
        status.failing_checks_kind = "network".into();
        status.outcome = outcome.into();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved)
    };
    let (mut runtime, instance, view) = setup_with_update(failed_check(true, true));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let mut revision = 1;
    for face in [LinuxLayoutFace::Host, LinuxLayoutFace::NoUiFace] {
        for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
            revision += 1;
            let state = failed_check(running, saved);
            let projection = state.projection();
            assert!(
                !projection.failing_persistent && update_outcome_line(&projection).is_some(),
                "the fixture is one failed check, a non-routine outcome the card paints"
            );
            assert!(runtime.replace_settings_update(state, revision));
            for (size, width, height) in [
                ("wide", 1_200.0, 820.0),
                ("medium", 849.0, 513.0),
                ("compact", 600.0, 820.0),
                ("short compact", 600.0, 560.0),
            ] {
                let Some(cx) = linux_layout_cx(face, width, height) else {
                    continue;
                };
                let context = format!("{face:?} {size} macOS r{running} s{saved}");
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if face == LinuxLayoutFace::NoUiFace {
                    let clipped = compiled
                        .paint_audit_lines()
                        .into_iter()
                        .filter(|line| {
                            line.contains("clipped=true") && line.contains("key=\"updates/")
                        })
                        .collect::<Vec<_>>();
                    assert!(
                        clipped.is_empty(),
                        "{context}: a card outgrows its section:\n{}",
                        clipped.join("\n")
                    );
                } else {
                    assert_zero_top_paint(&compiled, &context);
                }
                if matches!(size, "wide" | "medium") {
                    let painted = compiled
                        .semantic(&UiKey::new("updates/outcome"))
                        .unwrap_or_else(|| {
                            panic!("{context}: the failed check's cause stays on the card")
                        });
                    assert_eq!(painted.label, outcome, "{context}");
                }
            }
        }
    }
}

/// With the automatic-checks switch saved one way and running the other (or off both
/// ways), its timing sentence and "Checked N ago." both paint on the status card's
/// first page, inside the section, at the wide and medium workbenches, the compact
/// page and the short phone.
#[test]
fn the_checked_line_paints_beside_the_switch_sentence_at_every_width() {
    let state = |running: bool, saved: bool| {
        let mut status = update_status(false);
        status.updated_at = "2026-01-01T00:00:00Z".to_string();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved)
    };
    for (running, saved) in [(true, false), (false, true), (false, false)] {
        for (size, width, height) in [
            ("wide", 1_200.0, 820.0),
            ("medium", 849.0, 513.0),
            ("compact", 600.0, 820.0),
            ("short compact", 600.0, 560.0),
        ] {
            let context = format!("{size} r{running} s{saved}");
            let pages = update_route_pages(state(running, saved), width, height);
            let first = &pages[0];
            assert_zero_top_paint(first, &context);
            let painted = painted_texts(first)
                .join(" ")
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ");
            assert!(
                painted.contains("Checked "),
                "{context}: the last check paints beside the switch's sentence: {painted}"
            );
        }
    }
}

/// A Linux page in the short-landscape pager still paints a failed check's cause: the
/// full card carries the outcome in its detail, but the pager's summary says only
/// "See terminal status", so the outcome's own section is where the cause paints.
#[test]
fn a_linux_short_landscape_page_paints_a_failed_checks_cause() {
    let cause = "linux-update: GitHub answered 503 Service Unavailable while listing \
                 releases for alabsystems/aterm";
    let failed_check = || {
        let mut status = update_status(false);
        status.linux = Some(aterm_update::LinuxUpdateStatus {
            installed_build: 1,
            installed_version: String::new(),
            staged_build: None,
            staged_version: None,
            staged_commit: None,
            trial_phase: None,
            trial_starts: 0,
            trial_healthy: false,
            refused_newer: false,
        });
        status.failing_checks = 1;
        status.outcome = cause.into();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
    };
    let projection = failed_check().projection();
    assert!(projection.linux_host && projection.linux_attention);

    // The full card: the detail carries the cause, so it paints once.
    let medium = update_route_pages(failed_check(), 849.0, 513.0);
    let first = &medium[0];
    assert!(
        first.semantic(&UiKey::new("updates/outcome")).is_none(),
        "the Linux status card does not repeat the outcome its detail carries"
    );
    assert!(
        first
            .semantic(&UiKey::new("updates/detail"))
            .is_some_and(|detail| detail.label.contains("503")),
        "the Linux detail carries the cause"
    );

    // The short landscape list: the cause takes a stop of its own.
    let pages = update_route_pages(failed_check(), 568.0, 320.0);
    let painted = pages.iter().flat_map(painted_texts).collect::<Vec<_>>();
    assert!(
        painted
            .iter()
            .any(|text| text.starts_with("linux-update:") && text.contains("503")),
        "some screen of the short-landscape list paints the failed check's cause: \
         {painted:?}"
    );
    for (index, page) in pages.iter().enumerate() {
        assert_zero_top_paint(page, &format!("short-landscape Linux page {index}"));
    }
}

/// The compact rungs never call a page current while nothing checks: the compact
/// headline, short-landscape summary and tersest detail carry the running switch
/// value (a saved flip applies next launch), below every trouble arm, as the full
/// headline does.
#[test]
fn compact_update_rungs_never_call_a_page_current_while_checks_are_off() {
    let healthy = |running: bool, saved: bool| {
        UpdateState::from_status(1, "0.1.0", Some(&update_status(false)), false)
            .with_automatic_checks(running, saved)
    };
    let words = |projection: &UpdateProjection| {
        (
            compact_update_headline(projection),
            compact_update_summary_detail(projection).to_string(),
            compact_update_detail_minimum(projection),
        )
    };
    let current = words(&healthy(true, true).projection());
    let off = words(&healthy(false, false).projection());
    assert_ne!(current.0, off.0);
    assert_ne!(current.1, off.1);
    assert_ne!(current.2, off.2);
    for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
        let projection = healthy(running, saved).projection();
        let context = format!("r{running} s{saved}");
        assert_eq!(projection.automatic_checks, running, "{context}");
        assert_eq!(
            words(&projection),
            if running {
                current.clone()
            } else {
                off.clone()
            },
            "{context}: the rungs carry the RUNNING value"
        );
        // Painted, in the short-landscape summary the review measured: at the
        // platform maximum Dynamic Type, where the full card cannot fit its list.
        at_each_text_scale(&[2.0], "short-landscape summary rungs", |_| {
            let painted = update_route_pages(healthy(running, saved), 568.0, 320.0)
                .iter()
                .flat_map(painted_texts)
                .collect::<Vec<_>>();
            assert!(
                painted
                    .iter()
                    .any(|text| text == &current.0 || text == &off.0),
                "{context}: the summary paints its headline rung: {painted:?}"
            );
            let claims_current = painted
                .iter()
                .any(|text| text == "Current" || text.starts_with("Up to date"));
            assert_eq!(claims_current, running, "{context}: {painted:?}");
        });
    }

    // Trouble still outranks the switch.
    let mut failing = update_status(false);
    failing.failing_checks = aterm_update::PERSISTENT_AFTER;
    failing.failing_persistent = true;
    failing.failing_kind = "network".into();
    let failing = UpdateState::from_status(1, "0.1.0", Some(&failing), false)
        .with_automatic_checks(false, false)
        .projection();
    let failing = words(&failing);
    assert_ne!(failing.0, off.0);
    assert_ne!(failing.1, off.1);

    // A stranded channel is not "Up to date" in the summary either.
    let mut stranded = update_status(false);
    stranded.channel_unreadable = true;
    let stranded =
        words(&UpdateState::from_status(1, "0.1.0", Some(&stranded), false).projection());
    assert_ne!(stranded.0, current.0);
    assert_ne!(stranded.1, current.1);

    // An idle Linux copy says so too, below its disk and trouble facts.
    let mut linux = update_status(false);
    linux.linux = Some(aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: None,
        staged_version: None,
        staged_commit: None,
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    });
    let idle = |running: bool| {
        compact_update_headline(
            &UpdateState::from_status(1, "0.1.0", Some(&linux), false)
                .with_automatic_checks(running, running)
                .projection(),
        )
    };
    assert_ne!(idle(true), idle(false));
    assert_eq!(idle(false), off.0);
}

/// A COPY WITH NO IN-APP UPDATER IS TOLD HOW IT UPDATES WITHOUT A PATH (s-10): every
/// such copy is built from its owner's checkout, and which scripts a checkout has
/// differs between a development checkout and the public snapshot, so the detail line
/// names no file or folder (only `aterm help update` spells the commands out) and
/// still fits the Medium workbench's one-line slot. Runs on every host: the page is
/// built for a Windows availability directly, not by `cfg`. Neither macOS nor Windows
/// on a Linux host is Linux, which runs its own updater: there the same copy is never
/// told it has none. Which arm a platform takes is this test's own fact (the host's
/// `cfg`), not the page's, so a page that loses Linux's updater fails here.
#[test]
fn a_copy_without_an_updater_is_told_its_lane_in_one_path_free_line() {
    fn says(node: &UiNode, words: &str) -> bool {
        matches!(&node.content, UiContent::Text(spec) if spec.text.contains(words))
            || node.children.iter().any(|child| says(child, words))
    }
    let mut status = update_status(false);
    status.enabled = false;
    let update = UpdateState::from_status(1, "0.1.0", Some(&status), false).projection();
    assert!(!update.linux_host && !update.enabled);
    let mut state = SettingsViewState::new(&Config::default());
    state.navigate(SettingsRoute::SoftwareUpdate);
    for windows in [true, false] {
        let availability = SettingsAvailability {
            macos: false,
            windows,
            ..audited_availability()
        };
        if cfg!(target_os = "linux") && !windows {
            let (page, _) = update_page(
                &state,
                &update,
                availability,
                SettingsWidth::Wide,
                1_200.0,
                820.0,
            );
            assert!(
                !page.iter().any(|node| {
                    says(node, "No in-app updater here.") || says(node, PLATFORM_UPDATE_LANE)
                }),
                "windows={windows}: a platform with an updater is not told it has none"
            );
            continue;
        }
        for (variant, width, w, h) in [
            ("medium", SettingsWidth::Medium, 849.0, 513.0),
            ("wide", SettingsWidth::Wide, 1_200.0, 820.0),
        ] {
            let (page, _) = update_page(&state, &update, availability, width, w, h);
            let detail = node_by_key(&page, "updates/detail")
                .unwrap_or_else(|| panic!("{variant}: the status card has its detail line"));
            let text = match &detail.content {
                UiContent::Text(spec) => spec.text.clone(),
                UiContent::Group(group) => {
                    assert!(
                        detail.children.len() <= 1,
                        "{variant}: the lane is one line, not {}",
                        detail.children.len()
                    );
                    group
                        .label
                        .clone()
                        .expect("the detail carries its sentence")
                }
                other => panic!("{variant}: {other:?}"),
            };
            assert!(
                !text.contains('/') && !text.contains('\\'),
                "{variant} windows={windows}: a Settings sentence names no source path: {text:?}"
            );
            assert!(
                text.contains("checkout"),
                "{variant} windows={windows}: the lane is the owner's checkout: {text:?}"
            );
            let root = UiNode::new(
                "test/page",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::column().width(Length::Fill).height(Length::Fill))
            .children(page);
            let compiled = UiTree::new(root)
                .compile(LogicalRect::new(0.0, 0.0, w, h))
                .expect("the page compiles");
            let fit = compiled
                .text_fit_audit_line(&UiKey::new("updates/detail/line-0"))
                .unwrap_or_else(|| panic!("{variant}: the lane is painted"));
            assert!(
                fit.contains(" overflow=false "),
                "{variant}: the lane's one line holds its card: {fit}"
            );
        }
    }
}

/// SOFTWARE UPDATE NAMES ITSELF ONCE: under the page heading — its row, or the
/// compact toolbar's title — the status card carries no "Software Update" caption
/// of its own (the 102x29 and 80x24 windows painted it twice); only a window
/// where nothing else names the page (too short for the heading row, too narrow
/// for the toolbar's title: `page_named`) lets the card name the page, in the
/// caption case every card caption is painted in.
#[test]
fn software_update_names_itself_once() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let title = |compiled: &crate::native_ui::CompiledUi| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == "updates/title")
            .map(|node| match &node.content {
                UiContent::Text(text) => text.text.clone(),
                other => panic!("{other:?}"),
            })
    };
    for (width, height) in [(738.0, 420.0), (584.0, 350.0), (1_074.0, 684.0)] {
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
        assert!(
            compiled
                .semantic(&UiKey::new("settings/page-heading/software-update"))
                .is_some(),
            "{width}x{height}: the page heading"
        );
        assert_eq!(title(&compiled), None, "{width}x{height}");
    }
    // A short window's toolbar names the page, so the card does not.
    let short = compile_settings_view(&runtime, instance, view, &view_cx_at(584.0, 210.0));
    let toolbar = short
        .semantic(&UiKey::new("settings/compact-toolbar"))
        .expect("the toolbar")
        .rect;
    let heading = short
        .semantic(&UiKey::new("settings/page-heading/software-update"))
        .expect("584x210: the toolbar's title");
    assert!(
        heading.rect.bottom() <= toolbar.bottom() + 0.5,
        "584x210: the title is in the toolbar: {:?} in {toolbar:?}",
        heading.rect
    );
    assert_eq!(title(&short), None, "584x210");
    let narrow = view_cx_at(320.0, 210.0);
    let compiled = compile_settings_view(&runtime, instance, view, &narrow);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/page-heading/software-update"))
            .is_none(),
        "a window too short for the heading row and too narrow for the toolbar's title"
    );
    assert!(
        title(&compiled).is_some_and(|text| text == text.to_uppercase() && !text.is_empty()),
        "{:?}",
        title(&compiled)
    );
}

/// A SEARCH SAYS WHOLE WHAT THE UPDATE SWITCHES DO IN A COPY THAT CAN'T UPDATE:
/// with both switches written (Changed, Reset) in a copy that can't replace
/// itself, each search result paints its name, Changed and its note — the cause
/// first, then "no effect" — without cutting any of it off, at every window down to
/// 80x24: on the label line where it fits, else whole on the row's second line
/// (`row_label_line`), searched from a form page whose 720pt column stops growing at
/// 150 columns.
///
/// Unix only: the switches are Settings rows, and so search results, where a
/// native updater reads them (`native_advanced_effect`: macOS and Linux);
/// elsewhere Software Update shows them disabled and search names their keys.
#[cfg(unix)]
#[test]
fn a_search_paints_the_update_switches_notes_whole() {
    let mut status = update_status(false);
    status.installable = false;
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    replace_settings_source(
        &mut runtime,
        view,
        "[update]\nenabled = false\nauto_apply = false\n".to_string(),
    );
    for (id, value) in [
        (route_action(SettingsRoute::Security), None),
        (
            ActionId::new("settings/search"),
            Some(SemanticInput::Text("automatically".to_string())),
        ),
    ] {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation { id, value }),
            )
            .unwrap();
    }
    let note = NoEffectCause::CopyCantUpdate.disclosure().visual;
    for (width, height) in [
        (584.0, 350.0),
        (1_074.0, 684.0),
        (1_193.0, 516.0),
        (1_564.0, 854.0),
    ] {
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
        for key in [prefs::EDIT_UPDATE_ENABLED, "update.auto_apply"] {
            let label = format!("settings/label/{key}/visual/line-");
            let detail = format!("settings/detail/{key}/line-");
            let painted = compiled
                .paint
                .iter()
                .filter(|node| {
                    node.key.as_str().starts_with(&label) || node.key.as_str().starts_with(&detail)
                })
                .filter_map(|node| match &node.content {
                    UiContent::Text(text) => Some(text.text.clone()),
                    _ => None,
                })
                .collect::<Vec<_>>();
            if painted.is_empty() && width < 600.0 {
                // Below the fold of the compact search's first screen.
                continue;
            }
            let painted = painted.join(" ");
            assert!(
                painted.contains(CHANGED_WORD) && painted.contains(note.as_str()),
                "{key} at {width}x{height}: {painted}"
            );
        }
        let cut = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| {
                line.contains("key=\"settings/label/update.")
                    || line.contains("key=\"settings/detail/update.")
            })
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .collect::<Vec<_>>();
        assert!(cut.is_empty(), "{width}x{height}:\n{}", cut.join("\n"));
    }
}

/// A healthy update page: "You're up to date." over "aterm 0.1.0" and when it last
/// checked; no build number (About has it) and no updater decision sentence (its
/// cadence stays in `aterm ctl update status` and the log).
#[test]
fn a_healthy_update_page_paints_the_version_and_when_it_checked() {
    let mut status = update_status(false);
    // The decision sentence the updater writes (`github::cadence_note`).
    status.outcome = "up to date (latest release build 1) \u{b7} checks every 30 min".to_string();
    status.updated_at =
        aterm_types::rfc3339::format_rfc3339(aterm_time::unix_secs().unwrap() - 12 * 60);
    let state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
    assert_eq!(update_outcome_line(&state.projection()), None);
    let (mut runtime, instance, view) = setup_with_update(state);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_224.0, 722.0));
    assert!(compiled.semantic(&UiKey::new("updates/current")).is_some());
    assert!(
        compiled
            .semantics
            .iter()
            .all(|node| !node.key.as_str().starts_with("updates/outcome")),
        "a healthy decision authors no outcome row"
    );
    // A non-routine outcome the page does not otherwise say still gets its line.
    status.outcome = "no release carries an update manifest".to_string();
    let projection = UpdateState::from_status(1, "0.1.0", Some(&status), false).projection();
    assert_eq!(
        update_outcome_line(&projection).as_deref(),
        Some("no release carries an update manifest")
    );
}

/// The notes card says "newest version" only after a comparison: not for a stranded
/// machine (zero ledger failures, past the failing arm) nor a copy no check has
/// completed on. A persistent failure whose checks work (an install streak) never
/// says checks can't run. Negative control: a checked, healthy page says "newest".
#[test]
fn the_notes_card_says_newest_only_after_a_check() {
    let notes = |edit: &dyn Fn(&mut aterm_update::UpdateStatus)| {
        let mut status = update_status(false);
        status.updated_at = "2026-09-23T12:00:00Z".to_string();
        edit(&mut status);
        update_notes_lines(&UpdateState::from_status(1, "0.1.0", Some(&status), false).projection())
            .join(" ")
    };
    let newest = notes(&|_| {});
    let only_when_ready = notes(&|s| s.channel_unreadable = true);
    assert_ne!(
        newest, only_when_ready,
        "a checked, healthy page says newest"
    );
    assert_eq!(notes(&|s| s.updated_at = String::new()), only_when_ready);
    assert_eq!(
        notes(&|s| {
            s.failing_persistent = true;
            s.failing_kind = "apply".into();
            s.failing_applies = 3;
        }),
        only_when_ready
    );
    let unavailable = notes(&|s| {
        s.enabled = false;
        s.updated_at = String::new();
    });
    assert_ne!(unavailable, newest);
    assert_ne!(unavailable, only_when_ready);
}

#[test]
fn desktop_and_compact_update_pages_fit_wrapped_long_notes_and_outcome() {
    let mut status = update_status(true);
    status.changelog = Some(
        (0..48)
            .map(|index| {
                format!(
                    "{}- Change {index}: {}{} {}",
                    if index == 0 { "\t  " } else { "" },
                    "retained native Settings copy stays reachable and measurable across every renderer-authored page; ".repeat(3),
                    if index == 1 { "\u{2003}\u{2003}" } else { "" },
                    if index == 0 { "終".repeat(160) } else { format!("tail-{index}") },
                )
            })
            .collect::<Vec<_>>()
            .join("\n"),
    );
    status.outcome = "\t  The update is still ready; the install stopped: live terminals and visible screens remain attached;\u{2003}\u{2003}review the sessions before retrying the handoff.\n\nThe protected live-PTY and visible-screen handoff keeps every session running until an explicit retry is safe."
        .to_string();
    let expected_outcome = status.outcome.clone();
    let without_whitespace = |text: &str| {
        text.chars()
            .filter(|character| !character.is_whitespace())
            .collect::<String>()
    };

    for (variant, viewport_width, viewport_height) in
        [("desktop", 1_224.0, 722.0), ("compact", 568.0, 658.0)]
    {
        let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
        let expected_notes = update_state.projection().changelog.join("\n");
        let (mut runtime, instance, view) = setup_with_update(update_state);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let cx = view_cx_at(viewport_width, viewport_height);

        let mut saw_notes = false;
        // Each notes row's painted text and spoken text, in the order the list
        // reaches them: a row on two screens is read once.
        let mut notes_cards: Vec<(UiKey, String, String)> = Vec::new();
        let mut saw_outcome = false;
        let mut painted_outcome = String::new();
        let mut outcome_line_keys = BTreeSet::new();
        let screens = each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            assert_zero_top_paint(compiled, &format!("{variant} Update screen {top}"));
            let mut screen_outcome = String::new();
            let mut screen_lines = BTreeSet::new();
            for node in &compiled.paint {
                if node.key.as_str().starts_with("updates/release-notes")
                    && let UiContent::RichText(spec) = &node.content
                {
                    saw_notes = true;
                    // Each row says exactly the words it paints (s-25): never
                    // the whole changelog once per chunk.
                    assert_eq!(
                        without_whitespace(&spec.semantic_text),
                        without_whitespace(&spec.text),
                        "{variant}: a notes row speaks what it paints",
                    );
                    if !notes_cards.iter().any(|(key, ..)| *key == node.key) {
                        notes_cards.push((
                            node.key.clone(),
                            spec.text.clone(),
                            spec.semantic_text.clone(),
                        ));
                    }
                }
                if node.key.as_str().starts_with("updates/outcome/line-")
                    && let UiContent::Text(spec) = &node.content
                {
                    assert!(
                        screen_lines.insert(node.key.clone()),
                        "{variant}: outcome lines need unique stable keys",
                    );
                    assert!(
                        crate::tray_raster::ui_text_width(
                            &spec.text,
                            11.0 * crate::native_appearance::text_scale(),
                        ) <= node.rect.width + 0.5,
                        "{variant}: outcome line {:?} exceeds its authored rect",
                        node.key,
                    );
                    screen_outcome.push_str(&spec.text);
                }
            }
            if !screen_lines.is_empty() && outcome_line_keys.is_empty() {
                outcome_line_keys = screen_lines;
                painted_outcome = screen_outcome;
            }
            if let Some(outcome) = compiled
                .semantics
                .iter()
                .find(|node| node.key.as_str().starts_with("updates/outcome"))
            {
                saw_outcome = true;
                assert_eq!(outcome.label, expected_outcome);
            }
        });
        assert!(screens >= 2, "{variant}: long notes scroll");
        let painted_notes: String = notes_cards
            .iter()
            .map(|(_, text, _)| text.as_str())
            .collect();
        let spoken_notes: String = notes_cards.iter().map(|(.., said)| said.as_str()).collect();
        assert!(saw_notes, "{variant}: release-note rows remain reachable");
        assert_eq!(
            without_whitespace(&painted_notes),
            without_whitespace(&expected_notes),
            "{variant}: the release-note rows must not drop visible content",
        );
        assert_eq!(
            without_whitespace(&spoken_notes),
            without_whitespace(&expected_notes),
            "{variant}: read row by row, the notes are said once, whole",
        );
        assert!(saw_outcome, "{variant}: the outcome remains reachable");
        assert!(
            !outcome_line_keys.is_empty(),
            "{variant}: outcome must use inspectable per-line paint nodes",
        );
        // The outcome is a bounded summary inside the status card: a few lines,
        // elided rather than dropped, the exact ledger string on the semantic parent
        // above; it never scrambles or reorders what it shows.
        assert!(
            outcome_line_keys.len() <= MAX_UPDATE_OUTCOME_LINES,
            "{variant}: outcome is bounded to {MAX_UPDATE_OUTCOME_LINES} lines, saw {}",
            outcome_line_keys.len(),
        );
        let painted = without_whitespace(&painted_outcome);
        let complete =
            without_whitespace(&expected_outcome.split('\n').collect::<Vec<_>>().join(" "));
        let shown = painted.trim_end_matches('\u{2026}');
        assert!(
            complete.starts_with(shown) && !shown.is_empty(),
            "{variant}: the visible outcome is an exact leading run of the real one\n  shown: {shown}\n  whole: {complete}",
        );
    }
}

/// Widest UI-face text in an authored subtree, measured as `native_ui`'s paint audit
/// measures a Body-step `Text` node (every `updates/outcome/line-*` is one). Returns
/// `(required width, box given, key)`, applying the compiler's padding arithmetic, so
/// the answer is the painted measure.
fn widest_authored_text(node: &UiNode, width: f32) -> Option<(f32, f32, String)> {
    let inner = (width - node.layout.padding.left - node.layout.padding.right).max(0.0);
    let px = 13.0 * crate::native_appearance::text_scale();
    let face = crate::widget::TextFace::Ui;
    let mut worst = match &node.content {
        UiContent::Text(spec) => {
            let required = crate::tray_raster::ui_text_width_for(face, &spec.text, px);
            Some((required, width, node.key.as_str().to_string()))
        }
        _ => None,
    };
    for child in &node.children {
        let Some(found) = widest_authored_text(child, inner) else {
            continue;
        };
        let worse = match &worst {
            Some((required, available, _)) => found.0 - found.1 > required - available,
            None => true,
        };
        if worse {
            worst = Some(found);
        }
    }
    worst
}

/// Measure equals paint for the compact updater-outcome card at every text scale: the
/// measure its prose wraps to is the box its own insets leave. The release-notes
/// measure ([`update_release_notes_padding`], 14pt above 1.25×) differs from the
/// card's 16pt inset, so wrapping to it lets a greedy line paint past the edge. The
/// box is read off the node's own padding, so re-padding without re-measuring fails
/// at 1× too.
#[test]
fn compact_update_outcome_wraps_to_the_box_it_paints_in() {
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    let restore = crate::native_appearance::current_preferences();
    let mut status = update_status(true);
    // Long enough to wrap at every scale, so no width passes for want of a break.
    status.outcome =
        "The protected live terminal remains attached until the verified handoff retries."
            .to_string();
    let projection = UpdateState::from_status(1, "0.1.0", Some(&status), false).projection();

    for scale in [0.85_f32, 1.0, 1.25, 1.5, 1.75, 2.0] {
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale: scale,
                ..restore
            },
        );
        // 294.0 is the short-landscape section width (568×320 at 2×).
        for card_width in [180.0_f32, 240.0, 294.0, 360.0, 480.0, 620.0] {
            let (card, _) = compact_update_outcome(&projection, card_width)
                .expect("a non-routine outcome authors the card");
            // The font-independent half: the wrap measure is the box the insets
            // leave. Whether a greedy break lands in a gap depends on the UI face.
            let insets = card.layout.padding.left + card.layout.padding.right;
            assert_eq!(
                compact_update_outcome_text_width(card_width),
                card_width - insets,
                "{scale}x card {card_width}: wrap measure vs authored box",
            );
            let (required, available, key) =
                widest_authored_text(&card, card_width).expect("the card paints its wrapped lines");
            // The paint audit's overflow predicate (`native_ui::finish_text_fit`).
            assert!(
                required <= available + 0.5,
                "{scale}x card {card_width}: {key} wraps to \
                 {required:.1} in a {available:.1} box",
            );
        }
    }
    crate::native_appearance::install_preferences(restore);
}

/// Every section of the Update page stays reachable, complete and overflow-free at
/// the platform maximum Dynamic Type in short landscape: the updater outcome (one
/// line inside the status card) surfaces exactly once and fits, beside the page's two
/// controls.
#[test]
fn maximum_type_landscape_update_sections_are_complete() {
    at_each_text_scale(
        &[2.0],
        "2x Update section audit",
        maximum_type_landscape_update_sections_are_complete_at_scale,
    );
}

/// The body of [`maximum_type_landscape_update_sections_are_complete`].
fn maximum_type_landscape_update_sections_are_complete_at_scale(_scale: f32) {
    let mut status = update_status(true);
    status.outcome =
        "The protected live terminal remains attached until the verified handoff retries."
            .to_string();
    let expected_outcome = status.outcome.clone();
    let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
    let (mut runtime, instance, view) = setup_with_update(update_state);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();

    let cx = view_cx_at(568.0, 320.0);
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(compact_page_budget(state, cx.viewport).side_by_side_pager);

    let mut keys = BTreeSet::new();
    let mut saw_outcome = false;
    each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
        let context = format!("2x landscape Update screen {top}");
        compiled
            .validate_parity()
            .unwrap_or_else(|error| panic!("{context}: {error:?}"));
        assert_short_landscape_geometry(compiled, 2.0, &context);
        assert_zero_top_paint(compiled, &context);

        if let Some(hero) = compiled.semantic(&UiKey::new("updates/hero")) {
            assert_eq!(hero.role, SemanticRole::Status, "{context}: hero is Status");
        }
        // Whichever screen it lands on, the outcome keeps the exact ledger
        // string on its semantic node; the paint is bounded.
        if let Some(outcome) = compiled.semantic(&UiKey::new("updates/outcome")) {
            assert_eq!(
                outcome.label, expected_outcome,
                "{context}: exact updater outcome retained",
            );
            saw_outcome = true;
        }
        keys.extend(
            compiled
                .semantics
                .iter()
                .filter(|node| {
                    node.key.as_str().starts_with("updates/")
                        || node.key.as_str().starts_with("settings/control/update.")
                })
                .map(|node| node.key.as_str().to_string()),
        );
    });
    assert!(saw_outcome, "the outcome is reachable");
    // Both `[update]` switches, whole: the list lays the card out switch by
    // switch.
    for key in [
        "updates/hero",
        "updates/install-now",
        "updates/automatic",
        "settings/control/update.enabled",
        "settings/control/update.auto_apply",
        "updates/release-notes",
    ] {
        assert!(
            keys.contains(key),
            "2x landscape Update never reached {key}; saw {keys:?}",
        );
    }
}

/// 2026-08 settings audit: navigating Home → an ordinary form page moved
/// the content column ~130pt because each page centered around its OWN
/// route maximum. Sibling pages of one rail must share a left edge; the
/// narrower page keeps its deliberate width by yielding on the right.
/// THE MEASURE FOLLOWS THE LAYOUT, NOT THE ROUTE: every single-column page —
/// a form page, Harness, Packages, Messages, About, Search Results, a Top
/// Settings that stacks its cards — shares one content width, so a row is as
/// wide on Search Results as on its own page and the right edge holds still;
/// only cards that sit side by side (the Top grid) or the Themes gallery are
/// wider. NEGATIVE CONTROL: the route table this replaced gave Harness and
/// Search Results 1000pt beside Appearance's 720 at 1564x852, and Home's
/// stacked cards 897pt at 1193x516.
#[test]
fn content_width_follows_the_layout_not_the_route() {
    for (width, height) in [
        (1_564.0, 852.0),
        (1_193.0, 516.0),
        (1_275.0, 828.0),
        (976.0, 684.0),
    ] {
        let cx = view_cx_at(width, height);
        let content = |route: SettingsRoute, search: &str| {
            let (mut runtime, instance, view) = setup();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(route),
                        value: None,
                    }),
                )
                .unwrap();
            if !search.is_empty() {
                runtime
                    .dispatch(
                        instance,
                        view,
                        AppEvent::Action(ActionInvocation {
                            id: ActionId::new("settings/search"),
                            value: Some(SemanticInput::Text(search.to_string())),
                        }),
                    )
                    .unwrap();
            }
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let page = compiled
                .paint
                .iter()
                .find(|node| {
                    let key = node.key.as_str();
                    key.starts_with("settings/page/") || key == "settings/page/search-results"
                })
                .unwrap_or_else(|| panic!("{route:?} draws a page"));
            let UiContent::Group(_) = &page.content else {
                panic!("a page group")
            };
            // The page's column: its rect less the frame's insets, read off
            // the leading heading (About leads with its hero card).
            let lead = compiled
                .paint
                .iter()
                .find(|node| {
                    node.key.as_str().starts_with("settings/page-heading/")
                        || node.key.as_str() == "about/hero"
                })
                .unwrap_or_else(|| panic!("{route:?} leads with a heading"))
                .rect;
            (lead.width, compiled)
        };
        let (form, _) = content(SettingsRoute::Appearance, "");
        let context = |what: &str| format!("{what} at {width}x{height}");
        for route in [
            SettingsRoute::Modified,
            SettingsRoute::Terminal,
            SettingsRoute::Security,
            SettingsRoute::Harness,
            SettingsRoute::Packages,
            SettingsRoute::Messages,
            SettingsRoute::About,
            SettingsRoute::Manual,
        ] {
            let (column, _) = content(route, "");
            assert!(
                (column - form).abs() <= 0.5,
                "{}: {column} against the form's {form}",
                context(&format!("{route:?}"))
            );
        }
        // Search Results is the same form whatever page it was typed on.
        for route in [SettingsRoute::Security, SettingsRoute::About] {
            let (column, compiled) = content(route, "cursor");
            assert!(
                (column - form).abs() <= 0.5,
                "{}: {column} against {form}",
                context(&format!("search from {route:?}"))
            );
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/page/search-results"))
                    .is_some(),
                "premise: Search Results"
            );
        }
        // Top Settings is wider only while its cards sit side by side.
        let (home, compiled) = content(SettingsRoute::Home, "");
        if compiled
            .semantic(&UiKey::new("settings/top/grid"))
            .is_some()
        {
            assert!(home > form + 0.5, "{}", context("the Top grid"));
        } else {
            assert!(
                (home - form).abs() <= 0.5,
                "{}: stacked cards {home} against {form}",
                context("Top Settings")
            );
        }
        if (width, height) == (1_193.0, 516.0) {
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/top/grid"))
                    .is_none(),
                "premise: a short window stacks Top Settings' cards"
            );
        }
    }
}

#[test]
fn rail_sibling_pages_share_one_content_left_edge() {
    let (mut runtime, instance, view) = setup();
    let cx = view_cx_at(1_275.0, 828.0);
    let mut heading = |route: SettingsRoute| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(route),
                    value: None,
                }),
            )
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled
            .paint
            .iter()
            .find(|node| {
                // The About page leads with its hero card instead of the
                // shared page heading; both start at the content column.
                node.key.as_str().starts_with("settings/page-heading/")
                    || node.key.as_str() == "about/hero"
            })
            .unwrap_or_else(|| panic!("{route:?} paints a leading content node"))
            .rect
    };
    let mut heading_x = |route: SettingsRoute| heading(route).x;
    let home = heading_x(SettingsRoute::Home);
    for route in [
        SettingsRoute::CursorStyles,
        SettingsRoute::Appearance,
        SettingsRoute::Terminal,
        SettingsRoute::SoftwareUpdate,
        SettingsRoute::About,
    ] {
        let x = heading_x(route);
        assert!(
            (x - home).abs() <= 0.5,
            "{route:?} content column starts at {x}, Home at {home}"
        );
    }
    // The Look & Feel pages share one width too, so their cards do not jump
    // as you move between them.
    let appearance = heading(SettingsRoute::Appearance).width;
    for route in [
        SettingsRoute::Wallpaper,
        SettingsRoute::TextFonts,
        SettingsRoute::CursorStyles,
        SettingsRoute::TabColor,
    ] {
        let width = heading(route).width;
        assert!(
            (width - appearance).abs() <= 0.5,
            "{route:?} content is {width}pt wide, Appearance {appearance}pt"
        );
    }
}

/// A non-code value that overflows its column wraps at its own " · " separators,
/// every token whole and every line inside the measure; code identifiers keep
/// two-ended elision.
#[test]
fn long_noncode_metadata_values_wrap_at_separators_not_mid_token() {
    let value = "trustc 1.99.0-dev (dcc900ad) · trust · release · trust_verify off";
    let width = 340.0;
    let lines = metadata_value_lines("compiler", value, width);
    assert!(lines.len() >= 2, "the audited value wraps: {lines:?}");
    assert!(lines.len() <= MAX_METADATA_VALUE_LINES);
    assert!(
        lines.iter().all(|line| !line.contains('…')),
        "no token is chopped: {lines:?}"
    );
    assert_eq!(
        lines.join(" · "),
        value,
        "the wrap is a partition of the value at its separators"
    );
    let px = 13.0 * crate::native_appearance::text_scale();
    for line in &lines {
        assert!(
            metadata_value_text_width(line, px, false) <= width + 0.01,
            "every wrapped line fits the column: {line:?}"
        );
    }
    // A short value stays one untouched line; a hash too long for its
    // column is never cut: its characters wrap in order, every line inside
    // the column, with no hyphen to read as one of them.
    assert_eq!(
        metadata_value_lines("compiler", "trustc 1.99.0", width),
        vec!["trustc 1.99.0".to_string()]
    );
    let source = "0123456789abcdef".repeat(4);
    let hash = metadata_value_lines("commit", &source, 96.0);
    assert!(hash.len() > 1, "{hash:?}");
    assert_eq!(hash.concat(), source);
    assert!(
        hash.iter()
            .all(|line| metadata_value_text_width(line, px, true) <= 96.0 + 0.01),
        "{hash:?}"
    );
    // The card buys exactly the lines it paints: its facts beside their
    // names, the compiler's lines and the signature's one.
    let rows = vec![
        ("compiler".to_string(), value.to_string()),
        ("signature".to_string(), "7a022df9673ccebb".to_string()),
    ];
    let label_width = about_metadata_label_width();
    let inner = width + label_width + ABOUT_METADATA_ROW_GAP;
    let (card, height) = metadata_card("facts", "FACTS", &rows, inner, label_width);
    let row_height = 28.0_f32.max(18.0 * settings_text_scale());
    assert_eq!(
        height,
        2.0 * ABOUT_METADATA_CARD_PADDING
            + caption_line_height()
            + (lines.len() + 1) as f32 * (row_height + 4.0),
        "card height buys exactly the painted lines"
    );
    let compiled = crate::native_ui::UiTree::new(card)
        .compile(LogicalRect::new(0.0, 0.0, inner + 36.0, height))
        .expect("the card compiles");
    let painted = compiled
        .paint
        .iter()
        .filter(|node| node.key.as_str().starts_with("facts/value/compiler"))
        .count();
    assert_eq!(painted, lines.len(), "each wrapped line is painted");
}

/// A FACT TOO LONG FOR ITS LINE WRAPS BETWEEN ITS WORDS (the review of the
/// post-landing check's Settings ▸ Harness fixes): a ` · ` part wider than
/// the column breaks between its words — never `Cruise said done 6 ti…` —
/// and takes lines of its own, the next part starting the line after it;
/// a path breaks after its `/`s and, where a piece is still too wide,
/// between that piece's words; the words read in their order, every line
/// inside the measure. NEGATIVE CONTROL: wrapping at the ` · ` joints alone
/// cuts the first part with `…`.
#[test]
fn a_long_fact_wraps_between_its_words_on_lines_of_its_own() {
    let px = 13.0 * crate::native_appearance::text_scale();
    let words = |text: &str| {
        text.replace(FACT_SEPARATOR, " ")
            .split_whitespace()
            .map(str::to_string)
            .collect::<Vec<_>>()
    };
    let value = "Cruise said done 6 times (30 s of work or more) \u{b7} Land landed 4, quiet 1 \u{b7} \
                 Land to landed: about 6m (5)";
    let width = 180.0;
    let lines = metadata_value_lines("ends", value, width);
    assert!(lines.len() >= 4, "it wraps: {lines:?}");
    assert!(lines.len() <= MAX_METADATA_VALUE_LINES, "{lines:?}");
    for line in &lines {
        assert!(!line.contains('\u{2026}'), "nothing cut: {lines:?}");
        assert!(
            metadata_value_text_width(line, px, false) <= width - ABOUT_METADATA_TEXT_SAFETY + 0.01,
            "{line:?} fits the column"
        );
    }
    assert_eq!(words(&lines.join(" ")), words(value), "in order: {lines:?}");
    assert!(lines[0].starts_with("Cruise said done"), "{lines:?}");
    assert!(
        lines.iter().any(|line| line == "Land landed 4, quiet 1"),
        "the part after a wrapped one starts its own line: {lines:?}"
    );
    assert!(
        lines.iter().any(|line| line.starts_with("Land to landed")),
        "a wrapped part starts its own line: {lines:?}"
    );
    // A path breaks after its `/`s, a piece still too wide between its
    // words.
    let path = "/Applications/aterm (dev).app (the updater leaves this copy alone)";
    let lines = metadata_value_lines("running", path, 180.0);
    assert!(lines.len() >= 2, "{lines:?}");
    assert!(
        lines.iter().all(|line| !line.contains('\u{2026}')),
        "{lines:?}"
    );
    assert_eq!(lines.concat().replace(' ', ""), path.replace(' ', ""));
    assert!(
        lines[0].starts_with("/Applications/") && !lines[0].contains(' '),
        "the path's pieces first: {lines:?}"
    );
}

/// A FACT CARD'S LABEL COLUMN GIVES WAY TO ITS VALUES' WIDEST WORD (the
/// review of the post-landing check's Settings ▸ Harness fixes): the column
/// is as wide as the card's widest label, never narrower than About's, and
/// never so wide that a value's widest word is cut — so a long label beside
/// a long word leaves the word whole, and a short value leaves the label
/// whole however long. NEGATIVE CONTROL: the label's width alone takes the
/// word's room.
#[test]
fn a_fact_label_column_leaves_its_values_widest_word_whole() {
    let px = 13.0 * crate::native_appearance::text_scale();
    let width = |text: &str| metadata_value_text_width(text, px, false);
    let label = "A label much longer than About's column holds";
    let word = "Antidisestablishmentarianism";
    let inner = 360.0;
    let rows = vec![(label.to_string(), format!("short {word} words"))];
    let column = fact_label_width(&rows, inner);
    let value_width = inner - column - ABOUT_METADATA_ROW_GAP;
    assert!(
        width(word) + ABOUT_METADATA_TEXT_SAFETY <= value_width + 0.01,
        "the word whole in {value_width} beside a {column} column"
    );
    assert!(
        metadata_value_lines(label, &rows[0].1, value_width)
            .iter()
            .all(|line| !line.contains('\u{2026}')),
        "the value whole"
    );
    assert!(column > about_metadata_label_width(), "{column}");
    // A short value leaves the label all it needs.
    let rows = vec![(label.to_string(), "3".to_string())];
    let column = fact_label_width(&rows, 2.0 * inner);
    assert!(
        (column - width(label) - ABOUT_METADATA_TEXT_SAFETY).abs() < 0.01,
        "the label whole: {column}"
    );
    // Never narrower than About's.
    let rows = vec![("Os".to_string(), "x".to_string())];
    assert_eq!(fact_label_width(&rows, inner), about_metadata_label_width());
}

/// The build time reads on the reader's clock, as Messages' times do; UTC,
/// and saying so, only before the host has published a clock.
#[test]
fn about_build_time_reads_on_the_readers_clock() {
    let built = "2025-09-21T15:53:20Z";
    let clock = MessagesState {
        now_unix_ms: 1_758_470_000_000,
        utc_offset_s: -7 * 3600,
        ..MessagesState::empty()
    };
    assert_eq!(about_fact_value("built", built, &clock), "Today 8:53:20 AM");
    assert_eq!(
        about_fact_value("built", built, &MessagesState::empty()),
        "2025-09-21 15:53 UTC"
    );
    assert_eq!(about_fact_value("arch", "aarch64", &clock), "aarch64");
}

#[test]
fn local_settings_eliders_keep_combining_zwj_and_flag_graphemes_atomic() {
    for cluster in ["e\u{301}", "👩\u{200d}💻", "🇺🇳"] {
        // A fact's value wraps on whole graphemes, a code value too, and
        // neither is a word: nothing is put between them.
        for (label, width) in [("compiler", 72.0), ("commit", 72.0)] {
            let source = cluster.repeat(12);
            let lines = metadata_value_lines(label, &source, width);
            assert_eq!(lines.concat(), source, "{label}: nothing is cut or added");
            assert!(
                lines
                    .iter()
                    .flat_map(|line| line.graphemes())
                    .all(|grapheme| grapheme == cluster),
                "{label}'s wrap split {cluster:?}: {lines:?}"
            );
        }

        let prefix = cluster.repeat(2);
        let available =
            (crate::tray_raster::ui_text_width(&prefix, group_footnote_text_px()) + 1.0).max(48.0);
        let note = format!("{prefix} {}", cluster.repeat(40));
        let lines: Vec<String> =
            crate::tray_raster::ui_text_wrap_ranges(&note, group_footnote_text_px(), available)
                .into_iter()
                .map(|range| note[range].to_string())
                .collect();
        let first = format!("{prefix} ");
        assert_eq!(lines.first().map(String::as_str), Some(first.as_str()));
        assert_eq!(lines.concat(), note);
        assert!(lines.iter().all(|line| {
            crate::tray_raster::ui_text_width(line, group_footnote_text_px()) <= available + 0.5
                || line.graphemes().count() == 1
        }));
        assert!(
            lines
                .iter()
                .flat_map(|line| line.graphemes())
                .all(|grapheme| {
                    grapheme == cluster || grapheme.chars().all(char::is_whitespace)
                })
        );
    }
    // THE PAINTER'S ELIDER KEEPS THE LONGEST LEADING RUN OF WHOLE GRAPHEMES
    // WHOSE `…` FITS — what measuring every shorter candidate in turn keeps,
    // to the bit: the kern into the `…`, a face the UI face lacks (CJK),
    // zero-width and combining marks under the UI face's negative tracking,
    // and widths from nothing past the whole text. On the host's UI faces, as
    // a backend installs them: a test thread's store is cold, and its 0.6 em
    // a char has no kern, tracking or fallback face for the pen to get wrong.
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    #[cfg(target_os = "macos")]
    assert!(
        crate::tray_raster::ui_font_of(crate::widget::TextFace::Ui).is_some(),
        "the oracle measures on the host's UI face"
    );
    let px = 13.0 * crate::native_appearance::text_scale();
    for text in [
        "~/Library/Application Support/aterm/harness · AVAWAY To Ty",
        "設定ファイルの場所 · 日本語の説明",
        "a\u{200b}b\u{200b}c\u{200b}d\u{200b}e\u{200b}f\u{200b}g\u{200b}h",
        "e\u{301}e\u{301}e\u{301}e\u{301}e\u{301}e\u{301}e\u{301}e\u{301}",
    ] {
        for max in [0.5, 6.0, 9.0, 24.0, 47.5, 72.0, 140.0, 400.0] {
            // The painter's label elider: the longest run that fits BESIDE a
            // `…` measured on its own, in the regular and the semibold face,
            // as shedding one grapheme at a time and measuring again finds it.
            for face in [crate::widget::TextFace::Ui, crate::widget::TextFace::UiBold] {
                let width = |s: &str| crate::tray_raster::ui_text_width_for(face, s, px);
                let mut shed = text.to_string();
                if width(&shed) > max {
                    while !shed.is_empty() && width(&shed) + width("…") > max {
                        let (at, _) = shed.grapheme_indices().last().expect("not empty");
                        shed.truncate(at);
                    }
                    if width("…") <= max {
                        shed.truncate(shed.trim_end().len());
                        shed.push('…');
                    }
                }
                assert_eq!(
                    crate::native_ui::elide_text_label(text, max, px, face),
                    shed,
                    "{text:?} within {max} in {face:?}"
                );
            }
        }
    }
}

#[test]
fn bounded_numeric_setting_is_a_real_slider_and_keyboard_steps_exactly() {
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    state.route = SettingsRoute::TextFonts;
    let field = state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == prefs::EDIT_FONT_PX)
        .expect("font size field");
    field.seed = Some("14".to_string());
    field.placeholder = "14 px".to_string();
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_FONT_PX
    )));

    let cx = view_cx_at(900.0, 820.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let key = UiKey::new(format!("settings/control/{}", prefs::EDIT_FONT_PX));
    // The value's domain is the terminal's whole range: what the keys,
    // automation and a screen reader reach.
    assert_eq!(
        compiled.semantic(&key).unwrap().value,
        SemanticValue::Number {
            value: 14.0,
            minimum: 6.0,
            maximum: 200.0,
        }
    );
    let slider = compiled
        .paint
        .iter()
        .find_map(|node| {
            (node.key == key)
                .then_some(&node.content)
                .and_then(|content| {
                    let UiContent::Slider(control) = content else {
                        return None;
                    };
                    Some(control)
                })
        })
        .expect("numeric field paints as slider");
    assert_eq!(slider.spec.step, 1.0);
    assert_eq!(slider.spec.display_value, "14 px");
    // The bar draws the sizes people read at, and a drag maps over them.
    assert_eq!(slider.spec.track, Some((8.0, 36.0)));
    let rect = compiled
        .paint
        .iter()
        .find(|node| node.key == key)
        .expect("the slider's paint")
        .rect;
    let geometry = crate::native_ui::slider_geometry(rect);
    assert_eq!(
        compiled.slider_value_at(&key, geometry.track_right),
        Some(36.0)
    );
    assert_eq!(compiled.slider_value_at(&key, geometry.track_x), Some(8.0));

    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Right { extend: false }),
        )
        .unwrap();
    let edit = outcome.effects.iter().find_map(|effect| match effect {
        AppEffect::ConfigPatch { patch, .. } => patch.edits.first(),
        _ => None,
    });
    // A step writes the size, onto the platform's automatic one too (Linux's
    // 15 px): an explicit size is not taken for the automatic one
    // (`prefs::unset_literal`), so the step pins it as every other step does.
    assert_eq!(
        edit.map(|edit| edit.key.as_str()),
        Some(prefs::EDIT_FONT_PX)
    );
    assert_eq!(edit.and_then(|edit| edit.value.as_deref()), Some("15"));

    let range = prefs::range_of(prefs::EDIT_FONT_PX).unwrap();
    assert_eq!(normalize_slider_value(13.49, range).as_deref(), Some("13"));
    assert_eq!(normalize_slider_value(99.0, range).as_deref(), Some("99"));
    assert_eq!(normalize_slider_value(500.0, range).as_deref(), Some("200"));
    assert_eq!(normalize_slider_value(f64::NAN, range), None);
    // A fractional step writes the step's decimals, never binary noise.
    let line_height = prefs::range_of(prefs::EDIT_LINE_HEIGHT).expect("line height range");
    for (value, text) in [(1.2, "1.2"), (1.7, "1.7"), (0.8, "0.8"), (2.0, "2")] {
        assert_eq!(
            normalize_slider_value(value, line_height).as_deref(),
            Some(text)
        );
    }
}

/// A fractional-step slider saves the number it shows, never binary-float
/// noise (6 × 0.05 is 0.30000000000000004), from a drag, a semantic set and
/// an arrow key alike.
#[test]
fn slider_writes_land_on_the_step_grid_without_float_noise() {
    for (key, value, written) in [
        (prefs::EDIT_FAINT_OPACITY, 0.3, "0.3"),
        (prefs::EDIT_BACKGROUND_OPACITY, 0.7, "0.7"),
        (prefs::EDIT_WALLPAPER_DIM, 0.85, "0.85"),
        (prefs::EDIT_TRAIL_SOUND_VOLUME, 0.551, "0.55"),
    ] {
        let range = prefs::range_of(key).unwrap();
        assert_eq!(
            normalize_slider_value(value, range).as_deref(),
            Some(written),
            "{key}"
        );
    }

    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    state.route = SettingsRoute::Appearance;
    state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == prefs::EDIT_FAINT_OPACITY)
        .expect("faint opacity field")
        .seed = Some("0.85".to_string());
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_FAINT_OPACITY
    )));
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Right { extend: false }),
        )
        .unwrap();
    let edit = outcome.effects.iter().find_map(|effect| match effect {
        AppEffect::ConfigPatch { patch, .. } => patch.edits.first(),
        _ => None,
    });
    assert_eq!(edit.and_then(|edit| edit.value.as_deref()), Some("0.9"));
}

#[test]
fn typography_sliders_cover_and_preview_the_full_runtime_domain() {
    let config = Config {
        font_px: Some(100.0),
        font_weight: Some(950),
        ..Config::default()
    };
    let state = SettingsViewState::new(&config);
    // Every slider's domain is the runtime's (a size set past the bar's
    // usual 8–36 px widens the bar to hold it: below).
    for (key, expected, minimum, maximum) in [
        (prefs::EDIT_FONT_PX, 100.0, 6.0, 200.0),
        (prefs::EDIT_FONT_WEIGHT, 950.0, 1.0, 1000.0),
    ] {
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == key)
            .unwrap();
        assert_eq!(numeric_slider_value(field).unwrap().0, expected);
        let compiled = UiTree::new(setting_row(
            &state,
            index,
            field,
            false,
            SettingsWidth::Wide,
        ))
        .compile(LogicalRect::new(0.0, 0.0, 720.0, 64.0))
        .unwrap();
        assert_eq!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap()
                .value,
            SemanticValue::Number {
                value: expected,
                minimum,
                maximum,
            }
        );
    }
    let preview = renderer_preview_spec_for_key_with_font(
        &state,
        prefs::EDIT_FONT_PX,
        0,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
        None,
    )
    .unwrap();
    assert_eq!(preview.font_px, 100.0);
    assert!(preview.typography.variations.iter().any(|variation| {
        variation.tag == aterm_render::variation::WGHT_TAG && variation.value() == 950.0
    }));
}

#[test]
fn bounded_numeric_rows_disclose_configured_and_effective_without_rewriting_raw() {
    let config = Config {
        font_px: Some(500.0),
        line_height: Some(9.0),
        font_weight: Some(0),
        ..Config::default()
    };
    let state = SettingsViewState::new(&config);
    for (key, configured, effective, outcome) in [
        (
            prefs::EDIT_FONT_PX,
            "500",
            f64::from(crate::FONT_PX),
            "ignored",
        ),
        (prefs::EDIT_LINE_HEIGHT, "9", 2.0, "runtime clamps"),
        (prefs::EDIT_FONT_WEIGHT, "0", 1.0, "runtime clamps"),
    ] {
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == key)
            .unwrap();
        assert_eq!(field.seed.as_deref(), Some(configured));
        assert_eq!(state.raw_value(key).as_deref(), Some(configured));
        assert_eq!(
            numeric_slider_value_for_state(&state, field).unwrap().0,
            effective
        );
        let disclosure = bounded_numeric_disclosure(&state, field, false).unwrap();
        assert!(
            disclosure
                .semantic
                .contains(&format!("configured {configured}"))
        );
        assert!(disclosure.semantic.contains(outcome));

        let compiled = UiTree::new(setting_row(&state, index, field, true, SettingsWidth::Wide))
            .compile(LogicalRect::new(0.0, 0.0, 1_000.0, 90.0))
            .unwrap();
        let control = compiled
            .semantic(&UiKey::new(format!("settings/control/{key}")))
            .unwrap();
        assert!(control.label.contains(&format!("configured {configured}")));
        assert!(matches!(
            &control.value,
            SemanticValue::Number { value, .. } if *value == effective
        ));
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .unwrap()
                .label
                .contains(&format!("Configured {configured}")),
            "Modified must visibly retain the authored value for {key}"
        );
    }

    let off_step = Config {
        line_height: Some(1.03),
        ..Config::default()
    };
    let off_step = SettingsViewState::new(&off_step);
    let field = off_step
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_LINE_HEIGHT)
        .unwrap();
    assert_eq!(
        numeric_slider_value(field),
        Some((1.03, "1.03".to_string())),
        "step is an interaction increment, not a validity constraint"
    );
    assert_eq!(bounded_numeric_submission_error(field, Some("1.03")), None);
}

#[test]
fn bounded_native_float_non_finite_values_keep_sliders_and_disclose() {
    let mut state = SettingsViewState::new(&Config::default());
    let expected = BTreeMap::from([
        (prefs::EDIT_FONT_PX, f64::from(crate::FONT_PX)),
        // The platform default (`app_config::DEFAULT_LINE_HEIGHT`).
        (
            prefs::EDIT_LINE_HEIGHT,
            if cfg!(windows) { 1.1 } else { 1.0 },
        ),
        (prefs::EDIT_FONT_SIZE_SCALE, 1.0),
        (prefs::EDIT_MINIMUM_CONTRAST, 1.0),
        (
            prefs::EDIT_FAINT_OPACITY,
            f64::from(aterm_types::DIM_FACTOR),
        ),
        (prefs::EDIT_STEM_GAMMA, 1.0),
        (prefs::EDIT_CURSOR_TRAIL_INTENSITY, 0.0),
        (prefs::EDIT_CURSOR_TRAIL_RADIUS, 0.0),
        (prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH, 0.0),
        // The default rainbow kitty style's own radius.
        (prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS, 1.8),
        (prefs::EDIT_CURSOR_GLOW_SDR_BOOST, 0.0),
        (prefs::EDIT_TRAIL_SOUND_VOLUME, 0.0),
        (prefs::EDIT_FONT_WEIGHT_DARK_NUDGE, 0.0),
        (prefs::EDIT_BACKGROUND_OPACITY, 1.0),
        (prefs::EDIT_WALLPAPER_DIM, 0.3),
        (prefs::EDIT_WINDOW_PADDING, f64::from(crate::PAD_LOGICAL_PX)),
        (
            prefs::EDIT_WINDOW_PADDING_TOP,
            f64::from(crate::PAD_TOP_LOGICAL_PX),
        ),
        ("sparkle_words.profanity.intensity", 0.0),
        ("sparkle_words.ink.strength", 0.0),
    ]);
    for raw in ["NaN", "inf", "-inf"] {
        for (&key, &effective) in &expected {
            let index = state
                .legacy
                .fields
                .iter()
                .position(|field| field.key == key)
                .unwrap();
            state.legacy.fields[index].seed = Some(raw.to_string());
            state.raw_values.insert(key.to_string(), raw.to_string());
            let field = &state.legacy.fields[index];
            assert_eq!(
                numeric_slider_value_for_state(&state, field).unwrap().0,
                effective,
                "{key} {raw}"
            );
            let disclosure = bounded_numeric_disclosure(&state, field, false).unwrap();
            assert!(disclosure.semantic.contains(raw), "{key} {raw}");
            assert!(disclosure.semantic.contains("non-finite"), "{key} {raw}");
            assert!(
                bounded_numeric_submission_error(field, Some(raw))
                    .unwrap()
                    .contains("must be a number"),
                "{key} {raw}"
            );

            let compiled =
                UiTree::new(setting_row(&state, index, field, true, SettingsWidth::Wide))
                    .compile(LogicalRect::new(0.0, 0.0, 1_100.0, 90.0))
                    .unwrap();
            let control = compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap();
            assert!(control.label.contains("non-finite"), "{key} {raw}");
            assert!(matches!(
                &control.value,
                SemanticValue::Number { value, .. } if *value == effective
            ));
        }
    }
}

#[test]
fn rejected_bounded_numeric_return_retains_exact_draft_and_focus() {
    let (mut runtime, instance, view) = setup();
    let key = prefs::EDIT_FONT_PX;
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.route = SettingsRoute::TextFonts;
        // A bounded number typed into a text row (a placeholder that names
        // no number keeps the row a field).
        let field = state
            .legacy
            .fields
            .iter_mut()
            .find(|field| field.key == key)
            .unwrap();
        field.placeholder = "Automatic".to_string();
    }
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{key}")),
                value: None,
            }),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit("500".to_string())),
        )
        .unwrap();
    let rejected = runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Submit))
        .unwrap();
    assert!(
        rejected
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. }))
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert_eq!(state.editing_field.as_deref(), Some(key));
    assert_eq!(state.field_inputs[key].value(), "500");
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/control/font_px")
    );
    assert!(state.feedback.is_some(), "the refusal is said");
    assert!(
        state.field_errors.contains_key(key),
        "the reason sits under the row"
    );
}

/// An out-of-range size sent to the font size slider writes nothing, leaves
/// no draft behind, keeps the row and its keyboard, says why, and leaves the
/// specimen at the saved size in a card no taller than usual.
#[test]
fn an_out_of_range_font_size_keeps_the_row_and_the_specimen() {
    let (mut runtime, instance, view) = setup();
    replace_settings_source(&mut runtime, view, "font_px = 14\n".to_string());
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
    }
    let key = prefs::EDIT_FONT_PX;
    let rejected = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{key}")),
                value: Some(SemanticInput::Text("500".to_string())),
            }),
        )
        .unwrap();
    assert!(
        rejected
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. }))
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert!(!state.field_inputs.contains_key(key), "no draft to recover");
    assert_eq!(state.feedback.as_deref(), Some("Font size was not saved"));
    assert_eq!(
        state.field_errors.get(key).map(String::as_str),
        Some("Font size must be between 6 px and 200 px; 500 px was not saved"),
        "the reason sits under the row"
    );
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/control/font_px")
    );
    let cx = view_cx_at(900.0, 600.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let row = compiled
        .semantic(&UiKey::new("settings/control/font_px"))
        .expect("the size row stays on the page");
    assert!(row.rect.bottom() <= cx.viewport.height);
    let preview = compiled
        .semantic(&UiKey::new("settings/preview/text-fonts"))
        .expect("the specimen stays");
    assert!(preview.rect.height <= 2.0 * renderer_preview_height(SettingsWidth::Medium) + 0.01);
    let spec = renderer_preview_spec_for_key_with_font(
        state,
        key,
        0,
        crate::native_app::ViewMotionCx::default(),
        12.0,
        1.0,
        None,
    )
    .unwrap();
    assert_eq!(spec.font_px, 14.0, "the specimen keeps the saved size");

    // A draft the terminal would refuse, however it got there, never
    // reaches the specimen.
    let mut drafted = SettingsViewState::new(&Config {
        font_px: Some(14.0),
        ..Config::default()
    });
    drafted.field_inputs.insert(
        key.to_string(),
        crate::native_text_input::TextInputState::new("500".to_string()),
    );
    assert_eq!(preview_font_px(&drafted, 12.0), 14.0);
}

#[test]
fn motion_auto_discloses_platform_behavior_when_explicit_or_implicit() {
    // One word in the control's segment and its accessible name, its value
    // saying whether it is the default; the platform's own behaviour rides
    // the row's note and description.
    for (config, shown) in [
        (Config::default(), "Automatic (default)"),
        (
            Config {
                motion: Some("auto".to_string()),
                ..Config::default()
            },
            "Automatic",
        ),
    ] {
        let state = SettingsViewState::new(&config);
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == prefs::EDIT_MOTION)
            .unwrap();
        assert!(motion_value_is_auto(SettingsState::display_value(field)));
        let compiled = UiTree::new(setting_row(
            &state,
            index,
            field,
            false,
            SettingsWidth::Wide,
        ))
        .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
        .unwrap();
        let key = UiKey::new(format!("settings/control/{}", prefs::EDIT_MOTION));
        let semantic = compiled.semantic(&key).unwrap();
        assert_eq!(semantic.label, "Motion: Automatic");
        assert_eq!(semantic.value, SemanticValue::Text(shown.to_string()));
        let note = prefs::motion_auto_copy(std::env::consts::OS).0;
        assert!(
            semantic
                .description
                .as_deref()
                .is_some_and(|description| description.contains(note)),
            "{:?}",
            semantic.description
        );
        assert!(!semantic.label.contains("motion=auto"));
        let visual = compiled
            .paint
            .iter()
            .find_map(|node| {
                if node.key != key {
                    return None;
                }
                let UiContent::Button(button) = &node.content else {
                    return None;
                };
                button.spec.visual_label.as_deref()
            })
            .unwrap();
        assert_eq!(visual, "Automatic");
    }
}

