/// Every sub-page's parent is a permanent rail row, and while the sub-page
/// shows the rail lists it right after that parent; every other page leaves
/// the rail at its permanent rows.
#[test]
fn every_sub_page_parent_is_a_rail_row() {
    let mut sub_pages = 0;
    for route in SettingsRoute::ALL {
        let rail: Vec<SettingsRoute> = navigation_groups(route)
            .into_iter()
            .flat_map(|(_, routes)| routes)
            .collect();
        match route.rail_parent() {
            Some(parent) => {
                sub_pages += 1;
                assert!(parent.on_rail(), "{route:?} under {parent:?}");
                let at = rail
                    .iter()
                    .position(|row| *row == parent)
                    .unwrap_or_else(|| panic!("{parent:?} on the rail"));
                assert_eq!(rail.get(at + 1), Some(&route), "{route:?}");
                assert_eq!(rail.len(), SettingsRoute::rail_len() + 1);
            }
            None => assert_eq!(rail.len(), SettingsRoute::rail_len(), "{route:?}"),
        }
    }
    assert!(sub_pages > 0, "Themes at least is a sub-page");
}

/// OPENING A SUB-PAGE NEVER MOVES THE RAIL'S OTHER ROWS. Settings ▸ Themes
/// adds a row under Appearance; every row keeps its one rhythm, the title
/// and headings stay, and in a short window the list scrolls to show the
/// selected Themes row whole rather than squeezing twenty rows into the room
/// of nineteen.
#[test]
fn opening_themes_never_changes_the_rail_fit() {
    for (width, height) in [(849.0_f32, 460.0_f32), (1_200.0, 513.0), (1_200.0, 900.0)] {
        let cx = view_cx_at(width, height);
        let compile = |route: SettingsRoute| {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.navigate(route);
            compile_settings_view(&runtime, instance, view, &cx)
        };
        let appearance = compile(SettingsRoute::Appearance);
        let themes = compile(SettingsRoute::Themes);
        let at = format!("{width}x{height}");
        for key in [
            "settings/navigation-title",
            "settings/nav-label/look---feel",
        ] {
            let key = UiKey::new(key);
            assert!(
                appearance.semantic(&key).is_some(),
                "{} at {at}",
                key.as_str()
            );
            assert!(themes.semantic(&key).is_some(), "{} at {at}", key.as_str());
        }
        let rows = whole_rail_rows(&themes);
        assert!(
            rows.iter().any(|(key, _)| key == "settings/nav/themes"),
            "the selected sub-page row is whole at {at}: {rows:?}"
        );
        for (key, rect) in &rows {
            assert!(
                (rect.height - navigation_row_height(1.0)).abs() < 0.5,
                "{key} {rect:?} at {at}"
            );
        }
        let failures = themes.fit_failures();
        assert!(failures.is_empty(), "{at}: {failures:#?}");
    }
}

/// EVERY RAIL ROW'S WORDS ARE WHOLE, SELECTED OR NOT, at 1×, 1.25×, 1.5× and 2× text
/// in the wide and the medium rail, and the rail is one width whichever row is
/// selected: it is as wide as its widest row needs in the semibold a selected row
/// wears (`settings_navigation_width`). A fixed 216 and 196pt, set against Helvetica
/// Neue and Segoe UI, cut Noto Sans's "Wallpaper" (122.3pt in the medium rail's 120pt
/// slot at 2×), Helvetica Neue's selected "Messages" (120.7pt) and, at 1.25×, the
/// last rung that paints full names, "Keyboard & Input". Measured in this host's UI
/// face and, where this host can read them, the Linux ladder's.
#[test]
fn every_rail_row_is_whole_selected_or_not() {
    at_each_text_scale(&[1.0, 1.25, 1.5, 2.0], "the rail's rows", |scale| {
        for base_width in [849.0_f32, 1_200.0] {
            for face in [LinuxLayoutFace::Host, LinuxLayoutFace::LinuxLadder] {
                let (width, height) = (base_width * scale, 900.0 * scale);
                let mut rail_widths = Vec::new();
                for route in SettingsRoute::ALL {
                    let Some(cx) = linux_layout_cx(face, width, height) else {
                        break;
                    };
                    let (mut runtime, instance, view) = setup();
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!()
                    };
                    state.navigate(route);
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let at = format!("{route:?} selected, {width}x{height} at {scale} in {face:?}");
                    let navigation = compiled
                        .semantic(&UiKey::new("settings/navigation"))
                        .unwrap_or_else(|| panic!("the rail shows: {at}"));
                    rail_widths.push(navigation.rect.width);
                    let cut: Vec<String> = compiled
                        .fit_failures()
                        .into_iter()
                        .filter(|line| line.contains("key=\"settings/nav/"))
                        .collect();
                    assert!(cut.is_empty(), "{at}: {cut:#?}");
                }
                rail_widths.dedup();
                assert!(
                    rail_widths.len() <= 1,
                    "the rail moved with the selection at {width} at {scale} in {face:?}: \
                     {rail_widths:?}"
                );
            }
        }
    });
}

/// While Settings ▸ Themes shows, the compact category sheet lists it under
/// Appearance, selected; on Appearance it is not listed at all.
#[test]
fn the_category_sheet_selects_themes_under_appearance() {
    let cx = view_cx_at(568.0, 320.0);
    let sheet = |route: SettingsRoute| {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.navigate(route);
            state.compact_navigation = true;
        }
        let mut cells = std::collections::BTreeMap::<String, bool>::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
            for node in &compiled.semantics {
                if node.key.as_str().starts_with("settings/categories/")
                    && node.role == SemanticRole::Button
                {
                    cells.insert(
                        node.key.as_str().to_string(),
                        node.state.is_some_and(|state| state.selected),
                    );
                }
            }
        });
        cells
    };
    let themes = sheet(SettingsRoute::Themes);
    assert_eq!(themes.get("settings/categories/themes"), Some(&true));
    assert_eq!(themes.get("settings/categories/appearance"), Some(&false));
    assert_eq!(themes.len(), SettingsRoute::rail_len() + 1, "{themes:?}");
    // Negative control: on Appearance it is the selected cell and Themes
    // has none.
    let appearance = sheet(SettingsRoute::Appearance);
    assert_eq!(appearance.get("settings/categories/themes"), None);
    assert_eq!(
        appearance.get("settings/categories/appearance"),
        Some(&true)
    );
}

/// A compact page's first screen holds three whole rows and their notes at
/// the shipped 102x29 window (738x418) as at a tall narrow one: a one-line
/// compact row is the Medium row it is built as (44pt, a 36pt control),
/// never a taller touch-sized row, so the third setting's control and note
/// are whole above the list's edge, and the fourth is live only where it is
/// whole too (else it peeks in under them), with default values and with the
/// two zero values the rows' notes explain.
#[test]
fn compact_route_without_preview_admits_three_complete_rows_and_their_notes() {
    let whole = [
        prefs::EDIT_SCROLLBACK,
        prefs::EDIT_SEARCH_HISTORY_LINES,
        prefs::EDIT_BIDI,
    ];
    for (width, height) in [(474.0_f32, 658.0_f32), (738.0, 418.0)] {
        for source in ["", "scrollback_lines = 0\nsearch_history_lines = 0\n"] {
            let snapshot = VersionedConfigService::new(source.to_string())
                .unwrap()
                .snapshot();
            let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
            state.navigate(SettingsRoute::Terminal);
            let cx = view_cx_at(width, height);
            let compiled = settings_route_at(&state, &cx);
            let at = format!("{width}x{height} {source:?}");
            let list = compiled
                .semantic(&UiKey::new("settings/list"))
                .unwrap_or_else(|| panic!("{at}: the list"))
                .rect;
            let live = |key: &str| {
                let control = format!("settings/control/{key}");
                compiled.hits.iter().any(|hit| hit.key.as_str() == control)
            };
            for key in whole {
                assert!(live(key), "{at}: {key}'s control is whole and live");
                // The row's last painted line: its note, under the row.
                let lines = format!("settings/detail/{key}/line-");
                let note = compiled
                    .paint
                    .iter()
                    .filter(|node| node.key.as_str().starts_with(&lines))
                    .map(|node| node.rect.bottom())
                    .fold(None, |most: Option<f32>, bottom| {
                        Some(most.map_or(bottom, |most| most.max(bottom)))
                    })
                    .unwrap_or_else(|| panic!("{at}: {key} has its note under it"));
                assert!(
                    note <= list.bottom() + 0.5,
                    "{at}: {key}'s note ends inside the list: {note} in {list:?}"
                );
            }
            // The fourth row is live only where it is whole on the screen
            // (a two-segment choice fits beside its label at 474pt); else
            // it is the peek.
            let fourth = compiled
                .semantic(&UiKey::new(format!(
                    "settings/control/{}",
                    prefs::EDIT_AMBIGUOUS_WIDTH
                )))
                .map(|node| node.rect);
            assert!(
                !live(prefs::EDIT_AMBIGUOUS_WIDTH)
                    || fourth.is_some_and(|rect| rect.bottom() <= list.bottom() + 0.5),
                "{at}: the fourth row is live only where it is whole: {fourth:?} in {list:?}"
            );
            // An ordinary page shows every row it has, so it states no count.
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/results-range"))
                    .is_none()
            );
            for control in compiled
                .semantics
                .iter()
                .filter(|node| node.key.as_str().starts_with("settings/control/"))
            {
                assert!(control.rect.bottom() <= cx.viewport.bottom());
            }
        }
    }
}

/// A one-line compact row is the Medium row it is built as: the same row and
/// control height on the shipped 102x29 window as at 150x48.
#[test]
fn a_one_line_compact_row_is_as_tall_as_its_medium_row() {
    let heights = |width: f32, height: f32| {
        let mut state = SettingsViewState::new(&Config::default());
        state.navigate(SettingsRoute::Terminal);
        let compiled = settings_route_at(&state, &view_cx_at(width, height));
        let key = prefs::EDIT_SCROLLBACK;
        let row = compiled
            .semantics
            .iter()
            .find(|node| {
                node.key.as_str().starts_with("settings/row/")
                    && node.key.as_str().ends_with(&format!("/{key}"))
            })
            .unwrap_or_else(|| panic!("{width}x{height}: the row"))
            .rect
            .height;
        let control = compiled
            .semantic(&UiKey::new(format!("settings/control/{key}")))
            .unwrap_or_else(|| panic!("{width}x{height}: the control"))
            .rect
            .height;
        (row, control)
    };
    let compact = heights(738.0, 418.0);
    let medium = heights(1_074.0, 684.0);
    assert_eq!(compact, medium, "102x29 against 150x48");
    assert_eq!(medium, (44.0, 36.0), "at 1x text");
}

#[test]
fn compact_choice_picker_keeps_every_option_and_cancel_wholly_reachable() {
    for (viewport_width, viewport_height) in [
        // The ordinary 35-column Retina phone-width host presents an
        // exact 286.5-point semantic viewport.
        (286.5, 558.0),
        (320.0, 568.0),
        (390.0, 568.0),
        (474.0, 658.0),
    ] {
        // One theme always: the Color theme control opens the whole picker.
        let (mut runtime, instance, view) = theme_pair_runtime("theme = \"Default\"\n", true);
        let open = || ActionInvocation {
            id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
            value: None,
        };
        runtime
            .dispatch(instance, view, AppEvent::Action(open()))
            .unwrap();
        let cx = view_cx_at(viewport_width, viewport_height);
        let option_prefix = format!("settings/choice/{}/", prefs::EDIT_THEME);
        let context = format!("{viewport_width}x{viewport_height}");
        // Cancel closes it and hands the keyboard back to the control.
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/choice-close"),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view");
        };
        assert!(state.choice_picker.is_none(), "Cancel closes the picker");
        let theme_control = UiKey::new(format!("settings/control/{}", prefs::EDIT_THEME));
        assert_eq!(state.common.last_focus.as_ref(), Some(&theme_control));
        let closed = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            closed.focus_order.contains(&theme_control),
            "Cancel returns focus to the setting that opened the picker"
        );
        runtime
            .dispatch(instance, view, AppEvent::Action(open()))
            .unwrap();
        walk_open_choice_picker(
            &mut runtime,
            instance,
            view,
            &cx,
            prefs::EDIT_THEME,
            |compiled, index| {
                let picker = compiled
                    .semantic(&UiKey::new(format!(
                        "settings/choice-picker/{}",
                        prefs::EDIT_THEME
                    )))
                    .expect("compact theme picker");
                assert!(
                    picker.rect.x >= 0.0
                        && picker.rect.y >= 0.0
                        && picker.rect.right() <= viewport_width + 0.01
                        && picker.rect.bottom() <= viewport_height + 0.01,
                    "picker is whole at {context} on option {index}: {:?}",
                    picker.rect
                );
                let options = compiled
                    .semantics
                    .iter()
                    .filter(|node| node.key.as_str().starts_with(&option_prefix))
                    .collect::<Vec<_>>();
                assert!(!options.is_empty());
                for option in options
                    .iter()
                    .filter(|option| !list_cuts(compiled, &option.key))
                {
                    assert!(option.rect.height >= 44.0);
                    assert!(option.rect.width >= 140.0, "{context}: {:?}", option.rect);
                    assert!(option.rect.x >= picker.rect.x);
                    assert!(option.rect.right() <= picker.rect.right() + 0.01);
                    assert!(option.rect.bottom() <= picker.rect.bottom() + 0.01);
                    let paint = compiled
                        .paint
                        .iter()
                        .find(|paint| paint.key == option.key)
                        .expect("choice is painted");
                    let hit = compiled
                        .hits
                        .iter()
                        .find(|hit| hit.key == option.key)
                        .expect("choice is activatable");
                    assert_eq!(paint.rect, option.rect, "choice is not clipped");
                    assert_eq!(hit.rect, option.rect, "choice hit is not clipped");
                }
                for (index, option) in options.iter().enumerate() {
                    for other in options.iter().skip(index + 1) {
                        assert!(
                            option.rect.intersect(other.rect).is_none(),
                            "choices never overlap: {:?} and {:?}",
                            option.rect,
                            other.rect
                        );
                    }
                }
                let cancel = compiled
                    .semantic(&UiKey::new("settings/choice-close"))
                    .expect("Cancel");
                assert!(cancel.rect.height >= 44.0, "Cancel is touch-sized");
                assert!(cancel.rect.bottom() <= picker.rect.bottom() + 0.01);
            },
        );

        // The last option, reached by the keyboard, saves when activated.
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let last = compiled
            .hits
            .iter()
            .rfind(|hit| hit.key.as_str().starts_with(&option_prefix))
            .expect("an option on glass")
            .action
            .clone();
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: last,
                    value: None,
                }),
            )
            .unwrap();
        assert!(outcome.effects.iter().any(|effect| matches!(
            effect,
            AppEffect::ConfigPatch { patch, .. }
                if patch.edits.first().is_some_and(|edit| edit.key == prefs::EDIT_THEME)
        )));
    }
}

#[test]
fn short_landscape_audit_reaches_every_control_with_feedback() {
    at_each_text_scale(
        &[1.0, 1.5, 2.0],
        "short-landscape audit",
        short_landscape_audit_reaches_every_control_with_feedback_at_scale,
    );
}

/// Every screen of the list the view shows now, from its top to the last
/// one it scrolls to: compiled at each first stop in turn.
fn each_screen(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    mut each: impl FnMut(&crate::native_ui::CompiledUi, usize),
) -> usize {
    // Scrolling forgets a control kept in view, as the wheel does.
    let set_top = |runtime: &mut NativeRuntime, top: usize| {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.page_scroll = top;
        state.page_reveal = None;
    };
    set_top(runtime, 0);
    let _ = compile_settings_view(runtime, instance, view, cx);
    let limit = match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => state.result_page_limit.get().unwrap_or(0),
        _ => unreachable!(),
    };
    for top in 0..=limit {
        set_top(runtime, top);
        each(&compile_settings_view(runtime, instance, view, cx), top);
    }
    limit + 1
}

/// The first screen of the list that shows the node `key`, scrolled to as the
/// wheel scrolls.
fn screen_showing(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    key: &str,
) -> Option<crate::native_ui::CompiledUi> {
    let mut found = None;
    let mut wanted = None;
    each_screen(runtime, instance, view, cx, |compiled, top| {
        if wanted.is_none() && compiled.semantic(&UiKey::new(key)).is_some() {
            wanted = Some(top);
        }
    });
    if let Some(top) = wanted {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.page_scroll = top;
        state.page_reveal = None;
        found = Some(compile_settings_view(runtime, instance, view, cx));
    }
    found
}

/// The semantic keys under `prefix` that a compiled screen holds.
fn keys_with_prefix(compiled: &crate::native_ui::CompiledUi, prefix: &str) -> Vec<String> {
    compiled
        .semantics
        .iter()
        .filter(|node| node.key.as_str().starts_with(prefix))
        .map(|node| node.key.as_str().to_string())
        .collect()
}

/// One rung of [`short_landscape_audit_reaches_every_control_with_feedback`] ([`at_each_text_scale`]).
fn short_landscape_audit_reaches_every_control_with_feedback_at_scale(scale: f32) {
    let cx = view_cx_at(568.0, 320.0);

    for feedback_present in [false, true] {
        let feedback = feedback_present.then(|| "Settings status changed".to_string());
        let variant = if feedback_present {
            "with feedback"
        } else {
            "without feedback"
        };

        // The compact category sheet lists every destination, whole, on
        // some screen of its list.
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.compact_navigation = true;
            state.feedback = feedback.clone();
        }
        let mut categories = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("categories {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            categories.extend(keys_with_prefix(compiled, "settings/categories/"));
        });
        for route in SettingsRoute::ALL
            .into_iter()
            .filter(|route| route.on_rail())
        {
            assert!(
                categories.contains(&format!("settings/categories{}", route.path())),
                "categories at {scale}× {variant}: missing {}",
                route.label()
            );
        }

        // Every advanced category pages its preview and each control independently.
        for route in [
            SettingsRoute::Appearance,
            SettingsRoute::TextFonts,
            SettingsRoute::CursorMotion,
            SettingsRoute::Sound,
            SettingsRoute::WindowTabs,
            SettingsRoute::KeyboardInput,
            SettingsRoute::Terminal,
            SettingsRoute::Security,
        ] {
            // Cursor & Motion leads with the cursor style's link, and Sound
            // with the Music effects switch.
            let leading = usize::from(matches!(
                route,
                SettingsRoute::CursorMotion | SettingsRoute::Sound
            ));
            let (mut runtime, instance, view) = setup();
            let (total, expected_controls) = {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(route);
                state.feedback = feedback.clone();
                let expected_controls = state
                    .legacy
                    .fields
                    .iter()
                    .filter(|field| field_visible(field.key, false, false))
                    .filter(|field| {
                        route
                            .section()
                            .is_some_and(|section| prefs::section_of(field.key) == section)
                    })
                    .count()
                    + leading;
                (
                    expected_controls + usize::from(focused_preview_key(state).is_some()),
                    expected_controls,
                )
            };
            assert!(total >= expected_controls && total > 0, "{route:?}");
            let mut seen_controls = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
                let context = format!("{} screen {top} at {scale}× {variant}", route.label());
                assert_short_landscape_geometry(compiled, scale, &context);
                seen_controls.extend(keys_with_prefix(compiled, "settings/control/"));
                // The theme is its card's rows.
                if compiled
                    .semantics
                    .iter()
                    .any(|node| theme_card_control_key(node.key.as_str()))
                {
                    seen_controls.insert(format!("settings/control/{}", prefs::EDIT_THEME));
                }
            });
            assert_eq!(
                seen_controls.len(),
                expected_controls,
                "{} at {scale}× {variant}",
                route.label()
            );
        }

        // Manual's only action stays whole at 2× with the status band present.
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Manual);
            state.feedback = feedback.clone();
        }
        let manual = compile_settings_view(&runtime, instance, view, &cx);
        let context = format!("Manual at {scale}× {variant}");
        assert_short_landscape_geometry(&manual, scale, &context);
        assert!(
            manual
                .semantic(&UiKey::new("settings/manual/open"))
                .is_some(),
            "{context}"
        );

        // Top Settings: all six requested controls, and the theme and trail
        // cards keep their live previews.
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Home);
            state.feedback = feedback.clone();
        }
        let mut top_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("Top Settings screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            top_keys.extend(keys_with_prefix(compiled, "settings/"));
        });
        for key in [
            prefs::EDIT_THEME,
            prefs::EDIT_WINDOW_THEME,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            prefs::EDIT_TRAIL_SOUNDS,
            SPARKLE_WORDS_KEY,
            KEYWORD_KITTIES_KEY,
        ] {
            assert!(
                top_keys.contains(&format!("settings/control/{key}")),
                "Top Settings {key} at {scale}× {variant}"
            );
        }
        for preview in [
            "settings/top/theme/preview",
            "settings/top/cursor-trail/preview",
        ] {
            assert!(
                top_keys.contains(preview),
                "Top Settings {preview} at {scale}× {variant}"
            );
        }

        // Modified includes both reset-safe known structures and unknown
        // forward-compatible keys. Every exact authored override receives
        // its own complete summary/action slice.
        let mut source = (0..7)
            .map(|index| format!("future_{index} = {index}\n"))
            .collect::<String>();
        source.push_str("[keybindings]\n\"cmd+t\" = \"new_tab\"\n");
        let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
        let (mut runtime, instance, view) = setup();
        let overrides = {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
            state.navigate(SettingsRoute::Modified);
            state.feedback = feedback.clone();
            authored_manual_overrides(state)
        };
        assert_eq!(
            settings_field_result_count(match runtime.view_state(view) {
                Some(AppViewState::Settings(state)) => state,
                _ => unreachable!(),
            }),
            overrides.len()
        );
        let mut modified_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("Modified screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            modified_keys.extend(keys_with_prefix(compiled, "settings/modified/"));
        });
        for authored in &overrides {
            let fragment = key_fragment(&authored.key);
            let context = format!("Modified {} at {scale}× {variant}", authored.key);
            assert!(
                modified_keys.contains(&format!("settings/modified/manual/label/{fragment}")),
                "{context}: label"
            );
            assert!(
                modified_keys.contains(&format!("settings/modified/manual/open/{fragment}")),
                "{context}: Manual escape hatch"
            );
            if authored.reset_safe {
                assert!(
                    modified_keys.contains(&format!("settings/modified/manual/reset/{fragment}")),
                    "{context}: exact Reset"
                );
            }
        }

        // About's page count changes with Dynamic Type: read the range, audit each slice.
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::About);
            state.feedback = feedback.clone();
        }
        let mut about_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("About screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            about_keys.extend(keys_with_prefix(compiled, "about/"));
        });
        for key in [
            "about/copy-build-info",
            "about/open-site",
            "about/provenance/row/version",
            "about/provenance/row/build",
            "about/provenance/row/commit",
            "about/provenance/row/built",
            "about/provenance/row/arch",
            "about/provenance/row/compiler",
            "about/provenance/row/signature",
        ] {
            assert!(
                about_keys.contains(key),
                "About missing {key} at {scale}× {variant}; saw {about_keys:?}"
            );
        }

        // Both updater shapes: the status summary, the action, the automatic-updates
        // switch, the outcome and each release-notes page (the notes panel always says
        // something, so the set is the same).
        for staged in [false, true] {
            let status = update_status(staged);
            let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
            let (mut runtime, instance, view) = setup_with_update(update_state);
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::SoftwareUpdate);
                state.feedback = feedback.clone();
            }
            let mut keys = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
                let context = format!("Update staged={staged} screen {top} at {scale}× {variant}");
                assert_short_landscape_geometry(compiled, scale, &context);
                keys.extend(keys_with_prefix(compiled, "updates/"));
            });
            for key in [
                "updates/hero",
                "updates/install-now",
                "updates/automatic",
                "updates/release-notes",
            ] {
                assert!(
                    keys.contains(key),
                    "Update missing {key}: {staged} {scale}× {variant}"
                );
            }
            // The page has one button. `updates/check` is still a reducer arm and palette
            // command, so this guards against its button coming back.
            assert!(
                !keys.contains("updates/check"),
                "the retired Check button reappeared: {staged} {scale}× {variant}"
            );
        }

        // Packages lists status, the actions, all three maintenance switches
        // and every bounded program; a card taller than the room splits.
        let packages_state = live_packages_state(None);
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(packages_state, 2));
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Packages);
            state.feedback = feedback;
        }
        let mut package_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("Packages screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            package_keys.extend(
                compiled
                    .semantics
                    .iter()
                    .filter(|node| {
                        node.key.as_str().starts_with("packages/")
                            || node.key.as_str().starts_with("settings/control/packages.")
                            || node.key.as_str().starts_with("settings/control/reroute.")
                    })
                    .map(|node| node.key.as_str().to_string()),
            );
        });
        for key in [
            "packages/hero",
            "packages/check",
            "packages/install-default",
            "packages/service-line",
            // One update switch, "Automatic updates" (`enabled`; the retired
            // `auto_update` has no row), the install consent, the reroute's
            // announcement, and the Activity card with its Open Log.
            "settings/control/packages.enabled",
            "settings/control/packages.auto_install",
            "settings/control/reroute.announce",
            "packages/consent-note",
            "packages/programs/ay",
            "packages/activity/open-log",
        ] {
            assert!(
                package_keys.contains(key),
                "Packages missing {key} at {scale}× {variant}"
            );
        }
    }
}

/// The three Packages verbs sit in a row only where the hero card holds them whole and
/// stack anywhere narrower, so every button is inside the card at every width (from a
/// 774 pt, 100-column Medium page up). Negative control: a wide page keeps one row.
#[test]
fn the_packages_verbs_stay_inside_their_card_at_every_width() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    for width in [774.0_f32, 860.0, 1_040.0, 1_300.0] {
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, 900.0));
        let hero = compiled
            .semantic(&UiKey::new("packages/hero"))
            .unwrap_or_else(|| panic!("the hero at {width}"))
            .rect;
        let rects: Vec<_> = [
            "packages/check",
            "packages/install-default",
            "packages/uninstall-all",
        ]
        .iter()
        .map(|key| {
            compiled
                .semantic(&UiKey::new(*key))
                .unwrap_or_else(|| panic!("{key} at {width}"))
                .rect
        })
        .collect();
        for (key, rect) in ["check", "install", "remove"].iter().zip(&rects) {
            assert!(
                rect.x >= hero.x && rect.right() <= hero.right() + 0.5,
                "{key} leaves the card at {width}: {rect:?} in {hero:?}"
            );
        }
        if width >= 1_300.0 {
            assert!(
                rects.iter().all(|r| (r.y - rects[0].y).abs() < 0.5),
                "one row on a wide page: {rects:?}"
            );
        }
    }
}

#[test]
fn unset_text_setting_semantics_report_the_effective_default_while_paint_stays_quiet() {
    let state = SettingsViewState::new(&Config::default());
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_SHELL)
        .expect("shell field");
    assert!(field.seed.is_none());
    assert!(!field.placeholder.is_empty());
    let row = setting_row(&state, 0, field, false, SettingsWidth::Compact);
    let compiled = UiTree::new(row)
        .compile(LogicalRect::new(0.0, 0.0, 390.0, 72.0))
        .unwrap();
    let key = UiKey::new(format!("settings/control/{}", field.key));
    assert_eq!(
        compiled.semantic(&key).expect("semantic text field").value,
        SemanticValue::Text(field.placeholder.clone())
    );
    let paint = compiled
        .paint
        .iter()
        .find(|node| node.key == key)
        .expect("paint text field");
    let UiContent::TextField(control) = &paint.content else {
        panic!("the shell is a text field")
    };
    assert_eq!(control.spec.visual_value.as_deref(), Some(""));
}

/// The fonts a test machine "has": the pickers are built from this list, never
/// from the fonts installed where the test runs.
fn injected_font_families() -> Arc<aterm_render::font_catalog::MonospaceFamilies> {
    Arc::new(aterm_render::font_catalog::MonospaceFamilies {
        automatic: Some("SF Mono".to_string()),
        automatic_has_ligatures: false,
        bundled: vec!["Iosevka Term".to_string()],
        installed: vec!["Menlo".to_string(), "Monaco".to_string()],
        bold: vec!["Menlo Bold".to_string()],
        italic: Vec::new(),
        bold_italic: Vec::new(),
        symbol: vec!["Apple Symbols".to_string()],
        emoji: vec!["Apple Color Emoji".to_string()],
        // Menlo and Monaco have no `GSUB` ligatures; Iosevka Term has them.
        ligatures: [("menlo", false), ("monaco", false), ("iosevkaterm", true)]
            .into_iter()
            .map(|(family, ligatures)| (family.to_string(), ligatures))
            .collect(),
    })
}

fn font_picker_labels(runtime: &NativeRuntime, view: crate::native_app::ViewId) -> Vec<String> {
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    let picker = state.choice_picker.as_ref().expect("a font picker is open");
    // What the list shows: the options the typed filter leaves.
    picker
        .shown
        .iter()
        .map(|index| picker.options[*index].label.clone())
        .collect()
}

fn settings_action(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    id: &str,
) -> crate::native_app::DispatchOutcome {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(id),
                value: None,
            }),
        )
        .unwrap()
}

/// A font picker paints each row as it names it: Automatic says the face it
/// draws and Other… says Other…, neither the generic "Use default" a reset
/// row of another picker paints.
#[test]
fn a_font_picker_paints_its_automatic_and_other_rows_by_their_names() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        assert!(state.replace_font_families(injected_font_families()));
    }
    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family",
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    let picker = state.choice_picker.as_ref().expect("a font picker is open");
    assert!(picker.fonts);
    let painted: Vec<String> = picker
        .options
        .iter()
        .map(|option| {
            choice_option_button(option, 400.0, picker.fonts)
                .visual_label
                .expect("a painted label")
        })
        .collect();
    let named: Vec<String> = picker
        .options
        .iter()
        .map(|option| option.label.clone())
        .collect();
    assert_eq!(painted, named);
    // Another picker's reset row paints what its default is, never a bare
    // "Use default".
    let generic = ChoicePicker::new(
        prefs::EDIT_WINDOW_THEME,
        ["dark".to_string()],
        "dark",
        true,
        true,
        "auto",
    );
    let reset = generic
        .options
        .iter()
        .find(|option| option.value.is_none())
        .expect("a reset row");
    let painted = choice_option_button(reset, 400.0, generic.fonts)
        .visual_label
        .expect("a painted label");
    assert_ne!(painted, "Use default");
    let automatic = setting_choice_label(prefs::EDIT_WINDOW_THEME, "auto");
    assert!(painted.contains(&automatic), "{painted}");
}

/// An unset style, symbol or emoji row names what the terminal reported it
/// draws, in the row, its picker's Automatic entry and the preview header:
/// the real face, what is synthetic over it, the symbol and emoji faces.
/// Before a report, and for a row that names a face of its own, "Automatic"
/// stands alone. Before, only the family row ever named its face.
#[test]
fn unset_style_rows_name_the_faces_the_terminal_draws() {
    let drawn = aterm_render::DrawnFaces {
        regular: Some("SF Mono".to_string()),
        regular_has_ligatures: false,
        styles: [
            aterm_render::StyleDraw {
                face: Some("SF Mono Bold".to_string()),
                synthetic: aterm_render::StyleBits::REGULAR,
            },
            aterm_render::StyleDraw {
                face: Some("SF Mono Italic".to_string()),
                synthetic: aterm_render::StyleBits::REGULAR,
            },
            aterm_render::StyleDraw {
                face: Some("SF Mono Italic".to_string()),
                synthetic: aterm_render::StyleBits::BOLD,
            },
        ],
        symbol: Some("Noto Sans Symbols 2".to_string()),
        emoji: Some("Apple Color Emoji".to_string()),
    };
    let row_value = |runtime: &mut NativeRuntime,
                     instance: crate::native_app::AppInstanceId,
                     view: crate::native_app::ViewId,
                     key: &str| {
        let cx = view_cx_at(900.0, 2400.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        match compiled
            .semantic(&UiKey::new(format!("settings/control/{key}")))
            .map(|row| row.value.clone())
        {
            Some(SemanticValue::Text(text)) => text,
            other => panic!("{key}: {other:?}"),
        }
    };
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        assert!(state.replace_font_families(injected_font_families()));
    }
    assert_eq!(
        row_value(&mut runtime, instance, view, prefs::EDIT_FONT_FAMILY_BOLD),
        "Automatic",
        "no report yet"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        assert!(state.replace_drawn_faces(Some(drawn.clone())));
        assert!(!state.replace_drawn_faces(Some(drawn.clone())), "unchanged");
    }
    for (key, expected) in [
        (prefs::EDIT_FONT_FAMILY, "Automatic (SF Mono)"),
        (prefs::EDIT_FONT_FAMILY_BOLD, "Automatic (SF Mono Bold)"),
        (prefs::EDIT_FONT_FAMILY_ITALIC, "Automatic (SF Mono Italic)"),
        (
            prefs::EDIT_FONT_FAMILY_BOLD_ITALIC,
            "Automatic (SF Mono Italic)",
        ),
        (prefs::EDIT_SYMBOL_FONT, "Automatic (Noto Sans Symbols 2)"),
        (prefs::EDIT_EMOJI_FONT, "Automatic (Apple Color Emoji)"),
    ] {
        assert_eq!(
            row_value(&mut runtime, instance, view, key),
            expected,
            "{key}"
        );
    }
    // What is synthetic over a style's face is a fact after the row's name,
    // not part of the control's words: "Automatic (SF Mono Light Italic,
    // synthetic bold)" ran past a 210-252 pt control and was cut short. A
    // row drawn in its own face states none.
    let row_label = |runtime: &mut NativeRuntime, key: &str| {
        let cx = view_cx_at(900.0, 2400.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled
            .semantic(&UiKey::new(format!("settings/label/{key}")))
            .map(|label| label.label.clone())
            .unwrap_or_else(|| panic!("{key} has a label"))
    };
    assert_eq!(
        row_label(&mut runtime, prefs::EDIT_FONT_FAMILY_BOLD_ITALIC),
        format!("Bold italic font family{FACT_SEPARATOR}Synthetic bold")
    );
    assert_eq!(
        row_label(&mut runtime, prefs::EDIT_FONT_FAMILY_BOLD),
        "Bold font family"
    );
    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family_bold",
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        let picker = state
            .choice_picker
            .as_ref()
            .expect("the bold picker is open");
        assert_eq!(picker.options[0].label, "Automatic (SF Mono Bold)");
    }

    // A row with a face of its own: its picker's Automatic entry is not
    // what the terminal draws now, so it names nothing.
    let mut named = SettingsViewState::new(&Config {
        font_family_bold: Some("Menlo Bold".to_string()),
        ..Config::default()
    });
    named.replace_drawn_faces(Some(drawn));
    assert_eq!(
        font_automatic_label(&named, prefs::EDIT_FONT_FAMILY_BOLD),
        "Automatic"
    );
    assert_eq!(
        font_automatic_label(&named, prefs::EDIT_FONT_FAMILY_ITALIC),
        "Automatic (SF Mono Italic)"
    );
}

/// Font family is a list built from the host's installed fonts: Automatic
/// naming the face drawn, the bundled faces, the installed monospace
/// families, and Other…. Moving through it previews each family; choosing
/// one saves it.
#[test]
fn the_font_family_picker_lists_installed_families_and_previews_each() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        assert!(state.replace_font_families(injected_font_families()));
    }
    // The row is the list's button, naming the automatic face.
    let cx = view_cx_at(900.0, 700.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let row = compiled
        .semantic(&UiKey::new("settings/control/font_family"))
        .unwrap();
    assert_eq!(row.role, SemanticRole::Button);
    assert_eq!(
        row.value,
        SemanticValue::Text("Automatic (SF Mono)".to_string())
    );

    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family",
    );
    assert_eq!(
        font_picker_labels(&runtime, view),
        [
            "Automatic (SF Mono)",
            "Iosevka Term",
            "Menlo",
            "Monaco",
            "Other…"
        ]
    );
    // Down twice: Menlo is highlighted and previewed, nothing written.
    for _ in 0..2 {
        let moved = runtime
            .dispatch(instance, view, AppEvent::StepFocus(1))
            .unwrap();
        assert!(
            moved
                .effects
                .iter()
                .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. }))
        );
    }
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        assert_eq!(
            preview_font_candidate(state).regular.as_deref(),
            Some("Menlo")
        );
    }
    let chosen = settings_action(
        &mut runtime,
        instance,
        view,
        "settings/choice/font_family/2",
    );
    let edit = chosen.effects.iter().find_map(|effect| match effect {
        AppEffect::ConfigPatch { patch, .. } => patch.edits.first().cloned(),
        _ => None,
    });
    assert_eq!(
        edit.map(|edit| (edit.key, edit.value)),
        Some(("font_family".to_string(), Some("Menlo".to_string())))
    );
}

/// Typing into an open font picker narrows it as the resolvers compare names
/// and previews the first match; Backspace widens it again. Other… opens the
/// row for a typed name, which Return saves.
#[test]
fn the_font_picker_takes_typing_and_other_takes_a_name() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        state.replace_font_families(injected_font_families());
    }
    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family",
    );
    for typed in ["m", "e", "n"] {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::TextInput(TextInputEvent::Commit(typed.to_string())),
            )
            .unwrap();
    }
    assert_eq!(font_picker_labels(&runtime, view), ["Menlo", "Other…"]);
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        // Cancel still names what stays saved, though typing hid it.
        assert_eq!(
            picker_saved_label(state.choice_picker.as_ref().unwrap()),
            "Automatic (SF Mono)"
        );
    }
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        assert_eq!(
            preview_font_candidate(state).regular.as_deref(),
            Some("Menlo")
        );
    }
    for _ in 0..3 {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::TextInput(TextInputEvent::Backspace),
            )
            .unwrap();
    }
    assert_eq!(font_picker_labels(&runtime, view).len(), 5);

    // Other…: the row becomes its text field, and Return saves the name.
    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/choice/font_family/4",
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        assert!(state.choice_picker.is_none());
        assert_eq!(
            state.editing_field.as_deref(),
            Some(prefs::EDIT_FONT_FAMILY)
        );
    }
    let cx = view_cx_at(900.0, 700.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/control/font_family"))
            .unwrap()
            .role,
        SemanticRole::TextField
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit("Fira Code".to_string())),
        )
        .unwrap();
    let saved = runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Submit))
        .unwrap();
    let edit = saved.effects.iter().find_map(|effect| match effect {
        AppEffect::ConfigPatch { patch, .. } => patch.edits.first().cloned(),
        _ => None,
    });
    assert_eq!(
        edit.and_then(|edit| edit.value).as_deref(),
        Some("Fira Code")
    );
}

