/// A font the terminal could not find is not "Applied": its row says Not
/// found and is invalid, and the status line says what the terminal did.
/// Saving another name clears it.
#[test]
fn an_unknown_font_name_is_marked_not_found_on_its_row() {
    let mut state = SettingsViewState::new(&Config {
        font_family: Some("NoSuchFontXYZ".to_string()),
        ..Config::default()
    });
    state.feedback = Some("Applied · Undo available".to_string());
    let refusal = crate::native_font_catalog::FontRefusal {
        key: prefs::EDIT_FONT_FAMILY,
        family: "NoSuchFontXYZ".to_string(),
        reason: crate::native_font_catalog::FontRefusalReason::NotFound,
        from_theme: None,
    };
    assert!(state.replace_font_refusals(vec![refusal.clone()], true));
    assert_eq!(
        state.feedback.as_deref(),
        Some("Font not found: \u{201c}NoSuchFontXYZ\u{201d}. The terminal keeps the font it had.")
    );
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_FONT_FAMILY)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
    .unwrap();
    let control = compiled
        .semantic(&UiKey::new("settings/control/font_family"))
        .unwrap();
    assert!(
        control.label.contains("is not installed"),
        "{}",
        control.label
    );
    assert!(control.state.is_some_and(|state| state.invalid));
    let label = compiled
        .semantic(&UiKey::new("settings/label/font_family"))
        .unwrap();
    assert!(label.label.contains("Not found"), "{}", label.label);

    // The same refusal again announces nothing new; a row showing another
    // name is not marked by an old refusal.
    state.feedback = None;
    assert!(!state.replace_font_refusals(vec![refusal.clone()], true));
    assert!(state.feedback.is_none());
    let other = SettingsViewState::new(&Config {
        font_family: Some("Menlo".to_string()),
        ..Config::default()
    });
    assert!(other.font_refusal(prefs::EDIT_FONT_FAMILY).is_none());

    // Fixed outside Settings (a hand edit, a control verb): once the name is
    // no longer refused, its line goes; a line put up since then stays.
    let mut fixed = SettingsViewState::new(&Config {
        font_family: Some("NoSuchFontXYZ".to_string()),
        ..Config::default()
    });
    assert!(fixed.replace_font_refusals(vec![refusal.clone()], true));
    assert!(
        fixed
            .feedback
            .as_deref()
            .is_some_and(|line| line.starts_with("Font not found"))
    );
    assert!(fixed.replace_font_refusals(Vec::new(), true));
    assert_eq!(fixed.feedback, None, "the line went with the refusal");
    assert!(fixed.replace_font_refusals(vec![refusal], true));
    fixed.feedback = Some("Color theme set to Nord".to_string());
    assert!(fixed.replace_font_refusals(Vec::new(), true));
    assert_eq!(fixed.feedback.as_deref(), Some("Color theme set to Nord"));
}

/// A style row whose name resolved to a face of another style (`Menlo
/// Italic` in the Bold row) draws that face; the row says it is not a bold
/// face — a note, not an error — instead of a plain "Changed".
#[test]
fn a_style_row_naming_a_face_of_another_style_says_so() {
    let mut state = SettingsViewState::new(&Config {
        font_family_bold: Some("Menlo Italic".to_string()),
        ..Config::default()
    });
    let refusal = crate::native_font_catalog::FontRefusal {
        key: prefs::EDIT_FONT_FAMILY_BOLD,
        family: "Menlo Italic".to_string(),
        reason: crate::native_font_catalog::FontRefusalReason::WrongStyle,
        from_theme: None,
    };
    assert!(state.replace_font_refusals(vec![refusal], true));
    assert_eq!(
        state.feedback.as_deref(),
        Some("\u{201c}Menlo Italic\u{201d} is not a bold face. Bold text is drawn in it.")
    );
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_FONT_FAMILY_BOLD)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
    .unwrap();
    let label = compiled
        .semantic(&UiKey::new("settings/label/font_family_bold"))
        .unwrap();
    assert!(label.label.contains("Not a bold face"), "{}", label.label);
    let control = compiled
        .semantic(&UiKey::new("settings/control/font_family_bold"))
        .unwrap();
    assert!(
        control.state.is_some_and(|state| !state.invalid),
        "the face draws: a note, not an error"
    );
}

/// "Three display faces are on" describes the saved mix: once the mix
/// changes outside Settings, the line goes.
#[test]
fn the_full_display_face_line_goes_when_the_mix_changes_elsewhere() {
    let mut service =
        VersionedConfigService::new("display_font = \"chunky+pixel+engraved\"\n".to_string())
            .unwrap();
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view")
        };
        **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    }
    runtime
        .dispatch(instance, view, action("settings/display-face/bubble", None))
        .unwrap();
    let feedback = |runtime: &NativeRuntime| {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        state.feedback.clone()
    };
    assert_eq!(
        feedback(&runtime).as_deref(),
        Some("Three display faces are on, the most at once. Turn one off first.")
    );
    let unrelated = service
        .replace_external(
            "display_font = \"chunky+pixel+engraved\"\ntheme = \"Nord\"\n".to_string(),
        )
        .unwrap();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(unrelated))
        .unwrap();
    assert!(
        feedback(&runtime).is_some(),
        "another key's change leaves it"
    );
    let unset = service.replace_external(String::new()).unwrap();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(unset))
        .unwrap();
    assert_eq!(feedback(&runtime), None);
}

/// A display face is a layer over the font family, never in its place: the
/// specimen asks for the person's font AND the faces drawn over it, names the
/// faces it draws, and the Font family row stays live — the font still sets
/// the grid, draws what the faces lack and is the chrome's font. Before, the
/// face replaced the font, so the row read "Inactive: display face on".
#[test]
fn the_specimen_draws_the_display_layer_over_the_font_family() {
    let state = SettingsViewState::new(&Config {
        font_family: Some("Menlo".to_string()),
        display_font: Some("chunky".to_string()),
        ..Config::default()
    });
    let candidate = preview_font_candidate(&state);
    assert_eq!(candidate.regular.as_deref(), Some("Menlo"));
    assert_eq!(candidate.display, ["chunky"]);
    let spec = renderer_preview_spec_for_key_with_font(
        &state,
        prefs::EDIT_FONT_FAMILY,
        0,
        crate::native_app::ViewMotionCx::default(),
        12.0,
        1.0,
        None,
    )
    .unwrap();
    assert!(
        spec.semantic_value().contains("Chunky (display face)"),
        "{}",
        spec.semantic_value()
    );
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_FONT_FAMILY)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
    .unwrap();
    let label = compiled
        .semantic(&UiKey::new("settings/label/font_family"))
        .unwrap();
    assert!(!label.label.contains("nactive"), "{}", label.label);
    // A mix asks for every face it draws, in registry order, over Automatic.
    let mixed = SettingsViewState::new(&Config {
        display_font: Some("engraved+pixel".to_string()),
        ..Config::default()
    });
    let candidate = preview_font_candidate(&mixed);
    assert_eq!(candidate.regular, None);
    assert_eq!(candidate.display, ["pixel", "engraved"]);
}

/// The Ligatures switch says it does nothing with the font the terminal
/// draws when that font has no programming ligatures: the automatic face,
/// and any family the font list knows has none (Menlo, Monaco) — as saved,
/// as typed in a draft, spelled any way. A family with ligatures, a name the
/// list does not hold, and a switch already off say nothing. Before, only the
/// automatic face was ever judged.
#[test]
fn ligatures_say_when_the_drawn_font_has_none() {
    let ligatures_label = |state: &SettingsViewState| {
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == prefs::EDIT_LIGATURES)
            .unwrap();
        let compiled = UiTree::new(setting_row(state, index, field, false, SettingsWidth::Wide))
            .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
            .unwrap();
        compiled
            .semantic(&UiKey::new("settings/label/ligatures"))
            .unwrap()
            .label
            .clone()
    };
    let with = |config: Config| {
        let mut state = SettingsViewState::new(&config);
        state.replace_font_families(injected_font_families());
        state
    };
    let mut automatic = SettingsViewState::new(&Config::default());
    assert!(!ligatures_label(&automatic).contains("No effect"));
    automatic.replace_font_families(injected_font_families());
    assert!(
        ligatures_label(&automatic).contains("No effect with SF Mono"),
        "{}",
        ligatures_label(&automatic)
    );
    for family in ["Menlo", "menlo"] {
        let chosen = with(Config {
            font_family: Some(family.to_string()),
            ..Config::default()
        });
        assert!(
            ligatures_label(&chosen).contains("No effect with Menlo"),
            "{family}: {}",
            ligatures_label(&chosen)
        );
    }
    let mut drafted = with(Config::default());
    drafted.field_inputs.insert(
        prefs::EDIT_FONT_FAMILY.to_string(),
        crate::native_text_input::TextInputState::new("Monaco".to_string()),
    );
    assert!(
        ligatures_label(&drafted).contains("No effect with Monaco"),
        "{}",
        ligatures_label(&drafted)
    );
    // A name the font list does not hold — a path, a PostScript name — is
    // judged by the terminal's report of the face it draws, for the family
    // it draws now: never before a report, nor for a family being tried.
    let report = |ligatures: bool| aterm_render::DrawnFaces {
        regular: Some("Menlo".to_string()),
        regular_has_ligatures: ligatures,
        styles: std::array::from_fn(|_| aterm_render::StyleDraw {
            face: None,
            synthetic: aterm_render::StyleBits::REGULAR,
        }),
        symbol: None,
        emoji: None,
    };
    let mut path = with(Config {
        font_family: Some("/System/Library/Fonts/Menlo.ttc".to_string()),
        ..Config::default()
    });
    assert!(
        !ligatures_label(&path).contains("No effect"),
        "no report yet"
    );
    path.replace_drawn_faces(Some(report(false)));
    assert!(
        ligatures_label(&path).contains("No effect with Menlo"),
        "{}",
        ligatures_label(&path)
    );
    path.replace_drawn_faces(Some(report(true)));
    assert!(!ligatures_label(&path).contains("No effect"));
    let mut tried = with(Config::default());
    tried.replace_drawn_faces(Some(report(false)));
    tried.field_inputs.insert(
        prefs::EDIT_FONT_FAMILY.to_string(),
        crate::native_text_input::TextInputState::new("Menlo-Regular".to_string()),
    );
    assert!(
        !ligatures_label(&tried).contains("No effect"),
        "{}",
        ligatures_label(&tried)
    );
    // A theme's font is the one drawn when the config names none.
    let themed = {
        let text = "foreground = #e0e0e0\nbackground = #101418\nfont_family = Menlo\n";
        let parsed = aterm_types::scheme::parse_theme_str(text).expect("a theme");
        let catalog = crate::app_config::ThemeCatalog::from_parsed([("Mono".to_string(), parsed)]);
        let mut service = VersionedConfigService::new("theme = \"Mono\"\n".to_string()).unwrap();
        let mut state =
            SettingsViewState::from_snapshot(&service.replace_theme_catalog(catalog)).unwrap();
        state.replace_font_families(injected_font_families());
        state
    };
    assert!(
        ligatures_label(&themed).contains("No effect with Menlo"),
        "{}",
        ligatures_label(&themed)
    );
    for quiet in [
        Config {
            font_family: Some("Iosevka Term".to_string()),
            ..Config::default()
        },
        Config {
            font_family: Some("Not A Listed Family".to_string()),
            ..Config::default()
        },
        Config {
            font_family: Some("Menlo".to_string()),
            ligatures: Some(false),
            ..Config::default()
        },
    ] {
        let state = with(quiet);
        assert!(
            !ligatures_label(&state).contains("No effect"),
            "{}",
            ligatures_label(&state)
        );
    }
}

/// A `display:` font family — a theme's, or the config's older spelling —
/// names display faces, drawn as a layer over the automatic font
/// (`Config::display_faces_request`), never as the font. Settings shows it
/// so: the switches show those faces on, Ligatures says a display face is
/// on, the font row names the automatic face (under a theme's) or says what
/// the value does (the config's own), and turning the last face off writes
/// `off` over them rather than clearing a key that would bring them back.
/// Before, the row read "display:pixel (from theme Arcade)" with every switch
/// Off, while the terminal drew SF Mono under Pixel.
#[test]
fn a_display_family_shows_as_the_display_layer() {
    let catalog = {
        let text = "foreground = #e0e0e0\nbackground = #101418\nfont_family = display:pixel\n";
        let parsed = aterm_types::scheme::parse_theme_str(text).expect("a theme");
        crate::app_config::ThemeCatalog::from_parsed([("Arcade".to_string(), parsed)])
    };
    let view_over = |source: &str| {
        let mut service = VersionedConfigService::new(source.to_string()).unwrap();
        let snapshot = service.replace_theme_catalog(Arc::clone(&catalog));
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
            state.navigate(SettingsRoute::TextFonts);
            assert!(state.replace_font_families(injected_font_families()));
        }
        (service, runtime, instance, view)
    };
    let compiled_of = |runtime: &mut NativeRuntime,
                       instance: crate::native_app::AppInstanceId,
                       view: crate::native_app::ViewId| {
        let cx = view_cx_at(900.0, 2400.0);
        runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap()
    };
    let on = |compiled: &crate::native_ui::CompiledUi, id: &str| {
        compiled
            .semantic(&UiKey::new(format!("settings/display-face/{id}")))
            .map(|node| node.value.clone())
            == Some(SemanticValue::Bool(true))
    };
    let label = |compiled: &crate::native_ui::CompiledUi, key: &str| {
        compiled
            .semantic(&UiKey::new(format!("settings/label/{key}")))
            .unwrap_or_else(|| panic!("{key} label"))
            .label
            .clone()
    };
    let value = |compiled: &crate::native_ui::CompiledUi, key: &str| match compiled
        .semantic(&UiKey::new(format!("settings/control/{key}")))
        .map(|node| node.value.clone())
    {
        Some(SemanticValue::Text(text)) => text,
        other => panic!("{key}: {other:?}"),
    };
    let written = |outcome: crate::native_app::DispatchOutcome| {
        outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => patch
                    .edits
                    .iter()
                    .find(|edit| edit.key == prefs::EDIT_DISPLAY_FONT)
                    .map(|edit| edit.value.clone()),
                _ => None,
            })
            .expect("a display_font write")
    };

    // The theme's `display:` family.
    let (_service, mut runtime, instance, view) = view_over("theme = \"Arcade\"\n");
    let compiled = compiled_of(&mut runtime, instance, view);
    assert!(on(&compiled, "pixel"), "the theme's face is drawn");
    assert!(!on(&compiled, "chunky"));
    assert_eq!(
        value(&compiled, prefs::EDIT_FONT_FAMILY),
        "Automatic (SF Mono)"
    );
    assert!(
        label(&compiled, prefs::EDIT_LIGATURES).contains("Inactive: display face on"),
        "{}",
        label(&compiled, prefs::EDIT_LIGATURES)
    );
    let off = settings_action(&mut runtime, instance, view, "settings/display-face/pixel");
    assert_eq!(
        written(off),
        Some("off".to_string()),
        "over the theme's face"
    );

    // The config's older spelling.
    let (_service, mut runtime, instance, view) = view_over("font_family = \"display:pixel\"\n");
    let compiled = compiled_of(&mut runtime, instance, view);
    assert!(on(&compiled, "pixel"));
    assert!(
        label(&compiled, prefs::EDIT_FONT_FAMILY).contains("Display faces, not a font"),
        "{}",
        label(&compiled, prefs::EDIT_FONT_FAMILY)
    );
    let off = settings_action(&mut runtime, instance, view, "settings/display-face/pixel");
    assert_eq!(written(off), Some("off".to_string()));

    // Negative control: a face `display_font` alone turns on clears the key.
    let (_service, mut runtime, instance, view) = view_over("display_font = \"pixel\"\n");
    let compiled = compiled_of(&mut runtime, instance, view);
    assert!(on(&compiled, "pixel"));
    assert_eq!(label(&compiled, prefs::EDIT_FONT_FAMILY), "Font family");
    let off = settings_action(&mut runtime, instance, view, "settings/display-face/pixel");
    assert_eq!(written(off), None);
}

/// With three display faces on, the fourth switch says why it cannot come on
/// and stays reachable, and pressing it is refused with a message instead of
/// turning the oldest face off unseen.
#[test]
fn a_fourth_display_face_is_refused_out_loud() {
    let (mut runtime, instance, view) = setup();
    replace_settings_source(
        &mut runtime,
        view,
        "display_font = \"chunky+pixel+engraved\"\n".to_string(),
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        let (card, _) = display_faces_card(
            state,
            SettingsWidth::Medium,
            LogicalRect::new(0.0, 0.0, 900.0, 900.0),
        );
        let compiled = UiTree::new(card)
            .compile(LogicalRect::new(0.0, 0.0, 700.0, 900.0))
            .unwrap();
        let fourth = compiled
            .semantic(&UiKey::new("settings/display-face/bubble"))
            .unwrap();
        assert!(fourth.state.is_some_and(|state| state.enabled));
        assert!(
            fourth
                .description
                .as_deref()
                .is_some_and(|text| text.contains("turn one off")),
            "{:?}",
            fourth.description
        );
        let on = compiled
            .semantic(&UiKey::new("settings/display-face/chunky"))
            .unwrap();
        assert!(on.state.is_some_and(|state| state.enabled));
    }
    let refused = settings_action(&mut runtime, instance, view, "settings/display-face/bubble");
    assert!(
        refused
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. }))
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert_eq!(
        state.feedback.as_deref(),
        Some("Three display faces are on, the most at once. Turn one off first.")
    );
}

/// Each styled and fallback row lists the installed faces that suit it; a
/// saved name that is none of them is listed as current. Without the host's
/// list the family picker still offers Automatic, the bundled faces and
/// Other….
#[test]
fn every_font_row_lists_the_faces_that_suit_it() {
    let mut state = SettingsViewState::new(&Config {
        font_family_bold: Some("Hand Set Bold".to_string()),
        ..Config::default()
    });
    let labels = |state: &SettingsViewState, key: &str| {
        font_choice_picker(state, key)
            .options
            .into_iter()
            .map(|option| option.label)
            .collect::<Vec<_>>()
    };
    let bundled = aterm_render::bundled::selectable_families().len();
    assert_eq!(labels(&state, prefs::EDIT_FONT_FAMILY).len(), bundled + 2);
    state.replace_font_families(injected_font_families());
    assert_eq!(
        labels(&state, prefs::EDIT_FONT_FAMILY_BOLD),
        [
            "Automatic",
            "Menlo Bold",
            "Hand Set Bold (current)",
            "Other…"
        ]
    );
    assert_eq!(
        labels(&state, prefs::EDIT_EMOJI_FONT),
        ["Automatic", "Apple Color Emoji", "Other…"]
    );
    assert_eq!(
        labels(&state, prefs::EDIT_SYMBOL_FONT),
        ["Automatic", "Apple Symbols", "Other…"]
    );
    assert_eq!(
        font_choice_picker(&state, prefs::EDIT_FONT_FAMILY_BOLD).selected,
        2
    );
}

#[test]
fn update_check_command_and_reducer_share_enabled_state() {
    let assert_state = |update: UpdateState, expected_enabled: bool| {
        let (mut runtime, instance, view) = setup_with_update(update);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let command = runtime
            .commands(instance, view)
            .unwrap()
            .into_iter()
            .find(|command| command.id.as_str() == "updates/check")
            .expect("update command");
        assert_eq!(command.enabled, expected_enabled);
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("updates/check"),
                    value: None,
                }),
            )
            .unwrap();
        assert_eq!(
            outcome
                .effects
                .iter()
                .filter(|effect| matches!(effect, AppEffect::Update { .. }))
                .count(),
            usize::from(expected_enabled)
        );
    };

    assert_state(UpdateState::from_status(1, "0.1.0", None, false), false);
    let enabled = update_status(false);
    assert_state(
        UpdateState::from_status(1, "0.1.0", Some(&enabled), false),
        true,
    );
    assert_state(
        UpdateState::from_status(1, "0.1.0", Some(&enabled), true),
        false,
    );
}

#[test]
fn typography_list_pins_its_specimen_and_reaches_every_field() {
    at_each_text_scale(
        &[1.0],
        "typography page geometry",
        typography_list_pins_its_specimen_and_reaches_every_field_at_scale,
    );
}

/// [`typography_list_pins_its_specimen_and_reaches_every_field`] at 1.0× ([`at_each_text_scale`]).
fn typography_list_pins_its_specimen_and_reaches_every_field_at_scale(_scale: f32) {
    let mut renderer = aterm_render::Renderer::from_bytes(
        include_bytes!("../../aterm-render/tests/fixtures/jetbrains-mono.ttf"),
        36.0,
        aterm_render::Theme::default(),
    )
    .unwrap();
    renderer.set_runtime_font_discovery(false);
    crate::tray_raster::install_settled_chrome_fonts_for_test(renderer);
    // Medium and wide windows, the 80x24 launch window, and a short wide
    // one whose height forces the compact layout.
    for (width, height) in [
        (904.0, 600.0),
        (904.0, 579.0),
        (1280.0, 800.0),
        (580.0, 348.0),
        (1600.0, 494.0),
    ] {
        let (mut runtime, instance, view) = setup();
        replace_settings_source(&mut runtime, view, "font_px = 36\n".to_string());
        let expected: BTreeSet<String> = {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.navigate(SettingsRoute::TextFonts);
            state
                .legacy
                .fields
                .iter()
                .filter(|field| prefs::section_of(field.key) == prefs::Section::Typography)
                .filter(|field| field_visible(field.key, false, false))
                .filter(|field| field.key != prefs::EDIT_DISPLAY_FONT)
                .map(|field| format!("settings/control/{}", field.key))
                .collect()
        };
        let mut cx = view_cx_at(width, height);
        cx.terminal_font_px = 36.0;
        cx.terminal_scale = 2.0;
        cx.semantic_font = Some(
            crate::tray_raster::prepared_semantic_font_for_direct_view_test(
                &crate::widget::SemanticFontCandidate::default(),
            ),
        );
        let faces: BTreeSet<String> = aterm_render::DISPLAY_FACES
            .iter()
            .map(|face| format!("settings/display-face/{}", face.id))
            .collect();
        // The specimen is pinned over every screen; every native field and
        // every Display faces switch is reached whole.
        let mut seen = BTreeSet::new();
        let mut seen_faces = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, _top| {
            compiled.validate_parity().unwrap();
            if let Some(preview) = compiled.semantic(&UiKey::new("settings/preview/text-fonts")) {
                assert!(preview.rect.bottom() <= height + 0.01);
            }
            for control in compiled.semantics.iter().filter(|node| {
                node.key.as_str().starts_with("settings/control/")
                    || faces.contains(node.key.as_str())
            }) {
                assert!(control.rect.bottom() <= height + 0.01);
                assert!(
                    compiled.hits.iter().any(|hit| hit.key == control.key),
                    "{} must remain actionable",
                    control.key.as_str()
                );
                if faces.contains(control.key.as_str()) {
                    seen_faces.insert(control.key.as_str().to_string());
                } else {
                    seen.insert(control.key.as_str().to_string());
                }
            }
        });
        seen.retain(|key| expected.contains(key));
        assert_eq!(seen, expected, "all fields reachable at {width}x{height}");
        assert_eq!(
            seen_faces, faces,
            "every display face reachable at {width}x{height}"
        );
    }
}

/// A search for an agent finds its switch first: "claude" and "codex" each
/// put Supervise <product> sessions at the top of the settings found,
/// above the rows that only list the word as a synonym (the packages
/// switch, the harness's other rows): the agent's word is the
/// switch's own name (`prefs::own_name_of`), and on the same rung a hit on
/// a row's own names ranks before a synonym's (`SearchRank`). Every
/// supervisable agent, so a new one is held to it. Negative control: the
/// synonym rows are still found, below it.
#[test]
fn a_search_for_an_agent_finds_its_switch_first() {
    for agent in aterm_phase::Program::ALL
        .into_iter()
        .filter(|agent| agent.harness_table())
    {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/search"),
                    value: Some(SemanticInput::Text(agent.name().to_string())),
                }),
            )
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx());
        let rows: Vec<&str> = compiled
            .semantics
            .iter()
            .map(|node| node.key.as_str())
            .filter(|key| key.starts_with("settings/row/"))
            .collect();
        let switch = format!("/harness.{}.enabled", agent.name());
        assert!(
            rows.first().is_some_and(|row| row.ends_with(&switch)),
            "{}: {rows:?}",
            agent.name()
        );
        assert!(
            rows.iter().any(|row| row.ends_with("/packages.enabled")),
            "{}: the synonym rows are still found: {rows:?}",
            agent.name()
        );
    }
}

#[test]
fn search_is_global_ranked_and_keeps_category_context() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/search"),
                value: Some(SemanticInput::Text("clipboard".to_string())),
            }),
        )
        .unwrap();
    let cx = view_cx();
    let first = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    // "clipboard" lands two live native switches on one page, each under its own
    // category heading (`allow_osc52_query` is an ordinary security policy).
    assert!(
        first
            .semantic(&UiKey::new("settings/control/allow_osc52_query"))
            .is_some(),
        "the OSC 52 read policy is a live, searchable native switch"
    );
    assert!(
        first
            .semantic(&UiKey::new(
                "settings/group-heading/security---permissions/allow-osc52-query"
            ))
            .is_some(),
        "…grouped under its Security · Permissions heading"
    );
    let compiled = first;
    assert!(
        compiled
            .semantic(&UiKey::new("settings/control/copy_on_select"))
            .is_some()
    );
    // The page that holds the row, by its sidebar name, heads its group;
    // the row itself keeps its plain name.
    let label = compiled
        .semantic(&UiKey::new("settings/label/copy_on_select"))
        .expect("globally matched input setting");
    assert_eq!(label.label, "Copy on select");
    assert!(
        compiled.semantics.iter().any(|node| node
            .key
            .as_str()
            .starts_with("settings/group-heading/keyboard---input---clipboard/")),
        "category context: the Keyboard & Input · Clipboard heading"
    );
    assert!(
        compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("settings/nav/"))
            .all(|node| node.state.is_none_or(|state| !state.selected)),
        "global search must not imply that results are route-scoped"
    );
}

#[test]
fn default_on_boolean_apply_and_reset_round_trip_through_real_config_service() {
    let (mut runtime, instance, view) = setup();
    let mut service = VersionedConfigService::new(String::new()).unwrap();

    let modified = {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        state.navigate(SettingsRoute::Modified);
        runtime
            .render(instance, view, &view_cx())
            .unwrap()
            .compile(view_cx().viewport)
            .unwrap()
    };
    assert!(
        modified.semantic(&UiKey::new("settings/empty")).is_some(),
        "resolved default-on Boolean seeds are not raw overrides"
    );

    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK)),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let (patch, operation) = outcome
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, reply, .. } => Some((patch.clone(), reply.operation)),
            _ => None,
        })
        .expect("Boolean edit reaches config service");
    assert_eq!(
        patch.edits[0].expected,
        ExpectedConfigValue::Exact(None),
        "the absent raw key, not effective true, is the OCC expectation"
    );
    let (snapshot, undo) = apply_real_config_patch(&mut service, &patch);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: snapshot.revision,
                    undo,
                },
            },
        )
        .unwrap();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot.clone()))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    let blink = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
        .unwrap();
    assert_eq!(SettingsState::display_value(blink), "false");
    assert!(state.is_explicit(prefs::EDIT_CURSOR_BLINK));

    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/reset/{}", prefs::EDIT_CURSOR_BLINK)),
                value: None,
            }),
        )
        .unwrap();
    let (patch, operation) = outcome
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, reply, .. } => Some((patch.clone(), reply.operation)),
            _ => None,
        })
        .expect("reset reaches config service");
    assert_eq!(
        patch.edits[0].expected,
        ExpectedConfigValue::Exact(Some("false".to_string()))
    );
    assert_eq!(patch.edits[0].value, None);
    let (snapshot, undo) = apply_real_config_patch(&mut service, &patch);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: snapshot.revision,
                    undo,
                },
            },
        )
        .unwrap();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot.clone()))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    let blink = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
        .unwrap();
    assert_eq!(
        SettingsState::display_value(blink),
        "true",
        "removing the key restores the effective default-on display"
    );
    assert!(!state.is_explicit(prefs::EDIT_CURSOR_BLINK));
}

#[test]
fn indeterminate_config_publication_stays_unverified_until_snapshot_reconciliation() {
    let (mut runtime, instance, view) = setup();
    let (before_raw, before_display) = {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        state.last_undo = Some(UndoOffer::showing(41, "Cursor blink turned off"));
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
            .unwrap();
        (
            state.raw_value(prefs::EDIT_CURSOR_BLINK),
            SettingsState::display_value(field).to_string(),
        )
    };
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK)),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let (patch, operation) = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, reply, .. } => Some((patch.clone(), reply.operation)),
            _ => None,
        })
        .expect("change enters the config writer");

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Indeterminate {
                    message: "directory sync could not be verified".to_string(),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    assert_eq!(state.raw_value(prefs::EDIT_CURSOR_BLINK), before_raw);
    assert_eq!(
        SettingsState::display_value(
            state
                .legacy
                .fields
                .iter()
                .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
                .unwrap()
        ),
        before_display,
        "an unverified publication is never projected as a committed value"
    );
    assert_eq!(state.unverified_patch.as_ref(), Some(&patch));
    assert!(state.config_reconciliation_required);
    assert!(state.last_undo.is_none());
    assert!(state.feedback.is_some(), "the unverified save is said");

    let commands = runtime.commands(instance, view).unwrap();
    for id in ["settings/undo", "settings/reset-all"] {
        assert!(
            !commands
                .iter()
                .find(|command| command.id.as_str() == id)
                .unwrap()
                .enabled,
            "{id} remains blocked until reconciliation"
        );
    }
    // The page takes another press while the host reconciles the first
    // save. This bare reducer emits its request; the host's config lane
    // holds it behind reconciliation before it may write. The press turns
    // Copy on select off: on, its default here, would change nothing and
    // ask for no write.
    // NEGATIVE CONTROL: a press of its default changes nothing the file
    // holds, so it is no request at all, fence or none.
    let unchanged = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_COPY_ON_SELECT)),
                value: Some(SemanticInput::Bool(
                    crate::app_config::Config::default().copy_on_select_or_default(),
                )),
            }),
        )
        .unwrap();
    assert!(
        unchanged
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
        "a press of the default asks for no write"
    );
    let queued = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_COPY_ON_SELECT)),
                value: Some(SemanticInput::Bool(
                    !crate::app_config::Config::default().copy_on_select_or_default(),
                )),
            }),
        )
        .unwrap();
    assert_eq!(
        queued
            .effects
            .iter()
            .filter(|effect| matches!(effect, AppEffect::ConfigPatch { .. }))
            .count(),
        1,
        "the later press is a request for the host's fenced lane"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    assert!(state.config_reconciliation_required);
    assert_eq!(state.unverified_patch.as_ref(), Some(&patch));
    assert_eq!(state.raw_value(prefs::EDIT_CURSOR_BLINK), before_raw);
    assert!(
        state.last_undo.is_none(),
        "the new request verifies no save"
    );

    let snapshot = VersionedConfigService::new(String::new())
        .unwrap()
        .snapshot();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(!state.config_reconciliation_required);
    assert!(state.unverified_patch.is_none());
    assert!(state.feedback.is_none());
}

#[test]
fn reset_all_requires_an_explicit_confirmation_and_discloses_its_scope() {
    let (mut runtime, instance, view) = setup();
    replace_settings_source(
        &mut runtime,
        view,
        "theme = \"Nord\"\ncursor_blink = false\nkeybindings = { \"cmd+k\" = \"clear\" }\n"
            .to_string(),
    );
    let expected_edits = 2;

    let ask = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/reset-all"),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        ask.effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
        "the disclosure step must never mutate configuration"
    );

    let cx = view_cx_at(1_080.0, 720.0);
    let confirmation = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    assert!(
        confirmation
            .semantic(&UiKey::new("settings/status"))
            .is_some(),
        "scope disclosure"
    );
    assert_eq!(
        confirmation
            .semantics
            .iter()
            .filter(|node| {
                node.key.as_str().starts_with("settings/status")
                    && node.role == SemanticRole::Status
            })
            .count(),
        1
    );
    assert!(
        confirmation
            .semantic(&UiKey::new("settings/reset-all-cancel"))
            .is_some()
    );
    assert!(
        confirmation
            .semantic(&UiKey::new("settings/reset-all-confirm"))
            .is_some()
    );

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/reset-all-cancel"),
                value: None,
            }),
        )
        .unwrap();
    let stale_confirm = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/reset-all-confirm"),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        stale_confirm
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
        "a stale semantic confirm cannot bypass the disclosure"
    );

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/reset-all"),
                value: None,
            }),
        )
        .unwrap();
    let confirmed = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/reset-all-confirm"),
                value: None,
            }),
        )
        .unwrap();
    let patch = confirmed
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, .. } => Some(patch),
            _ => None,
        })
        .expect("explicit confirmation emits one clearing patch");
    assert_eq!(patch.edits.len(), expected_edits);
    assert!(patch.edits.iter().all(|edit| edit.value.is_none()));
    assert!(
        patch
            .edits
            .iter()
            .all(|edit| !prefs::manual_only_key(&edit.key)),
        "Reset All preserves every Manual-only value"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    assert!(!state.reset_all_confirmation);
}

/// Reset All keeps exactly what its disclosure names: every row Modified
/// lists under Manual overrides stays, and the rest is cleared — `shell`
/// too, which no ordinary page shows — with the retired `[packages]`
/// spelling the one override it clears, as the setting it spells resets.
/// The disclosure once promised "every setting" while `[harness] upgrade`
/// and `windowing_behavior` survived the
/// confirm unnamed; the inert `matrix_rain.materialize`, listed under
/// Manual overrides, was cleared (the negative control).
#[test]
fn reset_all_clears_every_setting_and_keeps_every_manual_override() {
    let source = r#"shell = "/bin/zsh"
theme = "Nord"
windowing_behavior = "attach"
cursor_nyan_sprite = "/aterm/no-such-reset-cat.png"
[harness]
upgrade = false
[matrix_rain]
materialize = true
[packages]
auto_update = false
"#;
    let (mut runtime, instance, view) = setup();
    let snapshot = VersionedConfigService::new(String::new())
        .unwrap()
        .replace_external(source.to_string())
        .unwrap();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    let overrides = authored_manual_override_keys(state)
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    let mut press = |id: &str| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap()
    };
    press("settings/reset-all");
    let confirmed = press("settings/reset-all-confirm");
    let patch = confirmed
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, .. } => Some(patch),
            _ => None,
        })
        .expect("the confirm clears");
    let cleared = patch
        .edits
        .iter()
        .map(|edit| edit.key.as_str())
        .collect::<BTreeSet<_>>();

    assert!(field_visible(prefs::EDIT_SHELL, true, false));
    for key in [prefs::EDIT_SHELL, prefs::EDIT_THEME] {
        assert!(!overrides.contains(key), "{key} is a Settings row");
        assert!(cleared.contains(key), "Reset All clears {key}: {patch:?}");
    }
    assert!(overrides.contains(prefs::RETIRED_PACKAGES_AUTO_UPDATE));
    assert!(cleared.contains(prefs::RETIRED_PACKAGES_AUTO_UPDATE));
    for key in [
        "windowing_behavior",
        prefs::EDIT_CURSOR_NYAN_SPRITE,
        "harness.upgrade",
        "matrix_rain.materialize",
    ] {
        assert!(overrides.contains(key), "{key} is a Manual override");
    }
    for key in &overrides {
        assert!(
            !cleared.contains(key.as_str()) || key == prefs::RETIRED_PACKAGES_AUTO_UPDATE,
            "Reset All keeps the Manual override {key}: {patch:?}"
        );
    }
}

