#[test]
fn authored_weight_axis_survives_until_an_explicit_weight_alias_overrides_it() {
    let axis_value = |candidate: &crate::widget::SemanticFontCandidate| {
        candidate
            .variations
            .iter()
            .find(|variation| variation.tag == aterm_render::variation::WGHT_TAG)
            .map(|variation| variation.value())
    };
    let variation_only = SettingsViewState::new(&Config {
        font_variation: Some(crate::app_config::FontList(vec!["wght=450".to_string()])),
        ..Config::default()
    });
    assert_eq!(
        axis_value(&preview_font_candidate(&variation_only)),
        Some(450.0)
    );

    let explicit_alias = SettingsViewState::new(&Config {
        font_variation: Some(crate::app_config::FontList(vec!["wght=450".to_string()])),
        font_weight: Some(625),
        ..Config::default()
    });
    let candidate = preview_font_candidate(&explicit_alias);
    assert_eq!(axis_value(&candidate), Some(625.0));
    assert_eq!(
        candidate
            .variations
            .iter()
            .filter(|variation| variation.tag == aterm_render::variation::WGHT_TAG)
            .count(),
        1,
        "the explicit alias replaces rather than duplicates the axis",
    );

    let mut retained_draft = variation_only;
    retained_draft.field_inputs.insert(
        prefs::EDIT_FONT_WEIGHT.to_string(),
        crate::native_text_input::TextInputState::new("700".to_string()),
    );
    // The preview keeps a draft after focus moves to a sibling font field, so it
    // must outrank the committed variation too.
    retained_draft.editing_field = Some(prefs::EDIT_FONT_FAMILY.to_string());
    assert_eq!(
        axis_value(&preview_font_candidate(&retained_draft)),
        Some(700.0)
    );

    let mut cleared_alias = SettingsViewState::new(&Config {
        font_variation: Some(crate::app_config::FontList(vec!["wght=450".to_string()])),
        font_weight: Some(625),
        ..Config::default()
    });
    cleared_alias.field_inputs.insert(
        prefs::EDIT_FONT_WEIGHT.to_string(),
        crate::native_text_input::TextInputState::new(String::new()),
    );
    assert_eq!(
        axis_value(&preview_font_candidate(&cleared_alias)),
        Some(450.0),
        "a retained blank is an authored reset and must not fall through to the raw alias",
    );
}

#[test]
fn snapshot_font_lists_use_parsed_values_while_raw_toml_only_proves_presence() {
    let service = VersionedConfigService::new(
        "font_variation = [\"wght=450\", \"opsz=14\"]\n\
         fallback_fonts = [\"Alpha Mono\", \"Beta Sans\"]\n"
            .to_string(),
    )
    .unwrap();
    let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    assert_eq!(
        state.raw_value(prefs::EDIT_FONT_VARIATION).as_deref(),
        Some("[\"wght=450\", \"opsz=14\"]"),
        "the production OCC projection is deliberately canonical TOML",
    );
    assert_eq!(
        state.raw_value(prefs::EDIT_FALLBACK_FONTS).as_deref(),
        Some("[\"Alpha Mono\", \"Beta Sans\"]")
    );

    let candidate = preview_font_candidate(&state);
    assert_eq!(candidate.fallback, ["Alpha Mono", "Beta Sans"]);
    assert_eq!(
        candidate
            .variations
            .iter()
            .find(|variation| variation.tag == aterm_render::variation::WGHT_TAG)
            .map(|variation| variation.value()),
        Some(450.0),
    );
    assert!(
        candidate
            .variations
            .iter()
            .any(|variation| variation.tag == u32::from_be_bytes(*b"opsz")
                && variation.value() == 14.0),
        "the second array entry is parsed without TOML punctuation",
    );
    assert_eq!(candidate.variations.len(), 2);
}

#[test]
fn blank_drafts_preview_reset_defaults_instead_of_stale_color_number_and_padding() {
    let mut color = SettingsViewState::new(&Config {
        foreground: Some("#112233".to_string()),
        ..Config::default()
    });
    color.route = SettingsRoute::Appearance;
    color.editing_field = Some(prefs::EDIT_FOREGROUND.to_string());
    color.field_inputs.insert(
        prefs::EDIT_FOREGROUND.to_string(),
        crate::native_text_input::TextInputState::new(String::new()),
    );
    assert_eq!(field_text(&color, prefs::EDIT_FOREGROUND, ""), "");
    assert_eq!(field_color(&color, prefs::EDIT_FOREGROUND), None);
    let mut reset = SettingsViewState::new(&Config::default());
    reset.route = SettingsRoute::Appearance;
    let reset_fg = renderer_preview_spec(
        &reset,
        0,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("default appearance preview")
    .terminal_theme
    .expect("terminal palette")
    .fg;
    let appearance = renderer_preview_spec(
        &color,
        0,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("appearance preview");
    assert_eq!(
        appearance.terminal_theme.expect("terminal palette").fg,
        reset_fg
    );
    assert_ne!(reset_fg, 0x0011_2233, "negative control: override differs");
    color.editing_field = Some(prefs::EDIT_BACKGROUND.to_string());
    color.field_inputs.insert(
        prefs::EDIT_BACKGROUND.to_string(),
        crate::native_text_input::TextInputState::new(String::new()),
    );
    assert_eq!(field_text(&color, prefs::EDIT_FOREGROUND, ""), "");
    let after_focus_move = renderer_preview_spec(
        &color,
        0,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("appearance preview after sibling focus");
    assert_eq!(
        after_focus_move
            .terminal_theme
            .expect("terminal palette")
            .fg,
        reset_fg,
        "the retained blank keeps previewing removal after focus moves",
    );

    let mut new_draft = SettingsViewState::new(&Config::default());
    new_draft.route = SettingsRoute::Appearance;
    new_draft.field_inputs.insert(
        prefs::EDIT_FOREGROUND.to_string(),
        crate::native_text_input::TextInputState::new("#345678".to_string()),
    );
    new_draft.editing_field = Some(prefs::EDIT_BACKGROUND.to_string());
    let retained = renderer_preview_spec(
        &new_draft,
        0,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("appearance preview with retained new draft");
    assert_eq!(
        retained.terminal_theme.expect("terminal palette").fg,
        0x0034_5678,
        "a nonexplicit retained draft remains projected after focus moves",
    );

    let mut number = SettingsViewState::new(&Config {
        line_height: Some(1.8),
        ..Config::default()
    });
    number.route = SettingsRoute::TextFonts;
    number.editing_field = Some(prefs::EDIT_LINE_HEIGHT.to_string());
    number.field_inputs.insert(
        prefs::EDIT_LINE_HEIGHT.to_string(),
        crate::native_text_input::TextInputState::new(String::new()),
    );
    let typography = renderer_preview_spec(
        &number,
        0,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("typography preview");
    // A blank draft previews the platform's default line height (1.1 on
    // Windows, 1.0 elsewhere), never the stale 1.8.
    assert_eq!(
        typography.line_height,
        crate::app_config::DEFAULT_LINE_HEIGHT
    );

    let mut padding = SettingsViewState::new(&Config {
        window_padding: Some(4.0),
        window_padding_top: Some(8.0),
        ..Config::default()
    });
    assert_eq!(constrained_window_top_padding(&padding), Some((8.0, 4.0)));
    padding.field_inputs.insert(
        prefs::EDIT_WINDOW_PADDING.to_string(),
        crate::native_text_input::TextInputState::new(String::new()),
    );
    assert_eq!(
        constrained_window_top_padding(&padding),
        None,
        "a retained blank resets base padding to 12 instead of preserving the stale 4",
    );
}

#[test]
fn about_copy_and_update_install_actions_emit_exact_typed_effects_and_complete() {
    let staged = update_status(true);
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&staged), false));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let copied = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("about/copy-build-info"),
                value: None,
            }),
        )
        .unwrap();
    let copy_operation = copied
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Clipboard { request, reply } => {
                assert_eq!(
                    request,
                    &ClipboardRequest::CopyText {
                        text: crate::about::provenance_text(),
                        sensitive: false,
                    }
                );
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("copy emits one typed clipboard request");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ClipboardFinished {
                operation: copy_operation,
                outcome: ClipboardOutcome::Copied,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert!(state.feedback.is_some(), "the copy completion is said");

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    // One button: with a build staged it installs it.
    let relaunch = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("updates/install-now"),
                value: None,
            }),
        )
        .unwrap();
    let relaunch_operation = relaunch
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Update { request, reply } => {
                assert_eq!(*request, UpdateRequest::InstallAndRelaunch);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("relaunch emits typed updater request");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::UpdateFinished {
                operation: relaunch_operation,
                outcome: UpdateOutcome::Blocked {
                    reasons: vec!["two sessions are still running".to_string()],
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert!(
        state
            .feedback
            .as_deref()
            .is_some_and(|line| line.contains("two sessions are still running")),
        "the updater's blocking reason is said: {:?}",
        state.feedback
    );
    // An install the updater took: the press's line goes with the `Accepted`, its only
    // completion; kept, it would say "Installing…" above a failed install's headline.
    let again = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("updates/install-now"),
                value: None,
            }),
        )
        .unwrap();
    let again_operation = again
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Update { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("the second press emits a typed updater request");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert!(state.feedback.is_some(), "the press says it is installing");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::UpdateFinished {
                operation: again_operation,
                outcome: UpdateOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(state.feedback.as_deref(), None);

    // …and with nothing staged the same button checks.
    let current = update_status(false);
    let (mut idle_runtime, idle_instance, idle_view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&current), false));
    idle_runtime
        .dispatch(
            idle_instance,
            idle_view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let check = idle_runtime
        .dispatch(
            idle_instance,
            idle_view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("updates/install-now"),
                value: None,
            }),
        )
        .unwrap();
    let check_operation = check
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Update { request, reply } => {
                assert_eq!(*request, UpdateRequest::Check);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("the one button checks when nothing is staged");
    idle_runtime
        .dispatch(
            idle_instance,
            idle_view,
            AppEvent::UpdateFinished {
                operation: check_operation,
                outcome: UpdateOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = idle_runtime.view_state(idle_view) else {
        panic!("Settings view")
    };
    // The check's headline says it is running and how it ended; the footer is silent.
    assert_eq!(state.feedback.as_deref(), None);

    // Retry IS a check (`execute_native_update` maps it to one): its press's
    // "Retrying update…" goes with the `Accepted` too.
    let retry = idle_runtime
        .dispatch(
            idle_instance,
            idle_view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("updates/retry"),
                value: None,
            }),
        )
        .unwrap();
    let retry_operation = retry
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Update { request, reply } => {
                assert_eq!(*request, UpdateRequest::Retry);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("retry emits a typed updater request");
    idle_runtime
        .dispatch(
            idle_instance,
            idle_view,
            AppEvent::UpdateFinished {
                operation: retry_operation,
                outcome: UpdateOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = idle_runtime.view_state(idle_view) else {
        panic!("Settings view")
    };
    assert_eq!(state.feedback.as_deref(), None);
}

/// UNDO IS TAKEN WHILE A CHANGE SAVES: while the page's write is on its way,
/// Undo (the button and Cmd-Z) names that write, the newest change, and a
/// press on it follows it in the lane ([`UndoTarget::Landing`]) and shows
/// what it puts back at once; the last change's token is never spent on
/// it. Its button then reads Redo, so a second press is taken too. (The
/// guard this replaced hid Undo and refused Cmd-Z while anything saved:
/// "Finish applying the current change before Undo.")
#[test]
fn a_write_on_its_way_offers_its_own_undo() {
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view")
    };
    state.route = SettingsRoute::Modified;
    state.last_undo = Some(UndoOffer::showing(77, "Cursor blink turned off"));
    state
        .raw_values
        .insert(prefs::EDIT_CURSOR_BLINK.to_string(), "false".to_string());
    state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
        .unwrap()
        .seed = Some("false".to_string());
    let set = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK)),
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    let write = set
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("the press writes");

    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    // The press shows at once: Cursor blink is back at its default, and no
    // control on the page waits on the write.
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/reset/{}",
                prefs::EDIT_CURSOR_BLINK
            )))
            .is_none(),
        "a row at its default has no Reset"
    );
    assert!(
        compiled
            .semantics
            .iter()
            .all(|node| node.state.is_none_or(|state| !state.busy)),
        "nothing reads as busy"
    );
    let undo_button = |runtime: &NativeRuntime| {
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled
            .semantic(&UiKey::new("settings/undo"))
            .map(|node| node.label.clone())
    };
    assert_eq!(
        undo_button(&runtime).as_deref(),
        Some("Undo"),
        "Undo stands beside the press's status while it saves"
    );
    assert!(
        runtime
            .commands(instance, view)
            .unwrap()
            .into_iter()
            .find(|command| command.id.as_str() == "settings/undo")
            .unwrap()
            .enabled,
        "and Cmd-Z takes it"
    );

    let undo = runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Undo))
        .unwrap();
    let targets: Vec<UndoTarget> = undo
        .effects
        .iter()
        .filter_map(|effect| match effect {
            AppEffect::ConfigUndo { target, .. } => Some(*target),
            _ => None,
        })
        .collect();
    assert_eq!(
        targets,
        vec![UndoTarget::Landing(write)],
        "the Undo follows the write it takes back, never the last change's token"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(state.feedback.as_deref(), Some("Undoing…"));
    assert_eq!(
        state.raw_value(prefs::EDIT_CURSOR_BLINK).as_deref(),
        Some("false"),
        "what the Undo puts back shows at once"
    );
    assert_eq!(
        undo_button(&runtime).as_deref(),
        Some("Redo"),
        "a second press on it is taken: it redoes the change"
    );
}

#[test]
fn open_choice_picker_reflows_across_live_dynamic_type_changes() {
    at_each_text_scale(
        &[1.0],
        "live Dynamic Type picker audit",
        open_choice_picker_reflows_across_live_dynamic_type_changes_at_scale,
    );
}

/// The body of [`open_choice_picker_reflows_across_live_dynamic_type_changes`].
fn open_choice_picker_reflows_across_live_dynamic_type_changes_at_scale(_scale: f32) {
    let install_scale = |text_scale| {
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale,
                ..crate::native_appearance::current_preferences()
            },
        );
    };
    install_scale(1.0);
    let cx = view_cx_at(286.5, 558.0);
    let (mut runtime, instance, view) = setup();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: None,
            }),
        )
        .unwrap();

    let ordinary = compile_settings_view(&runtime, instance, view, &cx);
    assert_zero_top_paint(&ordinary, "open picker at 1×");
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    let picker = state.choice_picker.as_ref().unwrap();
    let ordinary_window = picker.visible_cells().len();
    assert!(picker.is_visible(picker.selected));

    install_scale(2.0);
    let maximum = compile_settings_view(&runtime, instance, view, &cx);
    assert_zero_top_paint(&maximum, "same open picker at 2×");
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    let picker = state.choice_picker.as_ref().unwrap();
    assert!(
        picker.visible_cells().len() < ordinary_window,
        "larger text seats fewer rows"
    );
    assert!(picker.is_visible(picker.selected));

    install_scale(1.0);
    let expanded = compile_settings_view(&runtime, instance, view, &cx);
    assert_zero_top_paint(&expanded, "same open picker expanded back to 1×");
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    let picker = state.choice_picker.as_ref().unwrap();
    assert_eq!(picker.visible_cells().len(), ordinary_window);
    assert!(picker.is_visible(picker.selected));
}

#[test]
fn compact_top_status_cross_product_keeps_controls_and_recovery_actions_reachable() {
    at_each_text_scale(
        &[1.0, 1.5, 2.0],
        "compact status-dock audit",
        compact_top_status_cross_product_keeps_controls_and_recovery_actions_reachable_at_scale,
    );
}

/// One rung of
/// [`compact_top_status_cross_product_keeps_controls_and_recovery_actions_reachable`].
fn compact_top_status_cross_product_keeps_controls_and_recovery_actions_reachable_at_scale(
    scale: f32,
) {
    const WARNING: &str = "aterm.toml reload rejected: repair the invalid authored value before automatic reload can resume.";
    const VARIANTS: [&str; 4] = ["watcher", "ordinary", "draft", "reset"];
    // The page's own key list, so the test follows the real composition.
    const TOP_CONTROLS: [&str; 8] = TOP_SETTING_KEYS;
    const TOP_PREVIEWS: [&str; 3] = [
        "settings/top/theme/preview",
        "settings/top/text/preview",
        "settings/top/cursor-trail/preview",
    ];
    // The type specimen's least height (one whole line at the authored size)
    // under its card's title is more than a 320pt landscape list holds beside
    // the Serious Mode disclosure and a status bar; there it yields
    // (`constrain_top_split_card`), and the card keeps its controls.
    let preview_reachable_at =
        |preview: &str, height: f32| preview != "settings/top/text/preview" || height > 320.0;
    let configure = |state: &mut SettingsViewState, variant: &str| {
        state.config_watch_status = Some(WARNING.to_string());
        state.feedback = None;
        state.last_undo = None;
        state.reset_all_confirmation = false;
        state.draft_discard_confirmation = false;
        state.field_inputs.clear();
        match variant {
            "watcher" => {}
            "ordinary" => {
                state.feedback = Some("Saved. Undo is available.".to_string());
                state.last_undo = Some(UndoOffer::showing(7, "Saved. Undo is available."));
            }
            "draft" => {
                // A draft of a row Top Settings does not draw: the bar
                // recovers it from any page.
                state.field_inputs.insert(
                    prefs::EDIT_SYMBOL_FONT.to_string(),
                    crate::native_text_input::TextInputState::new(
                        "A retained unsaved symbol-font draft".to_string(),
                    ),
                );
            }
            "reset" => {
                state.feedback = Some("Reset all settings?".to_string());
                state.reset_all_confirmation = true;
            }
            _ => unreachable!(),
        }
    };
    // Where the Reset All question would be cut in the toolbar's dock it
    // takes the page's place ([`reset_all_question_takes_page`]): the page
    // waits on it, and its own controls come back with Cancel.
    let assert_statuses =
        |compiled: &crate::native_ui::CompiledUi, variant: &str, context: &str, page: bool| {
            assert_eq!(
                compiled
                    .semantics
                    .iter()
                    .filter(|node| {
                        node.key.as_str() == "settings/config-watch-status/detail"
                            && node.role == SemanticRole::Status
                    })
                    .count(),
                1,
                "{context}: one watcher live region"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/config-watch-status/detail"))
                    .is_some_and(|node| node.label.ends_with(WARNING)),
                "{context}: complete watcher detail"
            );
            let feedback_key = match variant {
                "watcher" => None,
                "draft" => Some("settings/draft-recovery/status"),
                "ordinary" | "reset" => Some("settings/status"),
                _ => unreachable!(),
            };
            if let Some(key) = feedback_key {
                assert_eq!(
                compiled
                    .semantics
                    .iter()
                    .filter(|node| node.key.as_str() == key && node.role == SemanticRole::Status)
                    .count(),
                1,
                "{context}: one feedback live region"
            );
            }
            assert_material_hit(compiled, "settings/compact-navigation", context);
            let action_keys: &[&str] = match variant {
                "watcher" => &[],
                "ordinary" => &["settings/undo"],
                "draft" => &["settings/drafts/review", "settings/drafts/discard-all"],
                "reset" => &["settings/reset-all-cancel", "settings/reset-all-confirm"],
                _ => unreachable!(),
            };
            for key in action_keys {
                assert_material_hit(compiled, key, context);
            }
            assert_all_hits_material_and_contained(compiled, context);
            if !page {
                assert!(
                    compiled
                        .semantic(&UiKey::new("settings/page/reset-all"))
                        .is_some(),
                    "{context}: the Reset All question takes the page"
                );
                return;
            }
            let serious = compiled
                .semantic(&UiKey::new("settings/top/serious-mode"))
                .unwrap_or_else(|| panic!("{context}: Serious Mode disclosure missing"));
            assert!(
                serious.rect.x >= compiled.bounds.x - 0.01
                    && serious.rect.y >= compiled.bounds.y - 0.01
                    && serious.rect.right() <= compiled.bounds.right() + 0.01
                    && serious.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                "{context}: Serious Mode disclosure escapes: {:?}",
                serious.rect
            );
        };

    for (viewport_width, viewport_height) in [(568.0, 320.0), (286.5, 558.0)] {
        let mut cx = view_cx_at(viewport_width, viewport_height);
        cx.motion.serious = true;
        for variant in VARIANTS {
            let (mut runtime, instance, view) = setup();
            replace_settings_source(&mut runtime, view, "serious_mode = true\n".to_string());
            let question_page = {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                configure(state, variant);
                reset_all_question_takes_page(state, cx.viewport)
            };
            if question_page {
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context =
                    format!("{variant} question at {viewport_width}×{viewport_height} {scale}×");
                assert_zero_top_paint(&compiled, &context);
                assert_statuses(&compiled, variant, &context, false);
                continue;
            }
            let mut seen = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
                let context = format!(
                    "{variant} Top screen {top} at {viewport_width}×{viewport_height} {scale}×"
                );
                assert_zero_top_paint(compiled, &context);
                assert_statuses(compiled, variant, &context, true);
                for key in TOP_CONTROLS {
                    let control = format!("settings/control/{key}");
                    // A control a list's edge cuts is live over what shows; it
                    // is checked whole on the screen that shows it whole.
                    if compiled.semantic(&UiKey::new(control.as_str())).is_none()
                        || list_cuts(compiled, &UiKey::new(control.as_str()))
                    {
                        continue;
                    }
                    assert_material_hit(compiled, &control, &context);
                    seen.insert(control);
                    // The cursor style's row is a link, not a setting row.
                    if scale >= 2.0 && key != prefs::EDIT_CURSOR_TRAIL_STYLE {
                        let label_key = UiKey::new(format!("settings/label/{key}"));
                        assert!(
                            compiled.semantic(&label_key).is_none(),
                            "{context}: Top visual label duplicated semantics"
                        );
                        assert!(
                            compiled.paint.iter().any(|node| node.key == label_key),
                            "{context}: Top visual label must still paint"
                        );
                        assert!(compiled.semantics.iter().any(|node| {
                            node.key.as_str().starts_with("settings/row/")
                                && node.key.as_str().ends_with(&format!("/{key}"))
                                && !node.label.is_empty()
                        }));
                    }
                }
                for preview_key in TOP_PREVIEWS {
                    let Some(preview) = compiled.semantic(&UiKey::new(preview_key)) else {
                        continue;
                    };
                    assert!(
                        preview.rect.width > 0.0
                            && preview.rect.height > 0.0
                            && preview.rect.right() <= compiled.bounds.right() + 0.01
                            && preview.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                        "{context}: preview escapes: {:?}",
                        preview.rect
                    );
                    seen.insert(preview_key.to_string());
                }
            });
            for key in TOP_CONTROLS {
                assert!(
                    seen.contains(&format!("settings/control/{key}")),
                    "{variant} at {viewport_width}×{viewport_height} {scale}×: {key} unreachable"
                );
            }
            for preview_key in TOP_PREVIEWS {
                assert!(
                    seen.contains(preview_key)
                        || !preview_reachable_at(preview_key, viewport_height),
                    "{variant} at {viewport_width}×{viewport_height} {scale}×: {preview_key} unreachable"
                );
            }

            // (Window appearance is its row's segments: no picker to walk.)
            {
                let key = prefs::EDIT_THEME;
                let (mut runtime, instance, view) = setup();
                replace_settings_source(&mut runtime, view, "serious_mode = true\n".to_string());
                runtime
                    .dispatch(
                        instance,
                        view,
                        AppEvent::Action(ActionInvocation {
                            id: ActionId::new(format!("settings/set/{key}")),
                            value: None,
                        }),
                    )
                    .unwrap();
                {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    configure(state, variant);
                }
                walk_open_choice_picker(
                    &mut runtime,
                    instance,
                    view,
                    &cx,
                    key,
                    |compiled, index| {
                        let context = format!(
                            "{variant} {key} picker option {index} at {viewport_width}×{viewport_height} {scale}×"
                        );
                        assert_zero_top_paint(compiled, &context);
                        assert_statuses(compiled, variant, &context, true);
                        assert_picker_descendants_contained(compiled, key, &context);
                        assert_material_hit(compiled, "settings/choice-close", &context);
                        assert_material_hit(
                            compiled,
                            &format!("settings/choice/{key}/{index}"),
                            &context,
                        );
                        let preview = compiled
                            .semantic(&UiKey::new("settings/top/choice-preview"))
                            .unwrap_or_else(|| panic!("{context}: missing picker preview"));
                        assert!(
                            preview.rect.width > 0.0
                                && preview.rect.height > 0.0
                                && preview.rect.right() <= compiled.bounds.right() + 0.01
                                && preview.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                            "{context}: picker preview escapes: {:?}",
                            preview.rect
                        );
                    },
                );
            }
        }
    }
}

#[test]
fn top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow() {
    at_each_text_scale(
        &[1.0, 1.5, 2.0],
        "Top Settings paint audit",
        top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow_at_scale,
    );
}

/// One rung of [`top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow`].
fn top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow_at_scale(scale: f32) {
    let viewports = match scale {
        value if value < 1.25 => vec![(1_200.0, 810.0), (390.0, 558.0), (568.0, 320.0)],
        value if value < 1.75 => vec![
            (1_140.0, 810.0),
            (390.0, 558.0),
            (286.5, 558.0),
            (568.0, 320.0),
        ],
        _ => vec![
            (1_520.0, 900.0),
            (320.0, 568.0),
            (286.5, 558.0),
            (568.0, 320.0),
        ],
    };
    let quote = |value: &str| aterm_toml::Value::String(value.to_string()).to_string();
    let cases = [
        (
            prefs::EDIT_THEME,
            aterm_types::scheme::builtin_names()
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>(),
        ),
        (
            prefs::EDIT_WINDOW_THEME,
            prefs::WINDOW_THEMES
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>(),
        ),
        (
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            prefs::CURSOR_TRAIL_STYLES
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>(),
        ),
    ];

    for (viewport_width, viewport_height) in viewports.iter().copied() {
        let cx = view_cx_at(viewport_width, viewport_height);

        // Every screen of the Top Settings list, not only the three
        // preview-bearing cards.
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
        }
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            assert_zero_top_paint(
                compiled,
                &format!("default Top screen {top} at {viewport_width}×{viewport_height} {scale}×"),
            );
        });

        // Commit every built-in value through the snapshot projection a real save
        // uses: the control keeps the exact value in semantics while its visual label
        // stays within the authored measure.
        for (key, values) in &cases {
            for value in values {
                let (mut runtime, instance, view) = setup();
                // The trail case authors its master, as the picker's own patch does:
                // Top Settings presents style and enablement as one choice, and the
                // master's absent-key default is platform-split. The `off` style still
                // projects "off", so the value list keeps its full span.
                let source = if *key == prefs::EDIT_CURSOR_TRAIL_STYLE {
                    format!("cursor_trail = true\n{key} = {}\n", quote(value))
                } else {
                    format!("{key} = {}\n", quote(value))
                };
                replace_settings_source(&mut runtime, view, source);
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_reveal = Some(UiKey::new(format!("settings/control/{key}")));
                state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!(
                    "committed {key}={value:?} at {viewport_width}×{viewport_height} {scale}×"
                );
                assert_zero_top_paint(&compiled, &context);
                let control = compiled
                    .semantic(&UiKey::new(format!("settings/control/{key}")))
                    .unwrap_or_else(|| panic!("{context}: missing committed control"));
                // The value in the words the control shows, never the config
                // token; whole, never cut. Window appearance is its row's
                // segments, which show their own short words.
                let shown = if *key == prefs::EDIT_WINDOW_THEME {
                    segment_label(key, value)
                } else {
                    setting_choice_label(key, value)
                };
                assert_eq!(
                    control.value,
                    SemanticValue::Text(shown.clone()),
                    "{context}: complete semantic value"
                );
                // The cursor style's control paints "More styles…" and is
                // named by it; the style is its value and its row's name.
                if *key != prefs::EDIT_CURSOR_TRAIL_STYLE {
                    assert!(
                        control.label.contains(&shown),
                        "{context}: the semantic label names the value as shown {:?}",
                        control.label
                    );
                }
            }
        }

        // One explicit committed value per picker gives the matrix its
        // reset candidate as well as every built-in. Walk every real page
        // and prove all semantic labels survive the bounded visuals. (The
        // cursor style has no picker: its control opens Cursor Styles; and
        // Window appearance is its row's segments.)
        for (key, values) in cases.iter().filter(|(key, _)| {
            *key != prefs::EDIT_CURSOR_TRAIL_STYLE && *key != prefs::EDIT_WINDOW_THEME
        }) {
            let current = values.first().expect("Top picker has choices");
            let (mut runtime, instance, view) = setup();
            replace_settings_source(&mut runtime, view, format!("{key} = {}\n", quote(current)));
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!("settings/set/{key}")),
                        value: None,
                    }),
                )
                .unwrap();
            let expected_labels = {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                state
                    .choice_picker
                    .as_ref()
                    .unwrap()
                    .options
                    .iter()
                    .map(|option| option.label.clone())
                    .collect::<BTreeSet<_>>()
            };
            let mut seen_labels = BTreeSet::new();
            walk_open_choice_picker(&mut runtime, instance, view, &cx, key, |compiled, index| {
                let context = format!(
                    "{key} picker option {index} at {viewport_width}×{viewport_height} {scale}×"
                );
                assert_zero_top_paint(compiled, &context);
                assert_picker_descendants_contained(compiled, key, &context);
                seen_labels.extend(
                    compiled
                        .semantics
                        .iter()
                        .filter(|node| {
                            node.key
                                .as_str()
                                .starts_with(&format!("settings/choice/{key}/"))
                        })
                        .map(|node| node.label.clone()),
                );
            });
            assert_eq!(
                seen_labels, expected_labels,
                "complete {key} picker semantics"
            );
        }
    }

    // Serious Mode is a projection state, not a route: walk all Top pages and visual
    // pickers with its disclosure, including the tight feedback-owned landscape budget.
    for (viewport_width, viewport_height) in viewports
        .iter()
        .copied()
        .filter(|(width, _)| SettingsWidth::for_viewport(*width) == SettingsWidth::Compact)
    {
        let mut cx = view_cx_at(viewport_width, viewport_height);
        cx.motion.serious = true;
        let (mut runtime, instance, view) = setup();
        replace_settings_source(&mut runtime, view, "serious_mode = true\n".to_string());
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
        }
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context =
                format!("Serious Top screen {top} at {viewport_width}×{viewport_height} {scale}×");
            assert_zero_top_paint(compiled, &context);
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/top/serious-mode"))
                    .is_some(),
                "{context}: missing Serious Mode disclosure"
            );
        });
        // (Window appearance is its row's segments: no picker to walk.)
        {
            let key = prefs::EDIT_THEME;
            let (mut runtime, instance, view) = setup();
            replace_settings_source(&mut runtime, view, "serious_mode = true\n".to_string());
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!("settings/set/{key}")),
                        value: None,
                    }),
                )
                .unwrap();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
            }
            walk_open_choice_picker(&mut runtime, instance, view, &cx, key, |compiled, index| {
                let context = format!(
                    "Serious {key} picker option {index} at {viewport_width}×{viewport_height} {scale}×"
                );
                assert_zero_top_paint(compiled, &context);
                assert_picker_descendants_contained(compiled, key, &context);
            });
        }
    }

    // The longest transient Top transaction status is also part of the
    // supported responsive state space.
    if scale >= 2.0 {
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.feedback = Some(top_effect_apply_feedback(true));
        let cx = view_cx_at(286.5, 558.0);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(
            &compiled,
            "Serious Mode transaction feedback at 286.5×558 2×",
        );

        // Recovery/status surfaces coexist with any route: exercise their longest
        // narrow-host states independently.
        for confirmation in [false, true] {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.field_inputs.insert(
                prefs::EDIT_SYMBOL_FONT.to_string(),
                crate::native_text_input::TextInputState::new(
                    "A retained unsaved symbol-font draft".to_string(),
                ),
            );
            state.draft_discard_confirmation = confirmation;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let context = if confirmation {
                "draft discard confirmation at 286.5×558 2×"
            } else {
                "draft recovery at 286.5×558 2×"
            };
            assert_zero_top_paint(&compiled, context);
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/draft-recovery/status"))
                    .is_some()
            );
            // Asked to confirm, the bar offers Cancel beside the destructive
            // Discard; else it offers Review beside Discard.
            let keys = if confirmation {
                [
                    "settings/drafts/discard-cancel",
                    "settings/drafts/discard-all",
                ]
            } else {
                ["settings/drafts/review", "settings/drafts/discard-all"]
            };
            for key in keys {
                assert!(
                    compiled.semantic(&UiKey::new(key)).is_some(),
                    "{context}: {key}"
                );
            }
        }

        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.feedback = Some("Reset all settings?".to_string());
        state.reset_all_confirmation = true;
        let reset = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&reset, "Reset All disclosure at 286.5×558 2×");

        let (mut runtime, instance, view) = setup();
        let warning = "aterm.toml reload rejected at /Users//example/配置/very-long-profile-name/aterm.toml: an authored value is invalid and must be repaired.";
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.config_watch_status = Some(warning.to_string());
        let watched = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&watched, "config watcher warning at 286.5×558 2×");
        assert!(
            watched
                .semantic(&UiKey::new("settings/config-watch-status/detail"))
                .is_some_and(|node| node.label.ends_with(warning)),
            "the complete warning is the detail's label"
        );
        assert_eq!(
            watched
                .semantics
                .iter()
                .filter(|node| {
                    node.key
                        .as_str()
                        .starts_with("settings/config-watch-status")
                        && node.role == SemanticRole::Status
                })
                .count(),
            1,
            "one reload warning must produce one live status"
        );
    }

    // Dynamic names are user data: byte-exact in the semantic value, clean in the
    // UTF-8 visual projection.
    if scale >= 2.0 {
        let name = "Aurora 👩‍💻 Observatory — a deliberately very long personal color theme";
        // A file whose own `name =` is its id: the picker shows it as written.
        let mut scheme = aterm_types::scheme::builtin("Dracula").unwrap();
        scheme.name = name.to_string();
        let themes = crate::app_config::ThemeCatalog::from_schemes([(name.to_string(), scheme)]);
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        **state = SettingsViewState::new(&Config {
            theme: Some(name.to_string()),
            ..Config::default()
        });
        let mut assets = (*state.assets).clone();
        assets.themes = themes;
        state.assets = Arc::new(assets);
        state.page_scroll = 0;
        let cx = view_cx_at(286.5, 558.0);
        let committed = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&committed, "long Unicode committed theme");
        let control = committed
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_THEME
            )))
            .unwrap();
        assert_eq!(control.value, SemanticValue::Text(name.to_string()));
        assert!(control.label.contains(name));
        // Its words wrap to the button, whole, never cut ([`choice_words`]).
        assert!(committed.paint_audit_lines().iter().any(|line| {
            line.contains(&format!("key=\"settings/control/{}\"", prefs::EDIT_THEME))
                && !line.contains('…')
                && line.contains("overflow=false")
        }));
        let painted = committed
            .paint
            .iter()
            .find_map(|node| match &node.content {
                UiContent::Button(button)
                    if node.key.as_str() == format!("settings/control/{}", prefs::EDIT_THEME) =>
                {
                    button.spec.visual_label.clone()
                }
                _ => None,
            })
            .unwrap_or_default();
        assert_eq!(painted_words(&painted), name, "{painted:?}");

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                    value: None,
                }),
            )
            .unwrap();
        let index = match runtime.view_state_mut(view) {
            Some(AppViewState::Settings(state)) => {
                let picker = state.choice_picker.as_mut().unwrap();
                let index = picker
                    .options
                    .iter()
                    .position(|option| option.value.as_deref() == Some(name))
                    .unwrap();
                picker.scroll_to(picker.position_of(index));
                state.common.last_focus = Some(UiKey::new(format!(
                    "settings/choice/{}/{index}",
                    prefs::EDIT_THEME
                )));
                index
            }
            _ => unreachable!(),
        };
        let picker = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&picker, "long Unicode theme picker");
        let option = picker
            .semantic(&UiKey::new(format!(
                "settings/choice/{}/{index}",
                prefs::EDIT_THEME
            )))
            .unwrap();
        assert_eq!(option.label, name);
        assert_picker_descendants_contained(
            &picker,
            prefs::EDIT_THEME,
            "long Unicode theme picker",
        );
    }
}

/// TOP SETTINGS HAS FOUR CARDS, the Text card — the font family and size
/// over the type specimen — among them, at every size: on the wide grid (its
/// band under the two columns), on a window the grid does not fit, and in
/// the compact list, every one painted whole on some screen with nothing cut
/// or overflowing.
#[test]
fn top_settings_has_a_text_card_at_every_size() {
    const TEXT_CARD: [&str; 4] = [
        "settings/top/text",
        "settings/top/text/preview",
        "settings/control/font_family",
        "settings/control/font_px",
    ];
    for (width, height) in [
        (584.0, 348.0),
        (738.0, 420.0),
        (1_074.0, 686.0),
        (1_200.0, 820.0),
        (1_564.0, 854.0),
    ] {
        let cx = view_cx_at(width, height);
        let (mut runtime, instance, view) = setup();
        let mut seen = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            assert_zero_top_paint(compiled, &format!("Top screen {top} at {width}x{height}"));
            for key in TEXT_CARD {
                if compiled
                    .paint
                    .iter()
                    .any(|node| !node.peek && node.rect == node.clip && node.key.as_str() == key)
                {
                    seen.insert(key);
                }
            }
            if let Some(preview) = compiled.semantic(&UiKey::new("settings/top/text/preview")) {
                assert_eq!(preview.label, "Typography preview");
            }
        });
        assert_eq!(seen.len(), TEXT_CARD.len(), "{width}x{height}: {seen:?}");
    }
}

/// The Text card's rows are Text & Fonts' own: that page still leads with
/// them, and Search still places them there (a negative control for the
/// Top key list, which hides a Top key from its page unless it leads it).
#[test]
fn text_fonts_still_lists_font_family_and_size() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::TextFonts),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 900.0));
    for key in [prefs::EDIT_FONT_FAMILY, prefs::EDIT_FONT_PX] {
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .is_some(),
            "Text & Fonts draws {key}"
        );
        assert_eq!(settings_location(key), SettingsRoute::TextFonts.label());
    }
    assert_eq!(
        settings_location(prefs::EDIT_THEME),
        SettingsRoute::Appearance.label()
    );
    assert_eq!(
        settings_location(prefs::EDIT_TRAIL_SOUNDS),
        SettingsRoute::Sound.label()
    );
    assert_eq!(
        settings_location(SPARKLE_WORDS_KEY),
        SettingsRoute::Home.label()
    );
}

#[test]
fn top_settings_is_default_native_page_with_requested_controls_and_previews() {
    let (runtime, instance, view) = setup();
    // Where nothing can sound (`trail_audio::output_available`), Music effects
    // carries its "No audio" status line, and the grid that line
    // lengthens takes a taller host to hold its four cards (at 1200x820 in
    // Noto Sans its right column is 494pt in 472).
    let roomy = if crate::trail_audio::output_available() {
        820.0
    } else {
        860.0
    };
    let cx = view_cx_at(1_200.0, roomy);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    compiled.validate_parity().unwrap();
    let overflow = compiled
        .paint_audit_lines()
        .into_iter()
        .filter(|line| line.contains("overflow=true"))
        .collect::<Vec<_>>();
    assert!(
        overflow.is_empty(),
        "wide Top Settings text must fit its authored bounds:\n{}",
        overflow.join("\n")
    );

    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(state.route, SettingsRoute::Home);
    for key in [
        prefs::EDIT_THEME,
        prefs::EDIT_WINDOW_THEME,
        prefs::EDIT_FONT_FAMILY,
        prefs::EDIT_FONT_PX,
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        prefs::EDIT_TRAIL_SOUNDS,
        SPARKLE_WORDS_KEY,
        KEYWORD_KITTIES_KEY,
    ] {
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .is_some(),
            "Top Settings exposes {key}"
        );
    }
    // No theme is one theme, Default: its card is the Color theme control
    // and the Follow system switch.
    assert!(
        compiled.semantic(&UiKey::new(THEME_MODE_ACTION)).is_some(),
        "Top Settings exposes {THEME_MODE_ACTION}"
    );
    for key in [
        "settings/top/theme/preview",
        "settings/top/text/preview",
        "settings/top/cursor-trail/preview",
    ] {
        assert!(compiled.semantic(&UiKey::new(key)).is_some(), "{key}");
    }

    let medium_cx = view_cx_at(900.0, roomy);
    let medium = runtime
        .render(instance, view, &medium_cx)
        .unwrap()
        .compile(medium_cx.viewport)
        .unwrap();
    for key in [
        format!("settings/control/{}", prefs::EDIT_WINDOW_THEME),
        format!("settings/control/{}", prefs::EDIT_CURSOR_TRAIL_STYLE),
        format!("settings/control/{}", prefs::EDIT_TRAIL_SOUNDS),
        format!("settings/control/{SPARKLE_WORDS_KEY}"),
        format!("settings/control/{KEYWORD_KITTIES_KEY}"),
        format!("settings/control/{}", prefs::EDIT_THEME),
        THEME_MODE_ACTION.to_string(),
    ] {
        assert!(
            medium.semantic(&UiKey::new(key.clone())).is_some(),
            "ordinary macOS-sized Top Settings exposes {key}"
        );
    }
    let manual = compiled
        .hits
        .iter()
        .find(|hit| hit.key == UiKey::new("settings/nav/manual"))
        .expect("Manual is a first-class native destination");
    assert_eq!(manual.action.as_str(), "settings/route/manual");
}

#[test]
fn top_keyword_toys_and_cursor_trail_emit_complete_runtime_patches() {
    let (mut runtime, instance, view) = setup();
    let toy = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{SPARKLE_WORDS_KEY}")),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let toy_patch = toy
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, .. } => Some(patch),
            _ => None,
        })
        .expect("toy toggle emits one typed config patch");
    assert_eq!(
        toy_patch
            .edits
            .iter()
            .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
            .collect::<Vec<_>>(),
        [
            (SPARKLE_MASTER_KEY, None),
            (SPARKLE_WORDS_KEY, Some("false")),
            (KEYWORD_KITTIES_KEY, None),
        ]
    );

    let legacy_service =
        VersionedConfigService::new("[sparkle_words]\nenabled = false\n".to_string()).unwrap();
    let legacy = SettingsViewState::from_snapshot(&legacy_service.snapshot()).unwrap();
    // The old shared master is its own written key, not either toy's.
    assert!(legacy.is_explicit(SPARKLE_MASTER_KEY));
    assert!(!legacy.is_explicit(SPARKLE_WORDS_KEY));
    assert!(!legacy.is_explicit(KEYWORD_KITTIES_KEY));
    assert!(!top_projected_toy_value(&legacy, SPARKLE_WORDS_KEY));
    assert!(!top_projected_toy_value(&legacy, KEYWORD_KITTIES_KEY));

    let (mut runtime, instance, view) = setup();
    let trail = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_TRAIL_STYLE)),
                value: Some(SemanticInput::Text("off".to_string())),
            }),
        )
        .unwrap();
    let trail_patch = trail
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, .. } => Some(patch),
            _ => None,
        })
        .expect("trail choice emits one typed config patch");
    assert_eq!(
        trail_patch
            .edits
            .iter()
            .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
            .collect::<Vec<_>>(),
        [(prefs::EDIT_CURSOR_TRAIL_STYLE, Some("off"))],
        "Off is the style alone: the effects switch keeps the momentum glow"
    );
}

#[test]
fn top_effect_controls_truthfully_escape_the_serious_mode_override() {
    fn projection(state: &SettingsViewState) -> (String, bool, bool, bool) {
        (
            top_projected_trail_value(state),
            top_projected_music_value(state),
            top_projected_toy_value(state, SPARKLE_WORDS_KEY),
            top_projected_toy_value(state, KEYWORD_KITTIES_KEY),
        )
    }

    fn dispatch_patch(
        source: &str,
        key: &str,
        value: SemanticInput,
    ) -> (VersionedConfigService, ConfigPatch) {
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        let before = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        assert!(field_bool(&before, prefs::EDIT_SERIOUS_MODE, false));
        assert_eq!(
            projection(&before),
            ("off".to_string(), false, false, false),
            "Serious Mode must suppress the complete product projection"
        );

        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view")
        };
        **state = before;
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{key}")),
                    value: Some(value),
                }),
            )
            .unwrap();
        let patch = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch.clone()),
                _ => None,
            })
            .expect("one atomic Top Settings patch");
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        assert!(
            state
                .feedback
                .as_deref()
                .is_some_and(|line| line.contains("Serious Mode")),
            "{:?}",
            state.feedback
        );
        let unique = patch
            .edits
            .iter()
            .map(|edit| edit.key.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(unique.len(), patch.edits.len(), "patch keys are unique");
        for edit in &patch.edits {
            assert_eq!(
                edit.expected,
                ExpectedConfigValue::Exact(
                    SettingsViewState::from_snapshot(&service.snapshot())
                        .unwrap()
                        .raw_value(&edit.key)
                ),
                "{} keeps an exact OCC precondition",
                edit.key
            );
        }
        (service, patch)
    }

    fn assert_transition(
        source: &str,
        key: &str,
        value: SemanticInput,
        expected_patch: &[(&str, Option<&str>)],
        expected_projection: (&str, bool, bool, bool),
    ) -> SettingsViewState {
        let (mut service, patch) = dispatch_patch(source, key, value);
        assert_eq!(
            patch
                .edits
                .iter()
                .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
                .collect::<Vec<_>>(),
            expected_patch
        );
        let (snapshot, _) = apply_real_config_patch(&mut service, &patch);
        let after = SettingsViewState::from_snapshot(&snapshot).unwrap();
        assert!(!field_bool(&after, prefs::EDIT_SERIOUS_MODE, false));
        assert_eq!(
            projection(&after),
            (
                expected_projection.0.to_string(),
                expected_projection.1,
                expected_projection.2,
                expected_projection.3,
            ),
            "only the selected Top Settings effect may change"
        );
        after
    }

    // THE SIBLING-PIN IS PLATFORM-CONDITIONAL, and that is the law working
    // rather than an exception to it. Escaping Serious Mode writes an explicit
    // off for every sibling that would otherwise spring back to life on the
    // way out. Where the cursor style and the typing glow are un-authored AND
    // their platform defaults are already Off (`app_config::DEFAULT_DECORATIVE_
    // EFFECTS`, i.e. Windows), they spring back to nothing — so there is
    // nothing to pin and the honest patch leaves the keys unwritten. "Only the
    // selected effect may change" is the invariant under test; the edit list is
    // its consequence, and the PROJECTION assertions below are identical on
    // every host.
    //
    // Only an off PIN is conditional. An edit that turns the trail ON is the
    // user's own selection and appears everywhere.
    fn expect(
        edits: &[(&'static str, Option<&'static str>)],
    ) -> Vec<(&'static str, Option<&'static str>)> {
        edits
            .iter()
            .copied()
            .filter(|(key, value)| {
                crate::app_config::DEFAULT_DECORATIVE_EFFECTS
                    || !matches!(
                        (*key, *value),
                        (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("off"))
                            | (prefs::EDIT_CURSOR_MOMENTUM_GLOW, Some("false"))
                    )
            })
            .collect()
    }

    let defaulted = "serious_mode = true\n";
    assert_transition(
        defaulted,
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        SemanticInput::Text("water".to_string()),
        &expect(&[
            (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("water")),
            (prefs::EDIT_CURSOR_MOMENTUM_GLOW, Some("false")),
            (prefs::EDIT_TRAIL_SOUNDS, Some("false")),
            (SPARKLE_WORDS_KEY, Some("false")),
            (KEYWORD_KITTIES_KEY, Some("false")),
            (prefs::EDIT_SERIOUS_MODE, None),
        ]),
        ("water", false, false, false),
    );
    assert_transition(
        defaulted,
        prefs::EDIT_TRAIL_SOUNDS,
        SemanticInput::Bool(true),
        &expect(&[
            (prefs::EDIT_TRAIL_SOUNDS, None),
            (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("off")),
            (prefs::EDIT_CURSOR_MOMENTUM_GLOW, Some("false")),
            (SPARKLE_WORDS_KEY, Some("false")),
            (KEYWORD_KITTIES_KEY, Some("false")),
            (prefs::EDIT_SERIOUS_MODE, None),
        ]),
        ("off", true, false, false),
    );
    assert_transition(
        defaulted,
        SPARKLE_WORDS_KEY,
        SemanticInput::Bool(true),
        &expect(&[
            (SPARKLE_MASTER_KEY, None),
            (SPARKLE_WORDS_KEY, None),
            (KEYWORD_KITTIES_KEY, Some("false")),
            (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("off")),
            (prefs::EDIT_CURSOR_MOMENTUM_GLOW, Some("false")),
            (prefs::EDIT_TRAIL_SOUNDS, Some("false")),
            (prefs::EDIT_SERIOUS_MODE, None),
        ]),
        ("off", false, true, false),
    );
    assert_transition(
        defaulted,
        KEYWORD_KITTIES_KEY,
        SemanticInput::Bool(true),
        &expect(&[
            (SPARKLE_MASTER_KEY, None),
            (SPARKLE_WORDS_KEY, Some("false")),
            (KEYWORD_KITTIES_KEY, None),
            (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("off")),
            (prefs::EDIT_CURSOR_MOMENTUM_GLOW, Some("false")),
            (prefs::EDIT_TRAIL_SOUNDS, Some("false")),
            (prefs::EDIT_SERIOUS_MODE, None),
        ]),
        ("off", false, false, true),
    );

    let explicitly_suppressed = "serious_mode = true\n\
         cursor_trail = false\n\
         cursor_trail_style = \"phaser\"\n\
         trail_sounds = false\n\
         [sparkle_words]\n\
         enabled = false\n\
         [sparkle_words.profanity]\n\
         enabled = true\n\
         [sparkle_words.feline]\n\
         enabled = true\n";
    let after = assert_transition(
        explicitly_suppressed,
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        SemanticInput::Text("water".to_string()),
        // The retired switch's `false` already keeps the glow off (it reads
        // Off), so only the style and the policy are edited; the writer drops
        // the retired key and pins the glow as it drew.
        &[
            (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("water")),
            (prefs::EDIT_SERIOUS_MODE, None),
        ],
        ("water", false, false, false),
    );
    assert_eq!(after.raw_value(prefs::RETIRED_CURSOR_TRAIL), None);
    assert!(!field_bool(
        &after,
        prefs::EDIT_CURSOR_MOMENTUM_GLOW,
        crate::app_config::DEFAULT_DECORATIVE_EFFECTS
    ));
    assert_eq!(
        after.raw_value(SPARKLE_MASTER_KEY).as_deref(),
        Some("false"),
        "an explicit shared-off toy policy needs no rewrite"
    );
    assert_eq!(
        after.raw_value(prefs::EDIT_TRAIL_SOUNDS).as_deref(),
        Some("false"),
        "an explicit sibling override is preserved byte-semantically"
    );
}

/// LEAVING SERIOUS MODE BY ANOTHER EFFECT KEEPS THE SAVED CURSOR STYLE
/// (lead-known-open #29). Turning Music effects, Sparkle words or Keyword
/// kitties on while Serious Mode hides them turns Serious Mode off and keeps
/// every other effect off — the cursor's style written Off — and the style
/// the person had stays in aterm.toml beside it, where Cursor Styles marks
/// it; choosing it there brings it back and the mark goes. Undo puts back
/// the style and Serious Mode. Every lane meets one writer, so `settings set`
/// of the style Off keeps it too; Modified lists it with its Reset; Reset All
/// leaves no mark behind a style that draws. Without the writer's rule the
/// exit overwrote the style with Off and nothing kept it.
#[test]
fn leaving_serious_mode_by_another_effect_keeps_the_saved_cursor_style() {
    const SOURCE: &str = "serious_mode = true\ncursor_trail_style = \"comet\"\n";
    let before_off = prefs::EDIT_CURSOR_TRAIL_STYLE_BEFORE_OFF;
    let patch_of = |state: SettingsViewState, id: String, value: Option<SemanticInput>| {
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(slot)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        **slot = state;
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value,
                }),
            )
            .unwrap();
        emitted_config_patch(&outcome)
    };
    let apply = |service: &mut VersionedConfigService, mut patch: ConfigPatch| {
        patch.base_revision = service.snapshot().revision;
        let request = ConfigPatchRequest {
            base_revision: patch.base_revision,
            edits: patch
                .edits
                .iter()
                .map(|edit| ConfigKeyEdit {
                    key: edit.key.clone(),
                    expected: {
                        let ExpectedConfigValue::Exact(value) = &edit.expected;
                        ExpectedValue::Exact(value.clone())
                    },
                    value: edit.value.clone(),
                })
                .collect(),
        };
        match service.patch(request) {
            ConfigPatchResult::Applied { snapshot, undo } => {
                (SettingsViewState::from_snapshot(&snapshot).unwrap(), undo)
            }
            other => panic!("the real config service refused the patch: {other:?}"),
        }
    };
    let marked = |state: &SettingsViewState| {
        listed_cursor_styles(state)
            .into_iter()
            .filter(|style| {
                style.group != CursorStyleGroup::Off
                    && style.description.starts_with(BEFORE_OFF_MARK)
            })
            .map(|style| style.value)
            .collect::<Vec<_>>()
    };

    for key in [
        prefs::EDIT_TRAIL_SOUNDS,
        SPARKLE_WORDS_KEY,
        KEYWORD_KITTIES_KEY,
    ] {
        let mut service = VersionedConfigService::new(SOURCE.to_string()).unwrap();
        let start = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        let escape = patch_of(
            start,
            format!("settings/set/{key}"),
            Some(SemanticInput::Bool(true)),
        );
        let (after, undo) = apply(&mut service, escape);
        assert!(
            !field_bool(&after, prefs::EDIT_SERIOUS_MODE, false),
            "{key}"
        );
        assert_eq!(
            top_projected_trail_value(&after),
            "off",
            "{key}: the cursor stays off"
        );
        assert_eq!(
            after.raw_value(before_off).as_deref(),
            Some("comet"),
            "{key}: the saved style is kept"
        );
        assert_eq!(marked(&after), ["comet"], "{key}: Cursor Styles marks it");
        // The saved Off, where the list lands, names it too.
        assert!(
            listed_cursor_styles(&after)[0]
                .description
                .starts_with(&format!(
                    "{BEFORE_OFF_MARK}: {} ",
                    cursor_style_name("comet")
                )),
            "{key}: Off names the style it replaced"
        );

        // Choosing it on Cursor Styles brings it back; the mark goes.
        let mut on_page = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        on_page.navigate(SettingsRoute::CursorStyles);
        let choose = patch_of(on_page, cursor_style_row_key("comet"), None);
        let mut restored_service =
            VersionedConfigService::new(service.snapshot().text.to_string()).unwrap();
        let (restored, _) = apply(&mut restored_service, choose);
        assert_eq!(top_projected_trail_value(&restored), "comet", "{key}");
        assert_eq!(restored.raw_value(before_off), None, "{key}");
        assert!(marked(&restored).is_empty(), "{key}");

        // Undo puts back the style and Serious Mode, and keeps nothing.
        let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
            panic!("{key}: undo refused")
        };
        let undone = SettingsViewState::from_snapshot(&snapshot).unwrap();
        assert!(
            field_bool(&undone, prefs::EDIT_SERIOUS_MODE, false),
            "{key}"
        );
        assert_eq!(top_authored_trail_value(&undone), "comet", "{key}");
        assert_eq!(undone.raw_value(before_off), None, "{key}");
    }

    // `aterm ctl settings set cursor_trail_style off` meets the same writer.
    let mut service =
        VersionedConfigService::new("cursor_trail_style = \"water\"\n".to_string()).unwrap();
    let ConfigPatchResult::Applied { snapshot, .. } = service.patch(ConfigPatchRequest {
        base_revision: service.snapshot().revision,
        edits: vec![ConfigKeyEdit {
            key: prefs::EDIT_CURSOR_TRAIL_STYLE.to_string(),
            expected: ExpectedValue::Any,
            value: Some("off".to_string()),
        }],
    }) else {
        panic!("settings set refused")
    };
    let off = SettingsViewState::from_snapshot(&snapshot).unwrap();
    assert_eq!(off.raw_value(before_off).as_deref(), Some("water"));
    assert_eq!(marked(&off), ["water"]);

    // Modified lists it by its style's name, and its Reset forgets it alone.
    let listed = authored_manual_overrides(&off)
        .into_iter()
        .find(|row| row.key == before_off)
        .expect("Modified lists the kept style");
    assert_eq!(
        Some(listed.label.as_str()),
        prefs::editable_fields(&crate::app_config::Config::default())
            .iter()
            .find(|field| field.key == before_off)
            .map(|field| field.label),
        "by its own name"
    );
    assert_eq!(listed.preview, cursor_style_name("water"));
    let mut modified = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    modified.navigate(SettingsRoute::Modified);
    let forget = patch_of(
        modified,
        manual_override_reset_action(before_off)
            .expect("a Reset")
            .as_str()
            .to_string(),
        None,
    );
    let (forgot, _) = apply(&mut service, forget);
    assert_eq!(forgot.raw_value(before_off), None);
    assert_eq!(
        forgot.raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE).as_deref(),
        Some("off")
    );

    // Reset All returns the style to its default; where that draws, no mark
    // is left behind it.
    let mut service = VersionedConfigService::new(
        "cursor_trail_style = \"off\"\ncursor_trail_style_before_off = \"water\"\n".to_string(),
    )
    .unwrap();
    let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let keys = reset_all_keys(&state)
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert!(keys.iter().any(|key| key == prefs::EDIT_CURSOR_TRAIL_STYLE));
    let revision = service.snapshot().revision;
    let ConfigPatchResult::Applied { snapshot, .. } = service.reset_all(revision, keys) else {
        panic!("Reset All refused")
    };
    let reset = SettingsViewState::from_snapshot(&snapshot).unwrap();
    assert_eq!(
        reset.raw_value(before_off).is_none(),
        crate::app_config::DEFAULT_DECORATIVE_EFFECTS
    );

    // A hand-edited older file: `cursor_trail = false` held Fire off, and
    // Cursor Styles marks Fire before anything is written.
    let held = SettingsViewState::from_snapshot(
        &VersionedConfigService::new(
            "cursor_trail = false\ncursor_trail_style = \"fire\"\n".to_string(),
        )
        .unwrap()
        .snapshot(),
    )
    .unwrap();
    assert_eq!(marked(&held), ["fire"]);
}

/// LEAVING SERIOUS MODE KEEPS AN OLD `classic mono` IN THE CURSOR'S COLOUR.
/// The old spelling says Classic and the cursor's colour; Serious Mode's exit
/// by another effect writes the style Off and keeps the style before it as
/// `classic` — and the writer puts the colour on Trail color (`cursor`) in
/// the same write, so choosing Classic again on Cursor Styles, where it is
/// marked, draws its one-colour face in the live cursor colour, and Trail
/// color names the cursor's colour, with its Reset. Undo of the exit puts
/// back the old spelling as it was, though the writer would not write it.
/// Without the writer's rule Classic came back in shifting colours.
#[test]
fn leaving_serious_mode_keeps_an_old_classic_mono_in_the_cursor_color() {
    use aterm_effects::cursor_fx::TrailColor;
    use aterm_effects::cursor_glow::GlowStyle;
    const SOURCE: &str = "serious_mode = true\ncursor_trail_style = \"classic mono\"\n";
    let dispatch = |state: SettingsViewState, id: String, value: Option<SemanticInput>| {
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(slot)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        **slot = state;
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value,
                }),
            )
            .unwrap();
        emitted_config_patch(&outcome)
    };
    let apply = |service: &mut VersionedConfigService, patch: ConfigPatch| {
        let request = ConfigPatchRequest {
            base_revision: service.snapshot().revision,
            edits: patch
                .edits
                .iter()
                .map(|edit| ConfigKeyEdit {
                    key: edit.key.clone(),
                    expected: {
                        let ExpectedConfigValue::Exact(value) = &edit.expected;
                        ExpectedValue::Exact(value.clone())
                    },
                    value: edit.value.clone(),
                })
                .collect(),
        };
        match service.patch(request) {
            ConfigPatchResult::Applied { snapshot, undo } => {
                (SettingsViewState::from_snapshot(&snapshot).unwrap(), undo)
            }
            other => panic!("the real config service refused the patch: {other:?}"),
        }
    };
    // What a window draws from the saved file.
    let drawn = |service: &VersionedConfigService| {
        let snapshot = service.snapshot();
        let config = &snapshot.config;
        let theme_cursor = 0x0009_69DA;
        let presentation =
            crate::app_config::resolve_trail_presentation(config.cursor_trail_style_raw());
        let glow = crate::app_config::resolve_cursor_glow(
            config.cursor_glow_inputs(true, theme_cursor, presentation),
            presentation,
            theme_cursor,
            true,
            0x00C8_D3F5,
            0x001A_1B26,
            0.5,
        );
        (
            glow.enabled.then_some(glow.style),
            glow.classic_mono,
            config.trail_color(),
        )
    };

    let mut service = VersionedConfigService::new(SOURCE.to_string()).unwrap();
    let start = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let escape = dispatch(
        start,
        format!("settings/set/{SPARKLE_WORDS_KEY}"),
        Some(SemanticInput::Bool(true)),
    );
    let (after, undo) = apply(&mut service, escape);
    assert!(!field_bool(&after, prefs::EDIT_SERIOUS_MODE, false));
    assert_eq!(top_projected_trail_value(&after), "off");
    assert_eq!(
        after
            .raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE_BEFORE_OFF)
            .as_deref(),
        Some("classic")
    );
    assert_eq!(
        after.raw_value(prefs::EDIT_CURSOR_TRAIL_COLOR).as_deref(),
        Some(prefs::TRAIL_COLOR_CURSOR),
        "the colour the old spelling said is kept beside it"
    );

    // Cursor Styles marks Classic; choosing it brings Classic back in the
    // cursor's colour.
    let mut on_page = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    on_page.navigate(SettingsRoute::CursorStyles);
    assert!(
        listed_cursor_styles(&on_page)
            .iter()
            .any(|style| style.value == "classic" && style.description.starts_with(BEFORE_OFF_MARK))
    );
    let choose = dispatch(on_page, cursor_style_row_key("classic"), None);
    let mut restored = VersionedConfigService::new(service.snapshot().text.to_string()).unwrap();
    let (restored_state, _) = apply(&mut restored, choose);
    assert_eq!(
        drawn(&restored),
        (Some(GlowStyle::Classic), true, TrailColor::Cursor),
        "Classic in the cursor's colour, as the old spelling drew"
    );
    let trail_color = restored_state
        .field_by_key(prefs::EDIT_CURSOR_TRAIL_COLOR)
        .expect("the Trail color row");
    assert_eq!(trail_color.placeholder, prefs::TRAIL_COLOR_CURSOR_LABEL);
    assert_eq!(
        color_picker::color_now(&restored_state, prefs::EDIT_CURSOR_TRAIL_COLOR),
        None,
        "no one colour: the cursor's, which a program may recolour"
    );
    assert!(restored_state.is_explicit(prefs::EDIT_CURSOR_TRAIL_COLOR));
    // Its Reset gives back Classic's own colours, and Modified says so.
    assert_eq!(
        modified_default_words(&restored_state, prefs::EDIT_CURSOR_TRAIL_COLOR).as_deref(),
        Some("Shifting colors")
    );
    // So does every knob whose default is the style's: the bloom size Reset
    // gives back is Classic's, not the rainbow kitty's an empty file draws.
    let classic_bloom = crate::app_config::Config::bloom_radius_style_default(
        crate::app_config::resolve_trail_style("classic"),
    );
    assert_eq!(
        modified_default_words(&restored_state, prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS),
        prefs::numeric_reading(
            prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS,
            f64::from(classic_bloom),
            &classic_bloom.to_string()
        )
    );
    if crate::app_config::DEFAULT_DECORATIVE_EFFECTS {
        assert_ne!(
            modified_default_words(&restored_state, prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS)
                .as_deref(),
            default_value_label(prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS),
            "the empty file's default is the rainbow kitty's"
        );
    }
    // A value the row takes: never flagged as a color the runtime ignores,
    // and typed in, saved.
    assert_eq!(
        registered_value_unavailability(&restored_state, None, prefs::EDIT_CURSOR_TRAIL_COLOR),
        None
    );
    assert_eq!(color_submission_error(trail_color, Some(" Cursor ")), None);
    assert!(
        color_submission_error(trail_color, Some("cursr"))
            .is_some_and(|refusal| refusal.contains("or cursor for the cursor's color"))
    );

    // Undo of the exit puts back the old spelling and Serious Mode, exactly.
    let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
        panic!("undo refused")
    };
    assert_eq!(&*snapshot.text, SOURCE);
}

/// UNDO PUTS BACK A SPELLING ONLY THE FILE HELD. Undo restores the file's
/// own text, and, where the file changed since, the merge that reverses the
/// change's own lines, wherever it reads as the file with the change taken
/// back: an old style alias (`nyan`) comes back as it was spelled, not as the
/// name the writer gives it (`rainbow kitty flying`), and an Off over an old
/// `classic mono` takes back the keys the writer wrote beside it (the style
/// before Off, the trail colour the spelling says). Before, an Undo after a
/// later change wrote the values back through the writer, which first refused
/// the alias ("undo refused"), then renamed it and kept those keys.
#[test]
fn undo_puts_back_an_old_style_alias() {
    const SOURCE: &str = "cursor_trail_style = \"nyan\"\n";
    let choose_over = |service: &mut VersionedConfigService, old: &str, style: &str| {
        let ConfigPatchResult::Applied { undo, .. } = service.patch(ConfigPatchRequest {
            base_revision: service.snapshot().revision,
            edits: vec![ConfigKeyEdit {
                key: prefs::EDIT_CURSOR_TRAIL_STYLE.to_string(),
                expected: ExpectedValue::Exact(Some(old.to_string())),
                value: Some(style.to_string()),
            }],
        }) else {
            panic!("the style change was refused")
        };
        undo
    };
    let choose =
        |service: &mut VersionedConfigService, style: &str| choose_over(service, "nyan", style);
    let font_px = |service: &mut VersionedConfigService| {
        let ConfigPatchResult::Applied { .. } = service.patch(ConfigPatchRequest {
            base_revision: service.snapshot().revision,
            edits: vec![ConfigKeyEdit {
                key: prefs::EDIT_FONT_PX.to_string(),
                expected: ExpectedValue::Exact(None),
                value: Some("15".to_string()),
            }],
        }) else {
            panic!("the later change was refused")
        };
    };
    let mut service = VersionedConfigService::new(SOURCE.to_string()).unwrap();
    let undo = choose(&mut service, "comet");
    let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
        panic!("undo refused")
    };
    assert_eq!(&*snapshot.text, SOURCE);

    // A later change elsewhere stays; the style goes back to its old spelling.
    let mut service = VersionedConfigService::new(SOURCE.to_string()).unwrap();
    let undo = choose(&mut service, "comet");
    font_px(&mut service);
    let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
        panic!("undo refused")
    };
    let undone = SettingsViewState::from_snapshot(&snapshot).unwrap();
    assert_eq!(
        undone.raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE).as_deref(),
        Some("nyan")
    );
    assert_eq!(undone.raw_value(prefs::EDIT_FONT_PX).as_deref(), Some("15"));

    // Off over an old `classic mono`, a later change, then Undo: the file
    // says what it said, the later change beside it.
    const MONO: &str = "cursor_trail_style = \"classic mono\"\n";
    let mut service = VersionedConfigService::new(MONO.to_string()).unwrap();
    let undo = choose_over(&mut service, "classic mono", "off");
    let off = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    assert_eq!(
        off.raw_value(prefs::EDIT_CURSOR_TRAIL_COLOR).as_deref(),
        Some(prefs::TRAIL_COLOR_CURSOR),
        "the Off wrote the colour the spelling says"
    );
    font_px(&mut service);
    let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
        panic!("undo refused")
    };
    let undone = SettingsViewState::from_snapshot(&snapshot).unwrap();
    for (key, value) in [
        (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("classic mono")),
        (prefs::EDIT_CURSOR_TRAIL_COLOR, None),
        (prefs::EDIT_CURSOR_TRAIL_STYLE_BEFORE_OFF, None),
        (prefs::EDIT_FONT_PX, Some("15")),
    ] {
        assert_eq!(
            undone.raw_value(key).as_deref(),
            value,
            "{key} in {}",
            snapshot.text
        );
    }
}

/// A toy's Reset removes that toy's own key and nothing else: the old shared
/// master and the other toy are rows of their own on Modified, with their
/// own Resets.
#[test]
fn resetting_a_toy_removes_only_its_own_key() {
    let source = "serious_mode = true\n[sparkle_words]\nenabled = false\n[sparkle_words.profanity]\nenabled = false\n[sparkle_words.feline]\nenabled = false\n";
    let service = VersionedConfigService::new(source.to_string()).unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!()
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/reset/{SPARKLE_WORDS_KEY}")),
                value: None,
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&outcome);
    assert_eq!(
        patch
            .edits
            .iter()
            .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
            .collect::<Vec<_>>(),
        [(SPARKLE_WORDS_KEY, None)]
    );
}

#[test]
fn modified_shows_authored_playful_values_and_names_serious_mode_suppression() {
    let service = VersionedConfigService::new(
        "serious_mode = true\ncursor_trail = true\ncursor_trail_style = \"water\"\n".to_string(),
    )
    .unwrap();
    let mut state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    state.navigate(SettingsRoute::Modified);
    assert_eq!(top_projected_trail_value(&state), "off");
    assert_eq!(top_authored_trail_value(&state), "water");
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
        .unwrap();
    let tree = UiTree::new(
        UiNode::new(
            "root",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Application)),
        )
        .layout(Layout::column())
        .children(vec![setting_row(
            &state,
            index,
            field,
            true,
            SettingsWidth::Wide,
        )]),
    )
    .compile(LogicalRect::new(0.0, 0.0, 760.0, 80.0))
    .unwrap();
    let control = tree
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_CURSOR_TRAIL_STYLE
        )))
        .unwrap();
    assert_eq!(
        control.value,
        SemanticValue::Text(cursor_style_name("water")),
        "the control speaks the style's name, never its config token"
    );
    let label = tree
        .semantic(&UiKey::new(format!(
            "settings/label/{}",
            prefs::EDIT_CURSOR_TRAIL_STYLE
        )))
        .unwrap();
    assert!(label.label.contains("Inactive: Serious Mode"));
}

