#[test]
fn modified_calls_a_key_this_build_still_reads_by_what_it_does_not_unknown() {
    let source = "[harness]\napprove_all = false\nauto_reads = true\n\
                  rm_breaker = \"yes\"\ntrust_dialog = \"maybe\"\nread_outside_cwd = \"no\"\n";
    let snapshot = VersionedConfigService::new(source.to_string())
        .unwrap()
        .snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let overrides = authored_manual_overrides(&state);
    let row = |key: &str| {
        overrides
            .iter()
            .find(|entry| entry.key == key)
            .unwrap_or_else(|| panic!("{key} has a Modified row"))
    };

    let limit = row("harness.approve_all");
    assert!(limit.known && !limit.reset_safe);
    assert_ne!(limit.label, UNKNOWN_KEY_LABEL);
    let inert = row("harness.auto_reads");
    assert_ne!(
        limit.preview, inert.preview,
        "a key that still limits approvals reads apart from one with no effect"
    );
    // Each value as the supervisor's reader takes it: `"yes"` is an on and
    // `"maybe"` no setting (neither limits), `"no"` an off (it limits).
    for (key, limits) in [
        ("harness.rm_breaker", false),
        ("harness.trust_dialog", false),
        ("harness.read_outside_cwd", true),
    ] {
        let expected = if limits {
            &limit.preview
        } else {
            &inert.preview
        };
        assert_eq!(&row(key).preview, expected, "{key}");
    }
    assert!(
        overrides
            .iter()
            .all(|entry| entry.preview != UNKNOWN_KEY_PREVIEW),
        "a key this build reads is never called ignored"
    );
}

#[test]
fn modified_manual_previews_are_typed_bounded_and_do_not_echo_unknown_values() {
    let secret = "do-not-render-this-forward-compatible-secret";
    let source = format!(
        "shell_args = [\"-c\", \"printf a,b\"]\nfuture_secret = \"{secret}\"\n[keybindings]\n\"cmd+t\" = \"new_tab\"\n\"cmd+w\" = \"close_tab\"\n"
    );
    let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let overrides = authored_manual_overrides(&state);

    let list = overrides
        .iter()
        .find(|entry| entry.key == prefs::EDIT_SHELL_ARGS)
        .expect("known Manual list override");
    assert_eq!(list.preview, "2 values");
    let map = overrides
        .iter()
        .find(|entry| entry.key == "keybindings")
        .expect("known Manual map override");
    assert_eq!(map.preview, "2 entries");
    let unknown = overrides
        .iter()
        .find(|entry| entry.key == "future_secret")
        .expect("unknown-key override");
    assert_eq!(unknown.label, "Unknown key");
    assert_eq!(unknown.preview, UNKNOWN_KEY_PREVIEW);
    assert!(!unknown.preview.contains(secret));

    let ordinal = overrides
        .iter()
        .position(|entry| entry.key == unknown.key)
        .unwrap();
    let compact = UiTree::new(manual_override_node(
        &state,
        unknown,
        ordinal,
        &key_fragment(&unknown.key),
        300.0,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 340.0, 280.0))
    .unwrap();
    let value_key = UiKey::new(format!(
        "settings/modified/manual/value/{}",
        key_fragment(&unknown.key)
    ));
    assert_eq!(compact.semantic(&value_key).unwrap().label, unknown.preview);
    assert!(
        compact
            .semantics
            .iter()
            .all(|node| !node.label.contains(secret)),
        "Modified semantics must not leak an unknown authored value"
    );

    let long = "x".repeat(MANUAL_OVERRIDE_VALUE_PREVIEW_GRAPHEMES + 20);
    let bounded = bounded_manual_override_value(&long);
    assert!(bounded.ends_with('…'));
    assert_eq!(
        bounded.chars().count(),
        MANUAL_OVERRIDE_VALUE_PREVIEW_GRAPHEMES + 1
    );
    assert_eq!(
        bounded_manual_override_value("alpha\n\tbeta\0"),
        "alpha beta"
    );
    for cluster in ["e\u{301}", "👩\u{200d}💻", "🇺🇳"] {
        let exact = format!("{}{cluster}", "x".repeat(71));
        assert_eq!(bounded_manual_override_value(&exact), exact);
        assert_eq!(exact.graphemes().count(), 72);
        let overflow = format!("{exact}y");
        assert_eq!(
            bounded_manual_override_value(&overflow),
            format!("{exact}…"),
            "72-boundary must keep {cluster:?} whole"
        );
    }

    // The 73rd visible cluster proves truncation; the multi-megabyte tail is never
    // normalized or retained to paint a 72-cluster glance.
    let mut huge = "q".repeat(73);
    huge.push_str(&" \n".repeat(1_100_000));
    assert!(huge.len() > 2 * 1024 * 1024);
    assert_eq!(
        bounded_manual_override_value(&huge),
        format!("{}…", "q".repeat(72))
    );
}

/// Retired keys — the bottom HUD's and the keyword kitty's old controls —
/// are KNOWN in Modified: no unknown-key story, no native control, and
/// Manual is the editing path. The HUD's are preserve-only (no destructive
/// Reset); the keyword kitty's do nothing, so they are no Settings row, offer
/// Remove, and removing one leaves nothing to report on a key that is gone.
#[test]
fn retired_keys_are_known_and_preserve_only_in_modified() {
    let source = concat!(
        "show_hud = true\n",
        "show_resources_hud = false\n",
        "show_engine_hud = true\n",
        "[sparkle_words.feline]\n",
        "idle = true\n",
        "gaze = false\n",
        "color = \"#44ccff\"\n",
        "intensity = 0.7\n",
    );
    let snapshot = VersionedConfigService::new(source.to_string())
        .unwrap()
        .snapshot();
    let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    state.navigate(SettingsRoute::Modified);
    let overrides = authored_manual_overrides(&state);
    for (key, kitty) in [
        ("show_hud", false),
        ("show_resources_hud", false),
        ("show_engine_hud", false),
        ("sparkle_words.feline.idle", true),
        ("sparkle_words.feline.gaze", true),
        ("sparkle_words.feline.color", true),
        ("sparkle_words.feline.intensity", true),
    ] {
        let (ordinal, retired) = overrides
            .iter()
            .enumerate()
            .find(|(_, entry)| entry.key == key)
            .unwrap_or_else(|| panic!("retired {key} remains visible in Modified"));
        assert!(retired.known, "{key}");
        assert_ne!(retired.label, UNKNOWN_KEY_LABEL, "{key}");
        assert_eq!(
            retired.reset_safe, kitty,
            "{key}: only a key that does nothing can be removed"
        );
        if kitty {
            assert!(native_compatibility_only_key(key), "{key}");
            assert!(
                state.legacy.fields.iter().all(|field| field.key != key),
                "retired {key} is no Settings row; Manual types it from its metadata"
            );
            assert!(
                crate::native_config_language::config_schema_entry(key).is_some(),
                "Manual still types retired {key}"
            );
        }
        let fragment = key_fragment(key);
        let compiled = UiTree::new(manual_override_node(
            &state, retired, ordinal, &fragment, 860.0,
        ))
        .compile(LogicalRect::new(0.0, 0.0, 900.0, 320.0))
        .unwrap();
        assert_eq!(
            compiled
                .semantic(&UiKey::new(format!(
                    "settings/modified/manual/reset/{fragment}"
                )))
                .is_some(),
            kitty,
            "{key}: Remove only where removing loses nothing"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(format!(
                    "settings/modified/manual/open/{fragment}"
                )))
                .is_some(),
            "Manual remains the editing path for {key}"
        );
        if kitty {
            // Removing it leaves nothing to report on a key that is gone.
            let removed = config_application_projection(
                &state,
                &ConfigPatch {
                    base_revision: 1,
                    edits: vec![ConfigEdit {
                        key: key.to_string(),
                        expected: ExpectedConfigValue::Exact(None),
                        value: None,
                    }],
                },
                audited_availability(),
            );
            assert!(
                removed.unavailable_notes.is_empty(),
                "{key}: {:?}",
                removed.unavailable_notes
            );
        }
    }
}

#[test]
fn modified_pages_every_manual_override_at_normal_and_large_text() {
    at_each_text_scale(
        &[1.0, 2.0],
        "Modified paging test",
        modified_pages_every_manual_override_at_normal_and_large_text_at_scale,
    );
}

/// One rung of [`modified_pages_every_manual_override_at_normal_and_large_text`].
fn modified_pages_every_manual_override_at_normal_and_large_text_at_scale(_scale: f32) {
    let source = (0..7)
        .map(|index| format!("future_{index} = {index}\n"))
        .collect::<String>();
    let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    state.navigate(SettingsRoute::Modified);
    let overrides = authored_manual_overrides(state);
    assert_eq!(overrides.len(), 7);
    assert_eq!(settings_field_result_count(state), overrides.len());
    let cx = view_cx_at(320.0, 568.0);
    for (offset, authored) in overrides.iter().enumerate() {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.page_scroll = offset;
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        let label = compiled
            .semantic(&UiKey::new(format!(
                "settings/modified/manual/label/{}",
                key_fragment(&authored.key)
            )))
            .unwrap_or_else(|| panic!("{} is reachable at offset {offset}", authored.key));
        assert!(label.rect.bottom() <= cx.viewport.bottom() + 0.01);
        let value = compiled
            .semantic(&UiKey::new(format!(
                "settings/modified/manual/value/{}",
                key_fragment(&authored.key)
            )))
            .unwrap_or_else(|| panic!("{} preview is reachable at offset {offset}", authored.key));
        assert!(value.rect.bottom() <= cx.viewport.bottom() + 0.01);
        assert!(label.rect.bottom() <= value.rect.y + 0.01);
    }
}

#[test]
fn reset_all_preserves_every_toml_native_and_forward_compatible_structure() {
    let source = r#"theme = "Nord"
cursor_nyan_sprite = "/aterm/no-such-reset-cat.png"
[packages]
exclude = ["ay"]
[keybindings]
"cmd+t" = "new_tab"
[[sparkle_words.custom]]
words = ["ultrathink"]
[future_feature]
enabled = true
"#;
    let mut service = VersionedConfigService::new(source.to_string()).unwrap();
    let snapshot = service.snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let result = service.reset_all(
        snapshot.revision,
        state
            .legacy
            .fields
            .iter()
            .filter(|field| !prefs::manual_only_key(field.key))
            .map(|field| field.key.to_string()),
    );
    let ConfigPatchResult::Applied { snapshot, .. } = result else {
        panic!("Reset All removes the native theme override");
    };
    assert!(!snapshot.text.contains("theme = \"Nord\""));
    for preserved in [
        "cursor_nyan_sprite = \"/aterm/no-such-reset-cat.png\"",
        "exclude = [\"ay\"]",
        "\"cmd+t\" = \"new_tab\"",
        "[[sparkle_words.custom]]",
        "[future_feature]",
        "enabled = true",
    ] {
        assert!(snapshot.text.contains(preserved), "missing {preserved:?}");
    }
}

/// The sidebar's arrow keys open Manual like any row: Down from Modified
/// shows the Manual page, the keyboard on its row, and opens no editor.
#[test]
fn the_rail_arrows_onto_manual_like_any_row() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view")
        };
        state.navigate(SettingsRoute::Modified);
        state.common.last_focus = Some(UiKey::new("settings/nav/modified"));
    }
    let stepped = runtime
        .dispatch(instance, view, AppEvent::StepFocus(1))
        .unwrap();
    assert!(
        stepped
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::OpenConfigEditor { .. })),
        "arrowing onto Manual opens nothing"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(state.route, SettingsRoute::Manual);
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/nav/manual")
    );
}

/// MANUAL IS A PAGE, AND OPENING ATERM.TOML IS ITS BUTTON: going to the
/// Manual route (the sidebar row, the palette's Go to Manual, a deep link)
/// shows the page and opens nothing; `settings/manual/open` — the page's
/// Open aterm.toml, the palette's Open aterm.toml — emits exactly one
/// path-free editor effect, and is disabled only while that request is
/// pending.
#[test]
fn manual_route_identity_and_every_action_open_the_typed_editor() {
    let (mut runtime, instance, view) = setup();
    assert_eq!(
        route_action(SettingsRoute::Manual).as_str(),
        "settings/route/manual"
    );
    let commands = runtime.commands(instance, view).unwrap();
    for id in ["settings/route/manual", "settings/manual/open"] {
        assert!(
            commands
                .iter()
                .any(|command| command.id.as_str() == id && command.enabled),
            "{id} participates in the native command surface"
        );
    }
    let went = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Manual),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        went.effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::OpenConfigEditor { .. })),
        "going to the Manual page opens nothing"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(state.route, SettingsRoute::Manual);

    let open = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/manual/open"),
                value: None,
            }),
        )
        .unwrap();
    let operation = open
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::OpenConfigEditor { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("Open aterm.toml emits exactly one path-free editor effect");
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        !commands
            .iter()
            .find(|command| command.id.as_str() == "settings/manual/open")
            .unwrap()
            .enabled,
        "a duplicate open is disabled only while the typed request is pending"
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigEditorFinished {
                operation,
                outcome: ConfigEditorOutcome::Failed {
                    message: "test denial".to_string(),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert!(state.pending.is_empty());
    assert!(state.feedback.as_deref().unwrap().contains("test denial"));
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands
            .iter()
            .find(|command| command.id.as_str() == "settings/manual/open")
            .unwrap()
            .enabled,
        "the Manual command reopens its editor while Settings remains on /manual"
    );
}

/// THE SOUND MENU, on the NATIVE surface (owner ask: "add the volume and
/// SFX menu to settings"): the audible rows are reachable on the native
/// Advanced pane, the bell row only where a beep exists, the master on Top
/// Settings (and search) rather than twice, and the keyword-toy internals
/// stay Manual-only.
#[test]
fn native_sound_menu_is_one_box_on_one_route() {
    let shown: Vec<&str> = prefs::SOUND_MENU_KEYS
        .iter()
        .copied()
        .filter(|key| field_visible(key, false, false))
        .collect();

    // The seven rows the Advanced pane paints: the volume slider, the palette and the
    // five voice toggles, by name.
    for required in [
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        prefs::EDIT_TRAIL_SOUND_STYLE,
        prefs::EDIT_TONE_MELODY,
        prefs::EDIT_TRAIL_SOUND_BED,
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
        // The output streak's pip.
        prefs::EDIT_OUTPUT_STREAK_SOUND,
    ] {
        assert!(
            shown.contains(&required),
            "{required} is not reachable from the native Sound menu"
        );
    }

    // The audible BEL row appears exactly where a beep call exists to suppress.
    assert_eq!(
        shown.contains(&prefs::EDIT_BELL_SOUND),
        cfg!(any(target_os = "macos", windows)),
        "the terminal bell row must not promise a beep this platform never makes"
    );

    // The master switch is no ordinary row: the Sound page leads with the
    // Top Settings card's own Music effects control (`music_effects_rows`), so
    // the two places run one transaction and cannot disagree.
    assert!(
        !field_visible(prefs::EDIT_TRAIL_SOUNDS, false, false),
        "the master is the shared Top control, not a second Advanced row"
    );
    assert!(
        field_visible(prefs::EDIT_TRAIL_SOUNDS, false, true),
        "the master must still answer a global search for sound"
    );
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Sound),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_024.0, 768.0));
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_TRAIL_SOUNDS
            )))
            .is_some(),
        "the Sound page leads with the Music effects switch"
    );

    // The bonk keys' escape from the keyword-toy rule is exact: their
    // sparkle-words siblings stay Manual-only.
    for sibling in [
        "sparkle_words.profanity.density",
        "sparkle_words.profanity.intensity",
    ] {
        assert!(
            !field_visible(sibling, false, false),
            "{sibling} must stay a Manual-only keyword-toy internal"
        );
    }
}

/// Reduce motion reads as its option label on every surface: the Motion
/// picker's "Reduce motion" is the word for the person's choice on the
/// Sound page's rows and its Music effects status, and in the cursor
/// preview's badge and spoken summary; no surface says "Reduced".
#[test]
fn reduce_motion_reads_as_its_option_label_on_every_surface() {
    let words = reduce_motion_words();
    assert_eq!(words, "Reduce motion", "the picker's own label");
    let stale = [
        "Motion: Reduced",
        "set to Reduced",
        "Motion reduced",
        "Reduced motion",
    ];
    // Negative control: the old status line is what the list catches.
    assert!(
        stale
            .iter()
            .any(|old| "On, currently suppressed by Motion: Reduced.".contains(old))
    );
    // With the cursor trail drawn (`trail_drawn`), so the music status's
    // cause is the motion policy and not the typing notes' missing trail.
    let snapshot = VersionedConfigService::new(trail_drawn("motion = \"reduced\"\n"))
        .unwrap()
        .snapshot();
    for route in [
        SettingsRoute::Sound,
        SettingsRoute::CursorMotion,
        SettingsRoute::Home,
    ] {
        let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(route);
        let compiled = settings_route_at(&state, &view_cx_at(1_200.0, 1_600.0));
        let mut said: Vec<String> = painted_texts(&compiled);
        for node in &compiled.semantics {
            said.push(node.label.clone());
            if let SemanticValue::Text(value) = &node.value {
                said.push(value.clone());
            }
        }
        let said = said.join("\n");
        // Where nothing can sound (`trail_audio::output_available`: off
        // macOS) the Sound page's rows say that first, and no motion policy.
        if route != SettingsRoute::Sound || crate::trail_audio::output_available() {
            assert!(said.contains(&words), "{route:?} names {words:?}:\n{said}");
        }
        for old in stale {
            assert!(!said.contains(old), "{route:?} still says {old:?}:\n{said}");
        }
    }
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let status = top_music_suppression_reason_for_output(
        &state,
        crate::native_app::ViewMotionCx::default(),
        true,
    )
    .expect("the music status names the pause");
    assert!(status.full().contains(&words), "{}", status.full());
}

/// A sound row says "Inactive" under a motion policy exactly where its voices
/// are silent, by the voice table the host plays by
/// (`aterm_effects::sound_policy::voice_gain`). Reduce motion, the system's
/// Reduce Motion and the load shed stop the light of the bonk and the output
/// streak, so their rows say so; the typing notes and the riff play on, so
/// Music effects, its volume, the melody, the bed and the riff say nothing.
/// This window being in the background silences nothing: the window that
/// plays is the one a key lands in.
#[test]
fn sound_rows_say_inactive_exactly_where_their_voices_are_silent() {
    use crate::motion::{MotionEffect, MotionMode, MotionPolicy};
    use aterm_effects::sound_policy::{Voice, VoiceTerms, voice_gain};
    let availability = audited_availability();
    let base = "cursor_trail = true\ncursor_trail_style = \"rainbow kitty pet\"\n\
                [output_streak]\nenabled = true\n";
    let rows: [(&str, &[Voice]); 7] = [
        (prefs::EDIT_TRAIL_SOUNDS, &Voice::ALL),
        (prefs::EDIT_TRAIL_SOUND_VOLUME, &Voice::ALL),
        (prefs::EDIT_TONE_MELODY, &[Voice::Keystroke]),
        (prefs::EDIT_TRAIL_SOUND_BED, &[Voice::Keystroke]),
        (prefs::EDIT_TRAIL_SOUND_RIFF, &[Voice::Riff]),
        (prefs::EDIT_SPARKLE_BONK, &[Voice::Bonk]),
        (prefs::EDIT_OUTPUT_STREAK_SOUND, &[Voice::StreakPip]),
    ];
    let still = crate::native_app::ViewMotionCx::default();
    // The playing window's policy for one effect.
    type Playing = fn(MotionEffect) -> MotionPolicy;
    // (the case, what is set, the Settings window's state, the playing
    // window's policy)
    let cases: [(&str, &str, crate::native_app::ViewMotionCx, Playing); 5] = [
        ("nothing", "", still, |_| MotionPolicy::Full),
        ("Reduce motion", "motion = \"reduced\"\n", still, |_| {
            MotionPolicy::resolve(MotionMode::Reduced, false, true)
        }),
        (
            "system Reduce Motion",
            "",
            crate::native_app::ViewMotionCx {
                system_reduced: true,
                ..still
            },
            |_| MotionPolicy::resolve(MotionMode::Auto, true, true),
        ),
        (
            "heavy load",
            "",
            crate::native_app::ViewMotionCx {
                performance_reduced: true,
                ..still
            },
            |effect| {
                if effect.load_shed_exempt() {
                    MotionPolicy::Full
                } else {
                    MotionPolicy::Reduced
                }
            },
        ),
        (
            "this window unfocused",
            "",
            crate::native_app::ViewMotionCx {
                focused: false,
                ..still
            },
            // The window a key lands in is focused.
            |_| MotionPolicy::Full,
        ),
    ];
    let mut idled = 0;
    for (case, extra, cx, playing) in cases {
        // Top-level keys go before the base's table.
        let source = format!("{extra}{base}");
        for (key, voices) in rows {
            let silent = voices.iter().all(|voice| {
                voice_gain(
                    *voice,
                    &VoiceTerms {
                        master: true,
                        own: true,
                        volume: 0.4,
                        raw_focused: true,
                        reduced_motion: voice
                            .motion_twin()
                            .is_some_and(|twin| !playing(twin).animate(twin)),
                    },
                )
                .is_none()
            });
            let effect = projected_effect(&source, &[], key, availability, cx);
            let inactive = effect
                .notes
                .iter()
                .any(|note| note.kind == EffectNoteKind::Inactive);
            assert_eq!(
                inactive, silent,
                "{case}: {key} says Inactive exactly when its voices are silent: {effect:?}"
            );
            idled += usize::from(inactive);
        }
    }
    assert!(
        idled >= 6,
        "non-vacuous: the bonk and the pip idle under each reduction"
    );
}

/// The Sound rows disclose their real gates and only those (a false "Inactive" says a
/// control is dead while the sound plays):
///
///   * the melody and ambient bed ride `CursorGlow::drain_sound_cues`, so
///     `cursor_trail = false` silences them;
///   * the sing-along riff is gated on the glow style, which `resolve_cursor_glow`
///     derives regardless of `enabled`, so its gate is the master switch.
///
/// Each case asserts the note it should carry as well as the one it must not.
#[test]
fn sound_rows_disclose_their_real_gates_and_no_false_ones() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();

    // Cue-borne voices: the trail really is their gate.
    for key in [prefs::EDIT_TONE_MELODY, prefs::EDIT_TRAIL_SOUND_BED] {
        // The retired switch's `false` reads as the style Off.
        let effect = projected_effect("cursor_trail = false\n", &[], key, availability, motion);
        assert!(
            effect_note_contains(&effect, "Cursor style Off"),
            "{key} must disclose the trail gate it actually has: {effect:?}"
        );
        let style_off = projected_effect(
            "cursor_trail = true\ncursor_trail_style = \"off\"\n",
            &[],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&style_off, "Cursor style Off"),
            "{key}: {style_off:?}"
        );
        assert!(!effect.has_live_effect, "{key}");
    }

    // The riff is not trail-gated…
    let trail_off = projected_effect(
        "cursor_trail = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_RIFF,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&trail_off, "cursor effects off"),
        "the riff still sings with the trail off; claiming otherwise is a lie: {trail_off:?}"
    );

    // Only the companion styles sing it: under another style it is idle.
    for source in [
        "cursor_trail = true\ncursor_trail_style = \"comet\"\n",
        "cursor_trail = true\ncursor_trail_style = \"off\"\n",
    ] {
        let riff = projected_effect(
            source,
            &[],
            prefs::EDIT_TRAIL_SOUND_RIFF,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&riff, "companion styles only"),
            "{source}{riff:?}"
        );
        assert!(!riff.has_live_effect, "{source}");
    }

    // THE VOLUME scales the bonk, the riff and the output sounds,
    // which all play with no trail drawn: the trail is not its gate, the
    // Music effects switch is.
    for source in [
        "cursor_trail = false\n",
        "cursor_trail = true\ncursor_trail_style = \"off\"\n",
    ] {
        let volume = projected_effect(
            source,
            &[],
            prefs::EDIT_TRAIL_SOUND_VOLUME,
            availability,
            motion,
        );
        assert!(volume.has_live_effect, "{source}{volume:?}");
        assert!(volume.notes.is_empty(), "{source}{volume:?}");
    }
    let volume_music_off = projected_effect(
        "trail_sounds = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&volume_music_off, "Music effects is Off"),
        "{volume_music_off:?}"
    );
    assert!(!volume_music_off.has_live_effect);

    // …and discloses the master switch, one of its gates.
    let music_off = projected_effect(
        "trail_sounds = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_RIFF,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&music_off, "Music effects is Off"),
        "the riff must disclose the master switch that does silence it: {music_off:?}"
    );
    assert!(!music_off.has_live_effect);

    // The bonk rides the word-decoration tick, not the glow: trail off is not its gate.
    let bonk_trail_off = projected_effect(
        "cursor_trail = false\n",
        &[],
        prefs::EDIT_SPARKLE_BONK,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&bonk_trail_off, "cursor effects off"),
        "the bonk fires with the trail off: {bonk_trail_off:?}"
    );
    // Its real gate, so the negative above cannot pass by disclosing nothing.
    let bonk_master_off = projected_effect(
        "[sparkle_words]\nenabled = false\n",
        &[],
        prefs::EDIT_SPARKLE_BONK,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&bonk_master_off, "all word effects are switched off"),
        "the bonk must disclose the sparkle master that does silence it: {bonk_master_off:?}"
    );
    // …and the Music master (`trail_sounds` in `sound_policy::bonk_sound_gain`). Both
    // bonk rows: `bonk_detonation` admits a cue kind into the same synth and draws
    // nothing.
    for key in [
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
    ] {
        let music_off = projected_effect("trail_sounds = false\n", &[], key, availability, motion);
        assert!(
            effect_note_contains(&music_off, "Music effects is Off"),
            "{key} must disclose the Music-effects master that does silence it: {music_off:?}"
        );
        assert!(!music_off.has_live_effect, "{key}");
    }

    // Platform truth: with no audio device the synth voices say so, while
    // the terminal bell — an OS alert sound, not a synth voice — does not.
    let silent = SettingsAvailability {
        trail_audio: false,
        ..availability
    };
    for key in [
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_OUTPUT_STREAK_SOUND,
    ] {
        let muted = projected_effect("", &[], key, silent, motion);
        assert!(
            effect_note_contains(&muted, "Audio unavailable"),
            "{key}: {muted:?}"
        );
        assert!(
            !muted.has_live_effect,
            "{key}: no device cannot play a synth voice"
        );
        let available = projected_effect(
            "[output_streak]\nenabled = true\n",
            &[],
            key,
            availability,
            motion,
        );
        assert!(
            !effect_note_contains(&available, "Audio unavailable"),
            "{key}: {available:?}"
        );
    }
    let bell = projected_effect("", &[], prefs::EDIT_BELL_SOUND, silent, motion);
    assert!(
        !effect_note_contains(&bell, "Audio unavailable"),
        "the OS bell does not need the trail-audio device: {bell:?}"
    );
}

/// A box says why its rows are idle only where all of them are. With cursor
/// effects off only Tone-adaptive melody and Ambient sound bed fall idle, so
/// the Sound box says nothing for itself (nothing claims Sound volume or the
/// bonks) and those two rows paint their own Inactive tag. With
/// Music effects off every row is idle for that one reason, and the box says
/// it once. Under Rainbow kitty the trail-effect box, whose duration and
/// intensity it still reads, says nothing for itself; the trail-color box,
/// both of whose rows it ignores, speaks of all of them, never of "it".
#[test]
fn a_box_says_why_its_rows_are_idle_only_where_all_of_them_are() {
    let state_for = |source: &str| {
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        SettingsViewState::from_snapshot(&service.snapshot()).unwrap()
    };
    let sound_box: Vec<&str> = prefs::SOUND_MENU_KEYS
        .iter()
        .copied()
        .filter(|key| prefs::group_of(key).0 == "Sound effects" && field_visible(key, false, false))
        .collect();
    assert!(sound_box.len() >= 2 && sound_box.contains(&prefs::EDIT_TRAIL_SOUND_VOLUME));
    assert_eq!(
        shared_inactive_reason(&state_for("cursor_trail = false\n"), &sound_box),
        None,
        "cursor effects off idles two of the box's rows, not Sound volume"
    );
    // Where nothing can sound (`trail_audio::output_available`) each row
    // says so itself, and Music effects idles no row.
    assert_eq!(
        shared_inactive_reason(&state_for("trail_sounds = false\n"), &sound_box)
            .map(|(_, sentence)| sentence),
        crate::trail_audio::output_available()
            .then(|| "These are inactive for now: Music effects is Off.".to_string()),
        "Music effects off idles every row of the box"
    );
    let rainbow = state_for(&trail_drawn(""));
    assert_eq!(
        shared_inactive_reason(
            &rainbow,
            &[
                prefs::EDIT_CURSOR_TRAIL_MS,
                prefs::EDIT_CURSOR_TRAIL_INTENSITY,
                prefs::EDIT_CURSOR_TRAIL_LENGTH,
                prefs::EDIT_CURSOR_TRAIL_RADIUS,
            ],
        ),
        None,
        "Rainbow kitty reads the duration and intensity"
    );
    assert_eq!(
        shared_inactive_reason(
            &rainbow,
            &[
                prefs::EDIT_CURSOR_TRAIL_COLOR,
                prefs::EDIT_CURSOR_TRAIL_ACCENT
            ],
        )
        .map(|(_, sentence)| sentence),
        Some("Rainbow kitty does not use these.".to_string())
    );

    // On the page: no box sentence, and the idle rows say it themselves.
    let (mut runtime, instance, view) = setup();
    replace_settings_source(&mut runtime, view, "cursor_trail = false\n".to_string());
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Sound),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 1_600.0));
    let painted = |prefixes: &[String]| -> String {
        compiled
            .paint
            .iter()
            .filter(|node| {
                !node.peek
                    && prefixes
                        .iter()
                        .any(|prefix| node.key.as_str().starts_with(prefix.as_str()))
            })
            .filter_map(|node| match &node.content {
                UiContent::Text(spec) => Some(spec.text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join(" ")
    };
    assert_eq!(
        painted(&["settings/group-reason/".to_string()]),
        "",
        "no sentence heads a box whose other rows still work"
    );
    // Where nothing can sound (`trail_audio::output_available`) a synth
    // voice's own tag says that first.
    let idle_tag = if crate::trail_audio::output_available() {
        "Inactive"
    } else {
        "Audio unavailable"
    };
    for key in [prefs::EDIT_TONE_MELODY, prefs::EDIT_TRAIL_SOUND_BED] {
        let row = painted(&[
            format!("settings/label/{key}/visual"),
            format!("settings/detail/{key}/line-"),
        ]);
        assert!(row.contains(idle_tag), "{key} paints its own tag: {row:?}");
    }
    let volume = painted(&[
        format!("settings/label/{}/visual", prefs::EDIT_TRAIL_SOUND_VOLUME),
        format!("settings/detail/{}/line-", prefs::EDIT_TRAIL_SOUND_VOLUME),
    ]);
    assert!(
        !volume.contains("Inactive"),
        "Sound volume works: {volume:?}"
    );
}

/// Bloom is a glow of light, which a light background cannot show (a light
/// theme draws trails as ink): on GitHub Light the Bloom switch and its two
/// sliders say they apply on dark themes only, before Bloom Off's own note;
/// on the default dark theme they are live, and Bloom Off still idles the
/// sliders.
#[test]
fn bloom_rows_say_they_have_no_effect_on_a_light_theme() {
    let project = |source: &str, key: &str| {
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        setting_effect_projection(
            &state,
            None,
            key,
            audited_availability(),
            // A dark system: with no theme authored, Default is dark.
            crate::native_app::ViewMotionCx {
                system_dark: true,
                ..crate::native_app::ViewMotionCx::default()
            },
        )
    };
    for key in [
        prefs::EDIT_CURSOR_TRAIL_BLOOM,
        prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH,
        prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS,
    ] {
        let light = project(
            &trail_drawn("theme = \"GitHub Light\"\ncursor_trail_style = \"comet\"\n"),
            key,
        );
        assert!(
            effect_note_contains(&light, "dark themes only") && !light.has_live_effect,
            "{key} on a light theme: {light:?}"
        );
        let dark = project(&trail_drawn("cursor_trail_style = \"comet\"\n"), key);
        assert!(
            !effect_note_contains(&dark, "dark themes only"),
            "{key} on the default dark theme: {dark:?}"
        );
    }
    let off = project(
        &trail_drawn("cursor_trail_style = \"comet\"\ncursor_trail_bloom = false\n"),
        prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH,
    );
    assert!(effect_note_contains(&off, "Bloom Off"), "{off:?}");
}

/// Serious Mode is disclosed on every audible row it silences, and on none it does
/// not. `serious_mode` stays out of the Sound box (`prefs::SOUND_MENU_KEYS`; one key,
/// one control) but is a real gate (`SeriousEffect::TerminalSound`), so it surfaces
/// as a per-row note. Every case first asserts the default posture is note-free.
#[test]
fn serious_mode_is_disclosed_on_the_sound_rows_it_silences() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    const TRAIL_ON: &str = "cursor_trail = true\n";
    const TRAIL_ON_SERIOUS: &str = "cursor_trail = true\nserious_mode = true\n";

    for key in [
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        prefs::EDIT_TRAIL_SOUND_STYLE,
        prefs::EDIT_TONE_MELODY,
        prefs::EDIT_TRAIL_SOUND_BED,
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_BELL_SOUND,
        // The bonks take the same note from the keyword-toy branch; pinning
        // them here keeps the BOX's promise whole rather than one branch's.
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
    ] {
        // Both postures author the trail master: "Inactive: cursor effects off"
        // outranks the Serious Mode note, and its absent-key default is
        // platform-split.
        let quiet = projected_effect(TRAIL_ON, &[], key, availability, motion);
        assert!(
            !effect_note_contains(&quiet, "Serious Mode"),
            "{key} must not claim Serious Mode with Serious Mode off: {quiet:?}"
        );
        let serious = projected_effect(TRAIL_ON_SERIOUS, &[], key, availability, motion);
        assert!(
            effect_note_contains(&serious, "Serious Mode"),
            "{key} is silent under Serious Mode and must say so: {serious:?}"
        );
        assert!(!serious.has_live_effect, "{key}");
    }

    // The master too, via the cursor-trail block's `motion_suppression`, not the sound
    // branch above. This describes the current state (Music effects On is suppressed),
    // not the action: turning it on clears Serious Mode
    // (`top_effect_controls_truthfully_escape_the_serious_mode_override`).
    let master = projected_effect(
        TRAIL_ON_SERIOUS,
        &[],
        prefs::EDIT_TRAIL_SOUNDS,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&master, "Serious Mode"),
        "Music effects On is silent under Serious Mode and must say so: {master:?}"
    );
}

/// A STYLE READS AS ITS NAME, through any spelling of it: the name its row
/// on Cursor Styles shows, in the closed control, the preview and the
/// accessible label alike. The naming is scoped to this key.
#[test]
fn every_cursor_style_spelling_reads_as_its_list_name() {
    for (spelling, name) in [
        ("rainbow kitty pet", "Rainbow kitty"),
        ("rainbow kitty", "Rainbow kitty"),
        ("Rainbow Kitty Tall", "Rainbow kitty"),
        ("kitty", "Rainbow kitty"),
        ("rainbow kitty underline", "Rainbow underline"),
        ("  nyan underline  ", "Rainbow underline"),
        ("nyan", "Flying kitty"),
        ("dog pet", "Rainbow dog"),
        ("rainbow dog", "Rainbow dog"),
        ("laser", "Lightning"),
        ("lightning", "Lightning"),
        ("classic lumen", "Classic"),
        ("classic mono", "Classic"),
        ("off", "Off"),
        // A spelling aterm does not know draws the default, and says so.
        ("plasma", "Rainbow kitty (unknown \"plasma\")"),
    ] {
        assert_eq!(
            setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, spelling),
            name,
            "{spelling:?}"
        );
    }
    // HONEST everywhere: every style's name on the Cursor Styles list, typed
    // into `aterm.toml`, is a spelling of that same style — so "Rainbow dog",
    // "Flying kitty" and `laser`'s "Lightning" all land back on their row.
    for &value in prefs::CURSOR_TRAIL_STYLES {
        let label = setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, value);
        assert_eq!(
            prefs::cursor_trail_style_canonical(&label.to_ascii_lowercase()),
            Some(value),
            "{value:?} is labelled {label:?}"
        );
    }
    // …and the relabelling is scoped to this key: a theme or another enum
    // with the same spelling keeps its own name.
    assert_eq!(
        setting_choice_label(prefs::EDIT_WINDOW_THEME, "rainbow kitty underline"),
        "Rainbow kitty underline"
    );
    assert_ne!(
        setting_choice_label(prefs::EDIT_THEME, "laser"),
        setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, "laser")
    );
}

#[test]
fn visual_forms_hide_inert_and_compatibility_only_effect_controls() {
    for key in [
        "matrix_rain.materialize",
        "matrix_rain.ink_text",
        "matrix_rain.phosphor",
        SPARKLE_MASTER_KEY,
    ] {
        assert!(!field_visible(key, false, false), "{key}");
        assert!(!field_visible(key, false, true), "{key}");
        // One classification on every surface: no audited row, so Modified
        // lists it among the keys only in aterm.toml, not as a row.
        assert!(!field_visible(key, true, false), "{key}");
    }
    assert!(field_visible(SPARKLE_WORDS_KEY, true, false));
    // Color theme and Window appearance lead the Appearance page as well as
    // Top Settings; the other Top Settings stay there alone.
    assert!(field_visible(prefs::EDIT_THEME, false, false));
    assert!(field_visible(prefs::EDIT_WINDOW_THEME, false, false));
    assert!(!field_visible(prefs::EDIT_TRAIL_SOUNDS, false, false));
    assert!(field_visible(prefs::EDIT_THEME, true, false));
    for macos_only in [
        prefs::EDIT_FONT_THICKEN,
        prefs::EDIT_BACKGROUND_OPACITY,
        prefs::EDIT_SECURE_KEYBOARD_ENTRY,
    ] {
        assert_eq!(
            field_visible(macos_only, false, false),
            cfg!(target_os = "macos"),
            "{macos_only} belongs in ordinary Advanced only where it has a live consumer"
        );
        assert!(
            field_visible(macos_only, true, false),
            "Modified preserves authored cross-platform configuration"
        );
    }
    assert!(
        field_visible(prefs::EDIT_ALLOW_OSC52_QUERY, false, false),
        "OSC 52 query has a live host: the GUI clipboard callback answers \
         authorized queries, so the switch is an ordinary security policy"
    );
    assert!(
        field_visible(prefs::EDIT_ALLOW_OSC52_QUERY, true, false),
        "Modified still lists the authored value"
    );
    assert!(
        field_visible(prefs::EDIT_CONFIRM_MULTILINE_PASTE, false, false),
        "the pastejacking confirm has a live host on every platform now \
         (macOS sheet / Windows dialog / Linux in-window banner)"
    );
    {
        let (key, supported) = (
            prefs::EDIT_ALLOW_NOTIFICATIONS,
            crate::notify::delivery_available(),
        );
        assert_eq!(
            field_visible(key, false, false),
            supported,
            "{key} belongs in ordinary Advanced only with a real platform host"
        );
        assert_eq!(field_visible(key, false, true), supported);
        assert!(
            field_visible(key, true, false),
            "Modified preserves authored cross-platform configuration"
        );
    }

    // Keys with no Settings control are aterm.toml keys on every surface.
    for key in ["update.owner", "matrix_rain.fps", prefs::EDIT_STEM_GAMMA] {
        assert!(!field_visible(key, false, false), "{key}");
        assert!(!field_visible(key, false, true), "{key}");
        assert!(!field_visible(key, true, false), "{key}");
    }
    // Keys with an audited consumer and a home are rows everywhere their
    // effect exists: the shell, the window's size and build badge, the
    // renderer and replay, and the trail's brightness.
    for key in [
        prefs::EDIT_SHELL,
        prefs::EDIT_SHOW_BUILD_BADGE,
        prefs::EDIT_COLUMNS,
        prefs::EDIT_LINES,
        prefs::EDIT_GPU,
        prefs::EDIT_TEMPORAL_RECORDING,
        prefs::EDIT_CURSOR_GLOW_SDR_BOOST,
    ] {
        assert!(field_visible(key, false, false), "{key}");
        assert!(field_visible(key, false, true), "{key}");
        assert!(field_visible(key, true, false), "{key}");
    }
    for (key, here) in [
        (
            prefs::EDIT_HDR_GLOW,
            cfg!(any(target_os = "macos", windows)),
        ),
        (prefs::EDIT_FOCUS_BOOST, cfg!(windows)),
    ] {
        assert_eq!(field_visible(key, false, false), here, "{key}");
        assert_eq!(field_visible(key, false, true), here, "{key}");
        assert!(field_visible(key, true, false), "{key}");
    }
    for key in [prefs::EDIT_SHELL_ARGS, prefs::EDIT_FONT_VARIATION] {
        assert!(prefs::manual_collection_key(key), "{key}");
        assert!(
            !field_visible(key, true, false),
            "lossless collection {key} stays in Manual instead of a scalar row"
        );
    }
    assert!(prefs::config_asset_source_key(
        prefs::EDIT_CURSOR_NYAN_SPRITE
    ));
    assert!(prefs::manual_only_key(prefs::EDIT_CURSOR_NYAN_SPRITE));
    assert!(
        !field_visible(prefs::EDIT_CURSOR_NYAN_SPRITE, true, true),
        "host-backed sprite source is edited through Manual's worker-validated path"
    );

    let fields = prefs::editable_fields(&Config::default());
    let ordinary_advanced_field = |field: &EditField| {
        field_visible(field.key, false, false)
            && SettingsRoute::ALL
                .into_iter()
                .filter_map(SettingsRoute::section)
                .any(|section| section == prefs::section_of(field.key))
    };
    for field in fields.iter().filter(|field| ordinary_advanced_field(field)) {
        assert!(
            native_advanced_effect(field.key).is_some(),
            "Advanced row {} has no audited shipping consumer",
            field.key
        );
    }
    for restart_only in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
        assert!(
            native_advanced_effect(restart_only).is_some()
                && prefs::application_timing(restart_only).is_some(),
            "restart-only {restart_only} is a row that says when it applies"
        );
    }
    for route in SettingsRoute::ALL {
        let Some(section) = route.section() else {
            continue;
        };
        let has_ordinary_row = fields.iter().any(|field| {
            prefs::section_of(field.key) == section && field_visible(field.key, false, false)
        });
        assert!(
            has_ordinary_row,
            "{} must not be an empty Advanced destination",
            route.label()
        );
    }
}

#[test]
fn restart_only_overrides_disclose_timing_in_rows_and_apply_feedback() {
    let snapshot =
        VersionedConfigService::new("columns = 96\nlines = 30\ngpu = false\n".to_string())
            .unwrap()
            .snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    for key in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
        let expected_timing = prefs::application_timing(key)
            .expect("restart-only timing")
            .words();
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == key)
            .unwrap();
        let compiled = UiTree::new(setting_row(&state, index, field, true, SettingsWidth::Wide))
            .compile(LogicalRect::new(0.0, 0.0, 720.0, 80.0))
            .unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .unwrap()
                .label
                .contains(expected_timing),
            "Modified visibly discloses timing for {key}"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap()
                .label
                .contains(expected_timing),
            "the native control name discloses timing for {key}"
        );
    }

    let (mut runtime, instance, view) = setup();
    // A revision past the view's own, so the snapshot is admitted.
    let mut snapshot = snapshot;
    snapshot.revision = 2;
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_GPU)),
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("restart-only edit reaches the shared config service");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 3,
                    undo: Some(7),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    let timing = prefs::application_timing(prefs::EDIT_GPU)
        .expect("restart-only timing")
        .words();
    assert!(
        state
            .feedback
            .as_deref()
            .is_some_and(|feedback| feedback.contains(timing)),
        "the apply feedback discloses the timing: {:?}",
        state.feedback
    );
}

#[test]
fn configured_draft_and_pinned_font_sizes_reach_paint_at_their_size_times_the_scale() {
    for size in [6.0_f32, 36.0, 200.0] {
        for scale in [1.0, 1.25, 2.0, 3.0] {
            for source in ["configured", "draft", "environment"] {
                let mut state = SettingsViewState::new(&Config {
                    font_px: Some(if source == "configured" { size } else { 14.0 }),
                    ..Config::default()
                });
                if source == "draft" {
                    state.field_inputs.insert(
                        prefs::EDIT_FONT_PX.to_string(),
                        crate::native_text_input::TextInputState::new(size.to_string()),
                    );
                } else if source == "environment" {
                    state.environment_overrides.insert(
                        prefs::EDIT_FONT_PX.to_string(),
                        crate::app_config::ActiveEnvironmentOverride {
                            variable: "--font-px",
                            effective: size.to_string(),
                        },
                    );
                }
                let spec = renderer_preview_spec_for_key_with_font(
                    &state,
                    prefs::EDIT_FONT_PX,
                    0,
                    crate::native_app::ViewMotionCx::default(),
                    24.0,
                    scale,
                    None,
                )
                .unwrap();
                // A size is px at 1×, the one font-size unit, whatever names
                // it; native paint scales it once for the display.
                assert_eq!(spec.font_px, size);
                let height = spec.preferred_height(108.0).min(600.0);
                let compiled = UiTree::new(crate::settings_preview::preview_node(
                    "physical-font-preview",
                    spec,
                    height,
                ))
                .compile(LogicalRect::new(0.0, 0.0, 900.0, 700.0))
                .unwrap();
                let painted_px = compiled
                    .tray(aterm_render::Theme::default(), 13.0)
                    .prims
                    .into_iter()
                    .find_map(|prim| match prim {
                        crate::widget::DrawPrim::TerminalSpecimen { spec, .. } => {
                            Some(spec.font_px * scale)
                        }
                        _ => None,
                    })
                    .expect("one complete specimen row reaches paint");
                // Painted at the size times the display scale, under the cap
                // the font bounds put on the terminal's device px too.
                let device = (size * scale).min(crate::FONT_PX_MAX);
                assert!(
                    (painted_px - device).abs() < 0.001,
                    "{source} {size}px at {scale}x painted {painted_px}px, not {device}px"
                );
            }
        }
    }
}

#[test]
