#[test]
fn modified_manual_override_discloses_lifecycle_and_precedence() {
    let snapshot =
        VersionedConfigService::new("[packages]\naccount = \"alabsystems\"\n".to_string())
            .unwrap()
            .snapshot();
    let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    state.environment_overrides.insert(
        "packages.account".to_string(),
        crate::app_config::ActiveEnvironmentOverride {
            // A fixture label: no `[packages]` key has a real environment override;
            // the disclosure's rendering is the subject.
            variable: "$ATERM_FIXTURE_OVERRIDE",
            effective: "machine-owner".to_string(),
        },
    );
    let authored = authored_manual_overrides(&state)
        .into_iter()
        .find(|entry| entry.key == "packages.account")
        .expect("packages.account is a Manual-only override");
    let compiled = UiTree::new(manual_override_node(
        &state,
        &authored,
        0,
        &key_fragment(&authored.key),
        860.0,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 220.0))
    .unwrap();
    let disclosure = compiled
        .semantic(&UiKey::new(format!(
            "settings/modified/manual/value/{}",
            key_fragment(&authored.key)
        )))
        .unwrap();
    assert!(
        disclosure
            .label
            .contains("$ATERM_FIXTURE_OVERRIDE remains active")
    );
    assert!(disclosure.label.contains("effective machine-owner"));
    let visual_lines = compiled
        .paint
        .iter()
        .filter(|node| {
            node.key.as_str().starts_with(&format!(
                "settings/modified/manual/value/{}/line-",
                key_fragment(&authored.key)
            ))
        })
        .collect::<Vec<_>>();
    assert!(!visual_lines.is_empty());
    assert!(visual_lines.iter().all(|line| {
        compiled.semantic(&line.key).is_none() && matches!(&line.content, UiContent::Text(_))
    }));
}

