#[test]
fn minimum_contrast_row_and_feedback_disclose_the_translucent_floor() {
    let glass: Config =
        aterm_toml::from_str("minimum_contrast = 1.0\nbackground_opacity = 0.7\n").unwrap();
    let state = SettingsViewState::new(&glass);
    assert_eq!(constrained_minimum_contrast(&state), Some((1.0, 4.5)));
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_MINIMUM_CONTRAST)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 1_000.0, 90.0))
    .unwrap();
    for key in [
        format!("settings/control/{}", prefs::EDIT_MINIMUM_CONTRAST),
        format!("settings/label/{}", prefs::EDIT_MINIMUM_CONTRAST),
    ] {
        let label = &compiled.semantic(&UiKey::new(key.clone())).unwrap().label;
        assert!(
            label.contains("4.5:1"),
            "{key} discloses the floor: {label}"
        );
    }

    for (source, expected) in [
        ("minimum_contrast = 4.5\nbackground_opacity = 0.7\n", None),
        ("minimum_contrast = 7.0\nbackground_opacity = 0.7\n", None),
        ("minimum_contrast = 1.0\nbackground_opacity = 1.0\n", None),
    ] {
        let config: Config = aterm_toml::from_str(source).unwrap();
        assert_eq!(
            constrained_minimum_contrast(&SettingsViewState::new(&config)),
            expected,
            "{source}"
        );
    }

    let mut drafts = SettingsViewState::new(&Config::default());
    drafts.field_inputs.insert(
        prefs::EDIT_BACKGROUND_OPACITY.to_string(),
        crate::native_text_input::TextInputState::new("0.6".to_string()),
    );
    assert_eq!(constrained_minimum_contrast(&drafts), Some((1.0, 4.5)));
    drafts.field_inputs.insert(
        prefs::EDIT_MINIMUM_CONTRAST.to_string(),
        crate::native_text_input::TextInputState::new("5".to_string()),
    );
    assert_eq!(constrained_minimum_contrast(&drafts), None);

    let opaque = SettingsViewState::new(&Config::default());
    let patch = |edits: &[(&str, &str)]| ConfigPatch {
        base_revision: 1,
        edits: edits
            .iter()
            .map(|(key, value)| ConfigEdit {
                key: (*key).to_string(),
                expected: ExpectedConfigValue::Exact(None),
                value: Some((*value).to_string()),
            })
            .collect(),
    };
    assert_eq!(
        post_patch_minimum_contrast_constraint(
            &opaque,
            &patch(&[(prefs::EDIT_BACKGROUND_OPACITY, "0.5")])
        ),
        Some((1.0, 4.5))
    );
    assert_eq!(
        post_patch_minimum_contrast_constraint(
            &opaque,
            &patch(&[
                (prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
                (prefs::EDIT_MINIMUM_CONTRAST, "4.5"),
            ])
        ),
        None,
        "the threshold itself is not raised"
    );
    assert_eq!(
        post_patch_minimum_contrast_constraint(
            &opaque,
            &patch(&[
                (prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
                (prefs::EDIT_MINIMUM_CONTRAST, "2"),
                (prefs::EDIT_COPY_ON_SELECT, "true"),
            ])
        ),
        Some((2.0, 4.5)),
        "mixed patches use the complete post-commit pair"
    );

    let snapshot = VersionedConfigService::new(
        "minimum_contrast = 1.0\nbackground_opacity = 1.0\n".to_string(),
    )
    .unwrap()
    .snapshot();
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_BACKGROUND_OPACITY)),
                value: Some(SemanticInput::Number(0.5)),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 2,
                    undo: None,
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    // The floor is the Minimum contrast row's to show; saving opacity says
    // only that it applied.
    let feedback = state.feedback.as_deref().unwrap();
    assert!(!feedback.contains("contrast"), "{feedback}");
}

#[test]
fn background_opacity_discloses_exact_platform_and_backend_availability() {
    let state = SettingsViewState::new(&Config::default());
    let project = |gpu| {
        setting_effect_projection(
            &state,
            None,
            prefs::EDIT_BACKGROUND_OPACITY,
            SettingsAvailability::runtime(gpu),
            crate::native_app::ViewMotionCx::default(),
        )
    };
    let cpu = project(false);
    assert!(!cpu.has_live_effect);
    assert!(
        !cpu.notes.is_empty(),
        "the CPU renderer's opaque grid is said"
    );
    let gpu = project(true);
    assert_eq!(
        gpu.has_live_effect,
        cfg!(target_os = "macos"),
        "only the macOS GPU applies window opacity"
    );
    assert_eq!(gpu.notes.is_empty(), cfg!(target_os = "macos"));
    assert!(
        setting_effect_projection(
            &state,
            None,
            prefs::EDIT_MINIMUM_CONTRAST,
            SettingsAvailability::runtime(false),
            crate::native_app::ViewMotionCx::default(),
        )
        .notes
        .is_empty()
    );
}

#[test]
fn unavailable_runtime_controls_stay_truthful_in_modified() {
    let state = SettingsViewState::new(&Config::default());
    let unavailable = |key| {
        setting_effect_projection(
            &state,
            None,
            key,
            SettingsAvailability::runtime(true),
            crate::native_app::ViewMotionCx::default(),
        )
        .notes
        .iter()
        .any(|note| note.kind == EffectNoteKind::Unavailable)
    };
    // `allow_osc52_query` is a live policy (the GUI answers authorized queries).
    assert!(!unavailable(prefs::EDIT_ALLOW_OSC52_QUERY));
    assert_eq!(
        !unavailable(prefs::EDIT_SECURE_KEYBOARD_ENTRY),
        cfg!(target_os = "macos"),
        "Secure Keyboard Entry actuates on macOS only"
    );
    assert_eq!(
        !unavailable(prefs::EDIT_ALLOW_NOTIFICATIONS),
        crate::notify::delivery_available()
    );
    assert!(
        !unavailable(prefs::EDIT_CONFIRM_MULTILINE_PASTE),
        "the pastejacking confirm actuates on every platform now \
         (macOS sheet / Windows dialog / Linux in-window banner)"
    );
    assert_eq!(
        !unavailable(prefs::EDIT_TRAIL_SOUNDS),
        crate::trail_audio::output_available()
    );
}

/// Settings reads the GPU capability its host presented (`ViewMotionCx::backend_gpu`;
/// `App::gpu_capable` answers it for an unredeemed headless intent too, pinned by
/// `the_settings_capability_read_follows_the_intent_the_app_holds`), so a deferred GPU
/// does not make HDR glow, bloom, P3 or backdrop materials read unavailable, while a
/// run settled on the CPU renderer still says so. The view reads no process global.
#[test]
fn a_deferred_gpu_intent_projects_the_same_availability_as_a_live_device() {
    let presented = |backend_gpu: bool| {
        let state = SettingsViewState::new(&Config::default());
        state.presented_motion.set(crate::native_app::ViewMotionCx {
            backend_gpu,
            ..crate::native_app::ViewMotionCx::default()
        });
        state
    };
    let (capable, settled) = (presented(true), presented(false));
    // Cursor bloom: a GPU post-effect on every platform. HDR glow is one only
    // where the platform presents HDR (`row_available_here`); on Linux, which
    // presents SDR, its one note is that platform's and never the renderer's.
    let key = prefs::EDIT_CURSOR_TRAIL_BLOOM;
    let effect = |availability| {
        projected_effect(
            "cursor_trail = true\ncursor_trail_style = \"fire\"\n",
            &[(key, "true")],
            key,
            availability,
            crate::native_app::ViewMotionCx::default(),
        )
    };
    let live_device = SettingsAvailability::for_state(&capable);
    let settled_cpu = SettingsAvailability::for_state(&settled);
    assert_eq!(live_device, SettingsAvailability::runtime(true));
    assert_ne!(
        settled_cpu, live_device,
        "the fixture must actually distinguish the two readings"
    );
    assert!(
        effect_note_contains(&effect(settled_cpu), "GPU renderer only"),
        "a run that has settled on the CPU renderer still discloses the denial"
    );
    assert!(
        !effect_note_contains(&effect(live_device), "GPU renderer only"),
        "a GPU-capable run never carries the denial"
    );

    // The routing through a real call site: `manual_override_disclosure` calls
    // `for_state` and returns the sentence a user reads.
    let authored = ManualOverride {
        key: key.to_string(),
        label: "Bloom".to_string(),
        preview: "true".to_string(),
        known: true,
        reset_safe: true,
    };
    let settled_disclosure = manual_override_disclosure(&settled, &authored);
    let capable_disclosure = manual_override_disclosure(&capable, &authored);
    assert!(
        settled_disclosure.contains("requires the GPU renderer"),
        "a settled CPU run still discloses the denial: {settled_disclosure}"
    );
    assert!(
        !capable_disclosure.contains("requires the GPU renderer"),
        "a GPU-capable run (an unredeemed intent included) is never denied: \
         {capable_disclosure}"
    );
}

#[test]
fn config_feedback_projection_distinguishes_unavailable_from_mixed_live_edits() {
    // HDR glow has a live consumer only while the trail draws glow quads, so author the
    // master rather than inherit a platform-split default.
    let state = SettingsViewState::new(&Config {
        cursor_trail: Some(true),
        ..Config::default()
    });
    let availability = SettingsAvailability {
        backend_gpu: false,
        macos: true,
        windows: false,
        notifications: true,
        trail_audio: false,
        packages: PackageAdmission::Ready,
        update_installable: UpdateInstallability::Installable,
    };
    let edit = |key: &str, value: &str| ConfigEdit {
        key: key.to_string(),
        expected: ExpectedConfigValue::Exact(None),
        value: Some(value.to_string()),
    };
    for (key, value) in [
        (prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
        (prefs::EDIT_TRAIL_SOUNDS, "true"),
    ] {
        let projection = config_application_projection(
            &state,
            &ConfigPatch {
                base_revision: 1,
                edits: vec![edit(key, value)],
            },
            availability,
        );
        assert!(!projection.has_live_edit, "{key} is saved but inert here");
        assert!(!projection.unavailable_notes.is_empty(), "{key}");
    }

    // On a screen that shows EDR, where HDR glow is the trail's brightness.
    state.presented_motion.set(crate::native_app::ViewMotionCx {
        display_edr: true,
        ..state.presented_motion.get()
    });
    let hdr = config_application_projection(
        &state,
        &ConfigPatch {
            base_revision: 1,
            edits: vec![edit(prefs::EDIT_HDR_GLOW, "false")],
        },
        SettingsAvailability {
            backend_gpu: true,
            ..availability
        },
    );
    assert!(
        hdr.has_live_edit,
        "disabling HDR glow gates the next present in an existing GPU window"
    );

    let mixed = config_application_projection(
        &state,
        &ConfigPatch {
            base_revision: 1,
            edits: vec![
                edit(prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
                edit(prefs::EDIT_COPY_ON_SELECT, "true"),
            ],
        },
        availability,
    );
    assert!(
        mixed.has_live_edit,
        "one real live edit makes the patch Applied"
    );
    assert!(
        !mixed.unavailable_notes.is_empty(),
        "the inert edit is still said"
    );
}

#[test]
fn config_feedback_projection_names_durable_effect_suppression() {
    let availability = SettingsAvailability {
        backend_gpu: true,
        macos: true,
        windows: false,
        notifications: true,
        trail_audio: true,
        packages: PackageAdmission::Ready,
        update_installable: UpdateInstallability::Installable,
    };
    let patch = |edits: &[(&str, &str)]| ConfigPatch {
        base_revision: 1,
        edits: edits
            .iter()
            .map(|(key, value)| ConfigEdit {
                key: (*key).to_string(),
                expected: ExpectedConfigValue::Exact(None),
                value: Some((*value).to_string()),
            })
            .collect(),
    };

    for (source, key, reason) in [
        (
            "serious_mode = true\n",
            prefs::EDIT_MATRIX_RAIN_ENABLED,
            "Currently inactive: Serious Mode",
        ),
        (
            "motion = \"reduced\"\n",
            prefs::EDIT_MATRIX_RAIN_ENABLED,
            "Currently inactive: Reduce motion",
        ),
    ] {
        let config: Config = aterm_toml::from_str(source).unwrap();
        let state = SettingsViewState::new(&config);
        let projection =
            config_application_projection(&state, &patch(&[(key, "true")]), availability);
        assert!(!projection.has_live_edit, "{source:?} {key}");
        assert!(projection.suppression_notes.contains(reason));
    }

    let config: Config = aterm_toml::from_str("serious_mode = true\n").unwrap();
    let state = SettingsViewState::new(&config);
    let mixed = config_application_projection(
        &state,
        &patch(&[
            (prefs::EDIT_MATRIX_RAIN_ENABLED, "true"),
            (prefs::EDIT_COPY_ON_SELECT, "true"),
        ]),
        availability,
    );
    assert!(mixed.has_live_edit);
    assert!(
        mixed
            .suppression_notes
            .contains("Currently inactive: Serious Mode")
    );
}

#[test]
