/// `desktop_alerts` (2026-09-28: the owner turned aterm's own desktop
/// alerts off; the lead kept them off on 2026-10-18, opt in with Notify Me)
/// is an ordinary Settings ▸ Security switch in its own "Notifications" box,
/// resolved OFF from the default config, and a search for "alerts" draws it.
/// NEGATIVE CONTROL: a config that turns it on seeds it ON, so the OFF is the
/// default's and not a dead switch. Only
/// where a desktop notifier exists: elsewhere it is Manual-only, like
/// `allow_notifications`.
#[test]
fn the_security_page_carries_the_desktop_alerts_switch() {
    let key = prefs::EDIT_DESKTOP_ALERTS;
    let on: Config = aterm_toml::from_str("desktop_alerts = true").unwrap();
    let seed = |cfg: &Config| {
        prefs::editable_fields(cfg)
            .into_iter()
            .find(|field| field.key == key)
            .and_then(|field| field.seed)
    };
    assert_eq!(seed(&Config::default()).as_deref(), Some("false"));
    assert_eq!(seed(&on).as_deref(), Some("true"), "an ON config seeds ON");
    if !crate::notify::delivery_available() {
        assert!(native_advanced_effect(key).is_none());
        return;
    }
    assert!(matches!(
        native_advanced_effect(key),
        Some(AdvancedEffectPath::DesktopNotifier)
    ));
    let (mut runtime, instance, view) = setup();
    go_to_route(&mut runtime, instance, view, SettingsRoute::Security);
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 900.0));
    let control = compiled
        .semantic(&UiKey::new(format!("settings/control/{key}")))
        .expect("the Security page draws the desktop-alerts switch");
    assert_eq!(control.value, SemanticValue::Bool(false), "default OFF");
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/search"),
                value: Some(SemanticInput::Text("alerts".to_string())),
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 900.0));
    assert!(
        compiled
            .semantic(&UiKey::new(format!("settings/control/{key}")))
            .is_some(),
        "a search for \"alerts\" draws it"
    );
}

#[test]
fn row_notes_are_native_semantic_and_fit_responsive_layouts() {
    at_each_text_scale(
        &[1.0, 2.0],
        "native-note audit",
        row_notes_are_native_semantic_and_fit_responsive_layouts_at_scale,
    );
}

/// One rung of [`row_notes_are_native_semantic_and_fit_responsive_layouts`] ([`at_each_text_scale`]).
fn row_notes_are_native_semantic_and_fit_responsive_layouts_at_scale(scale: f32) {
    for (viewport_width, viewport_height) in [(1_200.0, 720.0), (320.0, 568.0), (568.0, 320.0)] {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Security),
                    value: None,
                }),
            )
            .unwrap();
        let cx = view_cx_at(viewport_width, viewport_height);
        // The Permissions box's footnote speaks for the rows it holds.
        let permissions = prefs::editable_fields(&crate::app_config::Config::default())
            .into_iter()
            .map(|field| field.key)
            .filter(|key| {
                prefs::section_of(key) == prefs::Section::Security
                    && prefs::group_of(key).0 == "Permissions"
                    && field_visible(key, false, false)
            })
            .collect::<Vec<_>>();
        // EVERY PERMISSION DRAWS ITS OWN NOTE inside its row (none is the
        // box's, drawn under its last row as if that row's); its control's
        // description says it too.
        let notes: Vec<(&str, &str)> = permissions
            .iter()
            .copied()
            .zip(prefs::row_notes(&permissions))
            .filter_map(|(key, note)| match note? {
                prefs::RowNote::Own(note) => Some((key, note)),
                prefs::RowNote::Shared(note) => panic!("{key} shares {note:?}"),
            })
            .collect();
        assert_eq!(
            notes.len(),
            permissions.len(),
            "every Permissions row carries a note of its own"
        );
        let mut reached = false;
        let mut painted_notes = std::collections::BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("{viewport_width}×{viewport_height} screen {top} at {scale}×");
            for (key, note) in &notes {
                // Its control's description says the note on every screen
                // that shows the control, whether the note's lines are on it
                // or are the stop after it.
                if let Some(control) =
                    compiled.semantic(&UiKey::new(format!("settings/control/{key}")))
                {
                    assert!(
                        control
                            .description
                            .as_deref()
                            .is_some_and(|description| description.contains(note)),
                        "{context}: {key}'s description says its note"
                    );
                    reached = true;
                }
                // In its row, or the stop right after it where the two
                // outgrow a screen together.
                let lines = compiled
                    .paint
                    .iter()
                    .filter(|node| {
                        !node.peek
                            && (node
                                .key
                                .as_str()
                                .starts_with(&format!("settings/detail/{key}/line-"))
                                || node
                                    .key
                                    .as_str()
                                    .starts_with(&format!("settings/note/{key}/line-")))
                    })
                    .collect::<Vec<_>>();
                if lines.is_empty() {
                    continue;
                }
                // (An empty line is the room the row keeps for a tag its
                // fullest state shows there: paint-only too, and blank.)
                assert!(
                    lines.iter().all(|line| {
                        compiled.semantic(&line.key).is_none()
                            && matches!(&line.content, UiContent::Text(_) | UiContent::Group(_))
                    }),
                    "{context}: a note's lines are paint-only copy"
                );
                let painted = lines
                    .iter()
                    .filter_map(|line| match &line.content {
                        UiContent::Text(spec) => Some(spec.text.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>()
                    .join(" ");
                let words = |text: &str| text.split_whitespace().collect::<Vec<_>>().join(" ");
                if words(&painted).contains(&words(note)) {
                    painted_notes.insert(*key);
                }
            }
            let overflow = compiled
                .paint_audit_lines()
                .into_iter()
                .filter(|line| {
                    line.contains("paint-text key=\"settings/detail/")
                        && (line.contains("overflow=true") || line.contains("clip-truncated=true"))
                })
                .collect::<Vec<_>>();
            assert!(overflow.is_empty(), "{context}: {}", overflow.join("\n"));
        });
        assert!(
            reached,
            "native Permissions note at {viewport_width}×{viewport_height} {scale}×"
        );
        // Each note paints, in its row or the stop right after it.
        for (key, _) in &notes {
            assert!(
                painted_notes.contains(key),
                "{viewport_width}×{viewport_height} {scale}×: {key} paints its own note"
            );
        }
    }

    if scale == 2.0 {
        for route in SettingsRoute::ALL {
            let Some(section) = route.section() else {
                continue;
            };
            let (mut runtime, instance, view) = setup();
            // Cursor Styles with its default style drawn on every host
            // ([`trail_drawn`]): Off, Windows' default, has no tuning rows.
            if route == SettingsRoute::CursorStyles {
                replace_settings_source(&mut runtime, view, trail_drawn(""));
            }
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(route),
                        value: None,
                    }),
                )
                .unwrap();
            let expected = {
                let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                    unreachable!();
                };
                state
                    .legacy
                    .fields
                    .iter()
                    .filter(|field| {
                        prefs::section_of(field.key) == section
                            && field_visible(field.key, false, false)
                    })
                    .map(|field| field.key.to_string())
                    .collect::<BTreeSet<_>>()
            };
            let names = prefs::editable_fields(&crate::app_config::Config::default())
                .into_iter()
                .map(|field| (field.key, field.label))
                .collect::<std::collections::BTreeMap<_, _>>();
            // Cursor Styles shows the tuning the saved style (the default
            // here) draws with, and only that.
            let expected = if route == SettingsRoute::CursorStyles {
                let default =
                    crate::app_config::resolve_trail_style(prefs::DEFAULT_CURSOR_TRAIL_STYLE);
                expected
                    .into_iter()
                    .filter(|key| {
                        !prefs::CURSOR_STYLE_TUNING_KEYS.contains(&key.as_str())
                            || trail_style_uses(&default, key, false)
                    })
                    .collect()
            } else {
                expected
            };
            assert!(
                !expected.is_empty(),
                "{} lost every curated field",
                route.label()
            );
            let cx = view_cx_at(320.0, 568.0);
            let mut reached = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, page| {
                assert_zero_top_paint(
                    compiled,
                    &format!("2× compact {} screen {page}", route.label()),
                );
                let visible = compiled
                    .hits
                    .iter()
                    .filter_map(|hit| {
                        hit.key
                            .as_str()
                            .strip_prefix("settings/control/")
                            .filter(|key| expected.contains(*key))
                    })
                    .collect::<Vec<_>>();
                for key in visible.iter().filter(|key| {
                    // A control a list's edge cuts may answer under a label
                    // the edge took; it is checked where it shows whole.
                    !list_cuts(compiled, &UiKey::new(format!("settings/control/{key}")))
                }) {
                    let semantic_key = UiKey::new(format!("settings/label/{key}"));
                    let Some(semantic) = compiled.semantic(&semantic_key) else {
                        // A row taller than the room scrolls its name out
                        // above a control still drawn whole; the control
                        // then says the whole name itself.
                        assert!(
                            row_name_scrolled_out(compiled, key),
                            "2× compact {} screen {page}: {key} lost its complete label semantics",
                            route.label()
                        );
                        let control = compiled
                            .semantic(&UiKey::new(format!("settings/control/{key}")))
                            .unwrap_or_else(|| panic!("{key} answers with no semantics"));
                        let name = names
                            .get(*key)
                            .unwrap_or_else(|| panic!("{key} has no registry name"));
                        assert!(
                            control.label.starts_with(name) && !control.label.contains('…'),
                            "2× compact {} screen {page}: {key}'s name scrolled out and its control \
                             says {:?}, not {name:?}",
                            route.label(),
                            control.label,
                        );
                        continue;
                    };
                    assert!(
                        !semantic.label.contains('…'),
                        "2× compact {} screen {page}: semantic label was elided: {}",
                        route.label(),
                        semantic.label,
                    );
                    let visual = painted_row_label(compiled, key)
                        .unwrap_or_else(|| panic!("{key} lost its paint-only visual label"));
                    assert!(
                        visual.chars().any(char::is_alphanumeric),
                        "2× compact {} screen {page}: {key} collapsed to {visual:?}",
                        route.label(),
                    );
                    let control_key = format!("settings/control/{key}");
                    if let Some(UiContent::Button(button)) =
                        compiled.paint.iter().find_map(|node| {
                            (node.key.as_str() == control_key).then_some(&node.content)
                        })
                    {
                        let visual = button
                            .spec
                            .visual_label
                            .as_deref()
                            .unwrap_or(&button.spec.label);
                        assert!(
                            visual.chars().any(char::is_alphanumeric),
                            "2× compact {} screen {page}: {key} choice collapsed to {visual:?}",
                            route.label(),
                        );
                        assert!(
                            !button.spec.label.contains('…'),
                            "2× compact {} screen {page}: {key} control semantics were elided",
                            route.label(),
                        );
                    }
                }
                // No screen is only a preview: the list always shows a stop.
                assert!(
                    compiled.semantics.iter().any(|node| {
                        node.parent
                            .as_ref()
                            .is_some_and(|parent| parent.as_str() == "settings/list")
                    }),
                    "2× compact {} screen {page} shows no stop of its list\n{}",
                    route.label(),
                    compiled.paint_audit_lines().join("\n"),
                );
                reached.extend(visible.into_iter().map(str::to_string));
                // The theme is its card's rows (its slots, or the Color
                // theme control, and the Follow system switch).
                if expected.contains(prefs::EDIT_THEME)
                    && compiled
                        .hits
                        .iter()
                        .any(|hit| theme_card_control_key(hit.key.as_str()))
                {
                    reached.insert(prefs::EDIT_THEME.to_string());
                }
                assert_all_hits_material_and_contained(
                    compiled,
                    &format!("2× compact {} screen {page}", route.label()),
                );
            });
            assert_eq!(
                reached,
                expected,
                "2× compact {} must reach every curated field",
                route.label(),
            );
        }
    }
}

/// The byline steps down a fixed ladder — author · company · site, then
/// author · company, then the author, then the author's short form — to the
/// longest form its hero column really fits, so no width or text scale ever
/// paints it elided. The site joined the line on 2026-09-14 and clipped a
/// 286.5pt phone column at 1× ("…alab.sy…", 223.2pt required against 206.5pt
/// available). The LAST rung is measured like every other one: `Andrew
/// Yates` was the floor until 2026-09-17, when a 240pt host at 2× gave it a
/// 164.0pt column against its 164.6pt measure and the painter clipped the
/// name itself. Below the last rung the hero authors NO byline — asserted
/// here in both directions, so the omission can never hide a form that would
/// have fitted. Every scale runs on a thread of its own ([`at_each_text_scale`]).
#[test]
fn native_about_byline_steps_down_to_the_longest_form_its_column_fits() {
    at_each_text_scale(&[1.0, 1.5, 2.0], "About byline fit audit", |scale| {
        about_byline_sweep(scale, 30.0, 0.5)
    });
}

/// One Dynamic Type rung of the byline sweep, over widths `coarse` apart
/// from 120pt and, where two neighbours disagree about the hero (its
/// column, the rung painted, the short hero), bisected down to
/// `resolution` — the thresholds, which are where a byline can overflow.
///
/// WHY (30, 0.5), MEASURED 2026-09-30 by putting each of these into the
/// production ladder (temporary hooks, not committed): a fit slack of 17pt,
/// 10pt and the historical 0.6pt, a fit 3pt too tight, a 12pt measure where
/// the line paints at 13pt, the 48pt column clamp, an unmeasured floor rung,
/// and a width class starting the ladder past the first rung — every one turns this
/// sweep red, as it does the every-7.5pt sweep. Thinning to every 30pt
/// ALONE misses the 0.6pt slack and the 3pt-tight fit (a window narrower
/// than the step); the bisection is what keeps them.
fn about_byline_sweep(scale: f32, coarse: f32, resolution: f32) {
    let author_company = crate::build_info::AUTHOR_COMPANY_BYLINE;
    let author = aterm_types::identity::AUTHOR;
    let author_short = crate::build_info::AUTHOR_SHORT;
    let full = format!("{author_company} \u{00b7} {}", aterm_types::identity::SITE);
    let ladder = [full.as_str(), author_company, author, author_short];
    // The byline is Text/Success: the Body step, 13pt × scale, UI face.
    let px = 13.0 * scale;
    let width_of = |line: &str| crate::tray_raster::ui_text_width(line, px);
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    struct HeroByline {
        /// The painted line, its paint-audit row, and its semantic label —
        /// `None` when the hero authored no byline at all.
        painted: Option<(String, String, Option<String>)>,
        column: f32,
        /// The short hero: the wordmark beside the tagline, version and byline.
        short: bool,
    }
    // The byline's column: in the full hero `about/wordmark` is a child of the
    // SAME column, the version line below it; in the short hero the column is
    // `about/compact-identity`, beside the wordmark (s-3: the byline used to be
    // measured in the full hero's column and never painted in the short one).
    // Either measures the column even where no byline was authored — the one
    // geometry a byline node cannot report on. Where both exist the two
    // measures are asserted equal, which is what makes the proxy honest rather
    // than a second guess.
    let byline_at = |width: f32, height: f32| {
        let cx = view_cx_at(width, height);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let painted_rect = |key: &str| {
            compiled
                .paint
                .iter()
                .find(|node| node.key == UiKey::new(key))
                .map(|node| node.rect)
        };
        painted_rect("about/version-summary")?;
        let wordmark = compiled
            .paint
            .iter()
            .find(|node| node.key == UiKey::new("about/wordmark"))?;
        assert!(
            matches!(&wordmark.content, UiContent::Custom(spec)
                if spec.audit_id == crate::native_ui::WORDMARK_AUDIT),
            "{width}x{height} at {scale}×: the wordmark is the hero's wordmark node"
        );
        let short_column = painted_rect("about/compact-identity");
        let short = short_column.is_some();
        let column = short_column.map_or(wordmark.rect.width, |rect| rect.width);
        let painted = compiled
            .paint
            .iter()
            .find(|node| node.key == UiKey::new("about/byline"))
            .map(|node| {
                let UiContent::Text(spec) = &node.content else {
                    panic!("{width}x{height} at {scale}×: the byline is a text node");
                };
                assert!(
                    (node.rect.width - column).abs() < 0.05,
                    "{width}x{height} at {scale}×: the byline's {}pt box is its {column}pt hero column",
                    node.rect.width
                );
                let audit = compiled
                    .text_fit_audit_line(&UiKey::new("about/byline"))
                    .expect("the renderer audits the byline's fit");
                // A line the list's edge cuts, or one drawn in the strip under
                // its room, is a picture of the list going on: it is read where
                // a screen shows it whole.
                let shown = !node.peek && (node.clip.height - node.rect.height).abs() < 0.5;
                let label = compiled
                    .semantic(&UiKey::new("about/byline"))
                    .map(|semantic| semantic.label.clone())
                    .or_else(|| (!shown).then(|| spec.text.clone()));
                (spec.text.clone(), audit, label)
            });
        Some(HeroByline {
            painted,
            column,
            short,
        })
    };

    let mut rungs_seen = [0usize; 4];
    let mut omissions = 0usize;
    // One width of the sweep, every assertion it makes. What it returns —
    // the rung painted (`None`: no byline) and whether the hero is the short
    // one — is what [`sample_where_it_changes`] compares between neighbouring
    // widths. Every rung is measured from the first at every text size: no
    // width class starts the ladder further down (s-3).
    let mut at = |width: f32, height: f32| -> Option<(Option<usize>, bool)> {
        let hero = byline_at(width, height)?;
        let HeroByline {
            painted,
            column,
            short,
        } = hero;
        let context = format!("{width}x{height} at {scale}×");
        let want = ladder.iter().position(|form| width_of(form) <= column);
        let painted_rung = if let Some((text, audit, label)) = painted {
            let rung = ladder
                .iter()
                .position(|form| *form == text)
                .unwrap_or_else(|| panic!("{context}: {text:?} is not a byline form"));
            assert!(
                audit.contains(" overflow=false "),
                "{context}: the byline paints truncated: {audit}"
            );
            assert!(
                width_of(&text) <= column,
                "{context}: {text:?} is wider than its {column}pt column"
            );
            assert_eq!(
                Some(rung),
                want,
                "{context}: the byline painted rung {rung} ({text:?}), but the longest form its {column}pt column fits is rung {want:?}"
            );
            assert_eq!(
                label.as_deref(),
                Some(text.as_str()),
                "{context}: the byline reads out the line it paints"
            );
            rungs_seen[rung] += 1;
            Some(rung)
        } else {
            assert_eq!(
                want, None,
                "{context}: the hero authored no byline, yet rung {want:?} fits its {column}pt column"
            );
            omissions += 1;
            None
        };
        Some((painted_rung, short))
    };
    // From 120pt: the window floor is 164 logical points wide
    // (`App::whole_cell_min_size`), so the narrow band is shipping geometry.
    // 336pt tall is a short landscape compact host at 480-760pt.
    for height in [558.0_f32, 336.0, 400.0, 820.0] {
        sample_where_it_changes(120.0, 1_320.0, coarse, resolution, |width| {
            at(width, height)
        });
    }
    assert!(
        rungs_seen[0] > 0,
        "the sweep paints the whole byline somewhere at {scale}×: {rungs_seen:?}"
    );
    assert!(
        rungs_seen[3] > 0,
        "the sweep reaches the author's short form at {scale}×: {rungs_seen:?}"
    );
    assert!(
        omissions > 0,
        "the sweep reaches a column no rung fits at {scale}×, so the omission arm above is not vacuous"
    );

    if scale == 1.0 {
        let hero = byline_at(286.5, 558.0).expect("the phone About hero paints its byline");
        let (text, audit, label) = hero.painted.expect("the phone hero keeps a byline");
        assert_eq!(
            text, author_company,
            "the phone column keeps author and company"
        );
        assert_eq!(label.as_deref(), Some(author_company));
        assert!(audit.contains(" overflow=false "), "{audit}");
        assert!(
            rungs_seen[1] > 0,
            "the 1× sweep crosses from the whole byline to author and company: {rungs_seen:?}"
        );
    }

    if scale == 2.0 {
        // A 240pt host at 2× gives the hero a 164.0pt column (asserted below). Whether
        // `Andrew Yates` fits is the UI face's: 164.6pt in the x86_64 Linux host's face
        // (the floor rung would elide), 156.884pt in macOS's (it fits). So the law is
        // read from the measurement, the longest rung that fits, and the arm this host
        // cannot exercise says so on stderr.
        let hero = byline_at(240.0, 558.0).expect("a 240pt host paints the full About hero");
        assert!(!hero.short);
        assert!(
            (hero.column - 164.0).abs() < 0.05,
            "the 240pt hero column: {}",
            hero.column
        );
        // Read the whole ladder down: the longest rung that fits is painted, and if
        // even the short form overflows, no byline at all (as the 150pt arm asserts).
        let name_width = width_of(author);
        let want = [author, author_short]
            .into_iter()
            .find(|rung| width_of(rung) <= hero.column);
        match (want, hero.painted.as_ref()) {
            (Some(rung), Some((text, audit, label))) => {
                let law = if rung == author {
                    "a column the full name fits paints it whole and never steps below it"
                } else {
                    "a column the full name overflows steps to the author's short form"
                };
                assert_eq!(text, rung, "{law} ({name_width}pt vs {}pt)", hero.column);
                assert_eq!(label.as_deref(), Some(rung), "{law}");
                assert!(audit.contains(" overflow=false "), "{audit}");
            }
            (None, painted) => assert!(
                painted.is_none(),
                "no rung fits this host's {}pt column ({author_short:?} needs {}pt), so the \
                 hero authors NO byline rather than an elided name",
                hero.column,
                width_of(author_short)
            ),
            (Some(rung), None) => panic!(
                "{rung:?} fits the {}pt column, so the hero must paint it",
                hero.column
            ),
        }
        if want == Some(author) {
            // Keyed off the chosen rung, not a second copy of the condition. Written
            // to the stderr handle, not `eprintln!`, so libtest does not capture it
            // from a passing test.
            use std::io::Write as _;
            let line = format!(
                "native_about_byline_steps_down_to_the_longest_form_its_column_fits: the \
                 240pt / 2× step-down is NOT exercised at this width on this host: {author:?} measures {name_width}pt in this UI face against a {}pt \
                 column, so the full name fits. It measured 164.6pt on the x86_64 Linux \
                 host that extended this ladder (3091ede3b); the comment above this arm \
                 records both. The longest rung that fits is asserted instead, and the \
                 sweep above still reaches the short form at this scale, so the floor rung \
                 is exercised here — just not at 240pt.\n",
                hero.column
            );
            let _ = std::io::stderr().write_all(line.as_bytes());
        }

        // Below the last rung: a column too small for the short form authors no
        // byline rather than an elided name.
        let hero = byline_at(150.0, 558.0).expect("a 150pt host still paints the About hero");
        assert!(
            width_of(author_short) > hero.column,
            "no rung fits the 150pt host's {}pt column",
            hero.column
        );
        assert!(
            hero.painted.is_none(),
            "a column no rung fits paints no byline at all"
        );
        // Author, company and site are provenance rows, so `Copy Build Information`
        // still carries every fact the byline would have said.
        let provenance = crate::about::provenance_text();
        for fact in [
            crate::build_info::AUTHOR_ATTRIBUTION,
            crate::build_info::COMPANY,
            aterm_types::identity::SITE,
        ] {
            assert!(
                provenance.contains(fact),
                "the About provenance block still carries {fact:?}: {provenance}"
            );
        }
    }
}

#[test]
fn watcher_warning_is_global_separate_from_action_feedback_and_recovery_clears_it() {
    let (mut runtime, instance, view) = setup();
    let AppViewState::Settings(state) = runtime.view_state_mut(view).unwrap() else {
        panic!("Settings view state");
    };
    state.feedback = Some("Undo available".to_string());
    state.config_watch_status =
        Some("aterm.toml reload rejected: the file is not valid UTF-8.".to_string());

    let cx = view_cx_at(568.0, 420.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/config-watch-status/detail"))
            .is_some_and(|node| node.label.contains("not valid UTF-8")),
        "the watcher failure is visible on the current Settings route"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/status"))
            .map(|node| node.label.as_str()),
        Some("Undo available"),
        "persistent watcher status must not overwrite ordinary feedback"
    );

    let AppViewState::Settings(state) = runtime.view_state_mut(view).unwrap() else {
        panic!("Settings view state");
    };
    state.config_watch_status = None;
    let recovered = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        recovered
            .semantic(&UiKey::new("settings/config-watch-status"))
            .is_none(),
        "recovery clears only the watcher banner"
    );
    assert_eq!(
        recovered
            .semantic(&UiKey::new("settings/status"))
            .map(|node| node.label.as_str()),
        Some("Undo available")
    );
}

/// A wide global search whose top match drives the renderer preview ("kitty") leads
/// with its native rows; the Manual card follows them.
#[test]
fn wide_search_page_one_lists_native_rows_beside_the_manual_result() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/search"),
                value: Some(SemanticInput::Text("kitty".to_string())),
            }),
        )
        .unwrap();
    let cx = view_cx_at(1_275.0, 828.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let mut manual = false;
    each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
        manual |= compiled
            .semantic(&UiKey::new("settings/search/manual-result"))
            .is_some();
    });
    assert!(
        manual,
        "the Manual editor result stays a first-class search result"
    );
    let rows: Vec<&str> = compiled
        .semantics
        .iter()
        .map(|node| node.key.as_str())
        .filter(|key| key.starts_with("settings/row/"))
        .collect();
    assert!(
        !rows.is_empty(),
        "page 1 of a wide search must list native result rows, not only the Manual card"
    );
    assert!(
        rows.iter().any(|key| key.ends_with("cursor_trail_style")),
        "the ranked native match paints on page 1: {rows:?}"
    );
    // What the summary counts is search_count_states_what_its_result_lists_hold's.
    assert!(
        compiled
            .semantic(&UiKey::new("settings/results-range"))
            .is_some(),
        "search results always disclose what they found"
    );
}

/// Every visual line the painter is handed for one wrapped copy block, in
/// paint order.
fn painted_copy_lines(compiled: &crate::native_ui::CompiledUi, key: &str) -> Vec<String> {
    let prefix = format!("{key}/line-");
    compiled
        .paint
        .iter()
        .filter(|node| node.key.as_str().starts_with(prefix.as_str()))
        .map(|node| match &node.content {
            UiContent::Text(spec) => spec.text.clone(),
            other => panic!("{key} paints something other than text: {other:?}"),
        })
        .collect()
}

fn settings_route_at(state: &SettingsViewState, cx: &ViewCx<'_>) -> crate::native_ui::CompiledUi {
    settings_tree(
        state,
        &UpdateState::from_status(1, "0.1.0", None, false).projection(),
        &PackagesState::unobserved().projection(),
        &MessagesState::empty(),
        &HarnessState::unobserved().projection(),
        cx,
    )
    .compile(cx.viewport)
    .expect("Settings compiles")
}

/// THE SHIPPED DEFAULT WINDOW CAN READ ITS OWN EXPLANATORY COPY.
///
/// 80×24 is a 744×420 app viewport (`app_config.rs`), and long settings
/// strings were authored as ONE fixed line there, so the painter
/// ellipsized them — 280.6 and 108.7 points of text discarded with no
/// tooltip, wrap, scroll or selection to get any of it back (2026-09
/// settings audit):
///
/// * `settings/top/wallpaper/description` — required 968.6 against 688.0
/// * `settings/wallpaper/hint` — the ONLY pointer to where the wallpaper
///   dim and text-tint controls live, required 796.7
///
/// Neither was ever a compact-layout property: [`page_insets`]
/// caps the content column at [`FORM_MEASURE`] in EVERY width class,
/// so they were unreadable at every window size. (Both are one short line
/// now; the wrap path stays, and this still proves nothing is elided.) The
/// renderer's own fit
/// audit is the judge — `overflow=true` is the painter reporting that it
/// elided — and the complete sentence has to survive on the semantic label
/// as well as on glass.
#[test]
fn long_settings_copy_wraps_instead_of_one_elided_line() {
    // 80×24, the shipped default, and a roomy Wide host.
    for (width, height) in [(744.0_f32, 420.0_f32), (1_464.0, 796.0)] {
        let mut state = SettingsViewState::new(&Config::default());
        state.navigate(SettingsRoute::Wallpaper);
        let cx = view_cx_at(width, height);
        let compiled = settings_route_at(&state, &cx);
        let context = format!("Wallpaper at {width}×{height}");
        assert_zero_top_paint(&compiled, &context);

        // The Wallpaper card's note took over the description's sentence;
        // dim and text tint are rows of their own now, so the hint is gone.
        let key = "settings/wallpaper/note";
        let label = compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{context}: {key} is a semantic node"))
            .label
            .clone();
        let painted = painted_copy_lines(&compiled, key);
        assert!(
            painted.iter().all(|line| !line.contains('…')),
            "{context}: {key} paints no ellipsis: {painted:?}"
        );
        assert_eq!(
            painted
                .join(" ")
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" "),
            label.split_whitespace().collect::<Vec<_>>().join(" "),
            "{context}: {key} paints every word it claims"
        );
    }
}

// -----------------------------------------------------------------------
// Settings ▸ Messages
// -----------------------------------------------------------------------

/// Forty entries as the host would publish them (`App::messages_state`):
/// a folded crash record with its absolute path and an `Open log`, a
/// held staged update whose `Apply now` is spent, a live toolchain meter
/// on the band, then thirty-seven folded config warnings — newest first.
fn sample_messages() -> MessagesState {
    use crate::messages_host::MessageActionView;
    const BASE: u64 = 1_758_470_000_000;
    let at = |id: u64| BASE - (41 - id) * 60_000;
    let entry = |id: u64,
                 tag: &str,
                 severity: &'static str,
                 glyph: char,
                 title: &str,
                 detail: &[&str],
                 state: &'static str,
                 actions: Vec<MessageActionView>| MessageView {
        id,
        at_unix_ms: at(id),
        began_unix_ms: at(id),
        tag: tag.to_string(),
        severity,
        glyph,
        title: title.to_string(),
        detail: detail.iter().map(|line| (*line).to_string()).collect(),
        state,
        on_glass: None,
        repeats: 1,
        retired_unix_ms: (!matches!(state, "live" | "held")).then_some(at(id) + 30_000),
        superseded_by: None,
        answer: None,
        actions,
        sentences: 1,
    };
    let action = |index: u8, label: &'static str, still_actionable: bool| MessageActionView {
        index,
        label,
        still_actionable,
        declines: false,
    };
    let mut entries = vec![
        entry(
            40,
            "crash",
            "error",
            '\u{2715}',
            "aterm closed unexpectedly last time",
            &[
                "crash log at /Users//w/Library/Logs/aterm/crash-signal-11-1.log.seen",
                "signal 11 (SIGSEGV) in the render thread while compositing the frame",
            ],
            "folded",
            vec![action(0, "Open log", true)],
        ),
        entry(
            39,
            "update",
            "success",
            '\u{2713}',
            "aterm 0.91.0 is ready",
            &["build 1234 \u{2014} verified and ready to apply"],
            "held",
            vec![
                action(0, "Install now", false),
                action(1, "Software Update", true),
            ],
        ),
        entry(
            38,
            "toolchain",
            "info",
            '\u{21e3}',
            "Installing ALab toolchain",
            &["trust \u{00b7} extracting"],
            "live",
            vec![action(0, "Packages", true)],
        ),
    ];
    entries[2].on_glass = Some(0);
    for id in (1..=37).rev() {
        entries.push(entry(
            id,
            "config",
            "warn",
            '\u{26a0}',
            &format!("config warning {id}"),
            &["aterm.toml: unknown key `foo` at line 12"],
            "folded",
            Vec::new(),
        ));
    }
    MessagesState {
        revision: 7,
        now_unix_ms: BASE,
        entries,
        told_on: Vec::new(),
        tags: vec![
            ("crash".to_string(), 1),
            ("config".to_string(), 37),
            ("update".to_string(), 1),
            ("toolchain".to_string(), 1),
        ],
        log_folder: Some("/Users//w/Library/Logs/aterm".to_string()),
        saved: true,
        utc_offset_s: 0,
    }
}

/// [`sample_messages`] spread over the reader's calendar, newest first, the reader at
/// UTC on Sunday 2025-09-21 15:53:20: #40–#38 today, #37–#31 yesterday, #30–#21 on
/// Thursday, #20–#11 on Friday 12 September, #10–#1 on 17 August 2024, each group a
/// minute apart from 3:10 PM down.
fn multi_day_messages() -> MessagesState {
    const DAY: u64 = 86_400_000;
    let mut state = sample_messages();
    let now = state.now_unix_ms;
    // 15:10:00 UTC on the reader's day.
    let afternoon = now - (43 * 60 + 20) * 1000;
    for entry in &mut state.entries {
        let (days, first) = match entry.id {
            38..=40 => continue,
            31..=37 => (1, 37),
            21..=30 => (3, 30),
            11..=20 => (9, 20),
            _ => (400, 10),
        };
        entry.at_unix_ms = afternoon - days * DAY - (first - entry.id) * 60_000;
        entry.began_unix_ms = entry.at_unix_ms;
        entry.retired_unix_ms = entry.retired_unix_ms.map(|_| entry.at_unix_ms + 30_000);
    }
    state
}

/// The day headers a compiled page shows, top to bottom.
fn message_days(compiled: &crate::native_ui::CompiledUi) -> Vec<String> {
    compiled
        .semantics
        .iter()
        .filter(|node| {
            node.key.as_str().starts_with("settings/messages/day/")
                && !node.key.as_str().ends_with("/group")
        })
        .map(|node| node.label.clone())
        .collect()
}

/// A Settings controller holding [`sample_messages`], its view on the
/// Messages route.
fn setup_with_messages() -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(sample_messages(), 7));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Messages),
                value: None,
            }),
        )
        .unwrap();
    (runtime, instance, view)
}

