/// The ids of the rows a compiled page shows, in page order.
fn message_rows(compiled: &crate::native_ui::CompiledUi) -> Vec<u64> {
    compiled
        .semantics
        .iter()
        .filter_map(|node| {
            node.key
                .as_str()
                .strip_prefix("settings/messages/row/")?
                .strip_suffix("/title")?
                .parse::<u64>()
                .ok()
        })
        .collect()
}

fn messages_view_state(
    runtime: &NativeRuntime,
    view: crate::native_app::ViewId,
) -> &SettingsViewState {
    match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => state,
        _ => panic!("a Settings view"),
    }
}

/// Scroll the log end to end: compile the page at `cx`, hand each view to `visit`
/// with its index, and scroll `step` entries on (the `ScrollLines` the wheel, arrow
/// keys and a screen reader send) until the list stops. Returns the views visited.
fn scroll_messages_through(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    step: i32,
    mut visit: impl FnMut(&crate::native_ui::CompiledUi, usize),
) -> usize {
    for k in 0..600 {
        let compiled = compile_settings_view(runtime, instance, view, cx);
        visit(&compiled, k);
        let before = messages_view_state(runtime, view)
            .messages_drawn
            .get()
            .expect("the render drew a stop");
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(step))
            .unwrap();
        if messages_view_state(runtime, view).page_scroll == before {
            return k + 1;
        }
    }
    panic!("the list never reached its end");
}

/// Day headers: a log spanning more than one of the reader's local days is sectioned
/// newest first (`Today`, `Yesterday`, the weekday within the week, then the date,
/// with the year only off this year). A header is a heading for a screen reader,
/// never a control (no action, not focusable, skipped by the arrow keys); it stands
/// at the lead column's time x, every title keeps one origin, and a row under a past
/// day says its local time. The top entry always carries its day's header. A filter
/// hides a day it admits nothing from; a one-day log carries none.
#[test]
fn the_log_is_sectioned_by_the_readers_local_day() {
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(multi_day_messages(), 8));
    let cx = view_cx_at(1_200.0, 820.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let days = message_days(&compiled);
    assert_eq!(days.first().map(String::as_str), Some("Today"), "{days:?}");
    assert!(days.len() >= 2, "a multi-day view shows two days: {days:?}");
    let rows = message_rows(&compiled);
    let paint = |key: String| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .unwrap_or_else(|| panic!("{key} paints"))
            .clone()
    };
    let origins: Vec<f32> = rows
        .iter()
        .map(|id| paint(format!("settings/messages/row/{id}/label")).rect.x)
        .collect();
    assert!(
        origins.iter().all(|x| (x - origins[0]).abs() < 0.01),
        "one title origin under the headers: {origins:?}"
    );
    let when_x = paint(format!("settings/messages/row/{}/when", rows[0]))
        .rect
        .x;
    for node in compiled.semantics.iter().filter(|node| {
        node.key.as_str().starts_with("settings/messages/day/")
            && !node.key.as_str().ends_with("/group")
    }) {
        assert_eq!(node.role, SemanticRole::Heading, "{}", node.label);
        assert!(node.action.is_none(), "a header is no control");
        assert!(
            !compiled.focus_order.contains(&node.key),
            "the keyboard never lands on a header"
        );
        assert!(
            (node.rect.x - when_x).abs() < 0.01,
            "the header stands over the times: {} vs {when_x}",
            node.rect.x
        );
    }
    let when = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == format!("settings/messages/row/{id}/when"))
            .map(|node| match &node.content {
                UiContent::Text(spec) => spec.text.clone(),
                other => panic!("{other:?}"),
            })
    };
    assert_eq!(when(&compiled, 40).as_deref(), Some("1 min ago"), "today");
    assert_eq!(when(&compiled, 37).as_deref(), Some("3:10 PM"), "yesterday");

    // Scrolled end to end: every day once, in order, each view's first
    // entry under its own day's header.
    let mut seen: Vec<String> = Vec::new();
    scroll_messages_through(&mut runtime, instance, view, &cx, 1, |compiled, k| {
        let days = message_days(compiled);
        let top_day = compiled
            .semantics
            .iter()
            .find(|node| node.key.as_str().starts_with("settings/messages/day/"))
            .unwrap_or_else(|| panic!("view {k} opens under a header"));
        let first_row = message_rows(compiled)[0];
        let row = compiled
            .semantic(&UiKey::new(format!(
                "settings/messages/row/{first_row}/title"
            )))
            .expect("the first row");
        assert!(top_day.rect.y < row.rect.y, "view {k}: the header leads");
        for day in days {
            if !seen.contains(&day) {
                seen.push(day);
            }
        }
    });
    assert_eq!(
        seen.len(),
        5,
        "each of the fixture's five days is headed once: {seen:?}"
    );

    // The arrow keys step from today's last entry to yesterday's first,
    // past the header between them.
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(multi_day_messages(), 8));
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.common.last_focus = Some(UiKey::new("settings/messages/row/38/title"));
    }
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view)
            .common
            .last_focus
            .as_ref()
            .map(UiKey::as_str),
        Some("settings/messages/row/37/title")
    );

    // A filter hides a day it admits nothing from: the config warnings
    // start yesterday.
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        message_days(&compiled).first().map(String::as_str),
        Some("Yesterday")
    );

    // A log of one day: no header, and the rows keep their relative words.
    let (runtime, instance, view) = setup_with_messages();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(message_days(&compiled).is_empty());
    assert_eq!(when(&compiled, 40).as_deref(), Some("1 min ago"));
}

/// One past day is still headed (not a raw date in the time column), and the title
/// column holds its x as the filter changes. Negative control: a list of only today
/// carries no header (the test above).
#[test]
fn one_past_day_is_headed_and_the_titles_hold_their_x_across_filters() {
    const DAY: u64 = 86_400_000;
    let cx = view_cx_at(1_200.0, 820.0);
    // Every entry on one past local day (Thursday, three days back), a minute apart.
    let mut past = sample_messages();
    let thursday = past.now_unix_ms - 3 * DAY;
    for entry in &mut past.entries {
        entry.at_unix_ms = thursday - (40 - entry.id) * 60_000;
        entry.began_unix_ms = entry.at_unix_ms;
        entry.retired_unix_ms = entry.retired_unix_ms.map(|_| entry.at_unix_ms + 30_000);
    }
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(past, 8));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let days = message_days(&compiled);
    assert_eq!(
        days.len(),
        1,
        "one past day carries its one header: {days:?}"
    );
    let rows = message_rows(&compiled);
    let when_of = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == format!("settings/messages/row/{id}/when"))
            .map(|node| match &node.content {
                UiContent::Text(spec) => spec.text.clone(),
                other => panic!("{other:?}"),
            })
            .expect("a time")
    };
    let first = when_of(&compiled, rows[0]);
    assert!(
        !first.contains('-') && (first.ends_with("AM") || first.ends_with("PM")),
        "a clock under its day, never a date: {first}"
    );

    // The titles' x across the filters.
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(multi_day_messages(), 8));
    let title_x = |runtime: &NativeRuntime| {
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        let rows = message_rows(&compiled);
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == format!("settings/messages/row/{}/label", rows[0]))
            .expect("a title")
            .rect
            .x
    };
    let all = title_x(&runtime);
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    let filtered = title_x(&runtime);
    assert!(
        (all - filtered).abs() < 0.01,
        "the titles hold their x: {all} vs {filtered}"
    );
}

/// A SCREEN READER SCROLLS THE LOG (ruling 264): with no pager, the log's
/// card is a `List` carrying accesskit's scroll actions, and a scroll on
/// it routes to the same `ScrollLines` the wheel sends — the list moves
/// by those entries, and the rows that come into view are disclosure
/// buttons named by their titles, as before.
#[cfg(a11y_tree)]
#[test]
fn a_screen_reader_scrolls_the_log_list() {
    use crate::native_accessibility::{
        PublishedNativeAccessibility, RoutedAccessibilityAction, project_native_accessibility,
        route_accessibility_action,
    };
    use aterm_a11y::model::{Action, Role, TreeId};
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let projection = project_native_accessibility(&compiled, None).unwrap();
    let list = projection
        .id_for_key(&UiKey::new("settings/messages/list"))
        .expect("the list is published");
    let node = projection
        .update()
        .nodes
        .iter()
        .find(|(id, _)| *id == list)
        .map(|(_, node)| node.clone())
        .expect("the list's node");
    assert_eq!(node.role(), Role::List);
    assert_eq!(node.label(), Some("Messages"));
    assert!(node.supports_action(Action::ScrollDown));
    assert!(node.supports_action(Action::ScrollUp));
    let (_, routes) = projection.into_update_and_routes();
    let published = PublishedNativeAccessibility::new(view, 1, routes);
    let routed = route_accessibility_action(
        &published,
        &aterm_a11y::model::ActionRequest {
            context: Some(aterm_a11y::model::ActionContext::new(view.get(), 1)),
            action: Action::ScrollDown,
            target_tree: TreeId::ROOT,
            target_node: list,
            data: None,
        },
    )
    .expect("a scroll on the list routes");
    let RoutedAccessibilityAction::Scroll { lines, .. } = routed else {
        panic!("{routed:?}");
    };
    let before = message_rows(&compiled);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(lines))
        .unwrap();
    let after = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    let step = usize::try_from(lines).unwrap();
    assert_eq!(
        after[0], before[step],
        "scrolled {lines} entries: {before:?} → {after:?}"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let last = compiled
        .semantic(&UiKey::new(format!(
            "settings/messages/row/{}/title",
            after[after.len() - 1]
        )))
        .expect("the row scrolled into view");
    assert_eq!(last.role, SemanticRole::Button);
    assert_eq!(last.state.and_then(|state| state.expanded), Some(false));
}

/// The page is the log newest first; the chips are the tags present, in the fixed
/// order with their counts; a chip narrows the rows and the status line counts what
/// it admits; All puts everything back.
#[test]
fn messages_page_lists_newest_first_and_filters_by_tag() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/page/messages"))
            .is_some(),
        "the /messages route owns its own page"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/nav/messages"))
            .is_some(),
        "the rail exposes the Messages destination"
    );
    let shown = message_rows(&compiled);
    assert!(shown.len() >= 4, "{shown:?}");
    assert_eq!(shown[0], 40, "newest first");
    assert!(shown.windows(2).all(|pair| pair[0] > pair[1]), "{shown:?}");
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("40 messages")
    );
    let chips = |compiled: &crate::native_ui::CompiledUi| {
        compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("settings/messages/filter/"))
            .map(|node| {
                (
                    node.label.clone(),
                    node.state.is_some_and(|state| state.selected),
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        chips(&compiled),
        [
            ("All \u{00b7} 40".to_string(), true),
            ("Problems \u{00b7} 38".to_string(), false),
            ("All tags".to_string(), true),
            ("Crashes \u{00b7} 1".to_string(), false),
            ("Config \u{00b7} 37".to_string(), false),
            ("Updates \u{00b7} 1".to_string(), false),
            ("ALab tools \u{00b7} 1".to_string(), false),
        ],
        "the severity segments, then the tags' plain chip names (rulings 66 and \
         262); the action keys keep the tags"
    );
    // One scrolling list, no pager: the reducer's bound is where the list stops, its
    // view ending on the oldest entry.
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/pagination"))
            .is_none()
            && compiled
                .semantic(&UiKey::new("settings/messages/range"))
                .is_none(),
        "no pager"
    );
    assert!(
        shown.len() >= 14,
        "at least fourteen one-line rows at 1200\u{00d7}820: {}",
        shown.len()
    );
    let limit = messages_view_state(&runtime, view)
        .result_page_limit
        .get()
        .expect("the render bounds the reducer");
    assert_eq!(
        limit,
        40 - shown.len(),
        "the list scrolls until its oldest entry is its last row"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.page_scroll = limit;
    }
    let end = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    assert_eq!(end.last(), Some(&1), "the oldest entry closes the list");
    assert_eq!(end.len(), shown.len(), "a full view at the end: {end:?}");
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(3))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        limit,
        "never scrolled past its end"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.page_scroll = 0;
    }

    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let shown = message_rows(&compiled);
    assert!(shown.iter().all(|id| *id <= 37), "config only: {shown:?}");
    assert_eq!(shown[0], 37);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("37 of 40")
    );
    assert!(
        chips(&compiled)
            .iter()
            .any(|(label, selected)| label == "Config \u{00b7} 37" && *selected)
    );

    // The severity combines with the tag: config's warnings, the crash (another tag)
    // out.
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let shown = message_rows(&compiled);
    assert_eq!(shown[0], 37, "config's newest warning");
    assert!(!shown.contains(&40), "the crash is another tag: {shown:?}");
    assert!(
        chips(&compiled)
            .iter()
            .any(|(label, selected)| label == "Config \u{00b7} 37" && *selected),
        "the tag stays down"
    );
    // Every tag, the severity kept: the warnings set.
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tags-all",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let shown = message_rows(&compiled);
    assert_eq!(shown[0], 40, "the crash leads the warnings set");
    assert!(
        !shown.contains(&39) && !shown.contains(&38),
        "success and info are out: {shown:?}"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("38 of 40")
    );

    messages_action(&mut runtime, instance, view, "settings/messages/filter/all");
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(message_rows(&compiled)[0], 40);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("40 messages")
    );

    // An empty log: the invitation, no rows, no pager.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(MessagesState::empty(), 1));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Messages),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(message_rows(&compiled).is_empty());
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/empty"))
            .map(|node| node.label.as_str()),
        Some(MESSAGES_EMPTY)
    );
    // An empty log hides the filters and the count, and has nothing to copy.
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .is_none()
    );
    assert!(
        !compiled
            .semantics
            .iter()
            .any(|node| node.key.as_str().starts_with("settings/messages/filter/")),
        "no filters over nothing"
    );
    assert!(
        compiled
            .semantic(&UiKey::new(MESSAGES_COPY_ALL))
            .and_then(|node| node.state)
            .is_some_and(|state| !state.enabled),
        "Copy All has nothing to copy"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/range"))
            .is_none()
    );
}

/// The log's lead column: every row's title begins at the same x (the severity mark,
/// time and tag name take one fixed width, measured once per page), the tag reads as
/// its chip's words in the page's face, and a screen reader hears severity, chip and
/// time in words, never the wire's.
#[test]
fn the_log_rows_share_one_lead_column_and_speak_plain_words() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let rows = message_rows(&compiled);
    assert!(rows.len() >= 14, "{rows:?}");
    let paint = |key: String| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .unwrap_or_else(|| panic!("{key} paints"))
            .clone()
    };
    let origins: Vec<f32> = rows
        .iter()
        .map(|id| paint(format!("settings/messages/row/{id}/label")).rect.x)
        .collect();
    assert!(
        origins.iter().all(|x| (x - origins[0]).abs() < 0.01),
        "one title origin: {origins:?}"
    );
    // The tag as its chip's words, in the body face (never monospace).
    let tag = paint(format!("settings/messages/row/{}/tag", rows[0]));
    match &tag.content {
        UiContent::Text(spec) => {
            assert_eq!(spec.text, "Crashes");
            assert_ne!(spec.style, StyleRef::Code);
        }
        other => panic!("{other:?}"),
    }
    // The severity mark is the band's drawn icon, decorative.
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/messages/row/{}/severity",
                rows[0]
            )))
            .is_none(),
        "the mark is paint-only"
    );
    let tray = compiled.tray(aterm_render::Theme::default(), 13.0);
    assert!(
        tray.prims.iter().any(|prim| matches!(
            prim,
            crate::widget::DrawPrim::BandIcon {
                icon: aterm_render::BandIcon::Error,
                ..
            }
        )),
        "the crash row draws the band's cross"
    );
    assert!(
        tray.prims.iter().any(|prim| matches!(
            prim,
            crate::widget::DrawPrim::BandIcon {
                icon: aterm_render::BandIcon::Download,
                ..
            }
        )),
        "the toolchain row draws its own glyph's icon, as the band does (ruling 263)"
    );
    // The description: plain words.
    let title = compiled
        .semantic(&UiKey::new(format!(
            "settings/messages/row/{}/title",
            rows[0]
        )))
        .expect("the title control");
    assert_eq!(title.state.and_then(|state| state.expanded), Some(false));
    let described = compiled
        .paint
        .iter()
        .find_map(|node| match &node.content {
            UiContent::Button(control)
                if node.key.as_str() == format!("settings/messages/row/{}/title", rows[0]) =>
            {
                control.spec.description.clone()
            }
            _ => None,
        })
        .expect("a description");
    assert!(
        described.starts_with("Error, Crashes, ") && !described.contains('\u{00b7}'),
        "{described}"
    );
    // The arrow keys move between rows; a step past the view's last row scrolls the
    // list by one row.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/messages/row/{}/title",
            rows[0]
        )));
    }
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view)
            .common
            .last_focus
            .as_ref()
            .map(UiKey::as_str),
        Some(format!("settings/messages/row/{}/title", rows[1]).as_str())
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/messages/row/{}/title",
            rows[rows.len() - 1]
        )));
    }
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        1,
        "the list follows the focus by one row"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        message_rows(&compiled).last(),
        Some(&(rows[rows.len() - 1] - 1)),
        "the newly focused row is the view's last"
    );
}

/// A title press expands its row in place (the meta line, detail lines wrapped to the
/// page, every authored button with its live enablement, Copy), and a second press
/// folds it back.
#[test]
fn selecting_a_row_expands_its_detail_lines_and_actions() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let before = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/title",
    );
    assert_eq!(
        messages_view_state(&runtime, view).messages_selected,
        Some(39)
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let label = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .map(|node| node.label.clone())
            .unwrap_or_else(|| panic!("{key} renders"))
    };
    // A disclosure: expanded, never `selected`.
    let title = compiled
        .semantic(&UiKey::new("settings/messages/row/39/title"))
        .and_then(|node| node.state)
        .expect("the title is the disclosure control");
    assert_eq!(title.expanded, Some(true));
    assert!(!title.selected);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/40/title"))
            .and_then(|node| node.state)
            .and_then(|state| state.expanded),
        Some(false),
        "a closed entry says so"
    );
    // The meta line: the reader's local time and the state (the lead column says the
    // tag and severity).
    let meta = label("settings/messages/row/39/meta/0");
    assert!(
        meta.ends_with("3:51:20 PM \u{00b7} waiting to show") && !meta.contains("UTC"),
        "{meta}"
    );
    // The page's bounds do not move: the same entries, the open one grown.
    let after = message_rows(&compiled);
    assert_eq!(after.first(), before.first(), "{before:?} → {after:?}");
    assert!(
        after.iter().all(|id| before.contains(id)),
        "{before:?} → {after:?}"
    );
    assert_eq!(
        label("settings/messages/row/39/detail/0"),
        "build 1234 \u{2014} verified and ready to apply"
    );
    let enabled = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key} renders"))
            .state
            .is_none_or(|state| state.enabled)
    };
    assert!(
        !enabled("settings/messages/row/39/action/0"),
        "a build no longer staged cannot be applied from here"
    );
    assert!(enabled("settings/messages/row/39/action/1"));
    assert!(enabled("settings/messages/row/39/copy"));
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/40/meta/0"))
            .is_none(),
        "one row expands at a time"
    );
    // The expanded row is charged at its height: the rows below still fit, and the
    // page pages one row later.
    for node in &compiled.semantics {
        if node.key.as_str().starts_with("settings/messages/row/") {
            assert!(
                node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                "{} is clipped: {:?}",
                node.key.as_str(),
                node.rect
            );
        }
    }
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/title",
    );
    assert_eq!(messages_view_state(&runtime, view).messages_selected, None);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/39/meta/0"))
            .is_none(),
        "folded back"
    );
}

/// The Primary is the first intent a press can still perform: #39's `Install now`
/// names a build no longer staged, so it stays, disabled, and the accent and a bare
/// Return (`default_action`: the first enabled Primary) go to the first later intent
/// that can act and is not a decline. Controls: #40's `Open log`, pressable and
/// first, leads; a card with nothing pressable has no Primary; Copy is never one.
#[test]
fn the_primary_is_the_first_intent_a_press_can_still_perform() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let button = |compiled: &crate::native_ui::CompiledUi, key: &str| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .and_then(|node| match &node.content {
                UiContent::Button(control) => Some((control.style, control.state.enabled)),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{key} paints a button"))
    };
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/title",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        button(&compiled, "settings/messages/row/39/action/0"),
        (StyleRef::Secondary, false),
        "a dead Install now is not drawn as the thing to do"
    );
    assert_eq!(
        button(&compiled, "settings/messages/row/39/action/1"),
        (StyleRef::Primary, true)
    );
    assert_eq!(
        button(&compiled, "settings/messages/row/39/copy"),
        (StyleRef::Secondary, true)
    );
    assert_eq!(
        compiled
            .default_action
            .as_ref()
            .map(|(key, _)| key.as_str()),
        Some("settings/messages/row/39/action/1"),
        "Return presses the intent that can act"
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/title",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        button(&compiled, "settings/messages/row/40/action/0"),
        (StyleRef::Primary, true),
        "the control: a first intent that can act leads"
    );
    let state = sample_messages();
    let dead = |index: u8, label: &'static str| crate::messages_host::MessageActionView {
        index,
        label,
        still_actionable: false,
        declines: false,
    };
    let entry = MessageView {
        actions: vec![dead(0, "Install now"), dead(1, "Open log")],
        ..state.entries[1].clone()
    };
    let body = MessagesBody::of(&entry, 560.0, 0, state.now_unix_ms);
    assert_eq!(body.footer.iter().flatten().count(), 3, "both, and Copy");
    assert!(
        body.footer.iter().flatten().all(|b| !b.primary),
        "nothing pressable leads"
    );
}

/// A decline is never promoted to the Primary: on an upgrade card whose `Upgrade now`
/// went dead, `Skip version` does not take the accent or a bare Return
/// (`default_action`); the band never paints a decline in the accent
/// (`Intent::is_consequential`). With no later non-decline intent nothing leads and
/// Return stays inert. Controls: a dead `Install now` still hands it to `Open Software
/// Update`, and a first `Not today` a press can perform keeps it.
#[test]
fn a_decline_is_never_promoted_to_the_primary() {
    use crate::messages_host::MessageActionView;
    let act = |index: u8, label: &'static str, still_actionable: bool, declines: bool| {
        MessageActionView {
            index,
            label,
            still_actionable,
            declines,
        }
    };
    let cx = view_cx();
    let card = |actions: Vec<MessageActionView>| {
        let (mut runtime, instance, view) = setup();
        let mut state = sample_messages();
        assert_eq!(state.entries[1].id, 39);
        state.entries[1].actions = actions;
        assert!(runtime.replace_settings_messages(state, 7));
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Messages),
                    value: None,
                }),
            )
            .unwrap();
        messages_action(
            &mut runtime,
            instance,
            view,
            "settings/messages/row/39/title",
        );
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let styles = (0..2)
            .map(|k| {
                let key = format!("settings/messages/row/39/action/{k}");
                compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == key)
                    .and_then(|node| match &node.content {
                        UiContent::Button(control) => Some((control.style, control.state.enabled)),
                        _ => None,
                    })
                    .unwrap_or_else(|| panic!("{key} paints a button"))
            })
            .collect::<Vec<_>>();
        let default = compiled
            .default_action
            .as_ref()
            .map(|(key, _)| key.as_str().to_string());
        (styles, default)
    };
    for decline in ["Skip version", "Not today"] {
        assert_eq!(
            card(vec![
                act(0, "Upgrade now", false, false),
                act(1, decline, true, true),
            ]),
            (
                vec![(StyleRef::Secondary, false), (StyleRef::Secondary, true)],
                None
            ),
            "a dead Upgrade now does not hand {decline} the accent, nor Return"
        );
    }
    assert_eq!(
        card(vec![
            act(0, "Install now", false, false),
            act(1, "Software Update", true, false),
        ]),
        (
            vec![(StyleRef::Secondary, false), (StyleRef::Primary, true)],
            Some("settings/messages/row/39/action/1".to_string())
        ),
        "the control: a navigation still leads past a dead first intent"
    );
    assert_eq!(
        card(vec![
            act(0, "Not today", true, true),
            act(1, "Skip version", true, true),
        ]),
        (
            vec![(StyleRef::Primary, true), (StyleRef::Secondary, true)],
            Some("settings/messages/row/39/action/0".to_string())
        ),
        "the control: a first decline a press can perform keeps its place"
    );
}

/// The footer's Primary is a position in the offered intents, not an `ActionIndex`:
/// `primary_index` answers a position in `entry.actions`, each button's key keeps the
/// intent's own index, and a passed intent is not offered, so offered indices can
/// start past 0. Here the first offered intent (`action/1`) leads, and past a dead
/// `action/1` the pressable `action/2` does.
#[test]
fn the_footer_primary_is_a_position_in_the_offered_intents() {
    use crate::messages_host::MessageActionView;
    let act = |index: u8, label: &'static str, still_actionable: bool| MessageActionView {
        index,
        label,
        still_actionable,
        declines: false,
    };
    let state = sample_messages();
    let footer = |actions: Vec<MessageActionView>| {
        let entry = MessageView {
            actions,
            ..state.entries[1].clone()
        };
        MessagesBody::of(&entry, 560.0, 0, state.now_unix_ms)
            .footer
            .into_iter()
            .flatten()
            .map(|button| (button.key, button.primary, button.enabled))
            .collect::<Vec<_>>()
    };
    let row = format!("settings/messages/row/{}", state.entries[1].id);
    assert_eq!(
        footer(vec![act(1, "Show tab 2", true), act(2, "Settings", true)]),
        [
            (format!("{row}/action/1"), true, true),
            (format!("{row}/action/2"), false, true),
            (format!("{row}/copy"), false, true),
        ],
        "the first offered intent leads, whatever its index"
    );
    assert_eq!(
        footer(vec![
            act(1, "Install now", false),
            act(2, "Software Update", true),
        ]),
        [
            (format!("{row}/action/1"), false, false),
            (format!("{row}/action/2"), true, true),
            (format!("{row}/copy"), false, true),
        ],
        "past a dead first, the pressable one leads, never the dead one"
    );
}

/// An entry's leading `sentences` lines are the sentence (a next step for a person,
/// not monospace under Technical details); the move and the shell spelling stay
/// technical. Control: at one sentence line the remedy is technical.
#[test]
fn an_upgrade_records_why_and_next_step_are_its_sentence() {
    let state = sample_messages();
    let remedy = "it asks again on its own at 12:55 AM; Upgrade now asks it at its next pause; \
                  Skip This Version in the tab's menu keeps it on 2.1.280";
    let entry = MessageView {
        detail: vec![
            "behind for 7 h: it has not agreed to the move yet, so the upgrade rests, then \
             asks again"
                .to_string(),
            remedy.to_string(),
            "in tab 3 \u{00b7} Claude Code 2.1.280 \u{2192} 2.1.283".to_string(),
            "the same in any shell: `aterm harness upgrade s-d35e --now` or `--skip`".to_string(),
        ],
        sentences: 2,
        ..state.entries[0].clone()
    };
    let body = MessagesBody::of(&entry, 560.0, 0, state.now_unix_ms);
    let said = body.sentence.join(" ");
    assert!(said.contains("Upgrade now asks it"), "{:?}", body.sentence);
    assert!(said.contains("keeps it on 2.1.280"), "{:?}", body.sentence);
    assert!(
        body.technical.iter().all(|l| !l.contains("Upgrade now")),
        "{:?}",
        body.technical
    );
    assert!(body.technical.iter().any(|l| l.contains("in tab 3")));
    let one = MessagesBody::of(
        &MessageView {
            sentences: 1,
            ..entry
        },
        560.0,
        0,
        state.now_unix_ms,
    );
    assert!(
        one.technical.iter().any(|l| l.contains("Upgrade now")),
        "the control: {:?}",
        one.technical
    );
}

/// A diagram keeps its columns: a `toml` parse error, worded by the config lane from
/// the real parser, paints every detail row in monospace and reaches the painter row
/// for row, the caret row verbatim so the caret sits under its column. On a measure
/// too narrow for a row the row is cut, never reflowed: its pieces join back byte for
/// byte and none is wider than the box. A prose entry keeps the body face.
#[test]
fn a_diagram_entry_paints_its_rows_in_the_monospace_face_and_cuts_them() {
    let error = "x = [bad\n"
        .parse::<aterm_toml::edit::DocumentMut>()
        .expect_err("a malformed document")
        .to_string();
    let msg = crate::message_reporters::config_lane_error(&format!(
        "Config observation was not valid TOML: {error}"
    ));
    let caret = error
        .lines()
        .find(|row| row.contains('^'))
        .expect("the parser's caret row")
        .trim_end()
        .to_string();
    assert!(caret.starts_with(char::is_whitespace), "{caret:?}");
    let mut state = sample_messages();
    state.entries.insert(
        0,
        MessageView {
            id: 41,
            at_unix_ms: state.now_unix_ms,
            began_unix_ms: state.now_unix_ms,
            tag: "config".to_string(),
            severity: "warn",
            glyph: '\u{26a0}',
            title: msg.title.clone(),
            detail: msg.detail.clone(),
            state: "live",
            on_glass: None,
            repeats: 1,
            retired_unix_ms: None,
            superseded_by: None,
            answer: None,
            actions: Vec::new(),
            sentences: 1,
        },
    );
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(state, 8));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Messages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    // A diagram is technical whole: its rows are the entry's technical-details lines,
    // in the small monospace.
    let painted_code = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        let prefix = format!("settings/messages/row/{id}/code/");
        compiled
            .paint
            .iter()
            .filter(|node| node.key.as_str().starts_with(prefix.as_str()))
            .map(|node| match &node.content {
                UiContent::Text(spec) => (spec.text.clone(), spec.style),
                other => panic!("{prefix} paints something other than text: {other:?}"),
            })
            .collect::<Vec<_>>()
    };
    let painted_detail = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        let prefix = format!("settings/messages/row/{id}/detail/");
        compiled
            .paint
            .iter()
            .filter(|node| node.key.as_str().starts_with(prefix.as_str()))
            .map(|node| match &node.content {
                UiContent::Text(spec) => (spec.text.clone(), spec.style),
                other => panic!("{prefix} paints something other than text: {other:?}"),
            })
            .collect::<Vec<_>>()
    };
    select_message(&mut runtime, instance, view, 41);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let rows = painted_code(&compiled, 41);
    assert_eq!(
        rows.iter()
            .map(|(text, _)| text.clone())
            .collect::<Vec<_>>(),
        msg.detail,
        "row for row, none reflowed or trimmed"
    );
    assert!(
        painted_detail(&compiled, 41).is_empty(),
        "no prose sentence"
    );
    assert!(rows.iter().any(|(text, _)| *text == caret), "{rows:?}");
    assert!(
        rows.iter().all(|(_, style)| *style == StyleRef::Code),
        "{rows:?}"
    );
    let overflow = compiled
        .paint_audit_lines()
        .into_iter()
        .filter(|line| line.contains("overflow=true"))
        .collect::<Vec<_>>();
    assert!(overflow.is_empty(), "{}", overflow.join("\n"));
    // Prose is not a diagram: the crash entry keeps the body face.
    select_message(&mut runtime, instance, view, 40);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let prose = painted_detail(&compiled, 40);
    assert!(!prose.is_empty());
    assert!(
        prose.iter().all(|(_, style)| *style == StyleRef::Primary),
        "{prose:?}"
    );
    // Too narrow for the row: cut, the pieces joining back to it.
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Code);
    let long = format!("{caret}{}", " here".repeat(40));
    let pieces = messages_cut_code(&long, 120.0);
    assert!(pieces.len() > 1, "{pieces:?}");
    assert_eq!(pieces.concat(), long);
    assert!(pieces[0].starts_with(char::is_whitespace), "{pieces:?}");
    for piece in &pieces {
        let width = crate::tray_raster::measure_text(piece, px, crate::widget::TextWeight::Regular);
        assert!(width <= 120.0 + 0.01, "{piece:?} is {width} wide");
    }
}

/// The deep link measures the list it lands in: a chip showing one entry is a list of
/// one, which never scrolls; a reveal that drops the chip lands by the whole log's
/// list, so an entry deep in it is on screen, open.
#[test]
fn the_deep_link_lands_by_the_filter_it_leaves() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/crash",
    );
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        messages_view_state(&runtime, view).result_page_limit.get(),
        Some(0),
        "a list of one never scrolls"
    );
    // Entries run newest first: id 5 is the thirty-sixth row.
    select_message(&mut runtime, instance, view, 5);
    let top = {
        let state = messages_view_state(&runtime, view);
        assert!(state.messages_filter.is_all(), "the chip is dropped");
        state.page_scroll
    };
    assert!(top > 0, "landed deep in the whole log, not at its top");
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        message_rows(&compiled).contains(&5),
        "entry 5 is on the screen: {:?}",
        message_rows(&compiled)
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/5/detail/0"))
            .is_some(),
        "expanded"
    );
}

/// The deep link (design §4.5): `settings/messages/select` expands the entry, drops a
/// chip that would hide it, and lands on it (the list stays if the entry is already
/// on screen, else scrolls it toward the top), on the wide page and on a compact one
/// whose header scrolls with the list. A link before any render is landed by that
/// render, and the list moves on from where it drew.
#[test]
fn the_deep_link_selects_and_lands_on_the_entry() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    select_message(&mut runtime, instance, view, 40);
    {
        let state = messages_view_state(&runtime, view);
        assert_eq!(state.messages_selected, Some(40));
        assert!(
            state.messages_filter.is_all(),
            "the config chip would have hidden the crash: dropped"
        );
        assert_eq!(
            state.page_scroll, 0,
            "the newest entry is on the first screen"
        );
    }
    select_message(&mut runtime, instance, view, 5);
    let (top, limit) = {
        let state = messages_view_state(&runtime, view);
        (state.page_scroll, state.result_page_limit.get())
    };
    assert!(top > 0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let rows = message_rows(&compiled);
    assert!(rows.contains(&5), "…and it is on the screen: {rows:?}");
    assert!(
        rows.first() == Some(&5) || rows.last() == Some(&1),
        "at the top of the list, or the list at its end: {rows:?} ({top} of {limit:?})"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/5/detail/0"))
            .is_some(),
        "expanded"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/range"))
            .is_none(),
        "no pager says where: the list is where it is"
    );
    // An id the ring no longer holds: selected, the list at its top.
    select_message(&mut runtime, instance, view, 999);
    let state = messages_view_state(&runtime, view);
    assert_eq!(state.messages_selected, Some(999));
    assert_eq!(state.page_scroll, 0);

    // Compact: the header scrolls with the list; the link lands the entry
    // on the screen, open.
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(320.0, 568.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    select_message(&mut runtime, instance, view, 5);
    assert!(
        messages_view_state(&runtime, view).page_scroll > 0,
        "entry 5 is deep in the log"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        message_rows(&compiled).contains(&5),
        "the view holding the entry: {:?}",
        message_rows(&compiled)
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/5/detail/0"))
            .is_some()
    );

    // Before any render: the render lands it, and the next scroll moves on from there.
    for (width, height) in [(1_200.0, 820.0), (320.0, 568.0)] {
        let (mut runtime, instance, view) = setup_with_messages();
        select_message(&mut runtime, instance, view, 5);
        assert!(
            messages_view_state(&runtime, view).messages_reveal,
            "no render has measured the page yet"
        );
        let cx = view_cx_at(width, height);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            message_rows(&compiled).contains(&5),
            "{width}: the first render lands it: {:?}",
            message_rows(&compiled)
        );
        let drawn = messages_view_state(&runtime, view)
            .messages_drawn
            .get()
            .expect("the render drew a stop");
        assert!(drawn > 0, "{width}");
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(-1))
            .unwrap();
        let state = messages_view_state(&runtime, view);
        assert!(!state.messages_reveal, "{width}: adopted");
        assert_eq!(
            state.page_scroll,
            drawn - 1,
            "{width}: one up from the drawn stop"
        );
    }
}

/// [`sample_messages`] with the usage-limit notice the review of the owner's
/// notices imaged (2026-10-20; id 41, four sentence lines, too tall to read
/// whole under a wider page's pinned heading and filters at 864×462) at
/// index `at` of the newest-first list, at the time of the entry it
/// displaces.
fn messages_with_tall_notice(at: usize) -> (MessagesState, MessageView) {
    let mut log = sample_messages();
    let mut notice = log.entries[0].clone();
    notice.at_unix_ms = log.entries[at].at_unix_ms;
    notice.began_unix_ms = log.entries[at].began_unix_ms;
    notice.id = 41;
    notice.tag = "harness".to_string();
    notice.severity = "warn";
    notice.glyph = '\u{26a0}';
    notice.title = "Claude usage limit reached in tab 1".to_string();
    notice.detail = [
        "Run aterm harness accounts",
        "Claude Code hit this account's usage limit, and no other listed account can take over.",
        "aterm keeps this tab on its own account, so no other account replaces its login.",
        "aterm continues the tab by itself after the reset on Oct 23 at 9am.",
    ]
    .map(str::to_string)
    .to_vec();
    notice.sentences = 4;
    notice.state = "live";
    notice.retired_unix_ms = None;
    log.entries.insert(at, notice.clone());
    log.tags.push(("harness".to_string(), 1));
    (log, notice)
}

/// The Messages plan of `view` for the log `log`, laid out as the view's
/// last render laid the page out.
fn messages_plan_drawn(
    runtime: &NativeRuntime,
    view: crate::native_app::ViewId,
    log: &MessagesState,
) -> MessagesPlan {
    let state = messages_view_state(runtime, view);
    let (width, viewport) = state
        .messages_page_geometry
        .get()
        .expect("the render measured the page");
    let visible = messages_visible(log, &state.messages_filter);
    messages_plan(state, log, &visible, width, viewport)
}

/// Whether the compiled page shows every sentence line and the Copy of the
/// open entry `id` inside a window `height` tall.
fn open_entry_read_whole(compiled: &crate::native_ui::CompiledUi, id: u64, height: f32) -> bool {
    (0..4)
        .map(|k| format!("settings/messages/row/{id}/detail/{k}"))
        .chain([format!("settings/messages/row/{id}/copy")])
        .all(|key| {
            compiled
                .semantic(&UiKey::new(key.as_str()))
                .is_some_and(|node| node.rect.y >= -0.01 && node.rect.bottom() <= height + 0.01)
        })
}

/// Scroll the Messages list of `view` to stop `stop`, as a screen reader's
/// scroll to an offset does.
fn scroll_messages_to(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    stop: usize,
) {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/page-scroll"),
                value: Some(SemanticInput::Number(stop as f64)),
            }),
        )
        .unwrap();
}

/// THE LIST KEEPS ITS PLACE ACROSS A RESIZE (r3g-2). A window resized across
/// the switch that takes a wider page's header into the list
/// (`MessagesPlan::scrolls`) changes how many stops come before the first
/// entry, so the same `page_scroll` names another entry: grown from a
/// landing on the tall notice at 864×462 (stop 1, the header scrolled away),
/// the pinned header's stop 1 is the entry UNDER the notice, and the open
/// notice went above the view; shrunk again from its top, stop 0 seats the
/// header and no room under it for the notice; shrunk with the notice open
/// at the top of a list scrolled past its head, the scrolling list's stop is
/// the entry ABOVE it. The render draws from the same place and keeps the
/// open entry in view, read whole, and the next event moves on from the
/// stop it drew. NEGATIVE CONTROLS: the stop as it was shows another entry
/// at the top, or none.
#[test]
fn a_resize_across_the_header_switch_keeps_the_open_entry_in_view() {
    let small = view_cx_at(864.0, 462.0);
    let large = view_cx_at(864.0, 900.0);
    // Grown from the landing at the head of the list, then shrunk again.
    let (log, notice) = messages_with_tall_notice(0);
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(log.clone(), 8));
    let _ = compile_settings_view(&runtime, instance, view, &small);
    select_message(&mut runtime, instance, view, notice.id);
    let compiled = compile_settings_view(&runtime, instance, view, &small);
    assert!(
        messages_plan_drawn(&runtime, view, &log).scrolls,
        "premise: the header scrolls under the open notice"
    );
    assert_eq!(messages_view_state(&runtime, view).page_scroll, 1);
    assert_eq!(message_rows(&compiled).first(), Some(&notice.id));
    let compiled = compile_settings_view(&runtime, instance, view, &large);
    compiled.validate_parity().unwrap();
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(!plan.scrolls, "premise: grown, the header is pinned again");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&notice.id),
        "grown, the open entry left the top of the list"
    );
    assert!(open_entry_read_whole(&compiled, notice.id, 900.0));
    // NEGATIVE CONTROL: the landing's stop as it was starts under the notice.
    assert_eq!(plan.view(1).rows.start, 1);
    let compiled = compile_settings_view(&runtime, instance, view, &small);
    compiled.validate_parity().unwrap();
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(plan.scrolls, "premise: shrunk, the header scrolls again");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&notice.id),
        "shrunk again, the open entry left the view"
    );
    assert!(open_entry_read_whole(&compiled, notice.id, 462.0));
    // NEGATIVE CONTROL: the grown list's stop 0 seats the header, and no
    // entry under it.
    assert!(!plan.view(0).header.is_empty() && plan.view(0).rows.is_empty());
    // The next event moves on from the stop drawn.
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(messages_view_state(&runtime, view).page_scroll, 2);
    let compiled = compile_settings_view(&runtime, instance, view, &small);
    assert_eq!(message_rows(&compiled).first(), Some(&40), "one entry down");

    // Shrunk with the notice open at the top of a list scrolled past its head.
    let at = 2;
    let (log, notice) = messages_with_tall_notice(at);
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(log.clone(), 8));
    let _ = compile_settings_view(&runtime, instance, view, &large);
    messages_action(
        &mut runtime,
        instance,
        view,
        &format!("settings/messages/row/{}/title", notice.id),
    );
    scroll_messages_to(&mut runtime, instance, view, at);
    let compiled = compile_settings_view(&runtime, instance, view, &large);
    assert!(
        !messages_plan_drawn(&runtime, view, &log).scrolls,
        "premise: the open notice fits under the pinned header"
    );
    assert_eq!(message_rows(&compiled).first(), Some(&notice.id));
    let compiled = compile_settings_view(&runtime, instance, view, &small);
    compiled.validate_parity().unwrap();
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(plan.scrolls, "premise: shrunk, the header scrolls");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&notice.id),
        "shrunk, the list moved"
    );
    assert!(open_entry_read_whole(&compiled, notice.id, 462.0));
    // NEGATIVE CONTROL: the stop as it was puts the entry above on top.
    assert_eq!(plan.view(at).rows.start, at - 1);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(-1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        plan.lead_stops() + at - 1,
        "one up from the stop drawn"
    );
}

/// THE TAG POP-UP OPENS WHERE IT IS SEEN (r3g-2). Its chips grow the filters
/// card, and on a wider page whose open entry only just fits under the
/// pinned header that takes the header (the not-saved note and the filters)
/// into the list. A pop-up opened on a list scrolled into the log is DRAWN,
/// its card seated with the button the keyboard is on; Escape closes it, and
/// the list keeps the place the reader scrolled it to as the header is
/// pinned again; so does its own button, pressed on the card it seated.
/// NEGATIVE CONTROLS: in the list the press made, the stop it found seats no
/// header item, and so does that stop re-counted (a pop-up out of view
/// either way); after each close, the stop as it was shows another entry
/// at the top.
#[test]
fn a_tag_pop_up_opened_on_a_scrolled_wide_page_is_drawn() {
    let mut log = script_tag_messages(12);
    log.saved = false;
    let width = 864.0;
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(log.clone(), 8));
    // The open entry: the crash, its body two lines.
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/title",
    );
    let tag_menu = |runtime: &mut NativeRuntime, open: bool| {
        if let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) {
            state.messages_tag_menu = open;
        }
    };
    // A window whose pinned header holds the open entry with the pop-up
    // closed, and not with it open.
    let height = (300..1_200)
        .step_by(4)
        .map(|h| h as f32)
        .find(|&height| {
            let _ = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
            let closed = messages_plan_drawn(&runtime, view, &log);
            tag_menu(&mut runtime, true);
            let open = messages_plan_drawn(&runtime, view, &log);
            tag_menu(&mut runtime, false);
            !closed.scrolls
                && open.scrolls
                && closed
                    .header
                    .iter()
                    .any(|(node, _)| ui_node_holds(node, MESSAGES_TAG_MENU))
        })
        .expect("premise: a window where the open pop-up takes the header into the list");
    let cx = view_cx_at(width, height);
    let at = 3;
    scroll_messages_to(&mut runtime, instance, view, at);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let reader = message_rows(&compiled)[0];
    assert!(
        compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_some(),
        "premise: the pinned header shows the Tag button"
    );
    focus_key(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/filter/tag/script00"))
            .is_some(),
        "the pop-up just opened is drawn"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "the keyboard is on {focus:?}, which the page does not show"
    );
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(plan.scrolls, "premise: open, the header scrolls");
    // NEGATIVE CONTROLS: neither the stop the press found nor that stop
    // re-counted seats the card.
    let lead = plan.lead_stops();
    assert!(plan.view(at).header.is_empty());
    assert!(plan.view(messages_restop(at, 0, lead)).header.is_empty());

    // Scrolled into the log under the open pop-up, back to the reader's
    // entry, Escape closes it.
    scroll_messages_to(&mut runtime, instance, view, lead + at);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "premise: scrolled to the reader's entry"
    );
    runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
        .unwrap();
    assert!(
        !messages_view_state(&runtime, view).messages_tag_menu,
        "premise: Escape closed the pop-up"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(!plan.scrolls, "premise: closed, the header is pinned");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "Escape moved the list"
    );
    // NEGATIVE CONTROL: the stop as it was shows another entry on top.
    assert_eq!(plan.view(lead + at).rows.start, lead + at);

    // Opened again, its card seated under the note scrolled away, then
    // closed by its own button: the entries the reader saw under the card
    // stay at the top of the list under the pinned header.
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let seated = messages_view_state(&runtime, view).page_scroll;
    assert!(
        seated > 0
            && compiled
                .semantic(&UiKey::new("settings/messages/not-saved"))
                .is_none(),
        "premise: the card seated, the note above it scrolled away"
    );
    let under = *message_rows(&compiled)
        .first()
        .expect("premise: entries under the card");
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(!plan.scrolls, "premise: closed, the header is pinned");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&under),
        "closing the pop-up moved the list"
    );
    // NEGATIVE CONTROL: the seated stop as it was starts past that entry.
    let index = log
        .entries
        .iter()
        .position(|entry| entry.id == under)
        .expect("listed");
    assert_ne!(plan.view(seated).rows.start, index);

    // Opened again and scrolled back to the reader's entry, then closed by
    // focusing Search (r4g-7), a close that no reducer re-counts: the render
    // keeps the list's place as the header is pinned again, and the next
    // event moves on from the stop drawn.
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        messages_plan_drawn(&runtime, view, &log).scrolls,
        "premise: open, the header scrolls"
    );
    scroll_messages_to(&mut runtime, instance, view, lead + at);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "premise: scrolled to the reader's entry"
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/search"))),
        )
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert!(
        !state.messages_tag_menu && state.page_scroll == lead + at,
        "premise: focusing Search closed the pop-up and re-counted nothing"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(!plan.scrolls, "premise: closed, the header is pinned");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "focusing Search moved the list"
    );
    // NEGATIVE CONTROL: the stop as it was shows another entry on top.
    assert_eq!(plan.view(lead + at).rows.start, lead + at);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        at + 1,
        "one entry on from the reader's"
    );

    // Search can close the pop-up and the window can resize before a render.
    // The old geometry must still be measured with the menu it actually drew.
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    assert!(messages_plan_drawn(&runtime, view, &log).scrolls);
    scroll_messages_to(&mut runtime, instance, view, lead + at);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(message_rows(&compiled).first(), Some(&reader));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/search"))),
        )
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert!(
        !state.messages_tag_menu && state.page_scroll == lead + at,
        "premise: Search closed the menu without re-counting"
    );
    let resized = view_cx_at(width, height + 4.0);
    let compiled = compile_settings_view(&runtime, instance, view, &resized);
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(
        !plan.scrolls,
        "premise: the larger closed page pins the header"
    );
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "closing the pop-up while resizing moved the list"
    );
    // NEGATIVE CONTROL: the old open-menu stop names another entry here.
    assert_ne!(plan.view(lead + at).rows.start, at);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(messages_view_state(&runtime, view).page_scroll, at + 1);

    // No render need arrive between Search closing the pop-up and a scroll.
    // End must use the closed list's stops before it applies that list's limit.
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    let open = messages_plan_drawn(&runtime, view, &log);
    assert!(open.scrolls, "premise: open, the header scrolls");
    let scroll_lead = open.lead_stops();
    scroll_messages_to(&mut runtime, instance, view, scroll_lead + at);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(message_rows(&compiled).first(), Some(&reader));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/search"))),
        )
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert!(!state.messages_tag_menu && state.page_scroll == scroll_lead + at);
    let closed = messages_plan_drawn(&runtime, view, &log);
    assert!(!closed.scrolls, "premise: closed, the header is pinned");
    let end = closed.limit();
    assert!(
        end > scroll_lead,
        "premise: the list extends past the header"
    );
    let last = log.entries.last().expect("the log has entries").id;
    // NEGATIVE CONTROL: clamping the old count and only then re-counting it
    // stops short of the last entry. No render has settled the new count yet.
    let late = messages_restop(end, scroll_lead, closed.lead_stops());
    assert!(!closed.view(late).rows.contains(&(log.entries.len() - 1)));
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(i32::MAX))
        .unwrap();
    assert_eq!(messages_view_state(&runtime, view).page_scroll, end);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        message_rows(&compiled).contains(&last),
        "the scroll to the end must show the last entry"
    );
}

/// AN ENTRY OPENED FROM A SCROLLED LIST KEEPS THE READER'S TOP ENTRY (ruling
/// 264, r3g-2). A body too tall for the room under the pinned header takes
/// the header into the list, one stop more before the first entry, and the
/// press re-counts the stop: the entry at the top stays there, the one
/// opened under it read whole. (The deep-link test only closes, from a
/// landing at stop 1.) The window is one where the notice reads whole even
/// two entries under the top. NEGATIVE CONTROL: there the stop as it was
/// shows the notice whole too, so nothing else would set the list right,
/// with the entry above the reader's on top.
#[test]
fn an_entry_opened_from_a_scrolled_list_keeps_the_readers_top_entry() {
    let at = 4;
    let (log, notice) = messages_with_tall_notice(at);
    let width = 864.0;
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(log.clone(), 8));
    let open = |runtime: &mut NativeRuntime, id: Option<u64>| {
        if let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) {
            state.messages_selected = id;
        }
    };
    let height = (300..1_200)
        .step_by(2)
        .map(|h| h as f32)
        .find(|&height| {
            let _ = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
            let closed = messages_plan_drawn(&runtime, view, &log);
            open(&mut runtime, Some(notice.id));
            let opened = messages_plan_drawn(&runtime, view, &log);
            open(&mut runtime, None);
            !closed.scrolls
                && closed.view(at - 1).rows.contains(&at)
                && opened.scrolls
                && opened.view(opened.lead_stops() + at - 2).rows.contains(&at)
        })
        .expect("premise: a window where the notice reads whole two entries under the top");
    let cx = view_cx_at(width, height);
    scroll_messages_to(&mut runtime, instance, view, at - 1);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let reader = log.entries[at - 1].id;
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "premise: the reader's entry at the top"
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        &format!("settings/messages/row/{}/title", notice.id),
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let plan = messages_plan_drawn(&runtime, view, &log);
    assert!(plan.scrolls, "premise: open, the header scrolls");
    assert_eq!(
        message_rows(&compiled).first(),
        Some(&reader),
        "the opened entry moved the list"
    );
    assert!(open_entry_read_whole(&compiled, notice.id, height));
    // NEGATIVE CONTROL: the stop as it was holds the notice whole too, with
    // the entry above the reader's on top.
    let was = plan.view(at - 1);
    assert!(was.rows.contains(&at));
    assert_eq!(was.rows.start, at - 2);
}

/// A DEEP-LINKED ENTRY IS READ THROUGH ITS LAST LINE (the review of the
/// owner's notices, 2026-10-20: the band's `Details` on a usage-limit notice
/// at 864×462 opened the entry under the pinned heading and filters, and the
/// body, fitted to the room they left, dropped its `what to expect` line —
/// removed, not scrolled away, so no scroll brought it back). An open entry
/// too tall for that room takes the header's room too: the header scrolls
/// away with the list, and every sentence line and the footer stand inside
/// the window. Closing the entry pins the header again. NEGATIVE CONTROL:
/// the same body fitted to the room under the pinned header loses its last
/// line — the landing the review imaged (now kept, and too tall for that
/// room).
#[test]
fn a_deep_linked_entry_too_tall_for_the_pinned_header_is_read_whole() {
    let (log, notice) = messages_with_tall_notice(0);
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(log.clone(), 8));
    let (width, height) = (864.0, 462.0);
    let cx = view_cx_at(width, height);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    select_message(&mut runtime, instance, view, 41);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let section = compiled
        .semantic(&UiKey::new("settings/messages/section"))
        .expect("the header scrolls with the list")
        .rect;
    for key in (0..4)
        .map(|k| format!("settings/messages/row/41/detail/{k}"))
        .chain(["settings/messages/row/41/copy".to_string()])
    {
        let rect = compiled
            .semantic(&UiKey::new(key.as_str()))
            .unwrap_or_else(|| panic!("{key} is seated"))
            .rect;
        assert!(
            rect.y >= section.y - 0.01
                && rect.bottom() <= section.bottom() + 0.01
                && rect.bottom() <= height,
            "{key} stands inside the window: {rect:?} (section {section:?})"
        );
    }
    let said: Vec<String> = (0..12)
        .filter_map(|k| {
            compiled
                .semantic(&UiKey::new(format!("settings/messages/row/41/detail/{k}")))
                .map(|node| node.label.clone())
        })
        .collect();
    assert!(
        said.join(" ").contains("after the reset on Oct 23 at 9am."),
        "the expectation is read: {said:?}"
    );
    // Closed, the header is pinned again, the list where it was.
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/41/title",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/section"))
            .is_none(),
        "the wider page's header stays"
    );
    assert_eq!(messages_view_state(&runtime, view).page_scroll, 0);
    assert_eq!(message_rows(&compiled).first(), Some(&41));
    // NEGATIVE CONTROL: under the pinned header the body drops its last line.
    let state = messages_view_state(&runtime, view);
    let (width, viewport) = state
        .messages_page_geometry
        .get()
        .expect("the render measured the page");
    let visible = messages_visible(&log, &state.messages_filter);
    let plan = messages_plan(state, &log, &visible, width, viewport);
    assert!(!plan.scrolls);
    let mut body = MessagesBody::of(
        &notice,
        (plan.content_width - plan.indent() - 16.0).max(48.0),
        log.utc_offset_s,
        log.now_unix_ms,
    );
    // The room under the pinned header does not hold it whole: fitted
    // there (the body keeps its sentence whole and would be read a part at
    // a time, [`MessagesTall`]), it is still taller than the room.
    let room = plan.room - messages_row_height() - 2.0 * MESSAGES_LIST_PAD;
    body.fit(room);
    assert!(
        body.height() > room,
        "the control: {} in {room}",
        body.height()
    );
}

/// The page names an entry and a button by IDENTITY (design §4.4): the
/// effect carries an id and an index, never the path the intent holds,
/// and the host's answer becomes the feedback line; a button the
/// projection says is spent raises no effect at all.
#[test]
fn messages_entry_actions_never_carry_a_path() {
    let (mut runtime, instance, view) = setup_with_messages();
    let effects = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/action/0",
    );
    let operation = effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::MessageAct {
                id: 40,
                action: 0,
                reply,
            } => Some(reply.operation),
            _ => None,
        })
        .expect("one MessageAct effect naming the entry and the button");
    assert!(
        !format!("{effects:?}").contains("crash-signal"),
        "no effect carries the crash log's path: {effects:?}"
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::MessageActFinished {
                operation,
                outcome: MessageActOutcome::Performed {
                    feedback: "Opened the log".to_string(),
                },
            },
        )
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).feedback.as_deref(),
        Some("Opened the log")
    );
    // A spent button: the page says so and asks the host for nothing.
    let effects = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/action/0",
    );
    assert!(
        !effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::MessageAct { .. })),
        "{effects:?}"
    );
    let spent = messages_view_state(&runtime, view).feedback.clone();
    assert!(
        spent.is_some() && spent.as_deref() != Some("Opened the log"),
        "the page says the button is spent: {spent:?}"
    );
    let effects = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/999/action/0",
    );
    assert!(
        !effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::MessageAct { .. }))
    );
    assert!(
        messages_view_state(&runtime, view).feedback.is_some(),
        "the page says the entry is gone"
    );
}

/// A row's Copy puts the engine's own `copy_text` of that entry on the
/// clipboard. COPY ALL (design ruling 65): the entries the chip shows, newest
/// first, each as its own Copy puts it, under the build information — one
/// press for a report. With a chip down, only that chip's entries.
#[test]
fn copy_all_puts_every_shown_entry_and_the_build_on_the_clipboard() {
    let copied = |effects: Vec<AppEffect>| {
        effects
            .into_iter()
            .find_map(|effect| match effect {
                AppEffect::Clipboard {
                    request: ClipboardRequest::CopyText { text, sensitive },
                    ..
                } => {
                    assert!(!sensitive);
                    Some(text)
                }
                _ => None,
            })
            .expect("one clipboard effect")
    };
    let (mut runtime, instance, view) = setup_with_messages();
    let all = sample_messages();
    assert_eq!(
        copied(messages_action(
            &mut runtime,
            instance,
            view,
            "settings/messages/row/40/copy",
        )),
        all.entries[0].copy_text(),
        "the row's Copy is that entry's own copy text"
    );
    let text = copied(messages_action(
        &mut runtime,
        instance,
        view,
        MESSAGES_COPY_ALL,
    ));
    assert!(text.starts_with(&crate::about::provenance_text()), "{text}");
    for entry in &all.entries {
        assert!(text.contains(&entry.copy_text()), "{}", entry.title);
    }
    let crash = text.find("aterm closed unexpectedly").unwrap();
    let older = text.find("config warning 1\n").unwrap();
    assert!(crash < older, "newest first");
    // Negative control: with the crash chip down, only the crash is copied.
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/crash",
    );
    let text = copied(messages_action(
        &mut runtime,
        instance,
        view,
        MESSAGES_COPY_ALL,
    ));
    assert!(text.contains("aterm closed unexpectedly"));
    assert!(!text.contains("config warning"), "{text}");
    let commands = runtime.commands(instance, view).unwrap();
    assert!(commands.iter().any(|c| c.id.as_str() == MESSAGES_COPY_ALL));
}

/// Open Log Folder asks the host for its own log directory (the effect carries no
/// path) and, off macOS, the page names the folder instead.
#[test]
fn open_log_folder_asks_the_host_and_never_names_a_path() {
    let (mut runtime, instance, view) = setup_with_messages();
    let effects = messages_action(&mut runtime, instance, view, MESSAGES_OPEN_FOLDER);
    let asked = effects
        .iter()
        .any(|effect| matches!(effect, AppEffect::OpenLogFolder { .. }));
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    if cfg!(target_os = "macos") {
        assert!(asked, "{effects:?}");
        assert!(state.feedback.is_some());
    } else {
        assert!(!asked, "nothing is spawned off macOS");
        assert!(
            state
                .feedback
                .as_deref()
                .is_some_and(|line| line.contains("/Users//w/Library/Logs/aterm")),
            "the page names the folder instead: {:?}",
            state.feedback
        );
    }
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands
            .iter()
            .any(|c| c.id.as_str() == MESSAGES_OPEN_FOLDER && c.enabled)
    );
    // No folder: says so, and asks nothing.
    let (mut runtime, instance, view) = setup_with_messages();
    let mut none = sample_messages();
    none.log_folder = None;
    assert!(runtime.replace_settings_messages(none, 8));
    let effects = messages_action(&mut runtime, instance, view, MESSAGES_OPEN_FOLDER);
    assert!(
        !effects
            .iter()
            .any(|e| matches!(e, AppEffect::OpenLogFolder { .. }))
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.feedback.is_some(), "says so");
}

